window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["HOS"]={"book":"HOS","editions":{"hbo-source":[[1,1,"דְּבַר־יְהוָ֣ה ׀ אֲשֶׁ֣ר הָיָ֗ה אֶל־הוֹשֵׁ֨עַ֙ בֶּן־בְּאֵרִ֔י בִּ⁠ימֵ֨י עֻזִּיָּ֥ה יוֹתָ֛ם אָחָ֥ז יְחִזְקִיָּ֖ה מַלְכֵ֣י יְהוּדָ֑ה וּ⁠בִ⁠ימֵ֛י יָרָבְעָ֥ם בֶּן־יוֹאָ֖שׁ מֶ֥לֶךְ יִשְׂרָאֵֽל׃","dĕ̇bar-yĕhwá֣h ׀ ʼàşě֣r háyá֗h ʼel-hwòşé̌֨ʻa֙ bėn-bĕ̇ʼéri֔y bi̇⁠ymé֨y ʻuzi̇yá֥̇h ywòţá֛m ʼáẖá֥z yĕẖizĕqiyá֖̇h malĕké֣y yĕhẇdá֑h ẇ⁠bi⁠ymé֛y yárábĕʻá֥m bėn-ywòʼá֖ş̌ me֥lekĕ yişĕ̂ráʼéֽl׃"],[1,2,"תְּחִלַּ֥ת דִּבֶּר־יְהוָ֖ה בְּ⁠הוֹשֵׁ֑עַ פ וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־הוֹשֵׁ֗עַ לֵ֣ךְ קַח־לְ⁠ךָ֞ אֵ֤שֶׁת זְנוּנִים֙ וְ⁠יַלְדֵ֣י זְנוּנִ֔ים כִּֽי־זָנֹ֤ה תִזְנֶה֙ הָ⁠אָ֔רֶץ מֵֽ⁠אַחֲרֵ֖י יְהוָֽה׃","ţĕ̇ẖilȧ֥ţ di̇bėr-yĕhwá֖h bĕ̇⁠hwòşé֑̌ʻa p wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-hwòşé̌֗ʻa lé֣kĕ qaẖ-lĕ⁠ká֞ ʼé֤şěţ zĕnẇniym֙ wĕ⁠yalĕdé֣y zĕnẇni֔ym kiֽ̇y-zánò֤h ţizĕneh֙ há⁠ʼá֔reẕ méֽ⁠ʼaẖàré֖y yĕhwáֽh׃"],[1,3,"וַ⁠יֵּ֨לֶךְ֙ וַ⁠יִּקַּ֔ח אֶת־גֹּ֖מֶר בַּת־דִּבְלָ֑יִם וַ⁠תַּ֥הַר וַ⁠תֵּֽלֶד־ל֖⁠וֹ בֵּֽן׃","wa⁠yé̇֨lekĕ֙ wa⁠yi̇qȧ֔ẖ ʼeţ-gò֖̇mer bȧţ-di̇bĕlá֑yim wa⁠ţȧ֥har wa⁠ţéֽ̇led-l֖⁠wò béֽ̇n׃"],[1,4,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֵלָ֔י⁠ו קְרָ֥א שְׁמ֖⁠וֹ יִזְרְעֶ֑אל כִּי־ע֣וֹד מְעַ֗ט וּ⁠פָ֨קַדְתִּ֜י אֶת־דְּמֵ֤י יִזְרְעֶאל֙ עַל־בֵּ֣ית יֵה֔וּא וְ⁠הִ֨שְׁבַּתִּ֔י מַמְלְכ֖וּת בֵּ֥ית יִשְׂרָאֵֽל׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼélá֔y⁠w qĕrá֥ʼ şĕ̌m֖⁠wò yizĕrĕʻe֑ʼl ki̇y-ʻ֣wòd mĕʻa֗t ẇ⁠pá֨qadĕţi̇֜y ʼeţ-dĕ̇mé֤y yizĕrĕʻeʼl֙ ʻal-bé֣̇yţ yéh֔ẇʼ wĕ⁠hi֨şĕ̌bȧţi̇֔y mamĕlĕk֖ẇţ bé֥̇yţ yişĕ̂ráʼéֽl׃"],[1,5,"וְ⁠הָיָ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא וְ⁠שָֽׁבַרְתִּי֙ אֶת־קֶ֣שֶׁת יִשְׂרָאֵ֔ל בְּ⁠עֵ֖מֶק יִזְרְעֶֽאל׃","wĕ⁠háyá֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ wĕ⁠şáֽ̌barĕţi̇y֙ ʼeţ-qe֣şěţ yişĕ̂ráʼé֔l bĕ̇⁠ʻé֖meq yizĕrĕʻeֽʼl׃"],[1,6,"וַ⁠תַּ֤הַר עוֹד֙ וַ⁠תֵּ֣לֶד בַּ֔ת וַ⁠יֹּ֣אמֶר ל֔⁠וֹ קְרָ֥א שְׁמָ֖⁠הּ לֹ֣א רֻחָ֑מָה כִּי֩ לֹ֨א אוֹסִ֜יף ע֗וֹד אֲרַחֵם֙ אֶת־בֵּ֣ית יִשְׂרָאֵ֔ל כִּֽי־נָשֹׂ֥א אֶשָּׂ֖א לָ⁠הֶֽם׃","wa⁠ţȧ֤har ʻwòd֙ wa⁠ţé֣̇led bȧ֔ţ wa⁠yò֣̇ʼmer l֔⁠wò qĕrá֥ʼ şĕ̌má֖⁠ḣ lò֣ʼ ruẖá֑máh ki̇y֩ lò֨ʼ ʼwòsi֜yp ʻ֗wòd ʼàraẖém֙ ʼeţ-bé֣̇yţ yişĕ̂ráʼé֔l kiֽ̇y-náşò֥̂ʼ ʼeşá֖̇̂ʼ lá⁠heֽm׃"],[1,7,"וְ⁠אֶת־בֵּ֤ית יְהוּדָה֙ אֲרַחֵ֔ם וְ⁠הֽוֹשַׁעְתִּ֖י⁠ם בַּ⁠יהוָ֣ה אֱלֹֽהֵי⁠הֶ֑ם וְ⁠לֹ֣א אֽוֹשִׁיעֵ֗⁠ם בְּ⁠קֶ֤שֶׁת וּ⁠בְ⁠חֶ֨רֶב֙ וּ⁠בְ⁠מִלְחָמָ֔ה בְּ⁠סוּסִ֖ים וּ⁠בְ⁠פָרָשִֽׁים׃","wĕ⁠ʼeţ-bé֤̇yţ yĕhẇdáh֙ ʼàraẖé֔m wĕ⁠hֽwòşǎʻĕţi֖̇y⁠m bȧ⁠yhwá֣h ʼèlòֽhéy⁠he֑m wĕ⁠lò֣ʼ ʼֽwòşǐyʻé֗⁠m bĕ̇⁠qe֤şěţ ẇ⁠bĕ⁠ẖe֨reb֙ ẇ⁠bĕ⁠milĕẖámá֔h bĕ̇⁠sẇsi֖ym ẇ⁠bĕ⁠páráşǐֽym׃"],[1,8,"וַ⁠תִּגְמֹ֖ל אֶת־לֹ֣א רֻחָ֑מָה וַ⁠תַּ֖הַר וַ⁠תֵּ֥לֶד בֵּֽן׃","wa⁠ţi̇gĕmò֖l ʼeţ-lò֣ʼ ruẖá֑máh wa⁠ţȧ֖har wa⁠ţé֥̇led béֽ̇n׃"],[1,9,"וַ⁠יֹּ֕אמֶר קְרָ֥א שְׁמ֖⁠וֹ לֹ֣א עַמִּ֑י כִּ֤י אַתֶּם֙ לֹ֣א עַמִּ֔⁠י וְ⁠אָנֹכִ֖י לֹֽא־אֶהְיֶ֥ה לָ⁠כֶֽם׃ס","wa⁠yò̇֕ʼmer qĕrá֥ʼ şĕ̌m֖⁠wò lò֣ʼ ʻami֑̇y ki֤̇y ʼaţėm֙ lò֣ʼ ʻami̇֔⁠y wĕ⁠ʼánòki֖y lòֽʼ-ʼehĕye֥h lá⁠keֽm׃s"],[1,10,"וְֽ֠⁠הָיָה מִסְפַּ֤ר בְּנֵֽי־יִשְׂרָאֵל֙ כְּ⁠ח֣וֹל הַ⁠יָּ֔ם אֲשֶׁ֥ר לֹֽא־יִמַּ֖ד וְ⁠לֹ֣א יִסָּפֵ֑ר וְֽ֠⁠הָיָה בִּ⁠מְק֞וֹם אֲשֶׁר־יֵאָמֵ֤ר לָ⁠הֶם֙ לֹֽא־עַמִּ֣⁠י אַתֶּ֔ם יֵאָמֵ֥ר לָ⁠הֶ֖ם בְּנֵ֥י אֵֽל־חָֽי׃","wĕֽ֠⁠háyáh misĕpȧ֤r bĕ̇néֽy-yişĕ̂ráʼél֙ kĕ̇⁠ẖ֣wòl ha⁠yá̇֔m ʼàşě֥r lòֽʼ-yimȧ֖d wĕ⁠lò֣ʼ yisá̇pé֑r wĕֽ֠⁠háyáh bi̇⁠mĕq֞wòm ʼàşěr-yéʼámé֤r lá⁠hem֙ lòֽʼ-ʻami֣̇⁠y ʼaţė֔m yéʼámé֥r lá⁠he֖m bĕ̇né֥y ʼéֽl-ẖáֽy׃"],[1,11,"וְ֠⁠נִקְבְּצוּ בְּנֵֽי־יְהוּדָ֤ה וּ⁠בְנֵֽי־יִשְׂרָאֵל֙ יַחְדָּ֔ו וְ⁠שָׂמ֥וּ לָ⁠הֶ֛ם רֹ֥אשׁ אֶחָ֖ד וְ⁠עָל֣וּ מִן־הָ⁠אָ֑רֶץ כִּ֥י גָד֖וֹל י֥וֹם יִזְרְעֶֽאל׃","wĕ֠⁠niqĕbĕ̇ẕẇ bĕ̇néֽy-yĕhẇdá֤h ẇ⁠bĕnéֽy-yişĕ̂ráʼél֙ yaẖĕdá̇֔w wĕ⁠şá̂m֥ẇ lá⁠he֛m rò֥ʼş̌ ʼeẖá֖d wĕ⁠ʻál֣ẇ min-há⁠ʼá֑reẕ ki֥̇y gád֖wòl y֥wòm yizĕrĕʻeֽʼl׃"],[2,1,"אִמְר֥וּ לַ⁠אֲחֵי⁠כֶ֖ם עַמִּ֑⁠י וְ⁠לַ⁠אֲחֽוֹתֵי⁠כֶ֖ם רֻחָֽמָה׃","ʼimĕr֥ẇ la⁠ʼàẖéy⁠ke֖m ʻami֑̇⁠y wĕ⁠la⁠ʼàẖֽwòţéy⁠ke֖m ruẖáֽmáh׃"],[2,2,"רִ֤יבוּ בְ⁠אִמְּ⁠כֶם֙ רִ֔יבוּ כִּֽי־הִיא֙ לֹ֣א אִשְׁתִּ֔⁠י וְ⁠אָנֹכִ֖י לֹ֣א אִישָׁ֑⁠הּ וְ⁠תָסֵ֤ר זְנוּנֶ֨י⁠הָ֙ מִ⁠פָּנֶ֔י⁠ה וְ⁠נַאֲפוּפֶ֖י⁠הָ מִ⁠בֵּ֥ין שָׁדֶֽי⁠הָ׃","ri֤ybẇ bĕ⁠ʼimĕ̇⁠kem֙ ri֔ybẇ kiֽ̇y-hiyʼ֙ lò֣ʼ ʼişĕ̌ţi̇֔⁠y wĕ⁠ʼánòki֖y lò֣ʼ ʼiyşá֑̌⁠ḣ wĕ⁠ţásé֤r zĕnẇne֨y⁠há֙ mi⁠pá̇ne֔y⁠h wĕ⁠naʼàpẇpe֖y⁠há mi⁠bé֥̇yn şá̌deֽy⁠há׃"],[2,3,"פֶּן־אַפְשִׁיטֶ֣⁠נָּה עֲרֻמָּ֔ה וְ⁠הִ֨צַּגְתִּ֔י⁠הָ כְּ⁠י֖וֹם הִוָּֽלְדָ֑⁠הּ וְ⁠שַׂמְתִּ֣י⁠הָ כַ⁠מִּדְבָּ֗ר וְ⁠שַׁתִּ֨⁠הָ֙ כְּ⁠אֶ֣רֶץ צִיָּ֔ה וַ⁠הֲמִתִּ֖י⁠הָ בַּ⁠צָּמָֽא׃","pėn-ʼapĕşǐyte֣⁠ná̇h ʻàrumá̇֔h wĕ⁠hi֨ẕȧgĕţi̇֔y⁠há kĕ̇⁠y֖wòm hiwáֽ̇lĕdá֑⁠ḣ wĕ⁠şâmĕţi֣̇y⁠há ka⁠mi̇dĕbá̇֗r wĕ⁠şǎţi̇֨⁠há֙ kĕ̇⁠ʼe֣reẕ ẕiyá̇֔h wa⁠hàmiţi֖̇y⁠há bȧ⁠ẕá̇máֽʼ׃"],[2,4,"וְ⁠אֶת־בָּנֶ֖י⁠הָ לֹ֣א אֲרַחֵ֑ם כִּֽי־בְנֵ֥י זְנוּנִ֖ים הֵֽמָּה׃","wĕ⁠ʼeţ-bá̇ne֖y⁠há lò֣ʼ ʼàraẖé֑m kiֽ̇y-bĕné֥y zĕnẇni֖ym héֽmá̇h׃"],[2,5,"כִּ֤י זָֽנְתָה֙ אִמָּ֔⁠ם הֹבִ֖ישָׁה הֽוֹרָתָ֑⁠ם כִּ֣י אָמְרָ֗ה אֵלְכָ֞ה אַחֲרֵ֤י מְאַהֲבַ⁠י֙ נֹתְנֵ֤י לַחְמִ⁠י֙ וּ⁠מֵימַ֔⁠י צַמְרִ֣⁠י וּ⁠פִשְׁתִּ֔⁠י שַׁמְנִ֖⁠י וְ⁠שִׁקּוּיָֽ⁠י׃","ki֤̇y záֽnĕţáh֙ ʼimá̇֔⁠m hòbi֖yşá̌h hֽwòráţá֑⁠m ki֣̇y ʼámĕrá֗h ʼélĕká֞h ʼaẖàré֤y mĕʼahàba⁠y֙ nòţĕné֤y laẖĕmi⁠y֙ ẇ⁠méyma֔⁠y ẕamĕri֣⁠y ẇ⁠pişĕ̌ţi̇֔⁠y şǎmĕni֖⁠y wĕ⁠şǐq̇ẇyáֽ⁠y׃"],[2,6,"לָ⁠כֵ֛ן הִנְ⁠נִי־שָׂ֥ךְ אֶת־דַּרְכֵּ֖⁠ךְ בַּ⁠סִּירִ֑ים וְ⁠גָֽדַרְתִּי֙ אֶת־גְּדֵרָ֔⁠הּ וּ⁠נְתִיבוֹתֶ֖י⁠הָ לֹ֥א תִמְצָֽא׃","lá⁠ké֛n hinĕ⁠niy-şá֥̂kĕ ʼeţ-dȧrĕké֖̇⁠kĕ bȧ⁠si̇yri֑ym wĕ⁠gáֽdarĕţi̇y֙ ʼeţ-gĕ̇dérá֔⁠ḣ ẇ⁠nĕţiybwòţe֖y⁠há lò֥ʼ ţimĕẕáֽʼ׃"],[2,7,"וְ⁠רִדְּפָ֤ה אֶת־מְאַהֲבֶ֨י⁠הָ֙ וְ⁠לֹֽא־תַשִּׂ֣יג אֹתָ֔⁠ם וּ⁠בִקְשָׁ֖תַ⁠ם וְ⁠לֹ֣א תִמְצָ֑א וְ⁠אָמְרָ֗ה אֵלְכָ֤ה וְ⁠אָשׁ֨וּבָה֙ אֶל־אִישִׁ֣⁠י הָֽ⁠רִאשׁ֔וֹן כִּ֣י ט֥וֹב לִ֛⁠י אָ֖ז מֵ⁠עָֽתָּה׃","wĕ⁠ridĕ̇pá֤h ʼeţ-mĕʼahàbe֨y⁠há֙ wĕ⁠lòֽʼ-ţaşi֣̇̂yg ʼòţá֔⁠m ẇ⁠biqĕşá֖̌ţa⁠m wĕ⁠lò֣ʼ ţimĕẕá֑ʼ wĕ⁠ʼámĕrá֗h ʼélĕká֤h wĕ⁠ʼáş̌֨ẇbáh֙ ʼel-ʼiyşǐ֣⁠y háֽ⁠riʼş̌֔wòn ki֣̇y t֥wòb li֛⁠y ʼá֖z mé⁠ʻáֽţá̇h׃"],[2,8,"וְ⁠הִיא֙ לֹ֣א יָֽדְעָ֔ה כִּ֤י אָֽנֹכִי֙ נָתַ֣תִּי לָ֔⁠הּ הַ⁠דָּגָ֖ן וְ⁠הַ⁠תִּיר֣וֹשׁ וְ⁠הַ⁠יִּצְהָ֑ר וְ⁠כֶ֨סֶף הִרְבֵּ֥יתִי לָ֛⁠הּ וְ⁠זָהָ֖ב עָשׂ֥וּ לַ⁠בָּֽעַל׃","wĕ⁠hiyʼ֙ lò֣ʼ yáֽdĕʻá֔h ki֤̇y ʼáֽnòkiy֙ náţa֣ţi̇y lá֔⁠ḣ ha⁠dá̇gá֖n wĕ⁠ha⁠ţi̇yr֣wòş̌ wĕ⁠ha⁠yi̇ẕĕhá֑r wĕ⁠ke֨sep hirĕbé֥̇yţiy lá֛⁠ḣ wĕ⁠záhá֖b ʻáş֥̂ẇ la⁠báֽ̇ʻal׃"],[2,9,"לָ⁠כֵ֣ן אָשׁ֔וּב וְ⁠לָקַחְתִּ֤י דְגָנִ⁠י֙ בְּ⁠עִתּ֔⁠וֹ וְ⁠תִירוֹשִׁ֖⁠י בְּ⁠מֽוֹעֲד֑⁠וֹ וְ⁠הִצַּלְתִּי֙ צַמְרִ֣⁠י וּ⁠פִשְׁתִּ֔⁠י לְ⁠כַסּ֖וֹת אֶת־עֶרְוָתָֽ⁠הּ׃","lá⁠ké֣n ʼáş̌֔ẇb wĕ⁠láqaẖĕţi֤̇y dĕgáni⁠y֙ bĕ̇⁠ʻiţ̇֔⁠wò wĕ⁠ţiyrwòşǐ֖⁠y bĕ̇⁠mֽwòʻàd֑⁠wò wĕ⁠hiẕȧlĕţi̇y֙ ẕamĕri֣⁠y ẇ⁠pişĕ̌ţi̇֔⁠y lĕ⁠kaṡ֖wòţ ʼeţ-ʻerĕwáţáֽ⁠ḣ׃"],[2,10,"וְ⁠עַתָּ֛ה אֲגַלֶּ֥ה אֶת־נַבְלֻתָ֖⁠הּ לְ⁠עֵינֵ֣י מְאַהֲבֶ֑י⁠הָ וְ⁠אִ֖ישׁ לֹֽא־יַצִּילֶ֥⁠נָּה מִ⁠יָּדִֽ⁠י׃","wĕ⁠ʻaţá֛̇h ʼàgalė֥h ʼeţ-nabĕluţá֖⁠ḣ lĕ⁠ʻéyné֣y mĕʼahàbe֑y⁠há wĕ⁠ʼi֖yş̌ lòֽʼ-yaẕi̇yle֥⁠ná̇h mi⁠yá̇diֽ⁠y׃"],[2,11,"וְ⁠הִשְׁבַּתִּי֙ כָּל־מְשׂוֹשָׂ֔⁠הּ חַגָּ֖⁠הּ חָדְשָׁ֣⁠הּ וְ⁠שַׁבַּתָּ֑⁠הּ וְ⁠כֹ֖ל מוֹעֲדָֽ⁠הּ׃","wĕ⁠hişĕ̌bȧţi̇y֙ ká̇l-mĕş̂wòşá̂֔⁠ḣ ẖagá֖̇⁠ḣ ẖádĕşá֣̌⁠ḣ wĕ⁠şǎbȧţá֑̇⁠ḣ wĕ⁠kò֖l mwòʻàdáֽ⁠ḣ׃"],[2,12,"וַ⁠הֲשִׁמֹּתִ֗י גַּפְנָ⁠הּ֙ וּ⁠תְאֵ֣נָתָ֔⁠הּ אֲשֶׁ֣ר אָמְרָ֗ה אֶתְנָ֥ה הֵ֨מָּה֙ לִ֔⁠י אֲשֶׁ֥ר נָֽתְנוּ־לִ֖⁠י מְאַֽהֲבָ֑⁠י וְ⁠שַׂמְתִּ֣י⁠ם לְ⁠יַ֔עַר וַ⁠אֲכָלָ֖תַ⁠ם חַיַּ֥ת הַ⁠שָּׂדֶֽה׃","wa⁠hàşǐmò̇ţi֗y gȧpĕná⁠ḣ֙ ẇ⁠ţĕʼé֣náţá֔⁠ḣ ʼàşě֣r ʼámĕrá֗h ʼeţĕná֥h hé֨má̇h֙ li֔⁠y ʼàşě֥r náֽţĕnẇ-li֖⁠y mĕʼaֽhàbá֑⁠y wĕ⁠şâmĕţi֣̇y⁠m lĕ⁠ya֔ʻar wa⁠ʼàkálá֖ţa⁠m ẖayȧ֥ţ ha⁠şá̇̂deֽh׃"],[2,13,"וּ⁠פָקַדְתִּ֣י עָלֶ֗י⁠הָ אֶת־יְמֵ֤י הַ⁠בְּעָלִים֙ אֲשֶׁ֣ר תַּקְטִ֣יר לָ⁠הֶ֔ם וַ⁠תַּ֤עַד נִזְמָ⁠הּ֙ וְ⁠חֶלְיָתָ֔⁠הּ וַ⁠תֵּ֖לֶךְ אַחֲרֵ֣י מְאַהֲבֶ֑י⁠הָ וְ⁠אֹתִ֥⁠י שָׁכְחָ֖ה נְאֻם־יְהוָֽה׃פ","ẇ⁠páqadĕţi֣̇y ʻále֗y⁠há ʼeţ-yĕmé֤y ha⁠bĕ̇ʻáliym֙ ʼàşě֣r ţȧqĕti֣yr lá⁠he֔m wa⁠ţȧ֤ʻad nizĕmá⁠ḣ֙ wĕ⁠ẖelĕyáţá֔⁠ḣ wa⁠ţé֖̇lekĕ ʼaẖàré֣y mĕʼahàbe֑y⁠há wĕ⁠ʼòţi֥⁠y şá̌kĕẖá֖h nĕʼum-yĕhwáֽh׃p"],[2,14,"לָ⁠כֵ֗ן הִנֵּ֤ה אָֽנֹכִי֙ מְפַתֶּ֔י⁠הָ וְ⁠הֹֽלַכְתִּ֖י⁠הָ הַ⁠מִּדְבָּ֑ר וְ⁠דִבַּרְתִּ֖י עַל לִבָּֽ⁠הּ׃","lá⁠ké֗n hiné֤̇h ʼáֽnòkiy֙ mĕpaţė֔y⁠há wĕ⁠hòֽlakĕţi֖̇y⁠há ha⁠mi̇dĕbá֑̇r wĕ⁠dibȧrĕţi֖̇y ʻal libáֽ̇⁠ḣ׃"],[2,15,"וְ⁠נָתַ֨תִּי לָ֤⁠הּ אֶת־כְּרָמֶ֨י⁠הָ֙ מִ⁠שָּׁ֔ם וְ⁠אֶת־עֵ֥מֶק עָכ֖וֹר לְ⁠פֶ֣תַח תִּקְוָ֑ה וְ⁠עָ֤נְתָה שָּׁ֨מָּ⁠ה֙ כִּ⁠ימֵ֣י נְעוּרֶ֔י⁠הָ וִּ⁠כְ⁠י֖וֹם עֲלֹתָ֥⁠הּ מֵ⁠אֶֽרֶץ־מִצְרָֽיִם׃ס","wĕ⁠náţa֨ţi̇y lá֤⁠ḣ ʼeţ-kĕ̇ráme֨y⁠há֙ mi⁠şá̇̌֔m wĕ⁠ʼeţ-ʻé֥meq ʻák֖wòr lĕ⁠pe֣ţaẖ ţi̇qĕwá֑h wĕ⁠ʻá֤nĕţáh şá̇̌֨má̇⁠h֙ ki̇⁠ymé֣y nĕʻẇre֔y⁠há wi̇⁠kĕ⁠y֖wòm ʻàlòţá֥⁠ḣ mé⁠ʼeֽreẕ-miẕĕráֽyim׃s"],[2,16,"וְ⁠הָיָ֤ה בַ⁠יּוֹם־הַ⁠הוּא֙ נְאֻם־יְהוָ֔ה תִּקְרְאִ֖י אִישִׁ֑⁠י וְ⁠לֹֽא־תִקְרְאִי־לִ֥⁠י ע֖וֹד בַּעְלִֽ⁠י׃","wĕ⁠háyá֤h ba⁠ẏwòm-ha⁠hẇʼ֙ nĕʼum-yĕhwá֔h ţi̇qĕrĕʼi֖y ʼiyşǐ֑⁠y wĕ⁠lòֽʼ-ţiqĕrĕʼiy-li֥⁠y ʻ֖wòd bȧʻĕliֽ⁠y׃"],[2,17,"וַ⁠הֲסִרֹתִ֛י אֶת־שְׁמ֥וֹת הַ⁠בְּעָלִ֖ים מִ⁠פִּ֑י⁠הָ וְ⁠לֹֽא־יִזָּכְר֥וּ ע֖וֹד בִּ⁠שְׁמָֽ⁠ם׃","wa⁠hàsiròţi֛y ʼeţ-şĕ̌m֥wòţ ha⁠bĕ̇ʻáli֖ym mi⁠pi֑̇y⁠há wĕ⁠lòֽʼ-yizá̇kĕr֥ẇ ʻ֖wòd bi̇⁠şĕ̌máֽ⁠m׃"],[2,18,"וְ⁠כָרַתִּ֨י לָ⁠הֶ֤ם בְּרִית֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא עִם־חַיַּ֤ת הַ⁠שָּׂדֶה֙ וְ⁠עִם־ע֣וֹף הַ⁠שָּׁמַ֔יִם וְ⁠רֶ֖מֶשׂ הָֽ⁠אֲדָמָ֑ה וְ⁠קֶ֨שֶׁת וְ⁠חֶ֤רֶב וּ⁠מִלְחָמָה֙ אֶשְׁבּ֣וֹר מִן־הָ⁠אָ֔רֶץ וְ⁠הִשְׁכַּבְתִּ֖י⁠ם לָ⁠בֶֽטַח׃","wĕ⁠káraţi̇֨y lá⁠he֤m bĕ̇riyţ֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ʻim-ẖayȧ֤ţ ha⁠şá̇̂deh֙ wĕ⁠ʻim-ʻ֣wòp ha⁠şá̇̌ma֔yim wĕ⁠re֖meş̂ háֽ⁠ʼàdámá֑h wĕ⁠qe֨şěţ wĕ⁠ẖe֤reb ẇ⁠milĕẖámáh֙ ʼeşĕ̌ḃ֣wòr min-há⁠ʼá֔reẕ wĕ⁠hişĕ̌kȧbĕţi֖̇y⁠m lá⁠beֽtaẖ׃"],[2,19,"וְ⁠אֵרַשְׂתִּ֥י⁠ךְ לִ֖⁠י לְ⁠עוֹלָ֑ם וְ⁠אֵרַשְׂתִּ֥י⁠ךְ לִ⁠י֙ בְּ⁠צֶ֣דֶק וּ⁠בְ⁠מִשְׁפָּ֔ט וּ⁠בְ⁠חֶ֖סֶד וּֽ⁠בְ⁠רַחֲמִֽים׃","wĕ⁠ʼéraşĕ̂ţi֥̇y⁠kĕ li֖⁠y lĕ⁠ʻwòlá֑m wĕ⁠ʼéraşĕ̂ţi֥̇y⁠kĕ li⁠y֙ bĕ̇⁠ẕe֣deq ẇ⁠bĕ⁠mişĕ̌pá̇֔t ẇ⁠bĕ⁠ẖe֖sed ẇֽ⁠bĕ⁠raẖàmiֽym׃"],[2,20,"וְ⁠אֵרַשְׂתִּ֥י⁠ךְ לִ֖⁠י בֶּ⁠אֱמוּנָ֑ה וְ⁠יָדַ֖עַתְּ אֶת־יְהוָֽה׃ס","wĕ⁠ʼéraşĕ̂ţi֥̇y⁠kĕ li֖⁠y bė⁠ʼèmẇná֑h wĕ⁠yáda֖ʻaţĕ̇ ʼeţ-yĕhwáֽh׃s"],[2,21,"וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא אֶֽעֱנֶה֙ נְאֻם־יְהוָ֔ה אֶעֱנֶ֖ה אֶת־הַ⁠שָּׁמָ֑יִם וְ⁠הֵ֖ם יַעֲנ֥וּ אֶת־הָ⁠אָֽרֶץ׃","wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ ʼeֽʻèneh֙ nĕʼum-yĕhwá֔h ʼeʻène֖h ʼeţ-ha⁠şá̇̌má֑yim wĕ⁠hé֖m yaʻàn֥ẇ ʼeţ-há⁠ʼáֽreẕ׃"],[2,22,"וְ⁠הָ⁠אָ֣רֶץ תַּעֲנֶ֔ה אֶת־הַ⁠דָּגָ֖ן וְ⁠אֶת־הַ⁠תִּיר֣וֹשׁ וְ⁠אֶת־הַ⁠יִּצְהָ֑ר וְ⁠הֵ֖ם יַעֲנ֥וּ אֶֽת־יִזְרְעֶֽאל׃","wĕ⁠há⁠ʼá֣reẕ ţȧʻàne֔h ʼeţ-ha⁠dá̇gá֖n wĕ⁠ʼeţ-ha⁠ţi̇yr֣wòş̌ wĕ⁠ʼeţ-ha⁠yi̇ẕĕhá֑r wĕ⁠hé֖m yaʻàn֥ẇ ʼeֽţ-yizĕrĕʻeֽʼl׃"],[2,23,"וּ⁠זְרַעְתִּ֤י⁠הָ לִּ⁠י֙ בָּ⁠אָ֔רֶץ וְ⁠רִֽחַמְתִּ֖י אֶת־לֹ֣א רֻחָ֑מָה וְ⁠אָמַרְתִּ֤י לְ⁠לֹֽא־עַמִּי֙ עַמִּ⁠י־אַ֔תָּה וְ⁠ה֖וּא יֹאמַ֥ר אֱלֹהָֽ⁠י׃פ","ẇ⁠zĕraʻĕţi֤̇y⁠há li̇⁠y֙ bá̇⁠ʼá֔reẕ wĕ⁠riֽẖamĕţi֖̇y ʼeţ-lò֣ʼ ruẖá֑máh wĕ⁠ʼámarĕţi֤̇y lĕ⁠lòֽʼ-ʻami̇y֙ ʻami̇⁠y-ʼa֔ţá̇h wĕ⁠h֖ẇʼ yòʼma֥r ʼèlòháֽ⁠y׃p"],[3,1,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י ע֚וֹד לֵ֣ךְ אֱֽהַב־אִשָּׁ֔ה אֲהֻ֥בַת רֵ֖עַ וּ⁠מְנָאָ֑פֶת כְּ⁠אַהֲבַ֤ת יְהוָה֙ אֶת־בְּנֵ֣י יִשְׂרָאֵ֔ל וְ⁠הֵ֗ם פֹּנִים֙ אֶל־אֱלֹהִ֣ים אֲחֵרִ֔ים וְ⁠אֹהֲבֵ֖י אֲשִׁישֵׁ֥י עֲנָבִֽים׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y ʻ֚wòd lé֣kĕ ʼèֽhab-ʼişá̇̌֔h ʼàhu֥baţ ré֖ʻa ẇ⁠mĕnáʼá֑peţ kĕ̇⁠ʼahàba֤ţ yĕhwáh֙ ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֔l wĕ⁠hé֗m pò̇niym֙ ʼel-ʼèlòhi֣ym ʼàẖéri֔ym wĕ⁠ʼòhàbé֖y ʼàşǐyşé֥̌y ʻànábiֽym׃"],[3,2,"וָ⁠אֶכְּרֶ֣⁠הָ לִּ֔⁠י בַּ⁠חֲמִשָּׁ֥ה עָשָׂ֖ר כָּ֑סֶף וְ⁠חֹ֥מֶר שְׂעֹרִ֖ים וְ⁠לֵ֥תֶךְ שְׂעֹרִֽים׃","wá⁠ʼekĕ̇re֣⁠há li̇֔⁠y bȧ⁠ẖàmişá֥̇̌h ʻáşá֖̂r ká֑̇sep wĕ⁠ẖò֥mer şĕ̂ʻòri֖ym wĕ⁠lé֥ţekĕ şĕ̂ʻòriֽym׃"],[3,3,"וָ⁠אֹמַ֣ר אֵלֶ֗י⁠הָ יָמִ֤ים רַבִּים֙ תֵּ֣שְׁבִי לִ֔⁠י לֹ֣א תִזְנִ֔י וְ⁠לֹ֥א תִֽהְיִ֖י לְ⁠אִ֑ישׁ וְ⁠גַם־אֲנִ֖י אֵלָֽיִ⁠ךְ׃","wá⁠ʼòma֣r ʼéle֗y⁠há yámi֤ym rabi̇ym֙ ţé֣̇şĕ̌biy li֔⁠y lò֣ʼ ţizĕni֔y wĕ⁠lò֥ʼ ţiֽhĕyi֖y lĕ⁠ʼi֑yş̌ wĕ⁠gam-ʼàni֖y ʼéláֽyi⁠kĕ׃"],[3,4,"כִּ֣י ׀ יָמִ֣ים רַבִּ֗ים יֵֽשְׁבוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֵ֥ין מֶ֨לֶךְ֙ וְ⁠אֵ֣ין שָׂ֔ר וְ⁠אֵ֥ין זֶ֖בַח וְ⁠אֵ֣ין מַצֵּבָ֑ה וְ⁠אֵ֥ין אֵפ֖וֹד וּ⁠תְרָפִֽים׃","ki֣̇y ׀ yámi֣ym rabi̇֗ym yéֽşĕ̌bẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼé֥yn me֨lekĕ֙ wĕ⁠ʼé֣yn şá̂֔r wĕ⁠ʼé֥yn ze֖baẖ wĕ⁠ʼé֣yn maẕé̇bá֑h wĕ⁠ʼé֥yn ʼép֖wòd ẇ⁠ţĕrápiֽym׃"],[3,5,"אַחַ֗ר יָשֻׁ֨בוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וּ⁠בִקְשׁוּ֙ אֶת־יְהוָ֣ה אֱלֹהֵי⁠הֶ֔ם וְ⁠אֵ֖ת דָּוִ֣ד מַלְכָּ֑⁠ם וּ⁠פָחֲד֧וּ אֶל־יְהוָ֛ה וְ⁠אֶל־טוּב֖⁠וֹ בְּ⁠אַחֲרִ֥ית הַ⁠יָּמִֽים׃פ","ʼaẖa֗r yáşǔ֨bẇ֙ bĕ̇né֣y yişĕ̂ráʼé֔l ẇ⁠biqĕş̌ẇ֙ ʼeţ-yĕhwá֣h ʼèlòhéy⁠he֔m wĕ⁠ʼé֖ţ dá̇wi֣d malĕká֑̇⁠m ẇ⁠páẖàd֧ẇ ʼel-yĕhwá֛h wĕ⁠ʼel-tẇb֖⁠wò bĕ̇⁠ʼaẖàri֥yţ ha⁠yá̇miֽym׃p"],[4,1,"שִׁמְע֥וּ דְבַר־יְהוָ֖ה בְּנֵ֣י יִשְׂרָאֵ֑ל כִּ֣י רִ֤יב לַֽ⁠יהוָה֙ עִם־יוֹשְׁבֵ֣י הָ⁠אָ֔רֶץ כִּ֠י אֵין־אֱמֶ֧ת וְֽ⁠אֵין־חֶ֛סֶד וְ⁠אֵֽין־דַּ֥עַת אֱלֹהִ֖ים בָּ⁠אָֽרֶץ׃","şǐmĕʻ֥ẇ dĕbar-yĕhwá֖h bĕ̇né֣y yişĕ̂ráʼé֑l ki֣̇y ri֤yb laֽ⁠yhwáh֙ ʻim-ywòşĕ̌bé֣y há⁠ʼá֔reẕ ki̇֠y ʼéyn-ʼème֧ţ wĕֽ⁠ʼéyn-ẖe֛sed wĕ⁠ʼéֽyn-dȧ֥ʻaţ ʼèlòhi֖ym bá̇⁠ʼáֽreẕ׃"],[4,2,"אָלֹ֣ה וְ⁠כַחֵ֔שׁ וְ⁠רָצֹ֥חַ וְ⁠גָנֹ֖ב וְ⁠נָאֹ֑ף פָּרָ֕צוּ וְ⁠דָמִ֥ים בְּ⁠דָמִ֖ים נָגָֽעוּ׃","ʼálò֣h wĕ⁠kaẖé֔ş̌ wĕ⁠ráẕò֥ẖa wĕ⁠gánò֖b wĕ⁠náʼò֑p pá̇rá֕ẕẇ wĕ⁠dámi֥ym bĕ̇⁠dámi֖ym nágáֽʻẇ׃"],[4,3,"עַל־כֵּ֣ן ׀ תֶּאֱבַ֣ל הָ⁠אָ֗רֶץ וְ⁠אֻמְלַל֙ כָּל־יוֹשֵׁ֣ב בָּ֔⁠הּ בְּ⁠חַיַּ֥ת הַ⁠שָּׂדֶ֖ה וּ⁠בְ⁠ע֣וֹף הַ⁠שָּׁמָ֑יִם וְ⁠גַם־דְּגֵ֥י הַ⁠יָּ֖ם יֵאָסֵֽפוּ׃","ʻal-ké֣̇n ׀ ţėʼèba֣l há⁠ʼá֗reẕ wĕ⁠ʼumĕlal֙ ká̇l-ywòşé֣̌b bá̇֔⁠ḣ bĕ̇⁠ẖayȧ֥ţ ha⁠şá̇̂de֖h ẇ⁠bĕ⁠ʻ֣wòp ha⁠şá̇̌má֑yim wĕ⁠gam-dĕ̇gé֥y ha⁠yá֖̇m yéʼáséֽpẇ׃"],[4,4,"אַ֥ךְ אִ֛ישׁ אַל־יָרֵ֖ב וְ⁠אַל־יוֹכַ֣ח אִ֑ישׁ וְ⁠עַמְּ⁠ךָ֖ כִּ⁠מְרִיבֵ֥י כֹהֵֽן׃","ʼa֥kĕ ʼi֛yş̌ ʼal-yáré֖b wĕ⁠ʼal-ywòka֣ẖ ʼi֑yş̌ wĕ⁠ʻamĕ̇⁠ká֖ ki̇⁠mĕriybé֥y kòhéֽn׃"],[4,5,"וְ⁠כָשַׁלְתָּ֣ הַ⁠יּ֔וֹם וְ⁠כָשַׁ֧ל גַּם־נָבִ֛יא עִמְּ⁠ךָ֖ לָ֑יְלָה וְ⁠דָמִ֖יתִי אִמֶּֽ⁠ךָ׃","wĕ⁠káşǎlĕţá֣̇ ha⁠ẏ֔wòm wĕ⁠káşǎ֧l gȧm-nábi֛yʼ ʻimĕ̇⁠ká֖ lá֑yĕláh wĕ⁠dámi֖yţiy ʼimėֽ⁠ká׃"],[4,6,"נִדְמ֥וּ עַמִּ֖⁠י מִ⁠בְּלִ֣י הַ⁠דָּ֑עַת כִּֽי־אַתָּ֞ה הַ⁠דַּ֣עַת מָאַ֗סְתָּ וְ⁠אֶמְאָֽסְא⁠ךָ֙ מִ⁠כַּהֵ֣ן לִ֔⁠י וַ⁠תִּשְׁכַּח֙ תּוֹרַ֣ת אֱלֹהֶ֔י⁠ךָ אֶשְׁכַּ֥ח בָּנֶ֖י⁠ךָ גַּם־אָֽנִי׃","nidĕm֥ẇ ʻami֖̇⁠y mi⁠bĕ̇li֣y ha⁠dá֑̇ʻaţ kiֽ̇y-ʼaţá̇֞h ha⁠dȧ֣ʻaţ máʼa֗sĕţá̇ wĕ⁠ʼemĕʼáֽsĕʼ⁠ká֙ mi⁠kȧhé֣n li֔⁠y wa⁠ţi̇şĕ̌kȧẖ֙ ţ̇wòra֣ţ ʼèlòhe֔y⁠ká ʼeşĕ̌kȧ֥ẖ bá̇ne֖y⁠ká gȧm-ʼáֽniy׃"],[4,7,"כְּ⁠רֻבָּ֖⁠ם כֵּ֣ן חָֽטְאוּ־לִ֑⁠י כְּבוֹדָ֖⁠ם בְּ⁠קָל֥וֹן אָמִֽיר׃","kĕ̇⁠rubá֖̇⁠m ké֣̇n ẖáֽtĕʼẇ-li֑⁠y kĕ̇bwòdá֖⁠m bĕ̇⁠qál֥wòn ʼámiֽyr׃"],[4,8,"חַטַּ֥את עַמִּ֖⁠י יֹאכֵ֑לוּ וְ⁠אֶל־עֲוֺנָ֖⁠ם יִשְׂא֥וּ נַפְשֽׁ⁠וֹ׃","ẖatȧ֥ʼţ ʻami֖̇⁠y yòʼké֑lẇ wĕ⁠ʼel-ʻàwֺná֖⁠m yişĕ̂ʼ֥ẇ napĕşֽ̌⁠wò׃"],[4,9,"וְ⁠הָיָ֥ה כָ⁠עָ֖ם כַּ⁠כֹּהֵ֑ן וּ⁠פָקַדְתִּ֤י עָלָי⁠ו֙ דְּרָכָ֔י⁠ו וּ⁠מַעֲלָלָ֖י⁠ו אָשִׁ֥יב לֽ⁠וֹ׃","wĕ⁠háyá֥h ká⁠ʻá֖m kȧ⁠kò̇hé֑n ẇ⁠páqadĕţi֤̇y ʻáláy⁠w֙ dĕ̇ráká֔y⁠w ẇ⁠maʻàlálá֖y⁠w ʼáşǐ֥yb lֽ⁠wò׃"],[4,10,"וְ⁠אָֽכְלוּ֙ וְ⁠לֹ֣א יִשְׂבָּ֔עוּ הִזְנ֖וּ וְ⁠לֹ֣א יִפְרֹ֑צוּ כִּֽי־אֶת־יְהוָ֥ה עָזְב֖וּ לִ⁠שְׁמֹֽר׃","wĕ⁠ʼáֽkĕlẇ֙ wĕ⁠lò֣ʼ yişĕ̂bá̇֔ʻẇ hizĕn֖ẇ wĕ⁠lò֣ʼ yipĕrò֑ẕẇ kiֽ̇y-ʼeţ-yĕhwá֥h ʻázĕb֖ẇ li⁠şĕ̌mòֽr׃"],[4,11,"זְנ֛וּת וְ⁠יַ֥יִן וְ⁠תִיר֖וֹשׁ יִֽקַּֽח־לֵֽב׃","zĕn֛ẇţ wĕ⁠ya֥yin wĕ⁠ţiyr֖wòş̌ yiֽqȧֽẖ-léֽb׃"],[4,12,"עַמִּ⁠י֙ בְּ⁠עֵצ֣⁠וֹ יִשְׁאָ֔ל וּ⁠מַקְל֖⁠וֹ יַגִּ֣יד ל֑⁠וֹ כִּ֣י ר֤וּחַ זְנוּנִים֙ הִתְעָ֔ה וַ⁠יִּזְנ֖וּ מִ⁠תַּ֥חַת אֱלֹהֵי⁠הֶֽם׃","ʻami̇⁠y֙ bĕ̇⁠ʻéẕ֣⁠wò yişĕ̌ʼá֔l ẇ⁠maqĕl֖⁠wò yagi֣̇yd l֑⁠wò ki֣̇y r֤ẇẖa zĕnẇniym֙ hiţĕʻá֔h wa⁠yi̇zĕn֖ẇ mi⁠ţȧ֥ẖaţ ʼèlòhéy⁠heֽm׃"],[4,13,"עַל־רָאשֵׁ֨י הֶ⁠הָרִ֜ים יְזַבֵּ֗חוּ וְ⁠עַל־הַ⁠גְּבָעוֹת֙ יְקַטֵּ֔רוּ תַּ֣חַת אַלּ֧וֹן וְ⁠לִבְנֶ֛ה וְ⁠אֵלָ֖ה כִּ֣י ט֣וֹב צִלָּ֑⁠הּ עַל־כֵּ֗ן תִּזְנֶ֨ינָה֙ בְּנ֣וֹתֵי⁠כֶ֔ם וְ⁠כַלּוֹתֵי⁠כֶ֖ם תְּנָאַֽפְנָה׃","ʻal-ráʼşé̌֨y he⁠hári֜ym yĕzabé̇֗ẖẇ wĕ⁠ʻal-ha⁠gĕ̇báʻwòţ֙ yĕqaté̇֔rẇ ţȧ֣ẖaţ ʼal֧̇wòn wĕ⁠libĕne֛h wĕ⁠ʼélá֖h ki֣̇y t֣wòb ẕilá֑̇⁠ḣ ʻal-ké̇֗n ţi̇zĕne֨ynáh֙ bĕ̇n֣wòţéy⁠ke֔m wĕ⁠kal̇wòţéy⁠ke֖m ţĕ̇náʼaֽpĕnáh׃"],[4,14,"לֹֽא־אֶפְק֨וֹד עַל־בְּנוֹתֵי⁠כֶ֜ם כִּ֣י תִזְנֶ֗ינָה וְ⁠עַל־כַּלּֽוֹתֵי⁠כֶם֙ כִּ֣י תְנָאַ֔פְנָה כִּי־הֵם֙ עִם־הַ⁠זֹּנ֣וֹת יְפָרֵ֔דוּ וְ⁠עִם־הַ⁠קְּדֵשׁ֖וֹת יְזַבֵּ֑חוּ וְ⁠עָ֥ם לֹֽא־יָבִ֖ין יִלָּבֵֽט׃","lòֽʼ-ʼepĕq֨wòd ʻal-bĕ̇nwòţéy⁠ke֜m ki֣̇y ţizĕne֗ynáh wĕ⁠ʻal-kȧlֽ̇wòţéy⁠kem֙ ki֣̇y ţĕnáʼa֔pĕnáh ki̇y-hém֙ ʻim-ha⁠zò̇n֣wòţ yĕpáré֔dẇ wĕ⁠ʻim-ha⁠qĕ̇déş֖̌wòţ yĕzabé֑̇ẖẇ wĕ⁠ʻá֥m lòֽʼ-yábi֖yn yilá̇béֽt׃"],[4,15,"אִם־זֹנֶ֤ה אַתָּה֙ יִשְׂרָאֵ֔ל אַל־יֶאְשַׁ֖ם יְהוּדָ֑ה וְ⁠אַל־תָּבֹ֣אוּ הַ⁠גִּלְגָּ֗ל וְ⁠אַֽל־תַּעֲלוּ֙ בֵּ֣ית אָ֔וֶן וְ⁠אַל־תִּשָּׁבְע֖וּ חַי־יְהוָֽה׃","ʼim-zòne֤h ʼaţá̇h֙ yişĕ̂ráʼé֔l ʼal-yeʼĕşǎ֖m yĕhẇdá֑h wĕ⁠ʼal-ţá̇bò֣ʼẇ ha⁠gi̇lĕgá̇֗l wĕ⁠ʼaֽl-ţȧʻàlẇ֙ bé֣̇yţ ʼá֔wen wĕ⁠ʼal-ţi̇şá̇̌bĕʻ֖ẇ ẖay-yĕhwáֽh׃"],[4,16,"כִּ֚י כְּ⁠פָרָ֣ה סֹֽרֵרָ֔ה סָרַ֖ר יִשְׂרָאֵ֑ל עַתָּה֙ יִרְעֵ֣⁠ם יְהוָ֔ה כְּ⁠כֶ֖בֶשׂ בַּ⁠מֶּרְחָֽב׃","ki֚̇y kĕ̇⁠párá֣h sòֽrérá֔h sára֖r yişĕ̂ráʼé֑l ʻaţá̇h֙ yirĕʻé֣⁠m yĕhwá֔h kĕ̇⁠ke֖beş̂ bȧ⁠mėrĕẖáֽb׃"],[4,17,"חֲב֧וּר עֲצַבִּ֛ים אֶפְרָ֖יִם הַֽנַּֽח־לֽ⁠וֹ׃","ẖàb֧ẇr ʻàẕabi֛̇ym ʼepĕrá֖yim haֽnȧֽẖ-lֽ⁠wò׃"],[4,18,"סָ֖ר סָבְאָ֑⁠ם הַזְנֵ֣ה הִזְנ֔וּ אָהֲב֥וּ הֵב֛וּ קָל֖וֹן מָגִנֶּֽי⁠הָ׃","sá֖r sábĕʼá֑⁠m hazĕné֣h hizĕn֔ẇ ʼáhàb֥ẇ héb֛ẇ qál֖wòn máginėֽy⁠há׃"],[4,19,"צָרַ֥ר ר֛וּחַ אוֹתָ֖⁠הּ בִּ⁠כְנָפֶ֑י⁠הָ וְ⁠יֵבֹ֖שׁוּ מִ⁠זִּבְחוֹתָֽ⁠ם ס","ẕára֥r r֛ẇẖa ʼwòţá֖⁠ḣ bi̇⁠kĕnápe֑y⁠há wĕ⁠yébò֖ş̌ẇ mi⁠zi̇bĕẖwòţáֽ⁠m s"],[5,1,"שִׁמְעוּ־זֹ֨את הַ⁠כֹּהֲנִ֜ים וְ⁠הַקְשִׁ֣יבוּ ׀ בֵּ֣ית יִשְׂרָאֵ֗ל וּ⁠בֵ֤ית הַ⁠מֶּ֨לֶךְ֙ הַאֲזִ֔ינוּ כִּ֥י לָ⁠כֶ֖ם הַ⁠מִּשְׁפָּ֑ט כִּֽי־פַח֙ הֱיִיתֶ֣ם לְ⁠מִצְפָּ֔ה וְ⁠רֶ֖שֶׁת פְּרוּשָׂ֥ה עַל־תָּבֽוֹר׃","şǐmĕʻẇ-zò֨ʼţ ha⁠kò̇hàni֜ym wĕ⁠haqĕşǐ֣ybẇ ׀ bé֣̇yţ yişĕ̂ráʼé֗l ẇ⁠bé֤yţ ha⁠mė֨lekĕ֙ haʼàzi֔ynẇ ki֥̇y lá⁠ke֖m ha⁠mi̇şĕ̌pá֑̇t kiֽ̇y-paẖ֙ hèyiyţe֣m lĕ⁠miẕĕpá̇֔h wĕ⁠re֖şěţ pĕ̇rẇşá֥̂h ʻal-ţá̇bֽwòr׃"],[5,2,"וְ⁠שַׁחֲטָ֥ה שֵׂטִ֖ים הֶעְמִ֑יקוּ וַ⁠אֲנִ֖י מוּסָ֥ר לְ⁠כֻלָּֽ⁠ם׃","wĕ⁠şǎẖàtá֥h şé̂ti֖ym heʻĕmi֑yqẇ wa⁠ʼàni֖y mẇsá֥r lĕ⁠kuláֽ̇⁠m׃"],[5,3,"אֲנִי֙ יָדַ֣עְתִּי אֶפְרַ֔יִם וְ⁠יִשְׂרָאֵ֖ל לֹֽא־נִכְחַ֣ד מִמֶּ֑⁠נִּי כִּ֤י עַתָּה֙ הִזְנֵ֣יתָ אֶפְרַ֔יִם נִטְמָ֖א יִשְׂרָאֵֽל׃","ʼàniy֙ yáda֣ʻĕţi̇y ʼepĕra֔yim wĕ⁠yişĕ̂ráʼé֖l lòֽʼ-nikĕẖa֣d mimė֑⁠ni̇y ki֤̇y ʻaţá̇h֙ hizĕné֣yţá ʼepĕra֔yim nitĕmá֖ʼ yişĕ̂ráʼéֽl׃"],[5,4,"לֹ֤א יִתְּנוּ֙ מַ֣עַלְלֵי⁠הֶ֔ם לָ⁠שׁ֖וּב אֶל־אֱלֹֽהֵי⁠הֶ֑ם כִּ֣י ר֤וּחַ זְנוּנִים֙ בְּ⁠קִרְבָּ֔⁠ם וְ⁠אֶת־יְהוָ֖ה לֹ֥א יָדָֽעוּ׃","lò֤ʼ yiţĕ̇nẇ֙ ma֣ʻalĕléy⁠he֔m lá⁠ş֖̌ẇb ʼel-ʼèlòֽhéy⁠he֑m ki֣̇y r֤ẇẖa zĕnẇniym֙ bĕ̇⁠qirĕbá̇֔⁠m wĕ⁠ʼeţ-yĕhwá֖h lò֥ʼ yádáֽʻẇ׃"],[5,5,"וְ⁠עָנָ֥ה גְאֽוֹן־יִשְׂרָאֵ֖ל בְּ⁠פָנָ֑י⁠ו וְ⁠יִשְׂרָאֵ֣ל וְ⁠אֶפְרַ֗יִם יִכָּֽשְׁלוּ֙ בַּ⁠עֲוֺנָ֔⁠ם כָּשַׁ֥ל גַּם־יְהוּדָ֖ה עִמָּֽ⁠ם׃","wĕ⁠ʻáná֥h gĕʼֽwòn-yişĕ̂ráʼé֖l bĕ̇⁠páná֑y⁠w wĕ⁠yişĕ̂ráʼé֣l wĕ⁠ʼepĕra֗yim yikáֽ̇şĕ̌lẇ֙ bȧ⁠ʻàwֺná֔⁠m ká̇şǎ֥l gȧm-yĕhẇdá֖h ʻimáֽ̇⁠m׃"],[5,6,"בְּ⁠צֹאנָ֣⁠ם וּ⁠בִ⁠בְקָרָ֗⁠ם יֵֽלְכ֛וּ לְ⁠בַקֵּ֥שׁ אֶת־יְהוָ֖ה וְ⁠לֹ֣א יִמְצָ֑אוּ חָלַ֖ץ מֵ⁠הֶֽם׃","bĕ̇⁠ẕòʼná֣⁠m ẇ⁠bi⁠bĕqárá֗⁠m yéֽlĕk֛ẇ lĕ⁠baqé֥̇ş̌ ʼeţ-yĕhwá֖h wĕ⁠lò֣ʼ yimĕẕá֑ʼẇ ẖála֖ẕ mé⁠heֽm׃"],[5,7,"בַּ⁠יהוָ֣ה בָּגָ֔דוּ כִּֽי־בָנִ֥ים זָרִ֖ים יָלָ֑דוּ עַתָּ֛ה יֹאכְלֵ֥⁠ם חֹ֖דֶשׁ אֶת־חֶלְקֵי⁠הֶֽם׃ס","bȧ⁠yhwá֣h bá̇gá֔dẇ kiֽ̇y-báni֥ym zári֖ym yálá֑dẇ ʻaţá֛̇h yòʼkĕlé֥⁠m ẖò֖deş̌ ʼeţ-ẖelĕqéy⁠heֽm׃s"],[5,8,"תִּקְע֤וּ שׁוֹפָר֙ בַּ⁠גִּבְעָ֔ה חֲצֹצְרָ֖ה בָּ⁠רָמָ֑ה הָרִ֨יעוּ֙ בֵּ֣ית אָ֔וֶן אַחֲרֶ֖י⁠ךָ בִּנְיָמִֽין׃","ţi̇qĕʻ֤ẇ ş̌wòpár֙ bȧ⁠gi̇bĕʻá֔h ẖàẕòẕĕrá֖h bá̇⁠rámá֑h hári֨yʻẇ֙ bé֣̇yţ ʼá֔wen ʼaẖàre֖y⁠ká bi̇nĕyámiֽyn׃"],[5,9,"אֶפְרַ֨יִם֙ לְ⁠שַׁמָּ֣ה תִֽהְיֶ֔ה בְּ⁠י֖וֹם תּֽוֹכֵחָ֑ה בְּ⁠שִׁבְטֵי֙ יִשְׂרָאֵ֔ל הוֹדַ֖עְתִּי נֶאֱמָנָֽה׃","ʼepĕra֨yim֙ lĕ⁠şǎmá֣̇h ţiֽhĕye֔h bĕ̇⁠y֖wòm ţֽ̇wòkéẖá֑h bĕ̇⁠şǐbĕtéy֙ yişĕ̂ráʼé֔l hwòda֖ʻĕţi̇y neʼèmánáֽh׃"],[5,10,"הָיוּ֙ שָׂרֵ֣י יְהוּדָ֔ה כְּ⁠מַסִּיגֵ֖י גְּב֑וּל עֲלֵי⁠הֶ֕ם אֶשְׁפּ֥וֹךְ כַּ⁠מַּ֖יִם עֶבְרָתִֽ⁠י׃","háyẇ֙ şá̂ré֣y yĕhẇdá֔h kĕ̇⁠masi̇ygé֖y gĕ̇b֑ẇl ʻàléy⁠he֕m ʼeşĕ̌ṗ֥wòkĕ kȧ⁠mȧ֖yim ʻebĕráţiֽ⁠y׃"],[5,11,"עָשׁ֥וּק אֶפְרַ֖יִם רְצ֣וּץ מִשְׁפָּ֑ט כִּ֣י הוֹאִ֔יל הָלַ֖ךְ אַחֲרֵי־צָֽו׃","ʻáş֥̌ẇq ʼepĕra֖yim rĕẕ֣ẇẕ mişĕ̌pá֑̇t ki֣̇y hwòʼi֔yl hála֖kĕ ʼaẖàréy-ẕáֽw׃"],[5,12,"וַ⁠אֲנִ֥י כָ⁠עָ֖שׁ לְ⁠אֶפְרָ֑יִם וְ⁠כָ⁠רָקָ֖ב לְ⁠בֵ֥ית יְהוּדָֽה׃","wa⁠ʼàni֥y ká⁠ʻá֖ş̌ lĕ⁠ʼepĕrá֑yim wĕ⁠ká⁠ráqá֖b lĕ⁠bé֥yţ yĕhẇdáֽh׃"],[5,13,"וַ⁠יַּ֨רְא אֶפְרַ֜יִם אֶת־חָלְי֗⁠וֹ וִֽ⁠יהוּדָה֙ אֶת־מְזֹר֔⁠וֹ וַ⁠יֵּ֤לֶךְ אֶפְרַ֨יִם֙ אֶל־אַשּׁ֔וּר וַ⁠יִּשְׁלַ֖ח אֶל־מֶ֣לֶךְ יָרֵ֑ב וְ⁠ה֗וּא לֹ֤א יוּכַל֙ לִ⁠רְפֹּ֣א לָ⁠כֶ֔ם וְ⁠לֹֽא־יִגְהֶ֥ה מִ⁠כֶּ֖ם מָזֽוֹר׃","wa⁠yȧ֨rĕʼ ʼepĕra֜yim ʼeţ-ẖálĕy֗⁠wò wiֽ⁠yhẇdáh֙ ʼeţ-mĕzòr֔⁠wò wa⁠yé֤̇lekĕ ʼepĕra֨yim֙ ʼel-ʼaş̇̌֔ẇr wa⁠yi̇şĕ̌la֖ẖ ʼel-me֣lekĕ yáré֑b wĕ⁠h֗ẇʼ lò֤ʼ yẇkal֙ li⁠rĕpò֣̇ʼ lá⁠ke֔m wĕ⁠lòֽʼ-yigĕhe֥h mi⁠kė֖m mázֽwòr׃"],[5,14,"כִּ֣י אָנֹכִ֤י כַ⁠שַּׁ֨חַל֙ לְ⁠אֶפְרַ֔יִם וְ⁠כַ⁠כְּפִ֖יר לְ⁠בֵ֣ית יְהוּדָ֑ה אֲנִ֨י אֲנִ֤י אֶטְרֹף֙ וְ⁠אֵלֵ֔ךְ אֶשָּׂ֖א וְ⁠אֵ֥ין מַצִּֽיל׃","ki֣̇y ʼánòki֤y ka⁠şȧ̌֨ẖal֙ lĕ⁠ʼepĕra֔yim wĕ⁠ka⁠kĕ̇pi֖yr lĕ⁠bé֣yţ yĕhẇdá֑h ʼàni֨y ʼàni֤y ʼetĕròp֙ wĕ⁠ʼélé֔kĕ ʼeşá֖̇̂ʼ wĕ⁠ʼé֥yn maẕiֽ̇yl׃"],[5,15,"אֵלֵ֤ךְ אָשׁ֨וּבָה֙ אֶל־מְקוֹמִ֔⁠י עַ֥ד אֲשֶֽׁר־יֶאְשְׁמ֖וּ וּ⁠בִקְשׁ֣וּ פָנָ֑⁠י בַּ⁠צַּ֥ר לָ⁠הֶ֖ם יְשַׁחֲרֻֽ⁠נְנִי׃","ʼélé֤kĕ ʼáş̌֨ẇbáh֙ ʼel-mĕqwòmi֔⁠y ʻa֥d ʼàşěֽr-yeʼĕşĕ̌m֖ẇ ẇ⁠biqĕş֣̌ẇ páná֑⁠y bȧ⁠ẕȧ֥r lá⁠he֖m yĕşǎẖàruֽ⁠nĕniy׃"],[6,1,"לְכוּ֙ וְ⁠נָשׁ֣וּבָה אֶל־יְהוָ֔ה כִּ֛י ה֥וּא טָרָ֖ף וְ⁠יִרְפָּאֵ֑⁠נוּ יַ֖ךְ וְ⁠יַחְבְּשֵֽׁ⁠נוּ׃","lĕkẇ֙ wĕ⁠náş֣̌ẇbáh ʼel-yĕhwá֔h ki֛̇y h֥ẇʼ tárá֖p wĕ⁠yirĕpá̇ʼé֑⁠nẇ ya֖kĕ wĕ⁠yaẖĕbĕ̇şéֽ̌⁠nẇ׃"],[6,2,"יְחַיֵּ֖⁠נוּ מִ⁠יֹּמָ֑יִם בַּ⁠יּוֹם֙ הַ⁠שְּׁלִישִׁ֔י יְקִמֵ֖⁠נוּ וְ⁠נִחְיֶ֥ה לְ⁠פָנָֽי⁠ו׃","yĕẖayé֖̇⁠nẇ mi⁠yò̇má֑yim bȧ⁠ẏwòm֙ ha⁠şĕ̇̌liyşǐ֔y yĕqimé֖⁠nẇ wĕ⁠niẖĕye֥h lĕ⁠pánáֽy⁠w׃"],[6,3,"וְ⁠נֵדְעָ֣ה נִרְדְּפָ֗ה לָ⁠דַ֨עַת֙ אֶת־יְהוָ֔ה כְּ⁠שַׁ֖חַר נָכ֣וֹן מֽוֹצָא֑⁠וֹ וְ⁠יָב֤וֹא כַ⁠גֶּ֨שֶׁם֙ לָ֔⁠נוּ כְּ⁠מַלְק֖וֹשׁ י֥וֹרֶה אָֽרֶץ׃","wĕ⁠nédĕʻá֣h nirĕdĕ̇pá֗h lá⁠da֨ʻaţ֙ ʼeţ-yĕhwá֔h kĕ̇⁠şǎ֖ẖar nák֣wòn mֽwòẕáʼ֑⁠wò wĕ⁠yáb֤wòʼ ka⁠gė֨şěm֙ lá֔⁠nẇ kĕ̇⁠malĕq֖wòş̌ y֥wòreh ʼáֽreẕ׃"],[6,4,"מָ֤ה אֶֽעֱשֶׂה־לְּ⁠ךָ֙ אֶפְרַ֔יִם מָ֥ה אֶעֱשֶׂה־לְּ⁠ךָ֖ יְהוּדָ֑ה וְ⁠חַסְדְּ⁠כֶם֙ כַּֽ⁠עֲנַן־בֹּ֔קֶר וְ⁠כַ⁠טַּ֖ל מַשְׁכִּ֥ים הֹלֵֽךְ׃","má֤h ʼeֽʻèşêh-lĕ̇⁠ká֙ ʼepĕra֔yim má֥h ʼeʻèşêh-lĕ̇⁠ká֖ yĕhẇdá֑h wĕ⁠ẖasĕdĕ̇⁠kem֙ kȧֽ⁠ʻànan-bò̇֔qer wĕ⁠ka⁠tȧ֖l maşĕ̌ki֥̇ym hòléֽkĕ׃"],[6,5,"עַל־כֵּ֗ן חָצַ֨בְתִּי֙ בַּ⁠נְּבִיאִ֔ים הֲרַגְתִּ֖י⁠ם בְּ⁠אִמְרֵי־פִ֑⁠י וּ⁠מִשְׁפָּטֶ֖י⁠ךָ א֥וֹר יֵצֵֽא׃","ʻal-ké̇֗n ẖáẕa֨bĕţi̇y֙ bȧ⁠nĕ̇biyʼi֔ym hàragĕţi֖̇y⁠m bĕ̇⁠ʼimĕréy-pi֑⁠y ẇ⁠mişĕ̌pá̇te֖y⁠ká ʼ֥wòr yéẕéֽʼ׃"],[6,6,"כִּ֛י חֶ֥סֶד חָפַ֖צְתִּי וְ⁠לֹא־זָ֑בַח וְ⁠דַ֥עַת אֱלֹהִ֖ים מֵ⁠עֹלֽוֹת׃","ki֛̇y ẖe֥sed ẖápa֖ẕĕţi̇y wĕ⁠lòʼ-zá֑baẖ wĕ⁠da֥ʻaţ ʼèlòhi֖ym mé⁠ʻòlֽwòţ׃"],[6,7,"וְ⁠הֵ֕מָּה כְּ⁠אָדָ֖ם עָבְר֣וּ בְרִ֑ית שָׁ֖ם בָּ֥גְדוּ בִֽ⁠י׃","wĕ⁠hé֕má̇h kĕ̇⁠ʼádá֖m ʻábĕr֣ẇ bĕri֑yţ şá֖̌m bá֥̇gĕdẇ biֽ⁠y׃"],[6,8,"גִּלְעָ֕ד קִרְיַ֖ת פֹּ֣עֲלֵי אָ֑וֶן עֲקֻבָּ֖ה מִ⁠דָּֽם׃","gi̇lĕʻá֕d qirĕya֖ţ pò֣̇ʻàléy ʼá֑wen ʻàqubá֖̇h mi⁠dáֽ̇m׃"],[6,9,"וּ⁠כְ⁠חַכֵּ֨י אִ֜ישׁ גְּדוּדִ֗ים חֶ֚בֶר כֹּֽהֲנִ֔ים דֶּ֖רֶךְ יְרַצְּחוּ־שֶׁ֑כְמָ⁠ה כִּ֥י זִמָּ֖ה עָשֽׂוּ׃","ẇ⁠kĕ⁠ẖaké̇֨y ʼi֜yş̌ gĕ̇dẇdi֗ym ẖe֚ber kòֽ̇hàni֔ym dė֖rekĕ yĕraẕĕ̇ẖẇ-şě֑kĕmá⁠h ki֥̇y zimá֖̇h ʻáşֽ̂ẇ׃"],[6,10,"בְּ⁠בֵית֙ יִשְׂרָאֵ֔ל רָאִ֖יתִי שעריריה שָׁ֚ם זְנ֣וּת לְ⁠אֶפְרַ֔יִם נִטְמָ֖א יִשְׂרָאֵֽל׃","bĕ̇⁠béyţ֙ yişĕ̂ráʼé֔l ráʼi֖yţiy şʻryryh şá֚̌m zĕn֣ẇţ lĕ⁠ʼepĕra֔yim nitĕmá֖ʼ yişĕ̂ráʼéֽl׃"],[6,11,"גַּם־יְהוּדָ֕ה שָׁ֥ת קָצִ֖יר לָ֑⁠ךְ בְּ⁠שׁוּבִ֖⁠י שְׁב֥וּת עַמִּֽ⁠י׃פ","gȧm-yĕhẇdá֕h şá֥̌ţ qáẕi֖yr lá֑⁠kĕ bĕ̇⁠ş̌ẇbi֖⁠y şĕ̌b֥ẇţ ʻamiֽ̇⁠y׃p"],[7,1,"כְּ⁠רָפְאִ֣⁠י לְ⁠יִשְׂרָאֵ֗ל וְ⁠נִגְלָ֞ה עֲוֺ֤ן אֶפְרַ֨יִם֙ וְ⁠רָע֣וֹת שֹֽׁמְר֔וֹן כִּ֥י פָעֲל֖וּ שָׁ֑קֶר וְ⁠גַנָּ֣ב יָב֔וֹא פָּשַׁ֥ט גְּד֖וּד בַּ⁠חֽוּץ׃","kĕ̇⁠rápĕʼi֣⁠y lĕ⁠yişĕ̂ráʼé֗l wĕ⁠nigĕlá֞h ʻàwֺ֤n ʼepĕra֨yim֙ wĕ⁠ráʻ֣wòţ şòֽ̌mĕr֔wòn ki֥̇y páʻàl֖ẇ şá֑̌qer wĕ⁠ganá֣̇b yáb֔wòʼ pá̇şǎ֥t gĕ̇d֖ẇd bȧ⁠ẖֽẇẕ׃"],[7,2,"וּ⁠בַל־יֹֽאמְרוּ֙ לִ⁠לְבָבָ֔⁠ם כָּל־רָעָתָ֖⁠ם זָכָ֑רְתִּי עַתָּה֙ סְבָב֣וּ⁠ם מַֽעַלְלֵי⁠הֶ֔ם נֶ֥גֶד פָּנַ֖⁠י הָיֽוּ׃","ẇ⁠bal-yòֽʼmĕrẇ֙ li⁠lĕbábá֔⁠m ká̇l-ráʻáţá֖⁠m záká֑rĕţi̇y ʻaţá̇h֙ sĕbáb֣ẇ⁠m maֽʻalĕléy⁠he֔m ne֥ged pá̇na֖⁠y háyֽẇ׃"],[7,3,"בְּ⁠רָעָתָ֖⁠ם יְשַׂמְּחוּ־מֶ֑לֶךְ וּ⁠בְ⁠כַחֲשֵׁי⁠הֶ֖ם שָׂרִֽים׃","bĕ̇⁠ráʻáţá֖⁠m yĕşâmĕ̇ẖẇ-me֑lekĕ ẇ⁠bĕ⁠kaẖàşé̌y⁠he֖m şá̂riֽym׃"],[7,4,"כֻּלָּ⁠ם֙ מְנָ֣אֲפִ֔ים כְּמ֣וֹ תַנּ֔וּר בֹּעֵ֖רָה מֵֽ⁠אֹפֶ֑ה יִשְׁבּ֣וֹת מֵעִ֔יר מִ⁠לּ֥וּשׁ בָּצֵ֖ק עַד־חֻמְצָתֽ⁠וֹ׃","ku̇lá̇⁠m֙ mĕná֣ʼàpi֔ym kĕ̇m֣wò ţaṅ֔ẇr bò̇ʻé֖ráh méֽ⁠ʼòpe֑h yişĕ̌ḃ֣wòţ méʻi֔yr mi⁠l֥̇ẇş̌ bá̇ẕé֖q ʻad-ẖumĕẕáţֽ⁠wò׃"],[7,5,"י֣וֹם מַלְכֵּ֔⁠נוּ הֶחֱל֥וּ שָׂרִ֖ים חֲמַ֣ת מִ⁠יָּ֑יִן מָשַׁ֥ךְ יָד֖⁠וֹ אֶת־לֹצְצִֽים׃","y֣wòm malĕké̇֔⁠nẇ heẖèl֥ẇ şá̂ri֖ym ẖàma֣ţ mi⁠yá֑̇yin máşǎ֥kĕ yád֖⁠wò ʼeţ-lòẕĕẕiֽym׃"],[7,6,"כִּֽי־קֵרְב֧וּ כַ⁠תַּנּ֛וּר לִבָּ֖⁠ם בְּ⁠אָרְבָּ֑⁠ם כָּל־הַ⁠לַּ֨יְלָה֙ יָשֵׁ֣ן אֹֽפֵ⁠הֶ֔ם בֹּ֕קֶר ה֥וּא בֹעֵ֖ר כְּ⁠אֵ֥שׁ לֶהָבָֽה׃","kiֽ̇y-qérĕb֧ẇ ka⁠ţȧṅ֛ẇr libá֖̇⁠m bĕ̇⁠ʼárĕbá֑̇⁠m ká̇l-ha⁠lȧ֨yĕláh֙ yáşé֣̌n ʼòֽpé⁠he֔m bò̇֕qer h֥ẇʼ bòʻé֖r kĕ̇⁠ʼé֥ş̌ lehábáֽh׃"],[7,7,"כֻּלָּ֤⁠ם יֵחַ֨מּוּ֙ כַּ⁠תַּנּ֔וּר וְ⁠אָכְל֖וּ אֶת־שֹֽׁפְטֵי⁠הֶ֑ם כָּל־מַלְכֵי⁠הֶ֣ם נָפָ֔לוּ אֵין־קֹרֵ֥א בָ⁠הֶ֖ם אֵלָֽ⁠י׃","ku̇lá֤̇⁠m yéẖa֨ṁẇ֙ kȧ⁠ţȧṅ֔ẇr wĕ⁠ʼákĕl֖ẇ ʼeţ-şòֽ̌pĕtéy⁠he֑m ká̇l-malĕkéy⁠he֣m nápá֔lẇ ʼéyn-qòré֥ʼ bá⁠he֖m ʼéláֽ⁠y׃"],[7,8,"אֶפְרַ֕יִם בָּ⁠עַמִּ֖ים ה֣וּא יִתְבּוֹלָ֑ל אֶפְרַ֛יִם הָיָ֥ה עֻגָ֖ה בְּלִ֥י הֲפוּכָֽה׃","ʼepĕra֕yim bá̇⁠ʻami֖̇ym h֣ẇʼ yiţĕḃwòlá֑l ʼepĕra֛yim háyá֥h ʻugá֖h bĕ̇li֥y hàpẇkáֽh׃"],[7,9,"אָכְל֤וּ זָרִים֙ כֹּח֔⁠וֹ וְ⁠ה֖וּא לֹ֣א יָדָ֑ע גַּם־שֵׂיבָה֙ זָ֣רְקָה בּ֔⁠וֹ וְ⁠ה֖וּא לֹ֥א יָדָֽע׃","ʼákĕl֤ẇ záriym֙ kò̇ẖ֔⁠wò wĕ⁠h֖ẇʼ lò֣ʼ yádá֑ʻ gȧm-şé̂ybáh֙ zá֣rĕqáh ḃ֔⁠wò wĕ⁠h֖ẇʼ lò֥ʼ yádáֽʻ׃"],[7,10,"וְ⁠עָנָ֥ה גְאֽוֹן־יִשְׂרָאֵ֖ל בְּ⁠פָנָ֑י⁠ו וְ⁠לֹֽא־שָׁ֨בוּ֙ אֶל־יְהוָ֣ה אֱלֹֽהֵי⁠הֶ֔ם וְ⁠לֹ֥א בִקְשֻׁ֖⁠הוּ בְּ⁠כָל־זֹֽאת׃","wĕ⁠ʻáná֥h gĕʼֽwòn-yişĕ̂ráʼé֖l bĕ̇⁠páná֑y⁠w wĕ⁠lòֽʼ-şá̌֨bẇ֙ ʼel-yĕhwá֣h ʼèlòֽhéy⁠he֔m wĕ⁠lò֥ʼ biqĕşǔ֖⁠hẇ bĕ̇⁠kál-zòֽʼţ׃"],[7,11,"וַ⁠יְהִ֣י אֶפְרַ֔יִם כְּ⁠יוֹנָ֥ה פוֹתָ֖ה אֵ֣ין לֵ֑ב מִצְרַ֥יִם קָרָ֖אוּ אַשּׁ֥וּר הָלָֽכוּ׃","wa⁠yĕhi֣y ʼepĕra֔yim kĕ̇⁠ywòná֥h pwòţá֖h ʼé֣yn lé֑b miẕĕra֥yim qárá֖ʼẇ ʼaş֥̇̌ẇr háláֽkẇ׃"],[7,12,"כַּ⁠אֲשֶׁ֣ר יֵלֵ֗כוּ אֶפְר֤וֹשׂ עֲלֵי⁠הֶם֙ רִשְׁתִּ֔⁠י כְּ⁠ע֥וֹף הַ⁠שָּׁמַ֖יִם אֽוֹרִידֵ֑⁠ם אַיְסִרֵ֕⁠ם כְּ⁠שֵׁ֖מַע לַ⁠עֲדָתָֽ⁠ם׃ס","kȧ⁠ʼàşě֣r yélé֗kẇ ʼepĕr֤wòş̂ ʻàléy⁠hem֙ rişĕ̌ţi̇֔⁠y kĕ̇⁠ʻ֥wòp ha⁠şá̇̌ma֖yim ʼֽwòriydé֑⁠m ʼayĕsiré֕⁠m kĕ̇⁠şé֖̌maʻ la⁠ʻàdáţáֽ⁠m׃s"],[7,13,"א֤וֹי לָ⁠הֶם֙ כִּֽי־נָדְד֣וּ מִמֶּ֔⁠נִּי שֹׁ֥ד לָ⁠הֶ֖ם כִּֽי־פָ֣שְׁעוּ בִ֑⁠י וְ⁠אָנֹכִ֣י אֶפְדֵּ֔⁠ם וְ⁠הֵ֕מָּה דִּבְּר֥וּ עָלַ֖⁠י כְּזָבִֽים׃","ʼ֤wòy lá⁠hem֙ kiֽ̇y-nádĕd֣ẇ mimė֔⁠ni̇y şò֥̌d lá⁠he֖m kiֽ̇y-pá֣şĕ̌ʻẇ bi֑⁠y wĕ⁠ʼánòki֣y ʼepĕdé̇֔⁠m wĕ⁠hé֕má̇h di̇bĕ̇r֥ẇ ʻála֖⁠y kĕ̇zábiֽym׃"],[7,14,"וְ⁠לֹֽא־זָעֲק֤וּ אֵלַ⁠י֙ בְּ⁠לִבָּ֔⁠ם כִּ֥י יְיֵלִ֖ילוּ עַל־מִשְׁכְּבוֹתָ֑⁠ם עַל־דָּגָ֧ן וְ⁠תִיר֛וֹשׁ יִתְגּוֹרָ֖רוּ יָס֥וּרוּ בִֽ⁠י׃","wĕ⁠lòֽʼ-záʻàq֤ẇ ʼéla⁠y֙ bĕ̇⁠libá̇֔⁠m ki֥̇y yĕyéli֖ylẇ ʻal-mişĕ̌kĕ̇bwòţá֑⁠m ʻal-dá̇gá֧n wĕ⁠ţiyr֛wòş̌ yiţĕġwòrá֖rẇ yás֥ẇrẇ biֽ⁠y׃"],[7,15,"וַ⁠אֲנִ֣י יִסַּ֔רְתִּי חִזַּ֖קְתִּי זְרֽוֹעֹתָ֑⁠ם וְ⁠אֵלַ֖⁠י יְחַשְּׁבוּ־רָֽע׃","wa⁠ʼàni֣y yisȧ֔rĕţi̇y ẖizȧ֖qĕţi̇y zĕrֽwòʻòţá֑⁠m wĕ⁠ʼéla֖⁠y yĕẖaşĕ̇̌bẇ-ráֽʻ׃"],[7,16,"יָשׁ֣וּבוּ ׀ לֹ֣א עָ֗ל הָיוּ֙ כְּ⁠קֶ֣שֶׁת רְמִיָּ֔ה יִפְּל֥וּ בַ⁠חֶ֛רֶב שָׂרֵי⁠הֶ֖ם מִ⁠זַּ֣עַם לְשׁוֹנָ֑⁠ם ז֥וֹ לַעְגָּ֖⁠ם בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","yáş֣̌ẇbẇ ׀ lò֣ʼ ʻá֗l háyẇ֙ kĕ̇⁠qe֣şěţ rĕmiyá̇֔h yipĕ̇l֥ẇ ba⁠ẖe֛reb şá̂réy⁠he֖m mi⁠zȧ֣ʻam lĕş̌wòná֑⁠m z֥wò laʻĕgá֖̇⁠m bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[8,1,"אֶל־חִכְּ⁠ךָ֣ שֹׁפָ֔ר כַּ⁠נֶּ֖שֶׁר עַל־בֵּ֣ית יְהוָ֑ה יַ֚עַן עָבְר֣וּ בְרִיתִ֔⁠י וְ⁠עַל־תּוֹרָתִ֖⁠י פָּשָֽׁעוּ׃","ʼel-ẖikĕ̇⁠ká֣ şò̌pá֔r kȧ⁠nė֖şěr ʻal-bé֣̇yţ yĕhwá֑h ya֚ʻan ʻábĕr֣ẇ bĕriyţi֔⁠y wĕ⁠ʻal-ţ̇wòráţi֖⁠y pá̇şáֽ̌ʻẇ׃"],[8,2,"לִ֖⁠י יִזְעָ֑קוּ אֱלֹהַ֥⁠י יְֽדַעֲנ֖וּ⁠ךָ יִשְׂרָאֵֽל׃","li֖⁠y yizĕʻá֑qẇ ʼèlòha֥⁠y yĕֽdaʻàn֖ẇ⁠ká yişĕ̂ráʼéֽl׃"],[8,3,"זָנַ֥ח יִשְׂרָאֵ֖ל ט֑וֹב אוֹיֵ֖ב יִרְדְּֽפ⁠וֹ׃","zána֥ẖ yişĕ̂ráʼé֖l t֑wòb ʼwòyé֖b yirĕdĕֽ̇p⁠wò׃"],[8,4,"הֵ֤ם הִמְלִיכוּ֙ וְ⁠לֹ֣א מִמֶּ֔⁠נִּי הֵשִׂ֖ירוּ וְ⁠לֹ֣א יָדָ֑עְתִּי כַּסְפָּ֣⁠ם וּ⁠זְהָבָ֗⁠ם עָשׂ֤וּ לָ⁠הֶם֙ עֲצַבִּ֔ים לְמַ֖עַן יִכָּרֵֽת׃","hé֤m himĕliykẇ֙ wĕ⁠lò֣ʼ mimė֔⁠ni̇y héşî֖yrẇ wĕ⁠lò֣ʼ yádá֑ʻĕţi̇y kȧsĕpá֣̇⁠m ẇ⁠zĕhábá֗⁠m ʻáş֤̂ẇ lá⁠hem֙ ʻàẕabi̇֔ym lĕma֖ʻan yiká̇réֽţ׃"],[8,5,"זָנַח֙ עֶגְלֵ֣⁠ךְ שֹֽׁמְר֔וֹן חָרָ֥ה אַפִּ֖⁠י בָּ֑⁠ם עַד־מָתַ֕י לֹ֥א יוּכְל֖וּ נִקָּיֹֽן׃","zánaẖ֙ ʻegĕlé֣⁠kĕ şòֽ̌mĕr֔wòn ẖárá֥h ʼapi֖̇⁠y bá֑̇⁠m ʻad-máţa֕y lò֥ʼ yẇkĕl֖ẇ niqá̇yòֽn׃"],[8,6,"כִּ֤י מִ⁠יִּשְׂרָאֵל֙ וְ⁠ה֔וּא חָרָ֣שׁ עָשָׂ֔⁠הוּ וְ⁠לֹ֥א אֱלֹהִ֖ים ה֑וּא כִּֽי־שְׁבָבִ֣ים יִֽהְיֶ֔ה עֵ֖גֶל שֹׁמְרֽוֹן׃","ki֤̇y mi⁠yi̇şĕ̂ráʼél֙ wĕ⁠h֔ẇʼ ẖárá֣ş̌ ʻáşá̂֔⁠hẇ wĕ⁠lò֥ʼ ʼèlòhi֖ym h֑ẇʼ kiֽ̇y-şĕ̌bábi֣ym yiֽhĕye֔h ʻé֖gel şò̌mĕrֽwòn׃"],[8,7,"כִּ֛י ר֥וּחַ יִזְרָ֖עוּ וְ⁠סוּפָ֣תָ⁠ה יִקְצֹ֑רוּ קָמָ֣ה אֵֽין־ל֗⁠וֹ צֶ֚מַח בְּלִ֣י יַֽעֲשֶׂה־קֶּ֔מַח אוּלַ֣י יַֽעֲשֶׂ֔ה זָרִ֖ים יִבְלָעֻֽ⁠הוּ׃","ki֛̇y r֥ẇẖa yizĕrá֖ʻẇ wĕ⁠sẇpá֣ţá⁠h yiqĕẕò֑rẇ qámá֣h ʼéֽyn-l֗⁠wò ẕe֚maẖ bĕ̇li֣y yaֽʻàşêh-qė֔maẖ ʼẇla֣y yaֽʻàşê֔h zári֖ym yibĕláʻuֽ⁠hẇ׃"],[8,8,"נִבְלַ֖ע יִשְׂרָאֵ֑ל עַתָּה֙ הָי֣וּ בַ⁠גּוֹיִ֔ם כִּ⁠כְלִ֖י אֵֽין־חֵ֥פֶץ בּֽ⁠וֹ׃","nibĕla֖ʻ yişĕ̂ráʼé֑l ʻaţá̇h֙ háy֣ẇ ba⁠ġwòyi֔m ki̇⁠kĕli֖y ʼéֽyn-ẖé֥peẕ ḃֽ⁠wò׃"],[8,9,"כִּֽי־הֵ֨מָּה֙ עָל֣וּ אַשּׁ֔וּר פֶּ֖רֶא בּוֹדֵ֣ד ל֑⁠וֹ אֶפְרַ֖יִם הִתְנ֥וּ אֲהָבִֽים","kiֽ̇y-hé֨má̇h֙ ʻál֣ẇ ʼaş̇̌֔ẇr pė֖reʼ ḃwòdé֣d l֑⁠wò ʼepĕra֖yim hiţĕn֥ẇ ʼàhábiֽym"],[8,10,"גַּ֛ם כִּֽי־יִתְנ֥וּ בַ⁠גּוֹיִ֖ם עַתָּ֣ה אֲקַבְּצֵ֑⁠ם וַ⁠יָּחֵ֣לּוּ מְּעָ֔ט מִ⁠מַּשָּׂ֖א מֶ֥לֶךְ שָׂרִֽים׃","gȧ֛m kiֽ̇y-yiţĕn֥ẇ ba⁠ġwòyi֖m ʻaţá֣̇h ʼàqabĕ̇ẕé֑⁠m wa⁠yá̇ẖé֣l̇ẇ mĕ̇ʻá֔t mi⁠mȧşá֖̇̂ʼ me֥lekĕ şá̂riֽym׃"],[8,11,"כִּֽי־הִרְבָּ֥ה אֶפְרַ֛יִם מִזְבְּחֹ֖ת לַ⁠חֲטֹ֑א הָיוּ־ל֥⁠וֹ מִזְבְּח֖וֹת לַ⁠חֲטֹֽא׃","kiֽ̇y-hirĕbá֥̇h ʼepĕra֛yim mizĕbĕ̇ẖò֖ţ la⁠ẖàtò֑ʼ háyẇ-l֥⁠wò mizĕbĕ̇ẖ֖wòţ la⁠ẖàtòֽʼ׃"],[8,12,"אכתוב־ל֔⁠וֹ רבו תּֽוֹרָתִ֑⁠י כְּמוֹ־זָ֖ר נֶחְשָֽׁבוּ׃","ʼkţwb-l֔⁠wò rbw ţֽ̇wòráţi֑⁠y kĕ̇mwò-zá֖r neẖĕşáֽ̌bẇ׃"],[8,13,"זִבְחֵ֣י הַבְהָבַ֗⁠י יִזְבְּח֤וּ בָשָׂר֙ וַ⁠יֹּאכֵ֔לוּ יְהוָ֖ה לֹ֣א רָצָ֑⁠ם עַתָּ֞ה יִזְכֹּ֤ר עֲוֺנָ⁠ם֙ וְ⁠יִפְקֹ֣ד חַטֹּאותָ֔⁠ם הֵ֖מָּה מִצְרַ֥יִם יָשֽׁוּבוּ׃","zibĕẖé֣y habĕhába֗⁠y yizĕbĕ̇ẖ֤ẇ báşá̂r֙ wa⁠yò̇ʼké֔lẇ yĕhwá֖h lò֣ʼ ráẕá֑⁠m ʻaţá̇֞h yizĕkò֤̇r ʻàwֺná⁠m֙ wĕ⁠yipĕqò֣d ẖatò̇ʼwţá֔⁠m hé֖má̇h miẕĕra֥yim yáşֽ̌ẇbẇ׃"],[8,14,"וַ⁠יִּשְׁכַּ֨ח יִשְׂרָאֵ֜ל אֶת־עֹשֵׂ֗⁠הוּ וַ⁠יִּ֨בֶן֙ הֵֽיכָל֔וֹת וִֽ⁠יהוּדָ֕ה הִרְבָּ֖ה עָרִ֣ים בְּצֻר֑וֹת וְ⁠שִׁלַּחְתִּי־אֵ֣שׁ בְּ⁠עָרָ֔י⁠ו וְ⁠אָכְלָ֖ה אַרְמְנֹתֶֽי⁠הָ׃ס","wa⁠yi̇şĕ̌kȧ֨ẖ yişĕ̂ráʼé֜l ʼeţ-ʻòşé̂֗⁠hẇ wa⁠yi̇֨ben֙ héֽykál֔wòţ wiֽ⁠yhẇdá֕h hirĕbá֖̇h ʻári֣ym bĕ̇ẕur֑wòţ wĕ⁠şǐlȧẖĕţi̇y-ʼé֣ş̌ bĕ̇⁠ʻárá֔y⁠w wĕ⁠ʼákĕlá֖h ʼarĕmĕnòţeֽy⁠há׃s"],[9,1,"אַל־תִּשְׂמַ֨ח יִשְׂרָאֵ֤ל ׀ אֶל־גִּיל֙ כָּֽ⁠עַמִּ֔ים כִּ֥י זָנִ֖יתָ מֵ⁠עַ֣ל אֱלֹהֶ֑י⁠ךָ אָהַ֣בְתָּ אֶתְנָ֔ן עַ֖ל כָּל־גָּרְנ֥וֹת דָּגָֽן׃","ʼal-ţi̇şĕ̂ma֨ẖ yişĕ̂ráʼé֤l ׀ ʼel-gi̇yl֙ káֽ̇⁠ʻami̇֔ym ki֥̇y záni֖yţá mé⁠ʻa֣l ʼèlòhe֑y⁠ká ʼáha֣bĕţá̇ ʼeţĕná֔n ʻa֖l ká̇l-gá̇rĕn֥wòţ dá̇gáֽn׃"],[9,2,"גֹּ֥רֶן וָ⁠יֶ֖קֶב לֹ֣א יִרְעֵ֑⁠ם וְ⁠תִיר֖וֹשׁ יְכַ֥חֶשׁ בָּֽ⁠הּ׃","gò֥̇ren wá⁠ye֖qeb lò֣ʼ yirĕʻé֑⁠m wĕ⁠ţiyr֖wòş̌ yĕka֥ẖeş̌ báֽ̇⁠ḣ׃"],[9,3,"לֹ֥א יֵשְׁב֖וּ בְּ⁠אֶ֣רֶץ יְהוָ֑ה וְ⁠שָׁ֤ב אֶפְרַ֨יִם֙ מִצְרַ֔יִם וּ⁠בְ⁠אַשּׁ֖וּר טָמֵ֥א יֹאכֵֽלוּ׃","lò֥ʼ yéşĕ̌b֖ẇ bĕ̇⁠ʼe֣reẕ yĕhwá֑h wĕ⁠şá֤̌b ʼepĕra֨yim֙ miẕĕra֔yim ẇ⁠bĕ⁠ʼaş֖̇̌ẇr támé֥ʼ yòʼkéֽlẇ׃"],[9,4,"לֹא־יִסְּכ֨וּ לַ⁠יהוָ֥ה ׀ יַיִן֮ וְ⁠לֹ֣א יֶֽעֶרְבוּ־ל⁠וֹ֒ זִבְחֵי⁠הֶ֗ם כְּ⁠לֶ֤חֶם אוֹנִים֙ לָ⁠הֶ֔ם כָּל־אֹכְלָ֖י⁠ו יִטַמָּ֑אוּ כִּֽי־לַחְמָ֣⁠ם לְ⁠נַפְשָׁ֔⁠ם לֹ֥א יָב֖וֹא בֵּ֥ית יְהוָֽה׃","lòʼ-yisĕ̇k֨ẇ la⁠yhwá֥h ׀ yayin֮ wĕ⁠lò֣ʼ yeֽʻerĕbẇ-l⁠wò֒ zibĕẖéy⁠he֗m kĕ̇⁠le֤ẖem ʼwòniym֙ lá⁠he֔m ká̇l-ʼòkĕlá֖y⁠w yitamá֑̇ʼẇ kiֽ̇y-laẖĕmá֣⁠m lĕ⁠napĕşá̌֔⁠m lò֥ʼ yáb֖wòʼ bé֥̇yţ yĕhwáֽh׃"],[9,5,"מַֽה־תַּעֲשׂ֖וּ לְ⁠י֣וֹם מוֹעֵ֑ד וּ⁠לְ⁠י֖וֹם חַג־יְהוָֽה׃","maֽh-ţȧʻàş֖̂ẇ lĕ⁠y֣wòm mwòʻé֑d ẇ⁠lĕ⁠y֖wòm ẖag-yĕhwáֽh׃"],[9,6,"כִּֽי־הִנֵּ֤ה הָֽלְכוּ֙ מִ⁠שֹּׁ֔ד מִצְרַ֥יִם תְּקַבְּצֵ֖⁠ם מֹ֣ף תְּקַבְּרֵ֑⁠ם מַחְמַ֣ד לְ⁠כַסְפָּ֗⁠ם קִמּוֹשׂ֙ יִֽירָשֵׁ֔⁠ם ח֖וֹחַ בְּ⁠אָהֳלֵי⁠הֶֽם׃","kiֽ̇y-hiné֤̇h háֽlĕkẇ֙ mi⁠şò̇̌֔d miẕĕra֥yim ţĕ̇qabĕ̇ẕé֖⁠m mò֣p ţĕ̇qabĕ̇ré֑⁠m maẖĕma֣d lĕ⁠kasĕpá̇֗⁠m qiṁwòş̂֙ yiֽyráşé̌֔⁠m ẖ֖wòẖa bĕ̇⁠ʼáholéy⁠heֽm׃"],[9,7,"בָּ֣אוּ ׀ יְמֵ֣י הַ⁠פְּקֻדָּ֗ה בָּ֚אוּ יְמֵ֣י הַ⁠שִׁלֻּ֔ם יֵדְע֖וּ יִשְׂרָאֵ֑ל אֱוִ֣יל הַ⁠נָּבִ֗יא מְשֻׁגָּע֙ אִ֣ישׁ הָ⁠ר֔וּחַ עַ֚ל רֹ֣ב עֲוֺנְ⁠ךָ֔ וְ⁠רַבָּ֖ה מַשְׂטֵמָֽה׃","bá֣̇ʼẇ ׀ yĕmé֣y ha⁠pĕ̇qudá̇֗h bá֚̇ʼẇ yĕmé֣y ha⁠şǐlu̇֔m yédĕʻ֖ẇ yişĕ̂ráʼé֑l ʼèwi֣yl ha⁠ná̇bi֗yʼ mĕşǔgá̇ʻ֙ ʼi֣yş̌ há⁠r֔ẇẖa ʻa֚l rò֣b ʻàwֺnĕ⁠ká֔ wĕ⁠rabá֖̇h maşĕ̂témáֽh׃"],[9,8,"צֹפֶ֥ה אֶפְרַ֖יִם עִם־אֱלֹהָ֑⁠י נָבִ֞יא פַּ֤ח יָקוֹשׁ֙ עַל־כָּל־דְּרָכָ֔י⁠ו מַשְׂטֵמָ֖ה בְּ⁠בֵ֥ית אֱלֹהָֽי⁠ו׃","ẕòpe֥h ʼepĕra֖yim ʻim-ʼèlòhá֑⁠y nábi֞yʼ pȧ֤ẖ yáqwòş̌֙ ʻal-ká̇l-dĕ̇ráká֔y⁠w maşĕ̂témá֖h bĕ̇⁠bé֥yţ ʼèlòháֽy⁠w׃"],[9,9,"הֶעְמִֽיקוּ־שִׁחֵ֖תוּ כִּ⁠ימֵ֣י הַ⁠גִּבְעָ֑ה יִזְכּ֣וֹר עֲוֺנָ֔⁠ם יִפְק֖וֹד חַטֹּאותָֽ⁠ם׃ס","heʻĕmiֽyqẇ-şǐẖé֖ţẇ ki̇⁠ymé֣y ha⁠gi̇bĕʻá֑h yizĕk֣̇wòr ʻàwֺná֔⁠m yipĕq֖wòd ẖatò̇ʼwţáֽ⁠m׃s"],[9,10,"כַּ⁠עֲנָבִ֣ים בַּ⁠מִּדְבָּ֗ר מָצָ֨אתִי֙ יִשְׂרָאֵ֔ל כְּ⁠בִכּוּרָ֤ה בִ⁠תְאֵנָה֙ בְּ⁠רֵ֣אשִׁיתָ֔⁠הּ רָאִ֖יתִי אֲבֽוֹתֵי⁠כֶ֑ם הֵ֜מָּה בָּ֣אוּ בַֽעַל־פְּע֗וֹר וַ⁠יִּנָּֽזְרוּ֙ לַ⁠בֹּ֔שֶׁת וַ⁠יִּהְי֥וּ שִׁקּוּצִ֖ים כְּ⁠אָהֳבָֽ⁠ם׃","kȧ⁠ʻànábi֣ym bȧ⁠mi̇dĕbá̇֗r máẕá֨ʼţiy֙ yişĕ̂ráʼé֔l kĕ̇⁠bik̇ẇrá֤h bi⁠ţĕʼénáh֙ bĕ̇⁠ré֣ʼşǐyţá֔⁠ḣ ráʼi֖yţiy ʼàbֽwòţéy⁠ke֑m hé֜má̇h bá֣̇ʼẇ baֽʻal-pĕ̇ʻ֗wòr wa⁠yi̇náֽ̇zĕrẇ֙ la⁠bò̇֔şěţ wa⁠yi̇hĕy֥ẇ şǐq̇ẇẕi֖ym kĕ̇⁠ʼáhobáֽ⁠m׃"],[9,11,"אֶפְרַ֕יִם כָּ⁠ע֖וֹף יִתְעוֹפֵ֣ף כְּבוֹדָ֑⁠ם מִ⁠לֵּדָ֥ה וּ⁠מִ⁠בֶּ֖טֶן וּ⁠מֵ⁠הֵרָיֽוֹן׃","ʼepĕra֕yim ká̇⁠ʻ֖wòp yiţĕʻwòpé֣p kĕ̇bwòdá֑⁠m mi⁠lé̇dá֥h ẇ⁠mi⁠bė֖ten ẇ⁠mé⁠héráyֽwòn׃"],[9,12,"כִּ֤י אִם־יְגַדְּלוּ֙ אֶת־בְּנֵי⁠הֶ֔ם וְ⁠שִׁכַּלְתִּ֖י⁠ם מֵֽ⁠אָדָ֑ם כִּֽי־גַם־א֥וֹי לָ⁠הֶ֖ם בְּ⁠שׂוּרִ֥⁠י מֵ⁠הֶֽם׃","ki֤̇y ʼim-yĕgadĕ̇lẇ֙ ʼeţ-bĕ̇néy⁠he֔m wĕ⁠şǐkȧlĕţi֖̇y⁠m méֽ⁠ʼádá֑m kiֽ̇y-gam-ʼ֥wòy lá⁠he֖m bĕ̇⁠ş̂ẇri֥⁠y mé⁠heֽm׃"],[9,13,"אֶפְרַ֛יִם כַּ⁠אֲשֶׁר־רָאִ֥יתִי לְ⁠צ֖וֹר שְׁתוּלָ֣ה בְ⁠נָוֶ֑ה וְ⁠אֶפְרַ֕יִם לְ⁠הוֹצִ֥יא אֶל־הֹרֵ֖ג בָּנָֽי⁠ו׃","ʼepĕra֛yim kȧ⁠ʼàşěr-ráʼi֥yţiy lĕ⁠ẕ֖wòr şĕ̌ţẇlá֣h bĕ⁠náwe֑h wĕ⁠ʼepĕra֕yim lĕ⁠hwòẕi֥yʼ ʼel-hòré֖g bá̇náֽy⁠w׃"],[9,14,"תֵּן־לָ⁠הֶ֥ם יְהוָ֖ה מַה־תִּתֵּ֑ן תֵּן־לָ⁠הֶם֙ רֶ֣חֶם מַשְׁכִּ֔יל וְ⁠שָׁדַ֖יִם צֹמְקִֽים׃","ţé̇n-lá⁠he֥m yĕhwá֖h mah-ţi̇ţé֑̇n ţé̇n-lá⁠hem֙ re֣ẖem maşĕ̌ki̇֔yl wĕ⁠şá̌da֖yim ẕòmĕqiֽym׃"],[9,15,"כָּל־רָעָתָ֤⁠ם בַּ⁠גִּלְגָּל֙ כִּֽי־שָׁ֣ם שְׂנֵאתִ֔י⁠ם עַ֚ל רֹ֣עַ מַֽעַלְלֵי⁠הֶ֔ם מִ⁠בֵּיתִ֖⁠י אֲגָרְשֵׁ֑⁠ם לֹ֤א אוֹסֵף֙ אַהֲבָתָ֔⁠ם כָּל־שָׂרֵי⁠הֶ֖ם סֹרְרִֽים׃","ká̇l-ráʻáţá֤⁠m bȧ⁠gi̇lĕgá̇l֙ kiֽ̇y-şá֣̌m şĕ̂néʼţi֔y⁠m ʻa֚l rò֣ʻa maֽʻalĕléy⁠he֔m mi⁠bé̇yţi֖⁠y ʼàgárĕşé֑̌⁠m lò֤ʼ ʼwòsép֙ ʼahàbáţá֔⁠m ká̇l-şá̂réy⁠he֖m sòrĕriֽym׃"],[9,16,"הֻכָּ֣ה אֶפְרַ֔יִם שָׁרְשָׁ֥⁠ם יָבֵ֖שׁ פְּרִ֣י בלי־יַעֲשׂ֑וּ⁠ן גַּ֚ם כִּ֣י יֵֽלֵד֔וּ⁠ן וְ⁠הֵמַתִּ֖י מַחֲמַדֵּ֥י בִטְנָֽ⁠ם׃ס","huká֣̇h ʼepĕra֔yim şá̌rĕşá֥̌⁠m yábé֖ş̌ pĕ̇ri֣y bly-yaʻàş֑̂ẇ⁠n gȧ֚m ki֣̇y yéֽléd֔ẇ⁠n wĕ⁠hémaţi֖̇y maẖàmadé֥̇y bitĕnáֽ⁠m׃s"],[9,17,"יִמְאָסֵ֣⁠ם אֱלֹהַ֔⁠י כִּ֛י לֹ֥א שָׁמְע֖וּ ל֑⁠וֹ וְ⁠יִהְי֥וּ נֹדְדִ֖ים בַּ⁠גּוֹיִֽם׃ס","yimĕʼásé֣⁠m ʼèlòha֔⁠y ki֛̇y lò֥ʼ şá̌mĕʻ֖ẇ l֑⁠wò wĕ⁠yihĕy֥ẇ nòdĕdi֖ym bȧ⁠ġwòyiֽm׃s"],[10,1,"גֶּ֤פֶן בּוֹקֵק֙ יִשְׂרָאֵ֔ל פְּרִ֖י יְשַׁוֶּה־לּ֑⁠וֹ כְּ⁠רֹ֣ב לְ⁠פִרְי֗⁠וֹ הִרְבָּה֙ לַֽ⁠מִּזְבְּח֔וֹת כְּ⁠ט֣וֹב לְ⁠אַרְצ֔⁠וֹ הֵיטִ֖יבוּ מַצֵּבֽוֹת׃","gė֤pen ḃwòqéq֙ yişĕ̂ráʼé֔l pĕ̇ri֖y yĕşǎwėh-l֑̇⁠wò kĕ̇⁠rò֣b lĕ⁠pirĕy֗⁠wò hirĕbá̇h֙ laֽ⁠mi̇zĕbĕ̇ẖ֔wòţ kĕ̇⁠t֣wòb lĕ⁠ʼarĕẕ֔⁠wò héyti֖ybẇ maẕé̇bֽwòţ׃"],[10,2,"חָלַ֥ק לִבָּ֖⁠ם עַתָּ֣ה יֶאְשָׁ֑מוּ ה֚וּא יַעֲרֹ֣ף מִזְבְּחוֹתָ֔⁠ם יְשֹׁדֵ֖ד מַצֵּבוֹתָֽ⁠ם׃","ẖála֥q libá֖̇⁠m ʻaţá֣̇h yeʼĕşá֑̌mẇ h֚ẇʼ yaʻàrò֣p mizĕbĕ̇ẖwòţá֔⁠m yĕşò̌dé֖d maẕé̇bwòţáֽ⁠m׃"],[10,3,"כִּ֤י עַתָּה֙ יֹֽאמְר֔וּ אֵ֥ין מֶ֖לֶךְ לָ֑⁠נוּ כִּ֣י לֹ֤א יָרֵ֨אנוּ֙ אֶת־יְהֹוָ֔ה וְ⁠הַ⁠מֶּ֖לֶךְ מַה־יַּֽעֲשֶׂה־לָּֽ⁠נוּ׃","ki֤̇y ʻaţá̇h֙ yòֽʼmĕr֔ẇ ʼé֥yn me֖lekĕ lá֑⁠nẇ ki֣̇y lò֤ʼ yáré֨ʼnẇ֙ ʼeţ-yĕhòwá֔h wĕ⁠ha⁠mė֖lekĕ mah-yȧֽʻàşêh-láֽ̇⁠nẇ׃"],[10,4,"דִּבְּר֣וּ דְבָרִ֔ים אָל֥וֹת שָׁ֖וְא כָּרֹ֣ת בְּרִ֑ית וּ⁠פָרַ֤ח כָּ⁠רֹאשׁ֙ מִשְׁפָּ֔ט עַ֖ל תַּלְמֵ֥י שָׂדָֽי׃","di̇bĕ̇r֣ẇ dĕbári֔ym ʼál֥wòţ şá֖̌wĕʼ ká̇rò֣ţ bĕ̇ri֑yţ ẇ⁠pára֤ẖ ká̇⁠ròʼş̌֙ mişĕ̌pá̇֔t ʻa֖l ţȧlĕmé֥y şá̂dáֽy׃"],[10,5,"לְ⁠עֶגְלוֹת֙ בֵּ֣ית אָ֔וֶן יָג֖וּרוּ שְׁכַ֣ן שֹֽׁמְר֑וֹן כִּי־אָבַ֨ל עָלָ֜י⁠ו עַמּ֗⁠וֹ וּ⁠כְמָרָי⁠ו֙ עָלָ֣י⁠ו יָגִ֔ילוּ עַל־כְּבוֹד֖⁠וֹ כִּֽי־גָלָ֥ה מִמֶּֽ⁠נּוּ׃","lĕ⁠ʻegĕlwòţ֙ bé֣̇yţ ʼá֔wen yág֖ẇrẇ şĕ̌ka֣n şòֽ̌mĕr֑wòn ki̇y-ʼába֨l ʻálá֜y⁠w ʻaṁ֗⁠wò ẇ⁠kĕmáráy⁠w֙ ʻálá֣y⁠w yági֔ylẇ ʻal-kĕ̇bwòd֖⁠wò kiֽ̇y-gálá֥h mimėֽ⁠ṅẇ׃"],[10,6,"גַּם־אוֹת⁠וֹ֙ לְ⁠אַשּׁ֣וּר יוּבָ֔ל מִנְחָ֖ה לְ⁠מֶ֣לֶךְ יָרֵ֑ב בָּשְׁנָה֙ אֶפְרַ֣יִם יִקָּ֔ח וְ⁠יֵב֥וֹשׁ יִשְׂרָאֵ֖ל מֵ⁠עֲצָתֽ⁠וֹ׃","gȧm-ʼwòţ⁠wò֙ lĕ⁠ʼaş֣̇̌ẇr yẇbá֔l minĕẖá֖h lĕ⁠me֣lekĕ yáré֑b bá̇şĕ̌náh֙ ʼepĕra֣yim yiqá̇֔ẖ wĕ⁠yéb֥wòş̌ yişĕ̂ráʼé֖l mé⁠ʻàẕáţֽ⁠wò׃"],[10,7,"נִדְמֶ֥ה שֹׁמְר֖וֹן מַלְכָּ֑⁠הּ כְּ⁠קֶ֖צֶף עַל־פְּנֵי־מָֽיִם׃","nidĕme֥h şò̌mĕr֖wòn malĕká֑̇⁠ḣ kĕ̇⁠qe֖ẕep ʻal-pĕ̇néy-máֽyim׃"],[10,8,"וְ⁠נִשְׁמְד֞וּ בָּמ֣וֹת אָ֗וֶן חַטַּאת֙ יִשְׂרָאֵ֔ל ק֣וֹץ וְ⁠דַרְדַּ֔ר יַעֲלֶ֖ה עַל־מִזְבְּחוֹתָ֑⁠ם וְ⁠אָמְר֤וּ לֶֽ⁠הָרִים֙ כַּסּ֔וּ⁠נוּ וְ⁠לַ⁠גְּבָע֖וֹת נִפְל֥וּ עָלֵֽי⁠נוּ׃ס","wĕ⁠nişĕ̌mĕd֞ẇ bá̇m֣wòţ ʼá֗wen ẖatȧʼţ֙ yişĕ̂ráʼé֔l q֣wòẕ wĕ⁠darĕdȧ֔r yaʻàle֖h ʻal-mizĕbĕ̇ẖwòţá֑⁠m wĕ⁠ʼámĕr֤ẇ leֽ⁠háriym֙ kȧṡ֔ẇ⁠nẇ wĕ⁠la⁠gĕ̇báʻ֖wòţ nipĕl֥ẇ ʻáléֽy⁠nẇ׃s"],[10,9,"מִ⁠ימֵי֙ הַ⁠גִּבְעָ֔ה חָטָ֖אתָ יִשְׂרָאֵ֑ל שָׁ֣ם עָמָ֔דוּ לֹֽא־תַשִּׂיגֵ֧⁠ם בַּ⁠גִּבְעָ֛ה מִלְחָמָ֖ה עַל־בְּנֵ֥י עַֽלְוָֽה׃","mi⁠yméy֙ ha⁠gi̇bĕʻá֔h ẖátá֖ʼţá yişĕ̂ráʼé֑l şá֣̌m ʻámá֔dẇ lòֽʼ-ţaşi̇̂ygé֧⁠m bȧ⁠gi̇bĕʻá֛h milĕẖámá֖h ʻal-bĕ̇né֥y ʻaֽlĕwáֽh׃"],[10,10,"בְּ⁠אַוָּתִ֖⁠י וְ⁠אֶסֳּרֵ֑⁠ם וְ⁠אֻסְּפ֤וּ עֲלֵי⁠הֶם֙ עַמִּ֔ים בְּ⁠אָסְרָ֖⁠ם לִ⁠שְׁתֵּ֥י עינת⁠ם׃","bĕ̇⁠ʼawá̇ţi֖⁠y wĕ⁠ʼesȯré֑⁠m wĕ⁠ʼusĕ̇p֤ẇ ʻàléy⁠hem֙ ʻami̇֔ym bĕ̇⁠ʼásĕrá֖⁠m li⁠şĕ̌ţé֥̇y ʻynţ⁠m׃"],[10,11,"וְ⁠אֶפְרַ֜יִם עֶגְלָ֤ה מְלֻמָּדָה֙ אֹהַ֣בְתִּי לָ⁠ד֔וּשׁ וַ⁠אֲנִ֣י עָבַ֔רְתִּי עַל־ט֖וּב צַוָּארָ֑⁠הּ אַרְכִּ֤יב אֶפְרַ֨יִם֙ יַחֲר֣וֹשׁ יְהוּדָ֔ה יְשַׂדֶּד־ל֖⁠וֹ יַעֲקֹֽב׃","wĕ⁠ʼepĕra֜yim ʻegĕlá֤h mĕlumá̇dáh֙ ʼòha֣bĕţi̇y lá⁠d֔ẇş̌ wa⁠ʼàni֣y ʻába֔rĕţi̇y ʻal-t֖ẇb ẕawá̇ʼrá֑⁠ḣ ʼarĕki֤̇yb ʼepĕra֨yim֙ yaẖàr֣wòş̌ yĕhẇdá֔h yĕşâdėd-l֖⁠wò yaʻàqòֽb׃"],[10,12,"זִרְע֨וּ לָ⁠כֶ֤ם לִ⁠צְדָקָה֙ קִצְר֣וּ לְ⁠פִי־חֶ֔סֶד נִ֥ירוּ לָ⁠כֶ֖ם נִ֑יר וְ⁠עֵת֙ לִ⁠דְר֣וֹשׁ אֶת־יְהוָ֔ה עַד־יָב֕וֹא וְ⁠יֹרֶ֥ה צֶ֖דֶק לָ⁠כֶֽם׃","zirĕʻ֨ẇ lá⁠ke֤m li⁠ẕĕdáqáh֙ qiẕĕr֣ẇ lĕ⁠piy-ẖe֔sed ni֥yrẇ lá⁠ke֖m ni֑yr wĕ⁠ʻéţ֙ li⁠dĕr֣wòş̌ ʼeţ-yĕhwá֔h ʻad-yáb֕wòʼ wĕ⁠yòre֥h ẕe֖deq lá⁠keֽm׃"],[10,13,"חֲרַשְׁתֶּם־רֶ֛שַׁע עַוְלָ֥תָ⁠ה קְצַרְתֶּ֖ם אֲכַלְתֶּ֣ם פְּרִי־כָ֑חַשׁ כִּֽי־בָטַ֥חְתָּ בְ⁠דַרְכְּ⁠ךָ֖ בְּ⁠רֹ֥ב גִּבּוֹרֶֽי⁠ךָ׃","ẖàraşĕ̌ţėm-re֛şǎʻ ʻawĕlá֥ţá⁠h qĕẕarĕţė֖m ʼàkalĕţė֣m pĕ̇riy-ká֑ẖaş̌ kiֽ̇y-báta֥ẖĕţá̇ bĕ⁠darĕkĕ̇⁠ká֖ bĕ̇⁠rò֥b gi̇ḃwòreֽy⁠ká׃"],[10,14,"וְ⁠קָ֣אם שָׁאוֹן֮ בְּ⁠עַמֶּ⁠ךָ֒ וְ⁠כָל־מִבְצָרֶ֣י⁠ךָ יוּשַּׁ֔ד כְּ⁠שֹׁ֧ד שַֽׁלְמַ֛ן בֵּ֥ית אַֽרְבֵ֖אל בְּ⁠י֣וֹם מִלְחָמָ֑ה אֵ֥ם עַל־בָּנִ֖ים רֻטָּֽשָׁה׃","wĕ⁠qá֣ʼm şá̌ʼwòn֮ bĕ̇⁠ʻamė⁠ká֒ wĕ⁠kál-mibĕẕáre֣y⁠ká yẇşȧ̌֔d kĕ̇⁠şò֧̌d şǎֽlĕma֛n bé֥̇yţ ʼaֽrĕbé֖ʼl bĕ̇⁠y֣wòm milĕẖámá֑h ʼé֥m ʻal-bá̇ni֖ym rutáֽ̇şá̌h׃"],[10,15,"כָּ֗כָה עָשָׂ֤ה לָ⁠כֶם֙ בֵּֽית־אֵ֔ל מִ⁠פְּנֵ֖י רָעַ֣ת רָֽעַתְ⁠כֶ֑ם בַּ⁠שַּׁ֕חַר נִדְמֹ֥ה נִדְמָ֖ה מֶ֥לֶךְ יִשְׂרָאֵֽל׃","ká̇֗káh ʻáşá֤̂h lá⁠kem֙ béֽ̇yţ-ʼé֔l mi⁠pĕ̇né֖y ráʻa֣ţ ráֽʻaţĕ⁠ke֑m bȧ⁠şȧ̌֕ẖar nidĕmò֥h nidĕmá֖h me֥lekĕ yişĕ̂ráʼéֽl׃"],[11,1,"כִּ֛י נַ֥עַר יִשְׂרָאֵ֖ל וָ⁠אֹהֲבֵ֑⁠הוּ וּ⁠מִ⁠מִּצְרַ֖יִם קָרָ֥אתִי לִ⁠בְנִֽ⁠י׃","ki֛̇y na֥ʻar yişĕ̂ráʼé֖l wá⁠ʼòhàbé֑⁠hẇ ẇ⁠mi⁠mi̇ẕĕra֖yim qárá֥ʼţiy li⁠bĕniֽ⁠y׃"],[11,2,"קָרְא֖וּ לָ⁠הֶ֑ם כֵּ֚ן הָלְכ֣וּ מִ⁠פְּנֵי⁠הֶ֔ם לַ⁠בְּעָלִ֣ים יְזַבֵּ֔חוּ וְ⁠לַ⁠פְּסִלִ֖ים יְקַטֵּרֽוּ⁠ן׃","qárĕʼ֖ẇ lá⁠he֑m ké֚̇n hálĕk֣ẇ mi⁠pĕ̇néy⁠he֔m la⁠bĕ̇ʻáli֣ym yĕzabé̇֔ẖẇ wĕ⁠la⁠pĕ̇sili֖ym yĕqaté̇rֽẇ⁠n׃"],[11,3,"וְ⁠אָנֹכִ֤י תִרְגַּ֨לְתִּי֙ לְ⁠אֶפְרַ֔יִם קָחָ֖⁠ם עַל־זְרֽוֹעֹתָ֑י⁠ו וְ⁠לֹ֥א יָדְע֖וּ כִּ֥י רְפָאתִֽי⁠ם׃","wĕ⁠ʼánòki֤y ţirĕgȧ֨lĕţi̇y֙ lĕ⁠ʼepĕra֔yim qáẖá֖⁠m ʻal-zĕrֽwòʻòţá֑y⁠w wĕ⁠lò֥ʼ yádĕʻ֖ẇ ki֥̇y rĕpáʼţiֽy⁠m׃"],[11,4,"בְּ⁠חַבְלֵ֨י אָדָ֤ם אֶמְשְׁכֵ⁠ם֙ בַּ⁠עֲבֹת֣וֹת אַהֲבָ֔ה וָ⁠אֶהְיֶ֥ה לָ⁠הֶ֛ם כִּ⁠מְרִ֥ימֵי עֹ֖ל עַ֣ל לְחֵי⁠הֶ֑ם וְ⁠אַ֥ט אֵלָ֖י⁠ו אוֹכִֽיל׃","bĕ̇⁠ẖabĕlé֨y ʼádá֤m ʼemĕşĕ̌ké⁠m֙ bȧ⁠ʻàbòţ֣wòţ ʼahàbá֔h wá⁠ʼehĕye֥h lá⁠he֛m ki̇⁠mĕri֥yméy ʻò֖l ʻa֣l lĕẖéy⁠he֑m wĕ⁠ʼa֥t ʼélá֖y⁠w ʼwòkiֽyl׃"],[11,5,"לֹ֤א יָשׁוּב֙ אֶל־אֶ֣רֶץ מִצְרַ֔יִם וְ⁠אַשּׁ֖וּר ה֣וּא מַלְכּ֑⁠וֹ כִּ֥י מֵאֲנ֖וּ לָ⁠שֽׁוּב׃","lò֤ʼ yáş̌ẇb֙ ʼel-ʼe֣reẕ miẕĕra֔yim wĕ⁠ʼaş֖̇̌ẇr h֣ẇʼ malĕk֑̇⁠wò ki֥̇y méʼàn֖ẇ lá⁠şֽ̌ẇb׃"],[11,6,"וְ⁠חָלָ֥ה חֶ֨רֶב֙ בְּ⁠עָרָ֔י⁠ו וְ⁠כִלְּתָ֥ה בַדָּ֖י⁠ו וְ⁠אָכָ֑לָה מִֽ⁠מֹּעֲצ֖וֹתֵי⁠הֶֽם׃","wĕ⁠ẖálá֥h ẖe֨reb֙ bĕ̇⁠ʻárá֔y⁠w wĕ⁠kilĕ̇ţá֥h badá֖̇y⁠w wĕ⁠ʼáká֑láh miֽ⁠mò̇ʻàẕ֖wòţéy⁠heֽm׃"],[11,7,"וְ⁠עַמִּ֥⁠י תְלוּאִ֖ים לִ⁠מְשֽׁוּבָתִ֑⁠י וְ⁠אֶל־עַל֙ יִקְרָאֻ֔⁠הוּ יַ֖חַד לֹ֥א יְרוֹמֵם׃","wĕ⁠ʻami֥̇⁠y ţĕlẇʼi֖ym li⁠mĕşֽ̌ẇbáţi֑⁠y wĕ⁠ʼel-ʻal֙ yiqĕráʼu֔⁠hẇ ya֖ẖad lò֥ʼ yĕrwòmém׃"],[11,8,"אֵ֞יךְ אֶתֶּנְ⁠ךָ֣ אֶפְרַ֗יִם אֲמַגֶּנְ⁠ךָ֙ יִשְׂרָאֵ֔ל אֵ֚יךְ אֶתֶּנְ⁠ךָ֣ כְ⁠אַדְמָ֔ה אֲשִֽׂימְ⁠ךָ֖ כִּ⁠צְבֹאיִ֑ם נֶהְפַּ֤ךְ עָלַ⁠י֙ לִבִּ֔⁠י יַ֖חַד נִכְמְר֥וּ נִחוּמָֽ⁠י׃","ʼé֞ykĕ ʼeţėnĕ⁠ká֣ ʼepĕra֗yim ʼàmagėnĕ⁠ká֙ yişĕ̂ráʼé֔l ʼé֚ykĕ ʼeţėnĕ⁠ká֣ kĕ⁠ʼadĕmá֔h ʼàşîֽymĕ⁠ká֖ ki̇⁠ẕĕbòʼyi֑m nehĕpȧ֤kĕ ʻála⁠y֙ libi̇֔⁠y ya֖ẖad nikĕmĕr֥ẇ niẖẇmáֽ⁠y׃"],[11,9,"לֹ֤א אֶֽעֱשֶׂה֙ חֲר֣וֹן אַפִּ֔⁠י לֹ֥א אָשׁ֖וּב לְ⁠שַׁחֵ֣ת אֶפְרָ֑יִם כִּ֣י אֵ֤ל אָֽנֹכִי֙ וְ⁠לֹא־אִ֔ישׁ בְּ⁠קִרְבְּ⁠ךָ֣ קָד֔וֹשׁ וְ⁠לֹ֥א אָב֖וֹא בְּ⁠עִֽיר׃","lò֤ʼ ʼeֽʻèşêh֙ ẖàr֣wòn ʼapi̇֔⁠y lò֥ʼ ʼáş֖̌ẇb lĕ⁠şǎẖé֣ţ ʼepĕrá֑yim ki֣̇y ʼé֤l ʼáֽnòkiy֙ wĕ⁠lòʼ-ʼi֔yş̌ bĕ̇⁠qirĕbĕ̇⁠ká֣ qád֔wòş̌ wĕ⁠lò֥ʼ ʼáb֖wòʼ bĕ̇⁠ʻiֽyr׃"],[11,10,"אַחֲרֵ֧י יְהוָ֛ה יֵלְכ֖וּ כְּ⁠אַרְיֵ֣ה יִשְׁאָ֑ג כִּֽי־ה֣וּא יִשְׁאַ֔ג וְ⁠יֶחֶרְד֥וּ בָנִ֖ים מִ⁠יָּֽם׃","ʼaẖàré֧y yĕhwá֛h yélĕk֖ẇ kĕ̇⁠ʼarĕyé֣h yişĕ̌ʼá֑g kiֽ̇y-h֣ẇʼ yişĕ̌ʼa֔g wĕ⁠yeẖerĕd֥ẇ báni֖ym mi⁠yáֽ̇m׃"],[11,11,"יֶחֶרְד֤וּ כְ⁠צִפּוֹר֙ מִ⁠מִּצְרַ֔יִם וּ⁠כְ⁠יוֹנָ֖ה מֵ⁠אֶ֣רֶץ אַשּׁ֑וּר וְ⁠הוֹשַׁבְתִּ֥י⁠ם עַל־בָּתֵּי⁠הֶ֖ם נְאֻם־יְהוָֽה׃ס","yeẖerĕd֤ẇ kĕ⁠ẕiṗwòr֙ mi⁠mi̇ẕĕra֔yim ẇ⁠kĕ⁠ywòná֖h mé⁠ʼe֣reẕ ʼaş֑̇̌ẇr wĕ⁠hwòşǎbĕţi֥̇y⁠m ʻal-bá̇ţé̇y⁠he֖m nĕʼum-yĕhwáֽh׃s"],[11,12,"סְבָבֻ֤⁠נִי בְ⁠כַ֨חַשׁ֙ אֶפְרַ֔יִם וּ⁠בְ⁠מִרְמָ֖ה בֵּ֣ית יִשְׂרָאֵ֑ל וִֽ⁠יהוּדָ֗ה עֹ֥ד רָד֙ עִם־אֵ֔ל וְ⁠עִם־קְדוֹשִׁ֖ים נֶאֱמָֽן׃","sĕbábu֤⁠niy bĕ⁠ka֨ẖaş̌֙ ʼepĕra֔yim ẇ⁠bĕ⁠mirĕmá֖h bé֣̇yţ yişĕ̂ráʼé֑l wiֽ⁠yhẇdá֗h ʻò֥d rád֙ ʻim-ʼé֔l wĕ⁠ʻim-qĕdwòşǐ֖ym neʼèmáֽn׃"],[12,1,"אֶפְרַ֜יִם רֹעֶ֥ה ר֨וּחַ֙ וְ⁠רֹדֵ֣ף קָדִ֔ים כָּל־הַ⁠יּ֕וֹם כָּזָ֥ב וָ⁠שֹׁ֖ד יַרְבֶּ֑ה וּ⁠בְרִית֙ עִם־אַשּׁ֣וּר יִכְרֹ֔תוּ וְ⁠שֶׁ֖מֶן לְ⁠מִצְרַ֥יִם יוּבָֽל׃","ʼepĕra֜yim ròʻe֥h r֨ẇẖa֙ wĕ⁠ròdé֣p qádi֔ym ká̇l-ha⁠ẏ֕wòm ká̇zá֥b wá⁠şò֖̌d yarĕbė֑h ẇ⁠bĕriyţ֙ ʻim-ʼaş֣̇̌ẇr yikĕrò֔ţẇ wĕ⁠şě֖men lĕ⁠miẕĕra֥yim yẇbáֽl׃"],[12,2,"וְ⁠רִ֥יב לַֽ⁠יהוָ֖ה עִם־יְהוּדָ֑ה וְ⁠לִ⁠פְקֹ֤ד עַֽל־יַעֲקֹב֙ כִּ⁠דְרָכָ֔י⁠ו כְּ⁠מַעֲלָלָ֖י⁠ו יָשִׁ֥יב לֽ⁠וֹ׃","wĕ⁠ri֥yb laֽ⁠yhwá֖h ʻim-yĕhẇdá֑h wĕ⁠li⁠pĕqò֤d ʻaֽl-yaʻàqòb֙ ki̇⁠dĕráká֔y⁠w kĕ̇⁠maʻàlálá֖y⁠w yáşǐ֥yb lֽ⁠wò׃"],[12,3,"בַּ⁠בֶּ֖טֶן עָקַ֣ב אֶת־אָחִ֑י⁠ו וּ⁠בְ⁠אוֹנ֖⁠וֹ שָׂרָ֥ה אֶת־אֱלֹהִֽים׃","bȧ⁠bė֖ten ʻáqa֣b ʼeţ-ʼáẖi֑y⁠w ẇ⁠bĕ⁠ʼwòn֖⁠wò şá̂rá֥h ʼeţ-ʼèlòhiֽym׃"],[12,4,"וָ⁠יָּ֤שַׂר אֶל־מַלְאָךְ֙ וַ⁠יֻּכָ֔ל בָּכָ֖ה וַ⁠יִּתְחַנֶּן־ל֑⁠וֹ בֵּֽית־אֵל֙ יִמְצָאֶ֔⁠נּוּ וְ⁠שָׁ֖ם יְדַבֵּ֥ר עִמָּֽ⁠נוּ׃","wá⁠yá֤̇şâr ʼel-malĕʼákĕ֙ wa⁠yu̇ká֔l bá̇ká֖h wa⁠yi̇ţĕẖanėn-l֑⁠wò béֽ̇yţ-ʼél֙ yimĕẕáʼe֔⁠ṅẇ wĕ⁠şá֖̌m yĕdabé֥̇r ʻimáֽ̇⁠nẇ׃"],[12,5,"וַֽ⁠יהוָ֖ה אֱלֹהֵ֣י הַ⁠צְּבָא֑וֹת יְהוָ֖ה זִכְרֽ⁠וֹ׃","waֽ⁠yhwá֖h ʼèlòhé֣y ha⁠ẕĕ̇báʼ֑wòţ yĕhwá֖h zikĕrֽ⁠wò׃"],[12,6,"וְ⁠אַתָּ֖ה בֵּ⁠אלֹהֶ֣י⁠ךָ תָשׁ֑וּב חֶ֤סֶד וּ⁠מִשְׁפָּט֙ שְׁמֹ֔ר וְ⁠קַוֵּ֥ה אֶל־אֱלֹהֶ֖י⁠ךָ תָּמִֽיד׃","wĕ⁠ʼaţá֖̇h bé̇⁠ʼlòhe֣y⁠ká ţáş֑̌ẇb ẖe֤sed ẇ⁠mişĕ̌pá̇t֙ şĕ̌mò֔r wĕ⁠qawé֥̇h ʼel-ʼèlòhe֖y⁠ká ţá̇miֽyd׃"],[12,7,"כְּנַ֗עַן בְּ⁠יָד֛⁠וֹ מֹאזְנֵ֥י מִרְמָ֖ה לַ⁠עֲשֹׁ֥ק אָהֵֽב׃","kĕ̇na֗ʻan bĕ̇⁠yád֛⁠wò mòʼzĕné֥y mirĕmá֖h la⁠ʻàşò֥̌q ʼáhéֽb׃"],[12,8,"וַ⁠יֹּ֣אמֶר אֶפְרַ֔יִם אַ֣ךְ עָשַׁ֔רְתִּי מָצָ֥אתִי א֖וֹן לִ֑⁠י כָּל־יְגִיעַ֕⁠י לֹ֥א יִמְצְאוּ־לִ֖⁠י עָוֺ֥ן אֲשֶׁר־חֵֽטְא׃","wa⁠yò֣̇ʼmer ʼepĕra֔yim ʼa֣kĕ ʻáşǎ֔rĕţi̇y máẕá֥ʼţiy ʼ֖wòn li֑⁠y ká̇l-yĕgiyʻa֕⁠y lò֥ʼ yimĕẕĕʼẇ-li֖⁠y ʻáwֺ֥n ʼàşěr-ẖéֽtĕʼ׃"],[12,9,"וְ⁠אָנֹכִ֛י יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם עֹ֛ד אוֹשִֽׁיבְ⁠ךָ֥ בָ⁠אֳהָלִ֖ים כִּ⁠ימֵ֥י מוֹעֵֽד׃","wĕ⁠ʼánòki֛y yĕhwá֥h ʼèlòhe֖y⁠ká mé⁠ʼe֣reẕ miẕĕrá֑yim ʻò֛d ʼwòşǐֽybĕ⁠ká֥ bá⁠ʼoháli֖ym ki̇⁠ymé֥y mwòʻéֽd׃"],[12,10,"וְ⁠דִבַּ֨רְתִּי֙ עַל־הַ⁠נְּבִיאִ֔ים וְ⁠אָנֹכִ֖י חָז֣וֹן הִרְבֵּ֑יתִי וּ⁠בְ⁠יַ֥ד הַ⁠נְּבִיאִ֖ים אֲדַמֶּֽה׃","wĕ⁠dibȧ֨rĕţi̇y֙ ʻal-ha⁠nĕ̇biyʼi֔ym wĕ⁠ʼánòki֖y ẖáz֣wòn hirĕbé֑̇yţiy ẇ⁠bĕ⁠ya֥d ha⁠nĕ̇biyʼi֖ym ʼàdamėֽh׃"],[12,11,"אִם־גִּלְעָ֥ד אָ֨וֶן֙ אַךְ־שָׁ֣וְא הָי֔וּ בַּ⁠גִּלְגָּ֖ל שְׁוָרִ֣ים זִבֵּ֑חוּ גַּ֤ם מִזְבְּחוֹתָ⁠ם֙ כְּ⁠גַלִּ֔ים עַ֖ל תַּלְמֵ֥י שָׂדָֽי׃","ʼim-gi̇lĕʻá֥d ʼá֨wen֙ ʼakĕ-şá֣̌wĕʼ háy֔ẇ bȧ⁠gi̇lĕgá֖̇l şĕ̌wári֣ym zibé֑̇ẖẇ gȧ֤m mizĕbĕ̇ẖwòţá⁠m֙ kĕ̇⁠gali̇֔ym ʻa֖l ţȧlĕmé֥y şá̂dáֽy׃"],[12,12,"וַ⁠יִּבְרַ֥ח יַעֲקֹ֖ב שְׂדֵ֣ה אֲרָ֑ם וַ⁠יַּעֲבֹ֤ד יִשְׂרָאֵל֙ בְּ⁠אִשָּׁ֔ה וּ⁠בְ⁠אִשָּׁ֖ה שָׁמָֽר׃","wa⁠yi̇bĕra֥ẖ yaʻàqò֖b şĕ̂dé֣h ʼàrá֑m wa⁠yȧʻàbò֤d yişĕ̂ráʼél֙ bĕ̇⁠ʼişá̇̌֔h ẇ⁠bĕ⁠ʼişá֖̇̌h şá̌máֽr׃"],[12,13,"וּ⁠בְ⁠נָבִ֕יא הֶעֱלָ֧ה יְהוָ֛ה אֶת־יִשְׂרָאֵ֖ל מִ⁠מִּצְרָ֑יִם וּ⁠בְ⁠נָבִ֖יא נִשְׁמָֽר׃","ẇ⁠bĕ⁠nábi֕yʼ heʻèlá֧h yĕhwá֛h ʼeţ-yişĕ̂ráʼé֖l mi⁠mi̇ẕĕrá֑yim ẇ⁠bĕ⁠nábi֖yʼ nişĕ̌máֽr׃"],[12,14,"הִכְעִ֥יס אֶפְרַ֖יִם תַּמְרוּרִ֑ים וְ⁠דָמָי⁠ו֙ עָלָ֣י⁠ו יִטּ֔וֹשׁ וְ⁠חֶ֨רְפָּת֔⁠וֹ יָשִׁ֥יב ל֖⁠וֹ אֲדֹנָֽי⁠ו׃","hikĕʻi֥ys ʼepĕra֖yim ţȧmĕrẇri֑ym wĕ⁠dámáy⁠w֙ ʻálá֣y⁠w yiṫ֔wòş̌ wĕ⁠ẖe֨rĕpá̇ţ֔⁠wò yáşǐ֥yb l֖⁠wò ʼàdònáֽy⁠w׃"],[13,1,"כְּ⁠דַבֵּ֤ר אֶפְרַ֨יִם֙ רְתֵ֔ת נָשָׂ֥א ה֖וּא בְּ⁠יִשְׂרָאֵ֑ל וַ⁠יֶּאְשַׁ֥ם בַּ⁠בַּ֖עַל וַ⁠יָּמֹֽת׃","kĕ̇⁠dabé֤̇r ʼepĕra֨yim֙ rĕţé֔ţ náşá֥̂ʼ h֖ẇʼ bĕ̇⁠yişĕ̂ráʼé֑l wa⁠yėʼĕşǎ֥m bȧ⁠bȧ֖ʻal wa⁠yá̇mòֽţ׃"],[13,2,"וְ⁠עַתָּ֣ה ׀ יוֹסִ֣פוּ לַ⁠חֲטֹ֗א וַ⁠יַּעְשׂ֣וּ לָ⁠הֶם֩ מַסֵּכָ֨ה מִ⁠כַּסְפָּ֤⁠ם כִּ⁠תְבוּנָ⁠ם֙ עֲצַבִּ֔ים מַעֲשֵׂ֥ה חָרָשִׁ֖ים כֻּלֹּ֑⁠ה לָ⁠הֶם֙ הֵ֣ם אֹמְרִ֔ים זֹבְחֵ֣י אָדָ֔ם עֲגָלִ֖ים יִשָּׁקֽוּ⁠ן׃","wĕ⁠ʻaţá֣̇h ׀ ywòsi֣pẇ la⁠ẖàtò֗ʼ wa⁠yȧʻĕş֣̂ẇ lá⁠hem֩ masé̇ká֨h mi⁠kȧsĕpá֤̇⁠m ki̇⁠ţĕbẇná⁠m֙ ʻàẕabi̇֔ym maʻàşé֥̂h ẖáráşǐ֖ym ku̇lò֑̇⁠h lá⁠hem֙ hé֣m ʼòmĕri֔ym zòbĕẖé֣y ʼádá֔m ʻàgáli֖ym yişá̇̌qֽẇ⁠n׃"],[13,3,"לָ⁠כֵ֗ן יִֽהְיוּ֙ כַּ⁠עֲנַן־בֹּ֔קֶר וְ⁠כַ⁠טַּ֖ל מַשְׁכִּ֣ים הֹלֵ֑ךְ כְּ⁠מֹץ֙ יְסֹעֵ֣ר מִ⁠גֹּ֔רֶן וּ⁠כְ⁠עָשָׁ֖ן מֵ⁠אֲרֻבָּֽה׃","lá⁠ké֗n yiֽhĕyẇ֙ kȧ⁠ʻànan-bò̇֔qer wĕ⁠ka⁠tȧ֖l maşĕ̌ki֣̇ym hòlé֑kĕ kĕ̇⁠mòẕ֙ yĕsòʻé֣r mi⁠gò̇֔ren ẇ⁠kĕ⁠ʻáşá֖̌n mé⁠ʼàrubáֽ̇h׃"],[13,4,"וְ⁠אָנֹכִ֛י יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם וֵ⁠אלֹהִ֤ים זֽוּלָתִ⁠י֙ לֹ֣א תֵדָ֔ע וּ⁠מוֹשִׁ֥יעַ אַ֖יִן בִּלְתִּֽ⁠י׃","wĕ⁠ʼánòki֛y yĕhwá֥h ʼèlòhe֖y⁠ká mé⁠ʼe֣reẕ miẕĕrá֑yim wé⁠ʼlòhi֤ym zֽẇláţi⁠y֙ lò֣ʼ ţédá֔ʻ ẇ⁠mwòşǐ֥yʻa ʼa֖yin bi̇lĕţiֽ̇⁠y׃"],[13,5,"אֲנִ֥י יְדַעְתִּ֖י⁠ךָ בַּ⁠מִּדְבָּ֑ר בְּ⁠אֶ֖רֶץ תַּלְאֻבֽוֹת׃","ʼàni֥y yĕdaʻĕţi֖̇y⁠ká bȧ⁠mi̇dĕbá֑̇r bĕ̇⁠ʼe֖reẕ ţȧlĕʼubֽwòţ׃"],[13,6,"כְּ⁠מַרְעִיתָ⁠ם֙ וַ⁠יִּשְׂבָּ֔עוּ שָׂבְע֖וּ וַ⁠יָּ֣רָם לִבָּ֑⁠ם עַל־כֵּ֖ן שְׁכֵחֽוּ⁠נִי׃","kĕ̇⁠marĕʻiyţá⁠m֙ wa⁠yi̇şĕ̂bá̇֔ʻẇ şá̂bĕʻ֖ẇ wa⁠yá֣̇rám libá֑̇⁠m ʻal-ké֖̇n şĕ̌kéẖֽẇ⁠niy׃"],[13,7,"וָ⁠אֱהִ֥י לָ⁠הֶ֖ם כְּמוֹ־שָׁ֑חַל כְּ⁠נָמֵ֖ר עַל־דֶּ֥רֶךְ אָשֽׁוּר׃","wá⁠ʼèhi֥y lá⁠he֖m kĕ̇mwò-şá֑̌ẖal kĕ̇⁠námé֖r ʻal-dė֥rekĕ ʼáşֽ̌ẇr׃"],[13,8,"אֶפְגְּשֵׁ⁠ם֙ כְּ⁠דֹ֣ב שַׁכּ֔וּל וְ⁠אֶקְרַ֖ע סְג֣וֹר לִבָּ֑⁠ם וְ⁠אֹכְלֵ֥⁠ם שָׁם֙ כְּ⁠לָבִ֔יא חַיַּ֥ת הַ⁠שָּׂדֶ֖ה תְּבַקְּעֵֽ⁠ם׃","ʼepĕgĕ̇şé̌⁠m֙ kĕ̇⁠dò֣b şǎk̇֔ẇl wĕ⁠ʼeqĕra֖ʻ sĕg֣wòr libá֑̇⁠m wĕ⁠ʼòkĕlé֥⁠m şá̌m֙ kĕ̇⁠lábi֔yʼ ẖayȧ֥ţ ha⁠şá̇̂de֖h ţĕ̇baqĕ̇ʻéֽ⁠m׃"],[13,9,"שִֽׁחֶתְ⁠ךָ֥ יִשְׂרָאֵ֖ל כִּֽי־בִ֥⁠י בְ⁠עֶזְרֶֽ⁠ךָ׃","şǐֽẖeţĕ⁠ká֥ yişĕ̂ráʼé֖l kiֽ̇y-bi֥⁠y bĕ⁠ʻezĕreֽ⁠ká׃"],[13,10,"אֱהִ֤י מַלְכְּ⁠ךָ֙ אֵפ֔וֹא וְ⁠יוֹשִֽׁיעֲ⁠ךָ֖ בְּ⁠כָל־עָרֶ֑י⁠ךָ וְ⁠שֹׁ֣פְטֶ֔י⁠ךָ אֲשֶׁ֣ר אָמַ֔רְתָּ תְּנָ⁠ה־לִּ֖⁠י מֶ֥לֶךְ וְ⁠שָׂרִֽים׃","ʼèhi֤y malĕkĕ̇⁠ká֙ ʼép֔wòʼ wĕ⁠ywòşǐֽyʻà⁠ká֖ bĕ̇⁠kál-ʻáre֑y⁠ká wĕ⁠şò֣̌pĕte֔y⁠ká ʼàşě֣r ʼáma֔rĕţá̇ ţĕ̇ná⁠h-li֖̇⁠y me֥lekĕ wĕ⁠şá̂riֽym׃"],[13,11,"אֶֽתֶּן־לְ⁠ךָ֥ מֶ֨לֶךְ֙ בְּ⁠אַפִּ֔⁠י וְ⁠אֶקַּ֖ח בְּ⁠עֶבְרָתִֽ⁠י׃ס","ʼeֽţėn-lĕ⁠ká֥ me֨lekĕ֙ bĕ̇⁠ʼapi̇֔⁠y wĕ⁠ʼeqȧ֖ẖ bĕ̇⁠ʻebĕráţiֽ⁠y׃s"],[13,12,"צָרוּר֙ עֲוֺ֣ן אֶפְרָ֔יִם צְפוּנָ֖ה חַטָּאתֽ⁠וֹ׃","ẕárẇr֙ ʻàwֺ֣n ʼepĕrá֔yim ẕĕpẇná֖h ẖatá̇ʼţֽ⁠wò׃"],[13,13,"חֶבְלֵ֥י יֽוֹלֵדָ֖ה יָבֹ֣אוּ ל֑⁠וֹ הוּא־בֵן֙ לֹ֣א חָכָ֔ם כִּֽי־עֵ֥ת לֹֽא־יַעֲמֹ֖ד בְּ⁠מִשְׁבַּ֥ר בָּנִֽים׃","ẖebĕlé֥y yֽwòlédá֖h yábò֣ʼẇ l֑⁠wò hẇʼ-bén֙ lò֣ʼ ẖáká֔m kiֽ̇y-ʻé֥ţ lòֽʼ-yaʻàmò֖d bĕ̇⁠mişĕ̌bȧ֥r bá̇niֽym׃"],[13,14,"מִ⁠יַּ֤ד שְׁאוֹל֙ אֶפְדֵּ֔⁠ם מִ⁠מָּ֖וֶת אֶגְאָלֵ֑⁠ם אֱהִ֨י דְבָרֶי⁠ךָ֜ מָ֗וֶת אֱהִ֤י קָֽטָבְ⁠ךָ֙ שְׁא֔וֹל נֹ֖חַם יִסָּתֵ֥ר מֵ⁠עֵינָֽ⁠י׃","mi⁠yȧ֤d şĕ̌ʼwòl֙ ʼepĕdé̇֔⁠m mi⁠má֖̇weţ ʼegĕʼálé֑⁠m ʼèhi֨y dĕbárey⁠ká֜ má֗weţ ʼèhi֤y qáֽtábĕ⁠ká֙ şĕ̌ʼ֔wòl nò֖ẖam yisá̇ţé֥r mé⁠ʻéynáֽ⁠y׃"],[13,15,"כִּ֣י ה֔וּא בֵּ֥ן אַחִ֖ים יַפְרִ֑יא יָב֣וֹא קָדִים֩ ר֨וּחַ יְהוָ֜ה מִ⁠מִּדְבָּ֣ר עֹלֶ֗ה וְ⁠יֵב֤וֹשׁ מְקוֹר⁠וֹ֙ וְ⁠יֶחֱרַ֣ב מַעְיָנ֔⁠וֹ ה֣וּא יִשְׁסֶ֔ה אוֹצַ֖ר כָּל־כְּלִ֥י חֶמְדָּֽה׃","ki֣̇y h֔ẇʼ bé֥̇n ʼaẖi֖ym yapĕri֑yʼ yáb֣wòʼ qádiym֩ r֨ẇẖa yĕhwá֜h mi⁠mi̇dĕbá֣̇r ʻòle֗h wĕ⁠yéb֤wòş̌ mĕqwòr⁠wò֙ wĕ⁠yeẖèra֣b maʻĕyán֔⁠wò h֣ẇʼ yişĕ̌se֔h ʼwòẕa֖r ká̇l-kĕ̇li֥y ẖemĕdáֽ̇h׃"],[13,16,"תֶּאְשַׁם֙ שֹֽׁמְר֔וֹן כִּ֥י מָרְתָ֖ה בֵּֽ⁠אלֹהֶ֑י⁠הָ בַּ⁠חֶ֣רֶב יִפֹּ֔לוּ עֹלְלֵי⁠הֶ֣ם יְרֻטָּ֔שׁוּ וְ⁠הָרִיּוֹתָ֖י⁠ו יְבֻקָּֽעוּ׃פ","ţėʼĕşǎm֙ şòֽ̌mĕr֔wòn ki֥̇y márĕţá֖h béֽ̇⁠ʼlòhe֑y⁠há bȧ⁠ẖe֣reb yipò̇֔lẇ ʻòlĕléy⁠he֣m yĕrutá̇֔ş̌ẇ wĕ⁠háriẏwòţá֖y⁠w yĕbuqáֽ̇ʻẇ׃p"],[14,1,"שׁ֚וּבָ⁠ה יִשְׂרָאֵ֔ל עַ֖ד יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ כִּ֥י כָשַׁ֖לְתָּ בַּ⁠עֲוֺנֶֽ⁠ךָ׃","ş֚̌ẇbá⁠h yişĕ̂ráʼé֔l ʻa֖d yĕhwá֣h ʼèlòhe֑y⁠ká ki֥̇y káşǎ֖lĕţá̇ bȧ⁠ʻàwֺneֽ⁠ká׃"],[14,2,"קְח֤וּ עִמָּ⁠כֶם֙ דְּבָרִ֔ים וְ⁠שׁ֖וּבוּ אֶל־יְהוָ֑ה אִמְר֣וּ אֵלָ֗י⁠ו כָּל־תִּשָּׂ֤א עָוֺן֙ וְ⁠קַח־ט֔וֹב וּֽ⁠נְשַׁלְּמָ֥ה פָרִ֖ים שְׂפָתֵֽי⁠נוּ׃","qĕẖ֤ẇ ʻimá̇⁠kem֙ dĕ̇bári֔ym wĕ⁠ş֖̌ẇbẇ ʼel-yĕhwá֑h ʼimĕr֣ẇ ʼélá֗y⁠w ká̇l-ţi̇şá֤̇̂ʼ ʻáwֺn֙ wĕ⁠qaẖ-t֔wòb ẇֽ⁠nĕşǎlĕ̇má֥h pári֖ym şĕ̂páţéֽy⁠nẇ׃"],[14,3,"אַשּׁ֣וּר ׀ לֹ֣א יוֹשִׁיעֵ֗⁠נוּ עַל־סוּס֙ לֹ֣א נִרְכָּ֔ב וְ⁠לֹא־נֹ֥אמַר ע֛וֹד אֱלֹהֵ֖י⁠נוּ לְ⁠מַעֲשֵׂ֣ה יָדֵ֑י⁠נוּ אֲשֶׁר־בְּ⁠ךָ֖ יְרֻחַ֥ם יָתֽוֹם׃","ʼaş֣̇̌ẇr ׀ lò֣ʼ ywòşǐyʻé֗⁠nẇ ʻal-sẇs֙ lò֣ʼ nirĕká̇֔b wĕ⁠lòʼ-nò֥ʼmar ʻ֛wòd ʼèlòhé֖y⁠nẇ lĕ⁠maʻàşé֣̂h yádé֑y⁠nẇ ʼàşěr-bĕ̇⁠ká֖ yĕruẖa֥m yáţֽwòm׃"],[14,4,"אֶרְפָּא֙ מְשׁ֣וּבָתָ֔⁠ם אֹהֲבֵ֖⁠ם נְדָבָ֑ה כִּ֛י שָׁ֥ב אַפִּ֖⁠י מִמֶּֽ⁠נּוּ׃","ʼerĕpá̇ʼ֙ mĕş֣̌ẇbáţá֔⁠m ʼòhàbé֖⁠m nĕdábá֑h ki֛̇y şá֥̌b ʼapi֖̇⁠y mimėֽ⁠ṅẇ׃"],[14,5,"אֶהְיֶ֤ה כַ⁠טַּל֙ לְ⁠יִשְׂרָאֵ֔ל יִפְרַ֖ח כַּ⁠שּֽׁוֹשַׁנָּ֑ה וְ⁠יַ֥ךְ שָׁרָשָׁ֖י⁠ו כַּ⁠לְּבָנֽוֹן׃","ʼehĕye֤h ka⁠tȧl֙ lĕ⁠yişĕ̂ráʼé֔l yipĕra֖ẖ kȧ⁠şֽ̇̌wòşǎná֑̇h wĕ⁠ya֥kĕ şá̌ráşá֖̌y⁠w kȧ⁠lĕ̇bánֽwòn׃"],[14,6,"יֵֽלְכוּ֙ יֹֽנְקוֹתָ֔י⁠ו וִ⁠יהִ֥י כַ⁠זַּ֖יִת הוֹד֑⁠וֹ וְ⁠רֵ֥יחַֽ ל֖⁠וֹ כַּ⁠לְּבָנֽוֹן׃","yéֽlĕkẇ֙ yòֽnĕqwòţá֔y⁠w wi⁠yhi֥y ka⁠zȧ֖yiţ hwòd֑⁠wò wĕ⁠ré֥yẖaֽ l֖⁠wò kȧ⁠lĕ̇bánֽwòn׃"],[14,7,"יָשֻׁ֨בוּ֙ יֹשְׁבֵ֣י בְ⁠צִלּ֔⁠וֹ יְחַיּ֥וּ דָגָ֖ן וְ⁠יִפְרְח֣וּ כַ⁠גָּ֑פֶן זִכְר֖⁠וֹ כְּ⁠יֵ֥ין לְבָנֽוֹן׃ס","yáşǔ֨bẇ֙ yòşĕ̌bé֣y bĕ⁠ẕil̇֔⁠wò yĕẖaẏ֥ẇ dágá֖n wĕ⁠yipĕrĕẖ֣ẇ ka⁠gá֑̇pen zikĕr֖⁠wò kĕ̇⁠yé֥yn lĕbánֽwòn׃s"],[14,8,"אֶפְרַ֕יִם מַה־לִּ֥⁠י ע֖וֹד לָֽ⁠עֲצַבִּ֑ים אֲנִ֧י עָנִ֣יתִי וַ⁠אֲשׁוּרֶ֗⁠נּוּ אֲנִי֙ כִּ⁠בְר֣וֹשׁ רַֽעֲנָ֔ן מִמֶּ֖⁠נִּי פֶּרְיְ⁠ךָ֥ נִמְצָֽא׃","ʼepĕra֕yim mah-li֥̇⁠y ʻ֖wòd láֽ⁠ʻàẕabi֑̇ym ʼàni֧y ʻáni֣yţiy wa⁠ʼàş̌ẇre֗⁠ṅẇ ʼàniy֙ ki̇⁠bĕr֣wòş̌ raֽʻàná֔n mimė֖⁠ni̇y pėrĕyĕ⁠ká֥ nimĕẕáֽʼ׃"],[14,9,"מִ֤י חָכָם֙ וְ⁠יָ֣בֵֽן אֵ֔לֶּה נָב֖וֹן וְ⁠יֵֽדָעֵ֑⁠ם כִּֽי־יְשָׁרִ֞ים דַּרְכֵ֣י יְהוָ֗ה וְ⁠צַדִּקִים֙ יֵ֣לְכוּ בָ֔⁠ם וּ⁠פֹשְׁעִ֖ים יִכָּ֥שְׁלוּ בָֽ⁠ם׃","mi֤y ẖákám֙ wĕ⁠yá֣béֽn ʼé֔lėh náb֖wòn wĕ⁠yéֽdáʻé֑⁠m kiֽ̇y-yĕşá̌ri֞ym dȧrĕké֣y yĕhwá֗h wĕ⁠ẕadi̇qiym֙ yé֣lĕkẇ bá֔⁠m ẇ⁠pòşĕ̌ʻi֖ym yiká֥̇şĕ̌lẇ báֽ⁠m׃"]],"fra-lsg1910":[[1,1,"La parole de l'Éternel qui fut adressée à Osée, fils de Beéri, au temps d'Ozias, de Jotham, d'Achaz, d'Ézéchias, rois de Juda, et au temps de Jéroboam, fils de Joas, roi d'Israël.","La parole de l'Éternel qui fut adressée à Osée, fils de Beéri, au temps d'Ozias, de Jotham, d'Achaz, d'Ézéchias, rois de Juda, et au temps de Jéroboam, fils de Joas, roi d'Israël."],[1,2,"La première fois que l'Éternel adressa la parole à Osée, l'Éternel dit à Osée: Va, prends une femme prostituée et des enfants de prostitution; car le pays se prostitue, il abandonne l'Éternel!","La première fois que l'Éternel adressa la parole à Osée, l'Éternel dit à Osée: Va, prends une femme prostituée et des enfants de prostitution; car le pays se prostitue, il abandonne l'Éternel!"],[1,3,"Il alla, et il prit Gomer, fille de Diblaïm. Elle conçut, et lui enfanta un fils.","Il alla, et il prit Gomer, fille de Diblaïm. Elle conçut, et lui enfanta un fils."],[1,4,"Et l'Éternel lui dit: Appelle-le du nom de Jizreel; car encore un peu de temps, et je châtierai la maison de Jéhu pour le sang versé à Jizreel, je mettrai fin au royaume de la maison d'Israël.","Et l'Éternel lui dit: Appelle-le du nom de Jizreel; car encore un peu de temps, et je châtierai la maison de Jéhu pour le sang versé à Jizreel, je mettrai fin au royaume de la maison d'Israël."],[1,5,"En ce jour-là, je briserai l'arc d'Israël dans la vallée de Jizreel.","En ce jour-là, je briserai l'arc d'Israël dans la vallée de Jizreel."],[1,6,"Elle conçut de nouveau, et enfanta une fille. Et l'Éternel dit à Osée: Donne-lui le nom de Lo-Ruchama; car je n'aurai plus pitié de la maison d'Israël, je ne lui pardonnerai plus.","Elle conçut de nouveau, et enfanta une fille. Et l'Éternel dit à Osée: Donne-lui le nom de Lo-Ruchama; car je n'aurai plus pitié de la maison d'Israël, je ne lui pardonnerai plus."],[1,7,"Mais j'aurai pitié de la maison de Juda; je les sauverai par l'Éternel, leur Dieu, et je ne les sauverai ni par l'arc, ni par l'épée, ni par les combats, ni par les chevaux, ni par les cavaliers.","Mais j'aurai pitié de la maison de Juda; je les sauverai par l'Éternel, leur Dieu, et je ne les sauverai ni par l'arc, ni par l'épée, ni par les combats, ni par les chevaux, ni par les cavaliers."],[1,8,"Elle sevra Lo-Ruchama; puis elle conçut, et enfanta un fils.","Elle sevra Lo-Ruchama; puis elle conçut, et enfanta un fils."],[1,9,"Et l'Éternel dit: Donne-lui le nom de Lo-Ammi; car vous n'êtes pas mon peuple, et je ne suis pas votre Dieu.","Et l'Éternel dit: Donne-lui le nom de Lo-Ammi; car vous n'êtes pas mon peuple, et je ne suis pas votre Dieu."],[1,10,"Cependant le nombre des enfants d'Israël sera comme le sable de la mer, qui ne peut ni se mesurer ni se compter; et au lieu qu'on leur disait: Vous n'êtes pas mon peuple! on leur dira: Fils du Dieu vivant!","Cependant le nombre des enfants d'Israël sera comme le sable de la mer, qui ne peut ni se mesurer ni se compter; et au lieu qu'on leur disait: Vous n'êtes pas mon peuple! on leur dira: Fils du Dieu vivant!"],[1,11,"Les enfants de Juda et les enfants d'Israël se rassembleront, se donneront un chef, et sortiront du pays; car grande sera la journée de Jizreel.","Les enfants de Juda et les enfants d'Israël se rassembleront, se donneront un chef, et sortiront du pays; car grande sera la journée de Jizreel."],[2,1,"Dites à vos frères: Ammi! et à vos soeurs: Ruchama!","Dites à vos frères: Ammi! et à vos soeurs: Ruchama!"],[2,2,"Plaidez, plaidez contre votre mère, car elle n'est point ma femme, et je ne suis point son mari! Qu'elle ôte de sa face ses prostitutions, et de son sein ses adultères!","Plaidez, plaidez contre votre mère, car elle n'est point ma femme, et je ne suis point son mari! Qu'elle ôte de sa face ses prostitutions, et de son sein ses adultères!"],[2,3,"Sinon, je la dépouille à nu, je la mets comme au jour de sa naissance, je la rends semblable à un désert, à une terre aride, et je la fais mourir de soif;","Sinon, je la dépouille à nu, je la mets comme au jour de sa naissance, je la rends semblable à un désert, à une terre aride, et je la fais mourir de soif;"],[2,4,"et je n'aurai pas pitié de ses enfants, car ce sont des enfants de prostitution.","et je n'aurai pas pitié de ses enfants, car ce sont des enfants de prostitution."],[2,5,"Leur mère s'est prostituée, celle qui les a conçus s'est déshonorée, car elle a dit: J'irai après mes amants, qui me donnent mon pain et mon eau, ma laine et mon lin, mon huile et ma boisson.","Leur mère s'est prostituée, celle qui les a conçus s'est déshonorée, car elle a dit: J'irai après mes amants, qui me donnent mon pain et mon eau, ma laine et mon lin, mon huile et ma boisson."],[2,6,"C'est pourquoi voici, je vais fermer son chemin avec des épines et y élever un mur, afin qu'elle ne trouve plus ses sentiers.","C'est pourquoi voici, je vais fermer son chemin avec des épines et y élever un mur, afin qu'elle ne trouve plus ses sentiers."],[2,7,"Elle poursuivra ses amants, et ne les atteindra pas; elle les cherchera, et ne les trouvera pas. Puis elle dira: J'irai, et je retournerai vers mon premier mari, car alors j'étais plus heureuse que maintenant.","Elle poursuivra ses amants, et ne les atteindra pas; elle les cherchera, et ne les trouvera pas. Puis elle dira: J'irai, et je retournerai vers mon premier mari, car alors j'étais plus heureuse que maintenant."],[2,8,"Elle n'a pas reconnu que c'était moi qui lui donnais le blé, le moût et l'huile; et l'on a consacré au service de Baal l'argent et l'or que je lui prodiguais.","Elle n'a pas reconnu que c'était moi qui lui donnais le blé, le moût et l'huile; et l'on a consacré au service de Baal l'argent et l'or que je lui prodiguais."],[2,9,"C'est pourquoi je reprendrai mon blé en son temps et mon moût dans sa saison, et j'enlèverai ma laine et mon lin qui devaient couvrir sa nudité.","C'est pourquoi je reprendrai mon blé en son temps et mon moût dans sa saison, et j'enlèverai ma laine et mon lin qui devaient couvrir sa nudité."],[2,10,"Et maintenant je découvrirai sa honte aux yeux de ses amants, et nul ne la délivrera de ma main.","Et maintenant je découvrirai sa honte aux yeux de ses amants, et nul ne la délivrera de ma main."],[2,11,"Je ferai cesser toute sa joie, ses fêtes, ses nouvelles lunes, ses sabbats et toutes ses solennités.","Je ferai cesser toute sa joie, ses fêtes, ses nouvelles lunes, ses sabbats et toutes ses solennités."],[2,12,"Je ravagerai ses vignes et ses figuiers, dont elle disait: C'est le salaire que m'ont donné mes amants! Je les réduirai en une forêt, et les bêtes des champs les dévoreront.","Je ravagerai ses vignes et ses figuiers, dont elle disait: C'est le salaire que m'ont donné mes amants! Je les réduirai en une forêt, et les bêtes des champs les dévoreront."],[2,13,"Je la châtierai pour les jours où elle encensait les Baals, où elle se paraît de ses anneaux et de ses colliers, allait après ses amants, et m'oubliait, dit l'Éternel.","Je la châtierai pour les jours où elle encensait les Baals, où elle se paraît de ses anneaux et de ses colliers, allait après ses amants, et m'oubliait, dit l'Éternel."],[2,14,"C'est pourquoi voici, je veux l'attirer et la conduire au désert, et je parlerai à son coeur.","C'est pourquoi voici, je veux l'attirer et la conduire au désert, et je parlerai à son coeur."],[2,15,"Là, je lui donnerai ses vignes et la vallée d'Acor, comme une porte d'espérance, et là, elle chantera comme au temps de sa jeunesse, et comme au jour où elle remonta du pays d'Égypte.","Là, je lui donnerai ses vignes et la vallée d'Acor, comme une porte d'espérance, et là, elle chantera comme au temps de sa jeunesse, et comme au jour où elle remonta du pays d'Égypte."],[2,16,"En ce jour-là, dit l'Éternel, tu m'appelleras: Mon mari! et tu ne m'appelleras plus: Mon maître!","En ce jour-là, dit l'Éternel, tu m'appelleras: Mon mari! et tu ne m'appelleras plus: Mon maître!"],[2,17,"J'ôterai de sa bouche les noms des Baals, afin qu'on ne les mentionne plus par leurs noms.","J'ôterai de sa bouche les noms des Baals, afin qu'on ne les mentionne plus par leurs noms."],[2,18,"En ce jour-là, je traiterai pour eux une alliance avec les bêtes des champs, les oiseaux du ciel et les reptiles de la terre, je briserai dans le pays l'arc, l'épée et la guerre, et je les ferai reposer avec sécurité.","En ce jour-là, je traiterai pour eux une alliance avec les bêtes des champs, les oiseaux du ciel et les reptiles de la terre, je briserai dans le pays l'arc, l'épée et la guerre, et je les ferai reposer avec sécurité."],[2,19,"Je serai ton fiancé pour toujours; je serai ton fiancé par la justice, la droiture, la grâce et la miséricorde;","Je serai ton fiancé pour toujours; je serai ton fiancé par la justice, la droiture, la grâce et la miséricorde;"],[2,20,"je serai ton fiancé par la fidélité, et tu reconnaîtras l'Éternel.","je serai ton fiancé par la fidélité, et tu reconnaîtras l'Éternel."],[2,21,"En ce jour-là, j'exaucerai, dit l'Éternel, j'exaucerai les cieux, et ils exauceront la terre;","En ce jour-là, j'exaucerai, dit l'Éternel, j'exaucerai les cieux, et ils exauceront la terre;"],[2,22,"la terre exaucera le blé, le moût et l'huile, et ils exauceront Jizreel.","la terre exaucera le blé, le moût et l'huile, et ils exauceront Jizreel."],[2,23,"Je planterai pour moi Lo-Ruchama dans le pays, et je lui ferai miséricorde; je dirai à Lo-Ammi: Tu es mon peuple! et il répondra: Mon Dieu!","Je planterai pour moi Lo-Ruchama dans le pays, et je lui ferai miséricorde; je dirai à Lo-Ammi: Tu es mon peuple! et il répondra: Mon Dieu!"],[3,1,"L'Éternel me dit: Va encore, et aime une femme aimée d'un amant, et adultère; aime-la comme l'Éternel aime les enfants d'Israël, qui se tournent vers d'autres dieux et qui aiment les gâteaux de raisins.","L'Éternel me dit: Va encore, et aime une femme aimée d'un amant, et adultère; aime-la comme l'Éternel aime les enfants d'Israël, qui se tournent vers d'autres dieux et qui aiment les gâteaux de raisins."],[3,2,"Je l'achetai pour quinze sicles d'argent, un homer d'orge et un léthec d'orge.","Je l'achetai pour quinze sicles d'argent, un homer d'orge et un léthec d'orge."],[3,3,"Et je lui dis: Reste longtemps pour moi, ne te livre pas à la prostitution, ne sois à aucun homme, et je serai de même envers toi.","Et je lui dis: Reste longtemps pour moi, ne te livre pas à la prostitution, ne sois à aucun homme, et je serai de même envers toi."],[3,4,"Car les enfants d'Israël resteront longtemps sans roi, sans chef, sans sacrifice, sans statue, sans éphod, et sans théraphim.","Car les enfants d'Israël resteront longtemps sans roi, sans chef, sans sacrifice, sans statue, sans éphod, et sans théraphim."],[3,5,"Après cela, les enfants d'Israël reviendront; ils chercheront l'Éternel, leur Dieu, et David, leur roi; et ils tressailliront à la vue de l'Éternel et de sa bonté, dans la suite des temps.","Après cela, les enfants d'Israël reviendront; ils chercheront l'Éternel, leur Dieu, et David, leur roi; et ils tressailliront à la vue de l'Éternel et de sa bonté, dans la suite des temps."],[4,1,"Écoutez la parole de l'Éternel, enfants d'Israël! Car l'Éternel a un procès avec les habitants du pays, Parce qu'il n'y a point de vérité, point de miséricorde, Point de connaissance de Dieu dans le pays.","Écoutez la parole de l'Éternel, enfants d'Israël! Car l'Éternel a un procès avec les habitants du pays, Parce qu'il n'y a point de vérité, point de miséricorde, Point de connaissance de Dieu dans le pays."],[4,2,"Il n'y a que parjures et mensonges, Assassinats, vols et adultères; On use de violence, on commet meurtre sur meurtre.","Il n'y a que parjures et mensonges, Assassinats, vols et adultères; On use de violence, on commet meurtre sur meurtre."],[4,3,"C'est pourquoi le pays sera dans le deuil, Tous ceux qui l'habitent seront languissants, Et avec eux les bêtes des champs et les oiseaux du ciel; Même les poissons de la mer disparaîtront.","C'est pourquoi le pays sera dans le deuil, Tous ceux qui l'habitent seront languissants, Et avec eux les bêtes des champs et les oiseaux du ciel; Même les poissons de la mer disparaîtront."],[4,4,"Mais que nul ne conteste, que nul ne se livre aux reproches; Car ton peuple est comme ceux qui disputent avec les sacrificateurs.","Mais que nul ne conteste, que nul ne se livre aux reproches; Car ton peuple est comme ceux qui disputent avec les sacrificateurs."],[4,5,"Tu tomberas de jour, Le prophète avec toi tombera de nuit, Et je détruirai ta mère.","Tu tomberas de jour, Le prophète avec toi tombera de nuit, Et je détruirai ta mère."],[4,6,"Mon peuple est détruit, parce qu'il lui manque la connaissance. Puisque tu as rejeté la connaissance, Je te rejetterai, et tu seras dépouillé de mon sacerdoce; Puisque tu as oublié la loi de ton Dieu, J'oublierai aussi tes enfants.","Mon peuple est détruit, parce qu'il lui manque la connaissance. Puisque tu as rejeté la connaissance, Je te rejetterai, et tu seras dépouillé de mon sacerdoce; Puisque tu as oublié la loi de ton Dieu, J'oublierai aussi tes enfants."],[4,7,"Plus ils se sont multipliés, plus ils ont péché contre moi: Je changerai leur gloire en ignominie.","Plus ils se sont multipliés, plus ils ont péché contre moi: Je changerai leur gloire en ignominie."],[4,8,"Ils se repaissent des péchés de mon peuple, Ils sont avides de ses iniquités.","Ils se repaissent des péchés de mon peuple, Ils sont avides de ses iniquités."],[4,9,"Il en sera du sacrificateur comme du peuple; Je le châtierai selon ses voies, Je lui rendrai selon ses oeuvres.","Il en sera du sacrificateur comme du peuple; Je le châtierai selon ses voies, Je lui rendrai selon ses oeuvres."],[4,10,"Ils mangeront sans se rassasier, Ils se prostitueront sans multiplier, Parce qu'ils ont abandonné l'Éternel et ses commandements.","Ils mangeront sans se rassasier, Ils se prostitueront sans multiplier, Parce qu'ils ont abandonné l'Éternel et ses commandements."],[4,11,"La prostitution, le vin et le moût, font perdre le sens.","La prostitution, le vin et le moût, font perdre le sens."],[4,12,"Mon peuple consulte son bois, Et c'est son bâton qui lui parle; Car l'esprit de prostitution égare, Et ils se prostituent loin de leur Dieu.","Mon peuple consulte son bois, Et c'est son bâton qui lui parle; Car l'esprit de prostitution égare, Et ils se prostituent loin de leur Dieu."],[4,13,"Ils sacrifient sur le sommet des montagnes, Ils brûlent de l'encens sur les collines, Sous les chênes, les peupliers, les térébinthes, Dont l'ombrage est agréable. C'est pourquoi vos filles se prostituent, Et vos belles-filles sont adultères.","Ils sacrifient sur le sommet des montagnes, Ils brûlent de l'encens sur les collines, Sous les chênes, les peupliers, les térébinthes, Dont l'ombrage est agréable. C'est pourquoi vos filles se prostituent, Et vos belles-filles sont adultères."],[4,14,"Je ne punirai pas vos filles parce qu'elles se prostituent, Ni vos belles-filles parce qu'elles sont adultères, Car eux-mêmes vont à l'écart avec des prostituées, Et sacrifient avec des femmes débauchées. Le peuple insensé court à sa perte.","Je ne punirai pas vos filles parce qu'elles se prostituent, Ni vos belles-filles parce qu'elles sont adultères, Car eux-mêmes vont à l'écart avec des prostituées, Et sacrifient avec des femmes débauchées. Le peuple insensé court à sa perte."],[4,15,"Si tu te livres à la prostitution, ô Israël, Que Juda ne se rende pas coupable; N'allez pas à Guilgal, ne montez pas à Beth-Aven, Et ne jurez pas: L'Éternel est vivant!","Si tu te livres à la prostitution, ô Israël, Que Juda ne se rende pas coupable; N'allez pas à Guilgal, ne montez pas à Beth-Aven, Et ne jurez pas: L'Éternel est vivant!"],[4,16,"Parce qu'Israël se révolte comme une génisse indomptable, Maintenant l'Éternel le fera paître Comme un agneau dans de vastes plaines.","Parce qu'Israël se révolte comme une génisse indomptable, Maintenant l'Éternel le fera paître Comme un agneau dans de vastes plaines."],[4,17,"Éphraïm est attaché aux idoles: laisse-le!","Éphraïm est attaché aux idoles: laisse-le!"],[4,18,"À peine ont-ils cessé de boire Qu'ils se livrent à la prostitution; Leurs chefs sont avides d'ignominie.","À peine ont-ils cessé de boire Qu'ils se livrent à la prostitution; Leurs chefs sont avides d'ignominie."],[4,19,"Le vent les enveloppera de ses ailes, Et ils auront honte de leurs sacrifices.","Le vent les enveloppera de ses ailes, Et ils auront honte de leurs sacrifices."],[5,1,"Écoutez ceci, sacrificateurs! Sois attentive, maison d'Israël! Prête l'oreille, maison du roi! Car c'est à vous que le jugement s'adresse, Parce que vous avez été un piège à Mitspa, Et un filet tendu sur le Thabor.","Écoutez ceci, sacrificateurs! Sois attentive, maison d'Israël! Prête l'oreille, maison du roi! Car c'est à vous que le jugement s'adresse, Parce que vous avez été un piège à Mitspa, Et un filet tendu sur le Thabor."],[5,2,"Par leurs sacrifices, les infidèles s'enfoncent dans le crime, Mais j'aurai des châtiments pour eux tous.","Par leurs sacrifices, les infidèles s'enfoncent dans le crime, Mais j'aurai des châtiments pour eux tous."],[5,3,"Je connais Éphraïm, Et Israël ne m'est point caché; Car maintenant, Éphraïm, tu t'es prostitué, Et Israël s'est souillé.","Je connais Éphraïm, Et Israël ne m'est point caché; Car maintenant, Éphraïm, tu t'es prostitué, Et Israël s'est souillé."],[5,4,"Leurs oeuvres ne leur permettent pas de revenir à leur Dieu, Parce que l'esprit de prostitution est au milieu d'eux, Et parce qu'ils ne connaissent pas l'Éternel.","Leurs oeuvres ne leur permettent pas de revenir à leur Dieu, Parce que l'esprit de prostitution est au milieu d'eux, Et parce qu'ils ne connaissent pas l'Éternel."],[5,5,"L'orgueil d'Israël témoigne contre lui; Israël et Éphraïm tomberont par leur iniquité; Avec eux aussi tombera Juda.","L'orgueil d'Israël témoigne contre lui; Israël et Éphraïm tomberont par leur iniquité; Avec eux aussi tombera Juda."],[5,6,"Ils iront avec leurs brebis et leurs boeufs chercher l'Éternel, Mais ils ne le trouveront point: Il s'est retiré du milieu d'eux.","Ils iront avec leurs brebis et leurs boeufs chercher l'Éternel, Mais ils ne le trouveront point: Il s'est retiré du milieu d'eux."],[5,7,"Ils ont été infidèles à l'Éternel, Car ils ont engendré des enfants illégitimes; Maintenant un mois suffira pour les dévorer avec leurs biens.","Ils ont été infidèles à l'Éternel, Car ils ont engendré des enfants illégitimes; Maintenant un mois suffira pour les dévorer avec leurs biens."],[5,8,"Sonnez de la trompette à Guibea, Sonnez de la trompette à Rama! Poussez des cris à Beth-Aven! Derrière toi, Benjamin!","Sonnez de la trompette à Guibea, Sonnez de la trompette à Rama! Poussez des cris à Beth-Aven! Derrière toi, Benjamin!"],[5,9,"Éphraïm sera dévasté au jour du châtiment; J'annonce aux tribus d'Israël une chose certaine.","Éphraïm sera dévasté au jour du châtiment; J'annonce aux tribus d'Israël une chose certaine."],[5,10,"Les chefs de Juda sont comme ceux qui déplacent les bornes; Je répandrai sur eux ma colère comme un torrent.","Les chefs de Juda sont comme ceux qui déplacent les bornes; Je répandrai sur eux ma colère comme un torrent."],[5,11,"Éphraïm est opprimé, brisé par le jugement, Car il a suivi les préceptes qui lui plaisaient.","Éphraïm est opprimé, brisé par le jugement, Car il a suivi les préceptes qui lui plaisaient."],[5,12,"Je serai comme une teigne pour Éphraïm, Comme une carie pour la maison de Juda.","Je serai comme une teigne pour Éphraïm, Comme une carie pour la maison de Juda."],[5,13,"Éphraïm voit son mal, et Juda ses plaies; Éphraïm se rend en Assyrie, et s'adresse au roi Jareb; Mais ce roi ne pourra ni vous guérir, Ni porter remède à vos plaies.","Éphraïm voit son mal, et Juda ses plaies; Éphraïm se rend en Assyrie, et s'adresse au roi Jareb; Mais ce roi ne pourra ni vous guérir, Ni porter remède à vos plaies."],[5,14,"Je serai comme un lion pour Éphraïm, Comme un lionceau pour la maison de Juda; Moi, moi, je déchirerai, puis je m'en irai, J'emporterai, et nul n'enlèvera ma proie.","Je serai comme un lion pour Éphraïm, Comme un lionceau pour la maison de Juda; Moi, moi, je déchirerai, puis je m'en irai, J'emporterai, et nul n'enlèvera ma proie."],[5,15,"Je m'en irai, je reviendrai dans ma demeure, Jusqu'à ce qu'ils s'avouent coupables et cherchent ma face. Quand ils seront dans la détresse, ils auront recours à moi.","Je m'en irai, je reviendrai dans ma demeure, Jusqu'à ce qu'ils s'avouent coupables et cherchent ma face. Quand ils seront dans la détresse, ils auront recours à moi."],[6,1,"Venez, retournons à l'Éternel! Car il a déchiré, mais il nous guérira; Il a frappé, mais il bandera nos plaies.","Venez, retournons à l'Éternel! Car il a déchiré, mais il nous guérira; Il a frappé, mais il bandera nos plaies."],[6,2,"Il nous rendra la vie dans deux jours; Le troisième jour il nous relèvera, Et nous vivrons devant lui.","Il nous rendra la vie dans deux jours; Le troisième jour il nous relèvera, Et nous vivrons devant lui."],[6,3,"Connaissons, cherchons à connaître l'Éternel; Sa venue est aussi certaine que celle de l'aurore. Il viendra pour nous comme la pluie, Comme la pluie du printemps qui arrose la terre.","Connaissons, cherchons à connaître l'Éternel; Sa venue est aussi certaine que celle de l'aurore. Il viendra pour nous comme la pluie, Comme la pluie du printemps qui arrose la terre."],[6,4,"Que te ferai-je, Éphraïm? Que te ferai-je, Juda? Votre piété est comme la nuée du matin, Comme la rosée qui bientôt se dissipe.","Que te ferai-je, Éphraïm? Que te ferai-je, Juda? Votre piété est comme la nuée du matin, Comme la rosée qui bientôt se dissipe."],[6,5,"C'est pourquoi je les frapperai par les prophètes, Je les tuerai par les paroles de ma bouche, Et mes jugements éclateront comme la lumière.","C'est pourquoi je les frapperai par les prophètes, Je les tuerai par les paroles de ma bouche, Et mes jugements éclateront comme la lumière."],[6,6,"Car j'aime la piété et non les sacrifices, Et la connaissance de Dieu plus que les holocaustes.","Car j'aime la piété et non les sacrifices, Et la connaissance de Dieu plus que les holocaustes."],[6,7,"Ils ont, comme le vulgaire, transgressé l'alliance; C'est alors qu'ils m'ont été infidèles.","Ils ont, comme le vulgaire, transgressé l'alliance; C'est alors qu'ils m'ont été infidèles."],[6,8,"Galaad est une ville de malfaiteurs, Elle porte des traces de sang.","Galaad est une ville de malfaiteurs, Elle porte des traces de sang."],[6,9,"La troupe des sacrificateurs est comme une bande en embuscade, Commettant des assassinats sur le chemin de Sichem; Car ils se livrent au crime.","La troupe des sacrificateurs est comme une bande en embuscade, Commettant des assassinats sur le chemin de Sichem; Car ils se livrent au crime."],[6,10,"Dans la maison d'Israël j'ai vu des choses horribles: Là Éphraïm se prostitue, Israël se souille.","Dans la maison d'Israël j'ai vu des choses horribles: Là Éphraïm se prostitue, Israël se souille."],[6,11,"À toi aussi, Juda, une moisson est préparée, Quand je ramènerai les captifs de mon peuple.","À toi aussi, Juda, une moisson est préparée, Quand je ramènerai les captifs de mon peuple."],[7,1,"Lorsque je voulais guérir Israël, L'iniquité d'Éphraïm et la méchanceté de Samarie se sont révélées, Car ils ont agi frauduleusement; Le voleur est arrivé, la bande s'est répandue au dehors.","Lorsque je voulais guérir Israël, L'iniquité d'Éphraïm et la méchanceté de Samarie se sont révélées, Car ils ont agi frauduleusement; Le voleur est arrivé, la bande s'est répandue au dehors."],[7,2,"Ils ne se disent pas dans leur coeur Que je me souviens de toute leur méchanceté; Maintenant leurs oeuvres les entourent, Elles sont devant ma face.","Ils ne se disent pas dans leur coeur Que je me souviens de toute leur méchanceté; Maintenant leurs oeuvres les entourent, Elles sont devant ma face."],[7,3,"Ils réjouissent le roi par leur méchanceté, Et les chefs par leurs mensonges.","Ils réjouissent le roi par leur méchanceté, Et les chefs par leurs mensonges."],[7,4,"Ils sont tous adultères, Semblables à un four chauffé par le boulanger: Il cesse d'attiser le feu Depuis qu'il a pétri la pâte jusqu'à ce qu'elle soit levée.","Ils sont tous adultères, Semblables à un four chauffé par le boulanger: Il cesse d'attiser le feu Depuis qu'il a pétri la pâte jusqu'à ce qu'elle soit levée."],[7,5,"Au jour de notre roi, Les chefs se rendent malades par les excès du vin; Le roi tend la main aux moqueurs.","Au jour de notre roi, Les chefs se rendent malades par les excès du vin; Le roi tend la main aux moqueurs."],[7,6,"Ils appliquent aux embûches leur coeur pareil à un four; Toute la nuit dort leur boulanger, Et au matin le four brûle comme un feu embrasé.","Ils appliquent aux embûches leur coeur pareil à un four; Toute la nuit dort leur boulanger, Et au matin le four brûle comme un feu embrasé."],[7,7,"Ils sont tous ardents comme un four, Et ils dévorent leurs juges; Tous leurs rois tombent: Aucun d'eux ne m'invoque.","Ils sont tous ardents comme un four, Et ils dévorent leurs juges; Tous leurs rois tombent: Aucun d'eux ne m'invoque."],[7,8,"Éphraïm se mêle avec les peuples, Éphraïm est un gâteau qui n'a pas été retourné.","Éphraïm se mêle avec les peuples, Éphraïm est un gâteau qui n'a pas été retourné."],[7,9,"Des étrangers consument sa force, Et il ne s'en doute pas; La vieillesse s'empare de lui, Et il ne s'en doute pas.","Des étrangers consument sa force, Et il ne s'en doute pas; La vieillesse s'empare de lui, Et il ne s'en doute pas."],[7,10,"L'orgueil d'Israël témoigne contre lui; Ils ne reviennent pas à l'Éternel, leur Dieu, Et ils ne le cherchent pas, malgré tout cela.","L'orgueil d'Israël témoigne contre lui; Ils ne reviennent pas à l'Éternel, leur Dieu, Et ils ne le cherchent pas, malgré tout cela."],[7,11,"Éphraïm est comme une colombe stupide, sans intelligence; Ils implorent l'Égypte, ils vont en Assyrie.","Éphraïm est comme une colombe stupide, sans intelligence; Ils implorent l'Égypte, ils vont en Assyrie."],[7,12,"S'ils partent, j'étendrai sur eux mon filet, Je les précipiterai comme les oiseaux du ciel; Je les châtierai, comme ils en ont été avertis dans leur assemblée.","S'ils partent, j'étendrai sur eux mon filet, Je les précipiterai comme les oiseaux du ciel; Je les châtierai, comme ils en ont été avertis dans leur assemblée."],[7,13,"Malheur à eux, parce qu'ils me fuient! Ruine sur eux, parce qu'ils me sont infidèles! Je voudrais les sauver, Mais ils disent contre moi des paroles mensongères.","Malheur à eux, parce qu'ils me fuient! Ruine sur eux, parce qu'ils me sont infidèles! Je voudrais les sauver, Mais ils disent contre moi des paroles mensongères."],[7,14,"Ils ne crient pas vers moi dans leur coeur, Mais ils se lamentent sur leur couche; Ils se rassemblent pour avoir du blé et du moût, Et ils s'éloignent de moi.","Ils ne crient pas vers moi dans leur coeur, Mais ils se lamentent sur leur couche; Ils se rassemblent pour avoir du blé et du moût, Et ils s'éloignent de moi."],[7,15,"Je les ai châtiés, j'ai fortifié leurs bras; Et ils méditent le mal contre moi.","Je les ai châtiés, j'ai fortifié leurs bras; Et ils méditent le mal contre moi."],[7,16,"Ce n'est pas au Très-Haut qu'ils retournent; Ils sont comme un arc trompeur. Leurs chefs tomberont par l'épée, À cause de l'insolence de leur langue. C'est ce qui les rendra un objet de risée dans le pays d'Égypte.","Ce n'est pas au Très-Haut qu'ils retournent; Ils sont comme un arc trompeur. Leurs chefs tomberont par l'épée, À cause de l'insolence de leur langue. C'est ce qui les rendra un objet de risée dans le pays d'Égypte."],[8,1,"Embouche la trompette! L'ennemi fond comme un aigle sur la maison de l'Éternel, Parce qu'ils ont violé mon alliance, Et transgressé ma loi.","Embouche la trompette! L'ennemi fond comme un aigle sur la maison de l'Éternel, Parce qu'ils ont violé mon alliance, Et transgressé ma loi."],[8,2,"Ils crieront vers moi: Mon Dieu, nous te connaissons, nous Israël!","Ils crieront vers moi: Mon Dieu, nous te connaissons, nous Israël!"],[8,3,"Israël a rejeté le bien; L'ennemi le poursuivra.","Israël a rejeté le bien; L'ennemi le poursuivra."],[8,4,"Ils ont établi des rois sans mon ordre, Et des chefs à mon insu; Ils ont fait des idoles avec leur argent et leur or; C'est pourquoi ils seront anéantis.","Ils ont établi des rois sans mon ordre, Et des chefs à mon insu; Ils ont fait des idoles avec leur argent et leur or; C'est pourquoi ils seront anéantis."],[8,5,"L'Éternel a rejeté ton veau, Samarie! Ma colère s'est enflammée contre eux. Jusques à quand refuseront-ils de se purifier?","L'Éternel a rejeté ton veau, Samarie! Ma colère s'est enflammée contre eux. Jusques à quand refuseront-ils de se purifier?"],[8,6,"Il vient d'Israël, un ouvrier l'a fabriqué, Et ce n'est pas un Dieu; C'est pourquoi le veau de Samarie sera mis en pièces.","Il vient d'Israël, un ouvrier l'a fabriqué, Et ce n'est pas un Dieu; C'est pourquoi le veau de Samarie sera mis en pièces."],[8,7,"Puisqu'ils ont semé du vent, ils moissonneront la tempête; Ils n'auront pas un épi de blé; Ce qui poussera ne donnera point de farine, Et s'il y en avait, des étrangers la dévoreraient.","Puisqu'ils ont semé du vent, ils moissonneront la tempête; Ils n'auront pas un épi de blé; Ce qui poussera ne donnera point de farine, Et s'il y en avait, des étrangers la dévoreraient."],[8,8,"Israël est anéanti! Ils sont maintenant parmi les nations Comme un vase qui n'a pas de prix.","Israël est anéanti! Ils sont maintenant parmi les nations Comme un vase qui n'a pas de prix."],[8,9,"Car ils sont allés en Assyrie, Comme un âne sauvage qui se tient à l'écart; Éphraïm a fait des présents pour avoir des amis.","Car ils sont allés en Assyrie, Comme un âne sauvage qui se tient à l'écart; Éphraïm a fait des présents pour avoir des amis."],[8,10,"Quand même ils font des présents parmi les nations, Je vais maintenant les rassembler, Et bientôt ils souffriront sous le fardeau du roi des princes.","Quand même ils font des présents parmi les nations, Je vais maintenant les rassembler, Et bientôt ils souffriront sous le fardeau du roi des princes."],[8,11,"Éphraïm a multiplié les autels pour pécher, Et ces autels l'ont fait tomber dans le péché.","Éphraïm a multiplié les autels pour pécher, Et ces autels l'ont fait tomber dans le péché."],[8,12,"Que j'écrive pour lui toutes les ordonnances de ma loi, Elles sont regardées comme quelque chose d'étranger.","Que j'écrive pour lui toutes les ordonnances de ma loi, Elles sont regardées comme quelque chose d'étranger."],[8,13,"Ils immolent des victimes qu'ils m'offrent, Et ils en mangent la chair: L'Éternel n'y prend point de plaisir. Maintenant l'Éternel se souvient de leur iniquité, Et il punira leurs péchés: Ils retourneront en Égypte.","Ils immolent des victimes qu'ils m'offrent, Et ils en mangent la chair: L'Éternel n'y prend point de plaisir. Maintenant l'Éternel se souvient de leur iniquité, Et il punira leurs péchés: Ils retourneront en Égypte."],[8,14,"Israël a oublié celui qui l'a fait, Et a bâti des palais, Et Juda a multiplié les villes fortes; Mais j'enverrai le feu dans leurs villes, Et il en dévorera les palais.","Israël a oublié celui qui l'a fait, Et a bâti des palais, Et Juda a multiplié les villes fortes; Mais j'enverrai le feu dans leurs villes, Et il en dévorera les palais."],[9,1,"Israël, ne te livre pas à la joie, à l'allégresse, comme les peuples, De ce que tu t'es prostitué en abandonnant l'Éternel, De ce que tu as aimé un salaire impur dans toutes les aires à blé!","Israël, ne te livre pas à la joie, à l'allégresse, comme les peuples, De ce que tu t'es prostitué en abandonnant l'Éternel, De ce que tu as aimé un salaire impur dans toutes les aires à blé!"],[9,2,"L'aire et le pressoir ne les nourriront pas, Et le moût leur fera défaut.","L'aire et le pressoir ne les nourriront pas, Et le moût leur fera défaut."],[9,3,"Ils ne resteront pas dans le pays de l'Éternel; Éphraïm retournera en Égypte, Et ils mangeront en Assyrie des aliments impurs.","Ils ne resteront pas dans le pays de l'Éternel; Éphraïm retournera en Égypte, Et ils mangeront en Assyrie des aliments impurs."],[9,4,"Ils ne feront pas à l'Éternel des libations de vin: Elles ne lui seraient point agréables. Leurs sacrifices seront pour eux comme un pain de deuil; Tous ceux qui en mangeront se rendront impurs; Car leur pain ne sera que pour eux, Il n'entrera point dans la maison de l'Éternel.","Ils ne feront pas à l'Éternel des libations de vin: Elles ne lui seraient point agréables. Leurs sacrifices seront pour eux comme un pain de deuil; Tous ceux qui en mangeront se rendront impurs; Car leur pain ne sera que pour eux, Il n'entrera point dans la maison de l'Éternel."],[9,5,"Que ferez-vous aux jours solennels, Aux jours des fêtes de l'Éternel?","Que ferez-vous aux jours solennels, Aux jours des fêtes de l'Éternel?"],[9,6,"Car voici, ils partent à cause de la dévastation; L'Égypte les recueillera, Moph leur donnera des sépulcres; Ce qu'ils ont de précieux, leur argent, sera la proie des ronces, Et les épines croîtront dans leurs tentes.","Car voici, ils partent à cause de la dévastation; L'Égypte les recueillera, Moph leur donnera des sépulcres; Ce qu'ils ont de précieux, leur argent, sera la proie des ronces, Et les épines croîtront dans leurs tentes."],[9,7,"Ils arrivent, les jours du châtiment, Ils arrivent, les jours de la rétribution: Israël va l'éprouver! Le prophète est fou, l'homme inspiré a le délire, À cause de la grandeur de tes iniquités et de tes rébellions.","Ils arrivent, les jours du châtiment, Ils arrivent, les jours de la rétribution: Israël va l'éprouver! Le prophète est fou, l'homme inspiré a le délire, À cause de la grandeur de tes iniquités et de tes rébellions."],[9,8,"Éphraïm est une sentinelle contre mon Dieu; Le prophète... un filet d'oiseleur est sur toutes ses voies, Un ennemi dans la maison de son Dieu.","Éphraïm est une sentinelle contre mon Dieu; Le prophète... un filet d'oiseleur est sur toutes ses voies, Un ennemi dans la maison de son Dieu."],[9,9,"Ils sont plongés dans la corruption, comme aux jours de Guibea; L'Éternel se souviendra de leur iniquité, Il punira leurs péchés.","Ils sont plongés dans la corruption, comme aux jours de Guibea; L'Éternel se souviendra de leur iniquité, Il punira leurs péchés."],[9,10,"J'ai trouvé Israël comme des raisins dans le désert, J'ai vu vos pères comme les premiers fruits d'un figuier; Mais ils sont allés vers Baal-Peor, Ils se sont consacrés à l'infâme idole, Et ils sont devenus abominables comme l'objet de leur amour.","J'ai trouvé Israël comme des raisins dans le désert, J'ai vu vos pères comme les premiers fruits d'un figuier; Mais ils sont allés vers Baal-Peor, Ils se sont consacrés à l'infâme idole, Et ils sont devenus abominables comme l'objet de leur amour."],[9,11,"La gloire d'Éphraïm s'envolera comme un oiseau: Plus de naissance, plus de grossesse, plus de conception.","La gloire d'Éphraïm s'envolera comme un oiseau: Plus de naissance, plus de grossesse, plus de conception."],[9,12,"S'ils élèvent leurs enfants, Je les en priverai avant qu'ils soient des hommes; Et malheur à eux, quand je les abandonnerai!","S'ils élèvent leurs enfants, Je les en priverai avant qu'ils soient des hommes; Et malheur à eux, quand je les abandonnerai!"],[9,13,"Éphraïm, aussi loin que portent mes regards du côté de Tyr, Est planté dans un lieu agréable; Mais Éphraïm mènera ses enfants vers celui qui les tuera.","Éphraïm, aussi loin que portent mes regards du côté de Tyr, Est planté dans un lieu agréable; Mais Éphraïm mènera ses enfants vers celui qui les tuera."],[9,14,"Donne-leur, ô Éternel!... Que leur donneras-tu?... Donne-leur un sein qui avorte et des mamelles desséchées!","Donne-leur, ô Éternel!... Que leur donneras-tu?... Donne-leur un sein qui avorte et des mamelles desséchées!"],[9,15,"Toute leur méchanceté se montre à Guilgal; C'est là que je les ai pris en aversion. À cause de la malice de leurs oeuvres, Je les chasserai de ma maison. Je ne les aimerai plus; Tous leurs chefs sont des rebelles.","Toute leur méchanceté se montre à Guilgal; C'est là que je les ai pris en aversion. À cause de la malice de leurs oeuvres, Je les chasserai de ma maison. Je ne les aimerai plus; Tous leurs chefs sont des rebelles."],[9,16,"Éphraïm est frappé, sa racine est devenue sèche; Ils ne porteront plus de fruit; Et s'ils ont des enfants, Je ferai périr les objets de leur tendresse.","Éphraïm est frappé, sa racine est devenue sèche; Ils ne porteront plus de fruit; Et s'ils ont des enfants, Je ferai périr les objets de leur tendresse."],[9,17,"Mon Dieu les rejettera, parce qu'ils ne l'ont pas écouté, Et ils seront errants parmi les nations.","Mon Dieu les rejettera, parce qu'ils ne l'ont pas écouté, Et ils seront errants parmi les nations."],[10,1,"Israël était une vigne féconde, Qui rendait beaucoup de fruits. Plus ses fruits étaient abondants, Plus il a multiplié les autels; Plus son pays était prospère, Plus il a embelli les statues.","Israël était une vigne féconde, Qui rendait beaucoup de fruits. Plus ses fruits étaient abondants, Plus il a multiplié les autels; Plus son pays était prospère, Plus il a embelli les statues."],[10,2,"Leur coeur est partagé: ils vont en porter la peine. L'Éternel renversera leurs autels, détruira leurs statues.","Leur coeur est partagé: ils vont en porter la peine. L'Éternel renversera leurs autels, détruira leurs statues."],[10,3,"Et bientôt ils diront: Nous n'avons point de roi, Car nous n'avons pas craint l'Éternel; Et le roi, que pourrait-il faire pour nous?","Et bientôt ils diront: Nous n'avons point de roi, Car nous n'avons pas craint l'Éternel; Et le roi, que pourrait-il faire pour nous?"],[10,4,"Ils prononcent des paroles vaines, des serments faux, Lorsqu'ils concluent une alliance: Aussi le châtiment germera, comme une plante vénéneuse Dans les sillons des champs.","Ils prononcent des paroles vaines, des serments faux, Lorsqu'ils concluent une alliance: Aussi le châtiment germera, comme une plante vénéneuse Dans les sillons des champs."],[10,5,"Les habitants de Samarie seront consternés au sujet des veaux de Beth-Aven; Le peuple mènera deuil sur l'idole, Et ses prêtres trembleront pour elle, Pour sa gloire, qui va disparaître du milieu d'eux.","Les habitants de Samarie seront consternés au sujet des veaux de Beth-Aven; Le peuple mènera deuil sur l'idole, Et ses prêtres trembleront pour elle, Pour sa gloire, qui va disparaître du milieu d'eux."],[10,6,"Elle sera transportée en Assyrie, Pour servir de présent au roi Jareb. La confusion saisira Éphraïm, Et Israël aura honte de ses desseins.","Elle sera transportée en Assyrie, Pour servir de présent au roi Jareb. La confusion saisira Éphraïm, Et Israël aura honte de ses desseins."],[10,7,"C'en est fait de Samarie, de son roi, Comme de l'écume à la surface des eaux.","C'en est fait de Samarie, de son roi, Comme de l'écume à la surface des eaux."],[10,8,"Les hauts lieux de Beth-Aven, où Israël a péché, seront détruits; L'épine et la ronce croîtront sur leurs autels. Ils diront aux montagnes: Couvrez-nous! Et aux collines: Tombez sur nous!","Les hauts lieux de Beth-Aven, où Israël a péché, seront détruits; L'épine et la ronce croîtront sur leurs autels. Ils diront aux montagnes: Couvrez-nous! Et aux collines: Tombez sur nous!"],[10,9,"Depuis les jours de Guibea tu as péché, Israël! Là ils restèrent debout, La guerre contre les méchants ne les atteignit pas à Guibea.","Depuis les jours de Guibea tu as péché, Israël! Là ils restèrent debout, La guerre contre les méchants ne les atteignit pas à Guibea."],[10,10,"Je les châtierai à mon gré, Et des peuples s'assembleront contre eux, Quand on les enchaînera pour leur double iniquité.","Je les châtierai à mon gré, Et des peuples s'assembleront contre eux, Quand on les enchaînera pour leur double iniquité."],[10,11,"Éphraïm est une génisse dressée, et qui aime à fouler le grain, Mais je m'approcherai de son beau cou; J'attellerai Éphraïm, Juda labourera, Jacob hersera.","Éphraïm est une génisse dressée, et qui aime à fouler le grain, Mais je m'approcherai de son beau cou; J'attellerai Éphraïm, Juda labourera, Jacob hersera."],[10,12,"Semez selon la justice, moissonnez selon la miséricorde, Défrichez-vous un champ nouveau! Il est temps de chercher l'Éternel, Jusqu'à ce qu'il vienne, et répande pour vous la justice.","Semez selon la justice, moissonnez selon la miséricorde, Défrichez-vous un champ nouveau! Il est temps de chercher l'Éternel, Jusqu'à ce qu'il vienne, et répande pour vous la justice."],[10,13,"Vous avez cultivé le mal, moissonné l'iniquité, Mangé le fruit du mensonge; Car tu as eu confiance dans ta voie, Dans le nombre de tes vaillants hommes.","Vous avez cultivé le mal, moissonné l'iniquité, Mangé le fruit du mensonge; Car tu as eu confiance dans ta voie, Dans le nombre de tes vaillants hommes."],[10,14,"Il s'élèvera un tumulte parmi ton peuple, Et toutes tes forteresses seront détruites, Comme fut détruite Schalman Beth-Arbel, Au jour de la guerre, Où la mère fut écrasée avec les enfants.","Il s'élèvera un tumulte parmi ton peuple, Et toutes tes forteresses seront détruites, Comme fut détruite Schalman Beth-Arbel, Au jour de la guerre, Où la mère fut écrasée avec les enfants."],[10,15,"Voilà ce que vous attirera Béthel, À cause de votre extrême méchanceté, Vienne l'aurore, et c'en est fait du roi d'Israël.","Voilà ce que vous attirera Béthel, À cause de votre extrême méchanceté, Vienne l'aurore, et c'en est fait du roi d'Israël."],[11,1,"Quand Israël était jeune, je l'aimais, Et j'appelai mon fils hors d'Égypte.","Quand Israël était jeune, je l'aimais, Et j'appelai mon fils hors d'Égypte."],[11,2,"Mais ils se sont éloignés de ceux qui les appelaient; Ils ont sacrifié aux Baals, Et offert de l'encens aux idoles.","Mais ils se sont éloignés de ceux qui les appelaient; Ils ont sacrifié aux Baals, Et offert de l'encens aux idoles."],[11,3,"C'est moi qui guidai les pas d'Éphraïm, Le soutenant par ses bras; Et ils n'ont pas vu que je les guérissais.","C'est moi qui guidai les pas d'Éphraïm, Le soutenant par ses bras; Et ils n'ont pas vu que je les guérissais."],[11,4,"Je les tirai avec des liens d'humanité, avec des cordages d'amour, Je fus pour eux comme celui qui aurait relâché le joug près de leur bouche, Et je leur présentai de la nourriture.","Je les tirai avec des liens d'humanité, avec des cordages d'amour, Je fus pour eux comme celui qui aurait relâché le joug près de leur bouche, Et je leur présentai de la nourriture."],[11,5,"Ils ne retourneront pas au pays d'Égypte; Mais l'Assyrien sera leur roi, Parce qu'ils ont refusé de revenir à moi.","Ils ne retourneront pas au pays d'Égypte; Mais l'Assyrien sera leur roi, Parce qu'ils ont refusé de revenir à moi."],[11,6,"L'épée fondra sur leurs villes, Anéantira, dévorera leurs soutiens, À cause des desseins qu'ils ont eus.","L'épée fondra sur leurs villes, Anéantira, dévorera leurs soutiens, À cause des desseins qu'ils ont eus."],[11,7,"Mon peuple est enclin à s'éloigner de moi; On les rappelle vers le Très-Haut, Mais aucun d'eux ne l'exalte.","Mon peuple est enclin à s'éloigner de moi; On les rappelle vers le Très-Haut, Mais aucun d'eux ne l'exalte."],[11,8,"Que ferai-je de toi, Éphraïm? Dois-je te livrer, Israël? Te traiterai-je comme Adma? Te rendrai-je semblable à Tseboïm? Mon coeur s'agite au dedans de moi, Toutes mes compassions sont émues.","Que ferai-je de toi, Éphraïm? Dois-je te livrer, Israël? Te traiterai-je comme Adma? Te rendrai-je semblable à Tseboïm? Mon coeur s'agite au dedans de moi, Toutes mes compassions sont émues."],[11,9,"Je n'agirai pas selon mon ardente colère, Je renonce à détruire Éphraïm; Car je suis Dieu, et non pas un homme, Je suis le Saint au milieu de toi; Je ne viendrai pas avec colère.","Je n'agirai pas selon mon ardente colère, Je renonce à détruire Éphraïm; Car je suis Dieu, et non pas un homme, Je suis le Saint au milieu de toi; Je ne viendrai pas avec colère."],[11,10,"Ils suivront l'Éternel, qui rugira comme un lion, Car il rugira, et les enfants accourront de la mer.","Ils suivront l'Éternel, qui rugira comme un lion, Car il rugira, et les enfants accourront de la mer."],[11,11,"Ils accourront de l'Égypte, comme un oiseau, Et du pays d'Assyrie, comme une colombe. Et je les ferai habiter dans leurs maisons, dit l'Éternel.","Ils accourront de l'Égypte, comme un oiseau, Et du pays d'Assyrie, comme une colombe. Et je les ferai habiter dans leurs maisons, dit l'Éternel."],[11,12,"Éphraïm m'entoure de mensonge, Et la maison d'Israël de tromperie; Juda est encore sans frein vis-à-vis de Dieu, Vis-à-vis du Saint fidèle.","Éphraïm m'entoure de mensonge, Et la maison d'Israël de tromperie; Juda est encore sans frein vis-à-vis de Dieu, Vis-à-vis du Saint fidèle."],[12,1,"Éphraïm se repaît de vent, et poursuit le vent d'orient; Chaque jour il multiplie le mensonge et la violence; Il fait alliance avec l'Assyrie, Et on porte de l'huile en Égypte.","Éphraïm se repaît de vent, et poursuit le vent d'orient; Chaque jour il multiplie le mensonge et la violence; Il fait alliance avec l'Assyrie, Et on porte de l'huile en Égypte."],[12,2,"L'Éternel est aussi en contestation avec Juda, Et il punira Jacob pour sa conduite, Il lui rendra selon ses oeuvres.","L'Éternel est aussi en contestation avec Juda, Et il punira Jacob pour sa conduite, Il lui rendra selon ses oeuvres."],[12,3,"Dans le sein maternel Jacob saisit son frère par le talon, Et dans sa vigueur, il lutta avec Dieu.","Dans le sein maternel Jacob saisit son frère par le talon, Et dans sa vigueur, il lutta avec Dieu."],[12,4,"Il lutta avec l'ange, et il fut vainqueur, Il pleura, et lui adressa des supplications. Jacob l'avait trouvé à Béthel, Et c'est là que Dieu nous a parlé.","Il lutta avec l'ange, et il fut vainqueur, Il pleura, et lui adressa des supplications. Jacob l'avait trouvé à Béthel, Et c'est là que Dieu nous a parlé."],[12,5,"L'Éternel est le Dieu des armées; Son nom est l'Éternel.","L'Éternel est le Dieu des armées; Son nom est l'Éternel."],[12,6,"Et toi, reviens à ton Dieu, Garde la piété et la justice, Et espère toujours en ton Dieu.","Et toi, reviens à ton Dieu, Garde la piété et la justice, Et espère toujours en ton Dieu."],[12,7,"Éphraïm est un marchand qui a dans sa main des balances fausses, Il aime à tromper.","Éphraïm est un marchand qui a dans sa main des balances fausses, Il aime à tromper."],[12,8,"Et Éphraïm dit: À la vérité, je me suis enrichi, J'ai acquis de la fortune; Mais c'est entièrement le produit de mon travail; On ne trouvera chez moi aucune iniquité, rien qui soit un crime.","Et Éphraïm dit: À la vérité, je me suis enrichi, J'ai acquis de la fortune; Mais c'est entièrement le produit de mon travail; On ne trouvera chez moi aucune iniquité, rien qui soit un crime."],[12,9,"Et moi, je suis l'Éternel, ton Dieu, dès le pays d'Égypte; Je te ferai encore habiter sous des tentes, comme aux jours de fêtes.","Et moi, je suis l'Éternel, ton Dieu, dès le pays d'Égypte; Je te ferai encore habiter sous des tentes, comme aux jours de fêtes."],[12,10,"J'ai parlé aux prophètes, J'ai multiplié les visions, Et par les prophètes j'ai proposé des paraboles.","J'ai parlé aux prophètes, J'ai multiplié les visions, Et par les prophètes j'ai proposé des paraboles."],[12,11,"Si Galaad n'est que néant, ils seront certainement anéantis. Ils sacrifient des boeufs dans Guilgal: Aussi leurs autels seront comme des monceaux de pierres Sur les sillons des champs.","Si Galaad n'est que néant, ils seront certainement anéantis. Ils sacrifient des boeufs dans Guilgal: Aussi leurs autels seront comme des monceaux de pierres Sur les sillons des champs."],[12,12,"Jacob s'enfuit au pays d'Aram, Israël servit pour une femme, Et pour une femme il garda les troupeaux.","Jacob s'enfuit au pays d'Aram, Israël servit pour une femme, Et pour une femme il garda les troupeaux."],[12,13,"Par un prophète l'Éternel fit monter Israël hors d'Égypte, Et par un prophète Israël fut gardé.","Par un prophète l'Éternel fit monter Israël hors d'Égypte, Et par un prophète Israël fut gardé."],[12,14,"Éphraïm a irrité l'Éternel amèrement: Son Seigneur rejettera sur lui le sang qu'il a répandu, Il fera retomber sur lui la honte qui lui appartient.","Éphraïm a irrité l'Éternel amèrement: Son Seigneur rejettera sur lui le sang qu'il a répandu, Il fera retomber sur lui la honte qui lui appartient."],[13,1,"Lorsqu'Éphraïm parlait, c'était une terreur: Il s'élevait en Israël. Mais il s'est rendu coupable par Baal, et il est mort.","Lorsqu'Éphraïm parlait, c'était une terreur: Il s'élevait en Israël. Mais il s'est rendu coupable par Baal, et il est mort."],[13,2,"Maintenant ils continuent à pécher, Ils se font avec leur argent des images en fonte, Des idoles de leur invention; Toutes sont l'oeuvre des artisans. On dit à leur sujet: Que ceux qui sacrifient baisent les veaux!","Maintenant ils continuent à pécher, Ils se font avec leur argent des images en fonte, Des idoles de leur invention; Toutes sont l'oeuvre des artisans. On dit à leur sujet: Que ceux qui sacrifient baisent les veaux!"],[13,3,"C'est pourquoi ils seront comme la nuée du matin, Comme la rosée qui bientôt se dissipe, Comme la balle emportée par le vent hors de l'aire, Comme la fumée qui sort d'une fenêtre.","C'est pourquoi ils seront comme la nuée du matin, Comme la rosée qui bientôt se dissipe, Comme la balle emportée par le vent hors de l'aire, Comme la fumée qui sort d'une fenêtre."],[13,4,"Et moi, je suis l'Éternel, ton Dieu, dès le pays d'Égypte. Tu ne connais d'autre Dieu que moi, Et il n'y a de sauveur que moi.","Et moi, je suis l'Éternel, ton Dieu, dès le pays d'Égypte. Tu ne connais d'autre Dieu que moi, Et il n'y a de sauveur que moi."],[13,5,"Je t'ai connu dans le désert, Dans une terre aride.","Je t'ai connu dans le désert, Dans une terre aride."],[13,6,"Ils se sont rassasiés dans leurs pâturages; Ils se sont rassasiés, et leur coeur s'est enflé; C'est pourquoi ils m'ont oublié.","Ils se sont rassasiés dans leurs pâturages; Ils se sont rassasiés, et leur coeur s'est enflé; C'est pourquoi ils m'ont oublié."],[13,7,"Je serai pour eux comme un lion; Comme une panthère, je les épierai sur la route.","Je serai pour eux comme un lion; Comme une panthère, je les épierai sur la route."],[13,8,"Je les attaquerai, comme une ourse à qui l'on a enlevé ses petits, Et je déchirerai l'enveloppe de leur coeur; Je les dévorerai, comme une lionne; Les bêtes des champs les mettront en pièces.","Je les attaquerai, comme une ourse à qui l'on a enlevé ses petits, Et je déchirerai l'enveloppe de leur coeur; Je les dévorerai, comme une lionne; Les bêtes des champs les mettront en pièces."],[13,9,"Ce qui cause ta ruine, Israël, C'est que tu as été contre moi, contre celui qui pouvait te secourir.","Ce qui cause ta ruine, Israël, C'est que tu as été contre moi, contre celui qui pouvait te secourir."],[13,10,"Où donc est ton roi? Qu'il te délivre dans toutes tes villes! Où sont tes juges, au sujet desquels tu disais: Donne-moi un roi et des princes?","Où donc est ton roi? Qu'il te délivre dans toutes tes villes! Où sont tes juges, au sujet desquels tu disais: Donne-moi un roi et des princes?"],[13,11,"Je t'ai donné un roi dans ma colère, Je te l'ôterai dans ma fureur.","Je t'ai donné un roi dans ma colère, Je te l'ôterai dans ma fureur."],[13,12,"L'iniquité d'Éphraïm est gardée, Son péché est mis en réserve.","L'iniquité d'Éphraïm est gardée, Son péché est mis en réserve."],[13,13,"Les douleurs de celle qui enfante viendront pour lui; C'est un enfant peu sage, Qui, au terme voulu, ne sort pas du sein maternel.","Les douleurs de celle qui enfante viendront pour lui; C'est un enfant peu sage, Qui, au terme voulu, ne sort pas du sein maternel."],[13,14,"Je les rachèterai de la puissance du séjour des morts, Je les délivrerai de la mort. O mort, où est ta peste? Séjour des morts, où est ta destruction? Mais le repentir se dérobe à mes regards!","Je les rachèterai de la puissance du séjour des morts, Je les délivrerai de la mort. O mort, où est ta peste? Séjour des morts, où est ta destruction? Mais le repentir se dérobe à mes regards!"],[13,15,"Éphraïm a beau être fertile au milieu de ses frères, Le vent d'orient viendra, le vent de l'Éternel s'élèvera du désert, Desséchera ses sources, tarira ses fontaines. On pillera le trésor de tous les objets précieux.","Éphraïm a beau être fertile au milieu de ses frères, Le vent d'orient viendra, le vent de l'Éternel s'élèvera du désert, Desséchera ses sources, tarira ses fontaines. On pillera le trésor de tous les objets précieux."],[13,16,"Samarie sera punie, parce qu'elle s'est révoltée contre son Dieu. Ils tomberont par l'épée; Leurs petits enfants seront écrasés, Et l'on fendra le ventre de leurs femmes enceintes.","Samarie sera punie, parce qu'elle s'est révoltée contre son Dieu. Ils tomberont par l'épée; Leurs petits enfants seront écrasés, Et l'on fendra le ventre de leurs femmes enceintes."],[14,1,"Israël, reviens à l'Éternel, ton Dieu, Car tu es tombé par ton iniquité.","Israël, reviens à l'Éternel, ton Dieu, Car tu es tombé par ton iniquité."],[14,2,"Apportez avec vous des paroles, Et revenez à l'Éternel. Dites-lui: Pardonne toutes les iniquités, Et reçois-nous favorablement! Nous t'offrirons, au lieu de taureaux, l'hommage de nos lèvres.","Apportez avec vous des paroles, Et revenez à l'Éternel. Dites-lui: Pardonne toutes les iniquités, Et reçois-nous favorablement! Nous t'offrirons, au lieu de taureaux, l'hommage de nos lèvres."],[14,3,"L'Assyrien ne nous sauvera pas, nous ne monterons pas sur des chevaux, Et nous ne dirons plus à l'ouvrage de nos mains: Notre Dieu! Car c'est auprès de toi que l'orphelin trouve compassion.","L'Assyrien ne nous sauvera pas, nous ne monterons pas sur des chevaux, Et nous ne dirons plus à l'ouvrage de nos mains: Notre Dieu! Car c'est auprès de toi que l'orphelin trouve compassion."],[14,4,"Je réparerai leur infidélité, J'aurai pour eux un amour sincère; Car ma colère s'est détournée d'eux.","Je réparerai leur infidélité, J'aurai pour eux un amour sincère; Car ma colère s'est détournée d'eux."],[14,5,"Je serai comme la rosée pour Israël, Il fleurira comme le lis, Et il poussera des racines comme le Liban.","Je serai comme la rosée pour Israël, Il fleurira comme le lis, Et il poussera des racines comme le Liban."],[14,6,"Ses rameaux s'étendront; Il aura la magnificence de l'olivier, Et les parfums du Liban.","Ses rameaux s'étendront; Il aura la magnificence de l'olivier, Et les parfums du Liban."],[14,7,"Ils reviendront s'asseoir à son ombre, Ils redonneront la vie au froment, Et ils fleuriront comme la vigne; Ils auront la renommée du vin du Liban.","Ils reviendront s'asseoir à son ombre, Ils redonneront la vie au froment, Et ils fleuriront comme la vigne; Ils auront la renommée du vin du Liban."],[14,8,"Éphraïm, qu'ai-je à faire encore avec les idoles? Je l'exaucerai, je le regarderai, Je serai pour lui comme un cyprès verdoyant. C'est de moi que tu recevras ton fruit.","Éphraïm, qu'ai-je à faire encore avec les idoles? Je l'exaucerai, je le regarderai, Je serai pour lui comme un cyprès verdoyant. C'est de moi que tu recevras ton fruit."],[14,9,"Que celui qui est sage prenne garde à ces choses! Que celui qui est intelligent les comprenne! Car les voies de l'Éternel sont droites; Les justes y marcheront, Mais les rebelles y tomberont.","Que celui qui est sage prenne garde à ces choses! Que celui qui est intelligent les comprenne! Car les voies de l'Éternel sont droites; Les justes y marcheront, Mais les rebelles y tomberont."]],"spa-rv1909":[[1,1,"PALABRAde JehováquefuéáOseashijode Beeri, en díasde Ozías, Joathán, Achâz, y Ezechîas, reyesde Judá, y en díasde Jeroboamhijode Joas, reyde Israel.","PALABRAde JehováquefuéáOseashijode Beeri, en díasde Ozías, Joathán, Achâz, y Ezechîas, reyesde Judá, y en díasde Jeroboamhijode Joas, reyde Israel."],[1,2,"El principiode la palabrade Jehovácon Oseas. Y dijoJehováá Oseas: Ve, tómateuna mujerfornicaria, é hijosde fornicaciones: porquela tierrase daráá fornicarapartándosede Jehová.","El principiode la palabrade Jehovácon Oseas. Y dijoJehováá Oseas: Ve, tómateuna mujerfornicaria, é hijosde fornicaciones: porquela tierrase daráá fornicarapartándosede Jehová."],[1,3,"Fuépues, y tomóá Gomerhijade Diblaim, la cual concibióy le parióun hijo.","Fuépues, y tomóá Gomerhijade Diblaim, la cual concibióy le parióun hijo."],[1,4,"Y díjoleJehová: Ponlepor nombreJezreel; porquede aquíá pocoyo visitarélas sangresde Jezreelsobre la casade Jehú, y haré cesarel reinode la casade Israel.","Y díjoleJehová: Ponlepor nombreJezreel; porquede aquíá pocoyo visitarélas sangresde Jezreelsobre la casade Jehú, y haré cesarel reinode la casade Israel."],[1,5,"Y acaecerá que en aquel díaquebraréyo el arcode Israelen el vallede Jezreel.","Y acaecerá que en aquel díaquebraréyo el arcode Israelen el vallede Jezreel."],[1,6,"Y concibióaún, y parióuna hija. Y díjoleDios: Ponlepor nombreLo-ruhama: porquenomástendré misericordiade la casade Israel, sinoque los quitarédel todo.","Y concibióaún, y parióuna hija. Y díjoleDios: Ponlepor nombreLo-ruhama: porquenomástendré misericordiade la casade Israel, sinoque los quitarédel todo."],[1,7,"Mas de la casade Judátendré misericordia, y salvarélosen Jehovásu Dios: y nolos salvarécon arco, ni con espada, ni con batalla, ni con caballosni caballeros.","Mas de la casade Judátendré misericordia, y salvarélosen Jehovásu Dios: y nolos salvarécon arco, ni con espada, ni con batalla, ni con caballosni caballeros."],[1,8,"Y después de haber destetadoá Lo-ruhama, concibióy parióun hijo.","Y después de haber destetadoá Lo-ruhama, concibióy parióun hijo."],[1,9,"Y dijoDios: Ponlepor nombreLo-ammi: porquevosotrosnosois mi pueblo, niyoseré vuestro Dios.","Y dijoDios: Ponlepor nombreLo-ammi: porquevosotrosnosois mi pueblo, niyoseré vuestro Dios."],[1,10,"Con todo seráel númerode los hijosde Israelcomo la arenade la mar, quenise puede medirnicontar. Y será, quedonde se lesha dicho: Vosotrosnosois mi pueblo, lesserá dicho: Soishijosdel Diosviviente.","Con todo seráel númerode los hijosde Israelcomo la arenade la mar, quenise puede medirnicontar. Y será, quedonde se lesha dicho: Vosotrosnosois mi pueblo, lesserá dicho: Soishijosdel Diosviviente."],[1,11,"Y los hijosde Judáy de Israelserán congregadosen uno, y levantaránpara sí unacabeza, y subirándela tierra: porqueel díadeJezreelserá grande.","Y los hijosde Judáy de Israelserán congregadosen uno, y levantaránpara sí unacabeza, y subirándela tierra: porqueel díadeJezreelserá grande."],[2,1,"DECIDá vuestros hermanos, Ammi, y á vuestras hermanas, Ruhama:","DECIDá vuestros hermanos, Ammi, y á vuestras hermanas, Ruhama:"],[2,2,"Pleiteadcon vuestra madre, pleitead; porqueellanoes mi mujer, niyosumarido; quite pues susfornicacionesde surostro, y susadulteriosde entresuspechos;","Pleiteadcon vuestra madre, pleitead; porqueellanoes mi mujer, niyosumarido; quite pues susfornicacionesde surostro, y susadulteriosde entresuspechos;"],[2,3,"Nosea que yo la despojedesnuda, y la haga tornarcomo el díaen que nació, y la pongacomo un desierto, y la dejecomo tierraseca, y la matede sed.","Nosea que yo la despojedesnuda, y la haga tornarcomo el díaen que nació, y la pongacomo un desierto, y la dejecomo tierraseca, y la matede sed."],[2,4,"Nitendré misericordiade sus hijos: porqueson hijosde fornicaciones.","Nitendré misericordiade sus hijos: porqueson hijosde fornicaciones."],[2,5,"Porquesu madrefornicó; la que los engendrófué avergonzada; porquedijo: Irétrasmis amantes, que me danmi pany mi agua, mi lanay mi lino, mi aceitey mi bebida.","Porquesu madrefornicó; la que los engendrófué avergonzada; porquedijo: Irétrasmis amantes, que me danmi pany mi agua, mi lanay mi lino, mi aceitey mi bebida."],[2,6,"Por tanto, he aquí yo cerco tu caminocon espinas, y la cercarécon seto, y nohallarásus caminos.","Por tanto, he aquí yo cerco tu caminocon espinas, y la cercarécon seto, y nohallarásus caminos."],[2,7,"Y seguirásus amantes, y nolos alcanzará; buscarálos, y nolos hallará. Entonces dirá: Iré, y volverémeámi primermarido; porquemejorme iba entoncesque ahora.","Y seguirásus amantes, y nolos alcanzará; buscarálos, y nolos hallará. Entonces dirá: Iré, y volverémeámi primermarido; porquemejorme iba entoncesque ahora."],[2,8,"Y ellanoreconocióqueyole dabael trigo, y el vino, y el aceite, y queles multipliquéla platay el orocon quehicieroná Baal.","Y ellanoreconocióqueyole dabael trigo, y el vino, y el aceite, y queles multipliquéla platay el orocon quehicieroná Baal."],[2,9,"Por tantoyo tornaré, y tomarémi trigoá su tiempo, y mi vinoá su sazón, y quitarémi lanay mi linoque había dadopara cubrirsu desnudez.","Por tantoyo tornaré, y tomarémi trigoá su tiempo, y mi vinoá su sazón, y quitarémi lanay mi linoque había dadopara cubrirsu desnudez."],[2,10,"Y ahoradescubriréyo su locuradelante de los ojosde sus amantes, y nadiela libraráde mi mano.","Y ahoradescubriréyo su locuradelante de los ojosde sus amantes, y nadiela libraráde mi mano."],[2,11,"Y haré cesartodosu gozo, sus fiestas, sus nuevaslunas y sus sábados, y todassus festividades.","Y haré cesartodosu gozo, sus fiestas, sus nuevaslunas y sus sábados, y todassus festividades."],[2,12,"Y haré talarsus videsy sus higueras, de queha dicho: Mi salariome son, queme han dadomis amantes. Y reducirélasá un matorral, y las comeránlasbestiasdel campo.","Y haré talarsus videsy sus higueras, de queha dicho: Mi salariome son, queme han dadomis amantes. Y reducirélasá un matorral, y las comeránlasbestiasdel campo."],[2,13,"Y visitarésobreella los tiemposde los Baales, á los cuales incensaba, y adornábasede sus zarcillosy de sus joyeles, é íbase trassus amantesolvidada de mí, diceJehová.","Y visitarésobreella los tiemposde los Baales, á los cuales incensaba, y adornábasede sus zarcillosy de sus joyeles, é íbase trassus amantesolvidada de mí, diceJehová."],[2,14,"Emperohe aquí, yola induciré, y la llevaréal desierto, y hablaréásu corazón.","Emperohe aquí, yola induciré, y la llevaréal desierto, y hablaréásu corazón."],[2,15,"Y darélesus viñasdesde allí, y el vallede Achôrpor puertade esperanza; y allícantarácomo en los tiemposde su juventud, y como en el díade su subidade la tierrade Egipto.","Y darélesus viñasdesde allí, y el vallede Achôrpor puertade esperanza; y allícantarácomo en los tiemposde su juventud, y como en el díade su subidade la tierrade Egipto."],[2,16,"Y será que en aquel tiempo, diceJehová, me llamarásMarido mío, y nuncamásme llamarásBaali.","Y será que en aquel tiempo, diceJehová, me llamarásMarido mío, y nuncamásme llamarásBaali."],[2,17,"Porque quitaréde su bocalos nombresde los Baales, y nuncamásserán mentadospor sus nombres.","Porque quitaréde su bocalos nombresde los Baales, y nuncamásserán mentadospor sus nombres."],[2,18,"Y harépor ellos conciertoen aquel tiempoconlas bestiasdel campo, y conlas avesdel cielo, y conlas serpientesde la tierra: y quebraréarco, y espada, y batalladela tierra, y harélos dormirseguros.","Y harépor ellos conciertoen aquel tiempoconlas bestiasdel campo, y conlas avesdel cielo, y conlas serpientesde la tierra: y quebraréarco, y espada, y batalladela tierra, y harélos dormirseguros."],[2,19,"Y te desposaréconmigo para siempre; desposarte he conmigo en justicia, y juicio, y misericordia, y miseraciones.","Y te desposaréconmigo para siempre; desposarte he conmigo en justicia, y juicio, y misericordia, y miseraciones."],[2,20,"Y tedesposaréconmigo en fe, y conocerásá Jehová.","Y tedesposaréconmigo en fe, y conocerásá Jehová."],[2,21,"Y será que en aquel tiemporesponderé, diceJehová, yo responderéá los cielos, y ellosresponderáná la tierra;","Y será que en aquel tiemporesponderé, diceJehová, yo responderéá los cielos, y ellosresponderáná la tierra;"],[2,22,"Y la tierraresponderáal trigo, y al vino, y al aceite, y ellosresponderáná Jezreel.","Y la tierraresponderáal trigo, y al vino, y al aceite, y ellosresponderáná Jezreel."],[2,23,"Y sembrarélapara mí en la tierra, y tendré misericordiade Lo-ruhama: y diréá Lo-ammi: Pueblomío tú; y éldirá: Diosmío.","Y sembrarélapara mí en la tierra, y tendré misericordiade Lo-ruhama: y diréá Lo-ammi: Pueblomío tú; y éldirá: Diosmío."],[3,1,"Y DÍJOMEotravez Jehová: Ve, amauna mujeramadade sucompañero, aunque adúltera, como el amorde Jehovápara con los hijosde Israel; los cualesmiranádiosesajenos, y amanfrascosde vino.","Y DÍJOMEotravez Jehová: Ve, amauna mujeramadade sucompañero, aunque adúltera, como el amorde Jehovápara con los hijosde Israel; los cualesmiranádiosesajenos, y amanfrascosde vino."],[3,2,"Comprélaentonces para mí por quincedinerosde plata, y un homery mediode cebada;","Comprélaentonces para mí por quincedinerosde plata, y un homery mediode cebada;"],[3,3,"Y díjele: Tú estarás por mía muchosdías: nofornicarás, nitomarásotrovarón; nitampoco yovendréá ti.","Y díjele: Tú estarás por mía muchosdías: nofornicarás, nitomarásotrovarón; nitampoco yovendréá ti."],[3,4,"Porquemuchosdíasestaránlos hijosde Israelsinrey, y sinpríncipe, y sinsacrificio, y sinestatua, y sinephod, y sinteraphim.","Porquemuchosdíasestaránlos hijosde Israelsinrey, y sinpríncipe, y sinsacrificio, y sinestatua, y sinephod, y sinteraphim."],[3,5,"Despuésvolveránlos hijosde Israel, y buscaráná Jehovásu Dios, y á Davidsu rey; y temeráná Jehováy ásu bondaden el finde los días.","Despuésvolveránlos hijosde Israel, y buscaráná Jehovásu Dios, y á Davidsu rey; y temeráná Jehováy ásu bondaden el finde los días."],[4,1,"OIDpalabrade Jehová, hijosde Israel, porqueJehovápleitea conlos moradoresde la tierra; porquenohay verdad, nimisericordia, niconocimientode Diosen la tierra.","OIDpalabrade Jehová, hijosde Israel, porqueJehovápleitea conlos moradoresde la tierra; porquenohay verdad, nimisericordia, niconocimientode Diosen la tierra."],[4,2,"Perjurar, y mentir, y matar, y hurtary adulterarprevalecieron, y sangresse tocaroncon sangres.","Perjurar, y mentir, y matar, y hurtary adulterarprevalecieron, y sangresse tocaroncon sangres."],[4,3,"Porlo cual, se enlutarála tierra, y extenuarásetodomoradorde ella, con las bestiasdel campo, y las avesdel cielo: y aunlos pecesde la marfallecerán.","Porlo cual, se enlutarála tierra, y extenuarásetodomoradorde ella, con las bestiasdel campo, y las avesdel cielo: y aunlos pecesde la marfallecerán."],[4,4,"Ciertamentehombrenocontienda nireprendaá hombre, porque tu puebloes como los que resistenal sacerdote.","Ciertamentehombrenocontienda nireprendaá hombre, porque tu puebloes como los que resistenal sacerdote."],[4,5,"Caeráspor tanto en el día, y caerátambiéncontigoel profetade noche; y á tu madretalaré.","Caeráspor tanto en el día, y caerátambiéncontigoel profetade noche; y á tu madretalaré."],[4,6,"Mipueblofué talado, porque le faltósabiduría. Porquetú desechastela sabiduría, yo teecharédel sacerdocio: y pues que olvidastela leyde tuDios, tambiényome olvidaréde tushijos.","Mipueblofué talado, porque le faltósabiduría. Porquetú desechastela sabiduría, yo teecharédel sacerdocio: y pues que olvidastela leyde tuDios, tambiényome olvidaréde tushijos."],[4,7,"Conforme á su grandezaasípecaroncontra mí: trocaré su honraen afrenta.","Conforme á su grandezaasípecaroncontra mí: trocaré su honraen afrenta."],[4,8,"Comendel pecadode mi pueblo, y ensu maldadlevantansu alma.","Comendel pecadode mi pueblo, y ensu maldadlevantansu alma."],[4,9,"Tal seráel pueblocomo el sacerdote: y visitarésobre él sus caminos, y pagaréleconforme á sus obras.","Tal seráel pueblocomo el sacerdote: y visitarésobre él sus caminos, y pagaréleconforme á sus obras."],[4,10,"Y comerán, mas nose hartarán; fornicarán, mas nose aumentarán: porquedejaronde atender á Jehová.","Y comerán, mas nose hartarán; fornicarán, mas nose aumentarán: porquedejaronde atender á Jehová."],[4,11,"Fornicación, y vino, y mostoquitanel corazón.","Fornicación, y vino, y mostoquitanel corazón."],[4,12,"Mi puebloá su maderopregunta, y su palole responde: porqueespíritude fornicacioneslo engañó, y fornicarondebajo de sus dioses.","Mi puebloá su maderopregunta, y su palole responde: porqueespíritude fornicacioneslo engañó, y fornicarondebajo de sus dioses."],[4,13,"Sobrelas cabezasde los montessacrificaron, é incensaronsobrelos collados, debajode encinas, y álamos, y olmosquetuviesen buenasombra: portanto, vuestras hijasfornicarán, y adulteraránvuestras nueras.","Sobrelas cabezasde los montessacrificaron, é incensaronsobrelos collados, debajode encinas, y álamos, y olmosquetuviesen buenasombra: portanto, vuestras hijasfornicarán, y adulteraránvuestras nueras."],[4,14,"Novisitarésobre vuestras hijascuandofornicaren, ni sobre vuestras nuerascuandoadulteraren: porqueellosofrecen conlas rameras, y conlas malasmujeressacrifican: por tanto, el pueblosinentendimientocaerá.","Novisitarésobre vuestras hijascuandofornicaren, ni sobre vuestras nuerascuandoadulteraren: porqueellosofrecen conlas rameras, y conlas malasmujeressacrifican: por tanto, el pueblosinentendimientocaerá."],[4,15,"Sifornicarestú, Israel, á lo menos nopequeJudá: y noentréisen Gilgal, nisubáisá Beth-aven; nijuréis, ViveJehová.","Sifornicarestú, Israel, á lo menos nopequeJudá: y noentréisen Gilgal, nisubáisá Beth-aven; nijuréis, ViveJehová."],[4,16,"Porquecomo becerracerrerase apartóIsrael: ¿apacentarálosahoraJehovácomo á carnerosen anchura?","Porquecomo becerracerrerase apartóIsrael: ¿apacentarálosahoraJehovácomo á carnerosen anchura?"],[4,17,"Ephraimes dadoá ídolos; déjalo.","Ephraimes dadoá ídolos; déjalo."],[4,18,"Su bebidase corrompió; fornicaronpertinazmente: sus príncipesamaronlas dádivas, afrentade ellos.","Su bebidase corrompió; fornicaronpertinazmente: sus príncipesamaronlas dádivas, afrentade ellos."],[4,19,"Atólael vientoen sus alas, y de sus sacrificiosserán avergonzados.","Atólael vientoen sus alas, y de sus sacrificiosserán avergonzados."],[5,1,"SACERDOTES, oidesto, y estad atentos, casade Israel; y casadel rey, escuchad: porqueá vosotros es el juicio, pueshabéis sidolazoen Mizpa, y redextendida sobreTabor.","SACERDOTES, oidesto, y estad atentos, casade Israel; y casadel rey, escuchad: porqueá vosotros es el juicio, pueshabéis sidolazoen Mizpa, y redextendida sobreTabor."],[5,2,"Y haciendo víctimashan bajadohasta el profundo: por tanto yoseré la correcciónde todosellos.","Y haciendo víctimashan bajadohasta el profundo: por tanto yoseré la correcciónde todosellos."],[5,3,"Yoconozcoá Ephraim, é Israelnomees desconocido: porqueahora, oh Ephraim, has fornicado, y se ha contaminadoIsrael.","Yoconozcoá Ephraim, é Israelnomees desconocido: porqueahora, oh Ephraim, has fornicado, y se ha contaminadoIsrael."],[5,4,"Nopondrán sus pensamientosen volverseásu Dios, porqueespíritude fornicaciónestá en mediode ellos, y noconocená Jehová.","Nopondrán sus pensamientosen volverseásu Dios, porqueespíritude fornicaciónestá en mediode ellos, y noconocená Jehová."],[5,5,"Y la soberbiade Israelle desmentiráen su cara: é Israely Ephraimtropezaránen su pecado: tropezarátambiénJudáconellos.","Y la soberbiade Israelle desmentiráen su cara: é Israely Ephraimtropezaránen su pecado: tropezarátambiénJudáconellos."],[5,6,"Con susovejasy con susvacasandaránbuscandoá Jehová, y nole hallarán; apartósede ellos.","Con susovejasy con susvacasandaránbuscandoá Jehová, y nole hallarán; apartósede ellos."],[5,7,"Contra Jehováprevaricaron, porquehijosextrañoshan engendrado: ahoralos devoraráun mescon sus heredades.","Contra Jehováprevaricaron, porquehijosextrañoshan engendrado: ahoralos devoraráun mescon sus heredades."],[5,8,"Tocadbocinaen Gabaa, trompetaen Ramá: sonad tambor en Beth-aven: trasti, oh Benjamín.","Tocadbocinaen Gabaa, trompetaen Ramá: sonad tambor en Beth-aven: trasti, oh Benjamín."],[5,9,"Ephraim seráasoladoel díadel castigo: en las tribusde Israelhice conocerverdad.","Ephraim seráasoladoel díadel castigo: en las tribusde Israelhice conocerverdad."],[5,10,"Los príncipesde Judáfueroncomo los que traspasanmojones: derramarésobreellos como aguami ira.","Los príncipesde Judáfueroncomo los que traspasanmojones: derramarésobreellos como aguami ira."],[5,11,"Ephraim es vejado, quebrantadoen juicio, porquequisoandaren posde mandamientos.","Ephraim es vejado, quebrantadoen juicio, porquequisoandaren posde mandamientos."],[5,12,"Yopues seré como polillaá Ephraim, y como carcomaá la casade Judá.","Yopues seré como polillaá Ephraim, y como carcomaá la casade Judá."],[5,13,"Y veráEphraimsuenfermedad, y Judásullaga: iráentonces EphraimalAssur, y enviaráalreyJareb; mas élnoos podrásanar, nioscurarála llaga.","Y veráEphraimsuenfermedad, y Judásullaga: iráentonces EphraimalAssur, y enviaráalreyJareb; mas élnoos podrásanar, nioscurarála llaga."],[5,14,"Porqueyoseré como leóná Ephraim, y como cachorrode leóná la casade Judá: yo, yoarrebataré, y andaré; tomaré, y nohabrá quien liberte.","Porqueyoseré como leóná Ephraim, y como cachorrode leóná la casade Judá: yo, yoarrebataré, y andaré; tomaré, y nohabrá quien liberte."],[5,15,"Andaré, y tornaréá mi lugarhastaqueconozcan su pecado, y busquenmi rostro. En su angustiamadrugaráná mí.","Andaré, y tornaréá mi lugarhastaqueconozcan su pecado, y busquenmi rostro. En su angustiamadrugaráná mí."],[6,1,"VENIDy volvámonosáJehová: que élarrebató, y noscurará; hirió, y nosvendará.","VENIDy volvámonosáJehová: que élarrebató, y noscurará; hirió, y nosvendará."],[6,2,"Darános vidadespués de dos días: al tercerdíanosresucitará, y viviremosdelantede él.","Darános vidadespués de dos días: al tercerdíanosresucitará, y viviremosdelantede él."],[6,3,"Y conoceremos, y proseguiremosen conocerá Jehová: como el albaestá aparejadasu salida, y vendráá nosotroscomo la lluvia, como la lluviatardía ytempranaá la tierra.","Y conoceremos, y proseguiremosen conocerá Jehová: como el albaestá aparejadasu salida, y vendráá nosotroscomo la lluvia, como la lluviatardía ytempranaá la tierra."],[6,4,"¿Quéharéá ti, Ephraim? ¿Quéharéá ti, oh Judá? La piedadvuestra es como la nubede la mañana, y como el rocíoque de madrugadaviene.","¿Quéharéá ti, Ephraim? ¿Quéharéá ti, oh Judá? La piedadvuestra es como la nubede la mañana, y como el rocíoque de madrugadaviene."],[6,5,"Porestacausa cortécon los profetas, con las palabrasde mi bocalos maté; y tus juiciosserán comoluzque sale.","Porestacausa cortécon los profetas, con las palabrasde mi bocalos maté; y tus juiciosserán comoluzque sale."],[6,6,"Porquemisericordiaquise, y nosacrificio; y conocimientode Diosmás que holocaustos.","Porquemisericordiaquise, y nosacrificio; y conocimientode Diosmás que holocaustos."],[6,7,"Mas ellos, cual Adam, traspasaronel pacto: allíprevaricaroncontra mí.","Mas ellos, cual Adam, traspasaronel pacto: allíprevaricaroncontra mí."],[6,8,"Galaad, ciudadde obradoresde iniquidad, ensuciada de sangre.","Galaad, ciudadde obradoresde iniquidad, ensuciada de sangre."],[6,9,"Y como ladronesqueesperaná algúnhombre, así juntade sacerdotesmancomunadamentemataen el camino: porqueponen en efectola abominación.","Y como ladronesqueesperaná algúnhombre, así juntade sacerdotesmancomunadamentemataen el camino: porqueponen en efectola abominación."],[6,10,"En la casade Israelhe vistosuciedad: allífornicóEphraim, se contaminóIsrael:","En la casade Israelhe vistosuciedad: allífornicóEphraim, se contaminóIsrael:"],[6,11,"TambiénJudápusoen ti unaplanta, habiendo yo vueltola cautividadde mi pueblo.","TambiénJudápusoen ti unaplanta, habiendo yo vueltola cautividadde mi pueblo."],[7,1,"ESTANDO yo curando á Israel, descubriósela iniquidadde Ephraim, y las maldadesde Samaria; porqueobraronengaño: y vieneel ladrón, y el salteadordespojade fuera.","ESTANDO yo curando á Israel, descubriósela iniquidadde Ephraim, y las maldadesde Samaria; porqueobraronengaño: y vieneel ladrón, y el salteadordespojade fuera."],[7,2,"Y nodicen en su corazónque tengo en la memoriatodasu maldad: ahoralos rodearánsus obras; delantede míestán.","Y nodicen en su corazónque tengo en la memoriatodasu maldad: ahoralos rodearánsus obras; delantede míestán."],[7,3,"Con su maldadalegranal rey, y á los príncipescon sus mentiras.","Con su maldadalegranal rey, y á los príncipescon sus mentiras."],[7,4,"Todosellos adúlteros; son como hornoencendidopor el hornero, el cualcesará de avivardespués que esté hechala masa, hastaque esté leuda.","Todosellos adúlteros; son como hornoencendidopor el hornero, el cualcesará de avivardespués que esté hechala masa, hastaque esté leuda."],[7,5,"El díade nuestroreylos príncipeslohicieron enfermarcon vasos de vino: extendiósu manoconlos escarnecedores.","El díade nuestroreylos príncipeslohicieron enfermarcon vasos de vino: extendiósu manoconlos escarnecedores."],[7,6,"Porque aplicaronsu corazón, semejante á un horno, á sus artificios: todala nocheduermesu hornero; á la mañanaestá encendidocomo llamade fuego.","Porque aplicaronsu corazón, semejante á un horno, á sus artificios: todala nocheduermesu hornero; á la mañanaestá encendidocomo llamade fuego."],[7,7,"Todosellos ardencomo un horno, y devoraroná sus jueces: cayerontodossus reyes: nohay entre ellos quien ámí clame.","Todosellos ardencomo un horno, y devoraroná sus jueces: cayerontodossus reyes: nohay entre ellos quien ámí clame."],[7,8,"Ephraimse envolviócon los pueblos; Ephraimfuétortanovuelta.","Ephraimse envolviócon los pueblos; Ephraimfuétortanovuelta."],[7,9,"Comieronextrañossusustancia, y élnolo supo; y aunvejez se ha esparcidopor él, y élnolo entendió.","Comieronextrañossusustancia, y élnolo supo; y aunvejez se ha esparcidopor él, y élnolo entendió."],[7,10,"Y la soberbiade Israeltestificarácontra él en su cara: y nose tornaronáJehovásu Dios, nilo buscaroncon todoesto.","Y la soberbiade Israeltestificarácontra él en su cara: y nose tornaronáJehovásu Dios, nilo buscaroncon todoesto."],[7,11,"Y fuéEphraimcomo palomaincauta, sinentendimiento: llamaráná Egipto, acudiránal Asirio.","Y fuéEphraimcomo palomaincauta, sinentendimiento: llamaráná Egipto, acudiránal Asirio."],[7,12,"Cuandofueren, extenderé sobreellos mi red, hacerlos he caercomo avesdel cielo; castigarélosconforme á lo que se ha oídoen sus congregaciones.","Cuandofueren, extenderé sobreellos mi red, hacerlos he caercomo avesdel cielo; castigarélosconforme á lo que se ha oídoen sus congregaciones."],[7,13,"¡Ayde ellos! porquese apartarondemí: destrucciónsobre ellos, porquecontra mí se rebelaron; yolosredimí, y elloshablaroncontramí mentiras.","¡Ayde ellos! porquese apartarondemí: destrucciónsobre ellos, porquecontra mí se rebelaron; yolosredimí, y elloshablaroncontramí mentiras."],[7,14,"Y noclamaronámí con su corazóncuandoaullaron sobresus camas, parael trigoy el mostose congregaron, rebeláronsecontra mí.","Y noclamaronámí con su corazóncuandoaullaron sobresus camas, parael trigoy el mostose congregaron, rebeláronsecontra mí."],[7,15,"Y yolosceñí, esforcé sus brazos, y contramípensaronmal.","Y yolosceñí, esforcé sus brazos, y contramípensaronmal."],[7,16,"Tornáronse, mas noal Altísimo: fueroncomo arcoengañoso: cayeronsus príncipesá cuchillopor la soberbiade su lengua: éste será su escarnioen la tierrade Egipto.","Tornáronse, mas noal Altísimo: fueroncomo arcoengañoso: cayeronsus príncipesá cuchillopor la soberbiade su lengua: éste será su escarnioen la tierrade Egipto."],[8,1,"PON átu bocatrompeta. Vendrácomo águilacontrala casade Jehová, porquetraspasaronmi pacto, y se rebelaroncontrami ley.","PON átu bocatrompeta. Vendrácomo águilacontrala casade Jehová, porquetraspasaronmi pacto, y se rebelaroncontrami ley."],[8,2,"A mí clamaráIsrael: Diosmío, te hemos conocido.","A mí clamaráIsrael: Diosmío, te hemos conocido."],[8,3,"Israeldesamparóel bien: enemigolo perseguirá.","Israeldesamparóel bien: enemigolo perseguirá."],[8,4,"Elloshicieron reyes, mas nopormí; constituyeron príncipes, mas yo nolo supe: de suplatay de suorohicieronídolospara sí, para ser talados.","Elloshicieron reyes, mas nopormí; constituyeron príncipes, mas yo nolo supe: de suplatay de suorohicieronídolospara sí, para ser talados."],[8,5,"Tu becerro, oh Samaria, te hizo alejar; encendiósemi enojocontra ellos, hastaquenopudieronalcanzar inocencia.","Tu becerro, oh Samaria, te hizo alejar; encendiósemi enojocontra ellos, hastaquenopudieronalcanzar inocencia."],[8,6,"Porquede Israeles, y artíficelohizo; quenoes Dios: por loqueen pedazosserádeshecho el becerrode Samaria.","Porquede Israeles, y artíficelohizo; quenoes Dios: por loqueen pedazosserádeshecho el becerrode Samaria."],[8,7,"Porquesembraronviento, y torbellinosegarán: notendrán mies, niel fruto haráharina; sila hiciere, extrañosla tragarán.","Porquesembraronviento, y torbellinosegarán: notendrán mies, niel fruto haráharina; sila hiciere, extrañosla tragarán."],[8,8,"Será tragado Israel: prestoseránentre las gentescomo vasoen que nohay contentamiento.","Será tragado Israel: prestoseránentre las gentescomo vasoen que nohay contentamiento."],[8,9,"Porqueellossubieroná Assur, asnomontéspara sí solo: Ephraimcon salario alquilóamantes.","Porqueellossubieroná Assur, asnomontéspara sí solo: Ephraimcon salario alquilóamantes."],[8,10,"Aunquealquilená las gentes, ahoralas juntaré; y serán un pocoafligidospor la cargadel reyy de los príncipes.","Aunquealquilená las gentes, ahoralas juntaré; y serán un pocoafligidospor la cargadel reyy de los príncipes."],[8,11,"PorquemultiplicóEphraimaltarespara pecar, tuvoaltarespara pecar.","PorquemultiplicóEphraimaltarespara pecar, tuvoaltarespara pecar."],[8,12,"Escribíle las grandezasde mi ley, yfueron tenidaspor cosas ajenas.","Escribíle las grandezasde mi ley, yfueron tenidaspor cosas ajenas."],[8,13,"En los sacrificiosde mis dones sacrificaroncarne, y comieron: nolosquisoJehová: ahorase acordaráde suiniquidad, y visitarásupecado; ellosse tornaráná Egipto.","En los sacrificiosde mis dones sacrificaroncarne, y comieron: nolosquisoJehová: ahorase acordaráde suiniquidad, y visitarásupecado; ellosse tornaráná Egipto."],[8,14,"Olvidópues Israelá su Hacedor, y edificótemplos, y Judámultiplicóciudadesfuertes: mas yo meteréfuegoen sus ciudades, el cual devorarásus palacios.","Olvidópues Israelá su Hacedor, y edificótemplos, y Judámultiplicóciudadesfuertes: mas yo meteréfuegoen sus ciudades, el cual devorarásus palacios."],[9,1,"NOte alegres, oh Israel, hastasaltar de gozocomo los pueblos, pueshas fornicadoapartándotede tu Dios: amastesalariopor todaslas erasde trigo.","NOte alegres, oh Israel, hastasaltar de gozocomo los pueblos, pueshas fornicadoapartándotede tu Dios: amastesalariopor todaslas erasde trigo."],[9,2,"La eray el lagarnolos mantendrán; les fallaráel mosto.","La eray el lagarnolos mantendrán; les fallaráel mosto."],[9,3,"Noquedaránen la tierrade Jehová, sino que volveráEphraimá Egipto, y á Asiria, donde comeránvianda inmunda.","Noquedaránen la tierrade Jehová, sino que volveráEphraimá Egipto, y á Asiria, donde comeránvianda inmunda."],[9,4,"Noderramarán vinoá Jehová, niél tomará contentoen sus sacrificios; como pande enlutadosles serán á ellos: todoslos que comieren de él, serán inmundos. Será puesel pande ellos para sí mismos; noentraráen la casade Jehová.","Noderramarán vinoá Jehová, niél tomará contentoen sus sacrificios; como pande enlutadosles serán á ellos: todoslos que comieren de él, serán inmundos. Será puesel pande ellos para sí mismos; noentraráen la casade Jehová."],[9,5,"¿Quéharéisel díade la solemnidad, y el díade la fiestade Jehová?","¿Quéharéisel díade la solemnidad, y el díade la fiestade Jehová?"],[9,6,"Porque, he aquíse fueronellos á causa de la destrucción: Egiptolos recogerá, Memphislos enterrará: espinoposeerá por heredadlo deseable de su plata, ortigacrecerá en sus moradas.","Porque, he aquíse fueronellos á causa de la destrucción: Egiptolos recogerá, Memphislos enterrará: espinoposeerá por heredadlo deseable de su plata, ortigacrecerá en sus moradas."],[9,7,"Vinieronlos díasde la visitación, vinieronlos díasde la paga; conoceráloIsrael: necioel profeta, insensatoel varónde espíritu, á causa dela multitudde tu maldad, y grandeodio.","Vinieronlos díasde la visitación, vinieronlos díasde la paga; conoceráloIsrael: necioel profeta, insensatoel varónde espíritu, á causa dela multitudde tu maldad, y grandeodio."],[9,8,"AtalayaesEphraimpara conmi Dios: el profetaeslazode cazadorentodossus caminos, odioenla casade su Dios.","AtalayaesEphraimpara conmi Dios: el profetaeslazode cazadorentodossus caminos, odioenla casade su Dios."],[9,9,"Llegaron al profundo, corrompiéronse, como en los díasde Gabaa: ahora se acordaráde su iniquidad; visitarásu pecado.","Llegaron al profundo, corrompiéronse, como en los díasde Gabaa: ahora se acordaráde su iniquidad; visitarásu pecado."],[9,10,"Como uvasen el desiertohalléá Israel: como la fruta temprana de la higueraen su principioviá vuestros padres. Ellosentraroná Baal-peor, y se apartaronpara vergüenza, é hiciéronseabominablescomo aquelloque amaron.","Como uvasen el desiertohalléá Israel: como la fruta temprana de la higueraen su principioviá vuestros padres. Ellosentraroná Baal-peor, y se apartaronpara vergüenza, é hiciéronseabominablescomo aquelloque amaron."],[9,11,"Ephraim, cual avevolarásu gloriadesde el nacimiento, aun desde el vientrey desde la concepción.","Ephraim, cual avevolarásu gloriadesde el nacimiento, aun desde el vientrey desde la concepción."],[9,12,"Ysillegaren á grandessushijos, quitarélosde entre los hombres, porque¡ayde ellostambién, cuando de ellosme apartare!","Ysillegaren á grandessushijos, quitarélosde entre los hombres, porque¡ayde ellostambién, cuando de ellosme apartare!"],[9,13,"Ephraim, según veo, es semejante á Tiro, asentadaen lugar delicioso: mas Ephraimsacarásus hijosal matador.","Ephraim, según veo, es semejante á Tiro, asentadaen lugar delicioso: mas Ephraimsacarásus hijosal matador."],[9,14,"Dales, oh Jehová, lo queles has de dar: dalesmatrizexpeliente, y enjutospechos.","Dales, oh Jehová, lo queles has de dar: dalesmatrizexpeliente, y enjutospechos."],[9,15,"Todala maldadde ellos fuéen Gilgal; allí, pues, les tomé aversión: porla maliciade sus obrasecharélosde mi casa; nolos amarémás; todossus príncipesson desleales.","Todala maldadde ellos fuéen Gilgal; allí, pues, les tomé aversión: porla maliciade sus obrasecharélosde mi casa; nolos amarémás; todossus príncipesson desleales."],[9,16,"Ephraimfué herido, secósesu cepa, no harámásfruto: aunqueengendren, yo matarélo deseablede su vientre.","Ephraimfué herido, secósesu cepa, no harámásfruto: aunqueengendren, yo matarélo deseablede su vientre."],[9,17,"Mi Dioslos desechará, porqueellos nole oyeron; y andarán errantesentre las gentes.","Mi Dioslos desechará, porqueellos nole oyeron; y andarán errantesentre las gentes."],[10,1,"ES Israeluna frondosaviña, haciendo frutopara sí: conforme á la multiplicación de su frutomultiplicóaltares, conforme á la bondadde su tierraaumentaronsus estatuas.","ES Israeluna frondosaviña, haciendo frutopara sí: conforme á la multiplicación de su frutomultiplicóaltares, conforme á la bondadde su tierraaumentaronsus estatuas."],[10,2,"Dividiósesu corazón. Ahora seránhallados culpables: él quebrantarásus altares, asolarásus estatuas.","Dividiósesu corazón. Ahora seránhallados culpables: él quebrantarásus altares, asolarásus estatuas."],[10,3,"Porquediránahora: Notenemos rey, porquenotemimosá Jehová: ¿y quéharíael reypor nosotros?","Porquediránahora: Notenemos rey, porquenotemimosá Jehová: ¿y quéharíael reypor nosotros?"],[10,4,"Han habladopalabrasjurandoen vanoal haceralianza: por tanto, el juicioflorecerácomo ajenjoenlos surcosdel campo.","Han habladopalabrasjurandoen vanoal haceralianza: por tanto, el juicioflorecerácomo ajenjoenlos surcosdel campo."],[10,5,"Por las becerrasde Beth-avenserán atemorizadoslos moradoresde Samaria: porquesu pueblolamentaráá causa del becerro, y sus sacerdotesque enél se regocijabanporsu gloria, la cualserá disipada.","Por las becerrasde Beth-avenserán atemorizadoslos moradoresde Samaria: porquesu pueblolamentaráá causa del becerro, y sus sacerdotesque enél se regocijabanporsu gloria, la cualserá disipada."],[10,6,"Y aunserá él llevadoá Asiriaen presenteal reyJareb: Ephraimserá avergonzado, é Israelserá confusode su consejo.","Y aunserá él llevadoá Asiriaen presenteal reyJareb: Ephraimserá avergonzado, é Israelserá confusode su consejo."],[10,7,"De Samariafué cortadosu reycomo la espumasobrela superficiede las aguas.","De Samariafué cortadosu reycomo la espumasobrela superficiede las aguas."],[10,8,"Y los altaresde Avénserán destruídos, el pecadode Israel; crecerásobresus altaresespinoy cardo. Y diráná los montes: Cubridnos; y á los collados: Caedsobrenosotros.","Y los altaresde Avénserán destruídos, el pecadode Israel; crecerásobresus altaresespinoy cardo. Y diráná los montes: Cubridnos; y á los collados: Caedsobrenosotros."],[10,9,"Desde los díasde Gabaahas pecado, oh Israel: allíestuvieron: nolos tomóla batallaen Gabaacontralos inicuos.","Desde los díasde Gabaahas pecado, oh Israel: allíestuvieron: nolos tomóla batallaen Gabaacontralos inicuos."],[10,10,"Y los castigarécomo deseo: y pueblosse juntaránsobreellos cuando serán atadosen sus dossurcos.","Y los castigarécomo deseo: y pueblosse juntaránsobreellos cuando serán atadosen sus dossurcos."],[10,11,"Ephraimes becerradomada, amadoradel trillar; mas yopasarésobresu lozanacerviz: yoharé llevaryugoá Ephraim; araráJudá, quebrarásus terrones Jacob.","Ephraimes becerradomada, amadoradel trillar; mas yopasarésobresu lozanacerviz: yoharé llevaryugoá Ephraim; araráJudá, quebrarásus terrones Jacob."],[10,12,"Sembradpara vosotros en justicia, segadpara vosotros enmisericordia; aradpara vosotros barbecho: porque es el tiempode buscará Jehová, hastaque vengay os enseñejusticia.","Sembradpara vosotros en justicia, segadpara vosotros enmisericordia; aradpara vosotros barbecho: porque es el tiempode buscará Jehová, hastaque vengay os enseñejusticia."],[10,13,"Habéis aradoimpiedad, segasteisiniquidad: comeréisfrutode mentira: porqueconfiasteen tu camino, en la multitudde tus fuertes.","Habéis aradoimpiedad, segasteisiniquidad: comeréisfrutode mentira: porqueconfiasteen tu camino, en la multitudde tus fuertes."],[10,14,"Por tanto, en tus pueblosse levantaráalboroto, y todastus fortalezasserán destruídas, como destruyóSalmáná Beth-arbelel díade la batalla: la madrefué arrojadasobre los hijos.","Por tanto, en tus pueblosse levantaráalboroto, y todastus fortalezasserán destruídas, como destruyóSalmáná Beth-arbelel díade la batalla: la madrefué arrojadasobre los hijos."],[10,15,"Asíharáá vosotros Beth-elpor la maldadde vuestra maldad: en la mañanaserá del todocortadoelreyde Israel.","Asíharáá vosotros Beth-elpor la maldadde vuestra maldad: en la mañanaserá del todocortadoelreyde Israel."],[11,1,"CUANDOIsraelera muchacho, yo lo amé, y de Egiptollaméá mi hijo.","CUANDOIsraelera muchacho, yo lo amé, y de Egiptollaméá mi hijo."],[11,2,"Como los llamaban, asíellos se ibande su presencia; á los Baalessacrificaban, y á las esculturasofrecían sahumerios.","Como los llamaban, asíellos se ibande su presencia; á los Baalessacrificaban, y á las esculturasofrecían sahumerios."],[11,3,"Yocon todo eso guiaba en piesal mismo Ephraim, tomándolosdesus brazos; y noconocieronqueyolos cuidaba.","Yocon todo eso guiaba en piesal mismo Ephraim, tomándolosdesus brazos; y noconocieronqueyolos cuidaba."],[11,4,"Con cuerdashumanaslos traje, con cuerdasde amor: y fuípara ellos como los que alzanel yugodesobre sus mejillas, y lleguéhaciaél la comida.","Con cuerdashumanaslos traje, con cuerdasde amor: y fuípara ellos como los que alzanel yugodesobre sus mejillas, y lleguéhaciaél la comida."],[11,5,"Notornaráátierrade Egipto, antes el mismoAssurserá surey, porquenose quisieronconvertir.","Notornaráátierrade Egipto, antes el mismoAssurserá surey, porquenose quisieronconvertir."],[11,6,"Y caeráespadasobre sus ciudades, y consumirásus aldeas; consumirálasá causa de sus consejos.","Y caeráespadasobre sus ciudades, y consumirásus aldeas; consumirálasá causa de sus consejos."],[11,7,"Entre tanto, está mi puebloadheridoá la rebelióncontra mí: aunque lo llamanal Altísimo, ningunoabsolutamentequiere ensalzarle.","Entre tanto, está mi puebloadheridoá la rebelióncontra mí: aunque lo llamanal Altísimo, ningunoabsolutamentequiere ensalzarle."],[11,8,"¿Cómotengo de dejarte, oh Ehpraim? ¿he de entregarteyo, Israel? ¿cómopodré yo hacertecomo Adma, ni ponertecomo á Zeboim? Mi corazónse revuelvedentrode mí, inflámansetodasmis conmiseraciones.","¿Cómotengo de dejarte, oh Ehpraim? ¿he de entregarteyo, Israel? ¿cómopodré yo hacertecomo Adma, ni ponertecomo á Zeboim? Mi corazónse revuelvedentrode mí, inflámansetodasmis conmiseraciones."],[11,9,"Noejecutaréel furorde mi ira, novolverépara destruirá Ephraim: porqueDiossoy, y nohombre; el Santoen mediode ti: y noentraréen la ciudad.","Noejecutaréel furorde mi ira, novolverépara destruirá Ephraim: porqueDiossoy, y nohombre; el Santoen mediode ti: y noentraréen la ciudad."],[11,10,"En posde Jehovácaminarán: élbramará como león: cual leónrugiráélde cierto, y los hijosse moverán azoradosdel occidente.","En posde Jehovácaminarán: élbramará como león: cual leónrugiráélde cierto, y los hijosse moverán azoradosdel occidente."],[11,11,"Como avese moveránvelozmente de Egipto, y de la tierrade Asiriacomo paloma; y pondrélosensus casas, diceJehová.","Como avese moveránvelozmente de Egipto, y de la tierrade Asiriacomo paloma; y pondrélosensus casas, diceJehová."],[11,12,"",""],[12,1,"CERCÓMEEphraimconmentira, y la casade Israelconengaño: mas Judáaundomina conDios, y es fielconlos santos.","CERCÓMEEphraimconmentira, y la casade Israelconengaño: mas Judáaundomina conDios, y es fielconlos santos."],[12,2,"Ephraimse apacientadel viento, y sigueal solano: mentiray destrucciónaumentacontinuamente; porque hicieronalianzaconlos Asirios, y aceitese llevaá Egipto.","Ephraimse apacientadel viento, y sigueal solano: mentiray destrucciónaumentacontinuamente; porque hicieronalianzaconlos Asirios, y aceitese llevaá Egipto."],[12,3,"Pleitotiene JehováconJudápara visitar á Jacobconforme á sus caminos: pagaráleconforme á sus obras.","Pleitotiene JehováconJudápara visitar á Jacobconforme á sus caminos: pagaráleconforme á sus obras."],[12,4,"En el vientre tomó por el calcañará suhermano, y con sufortalezavencióal ángel.","En el vientre tomó por el calcañará suhermano, y con sufortalezavencióal ángel."],[12,5,"Vencióalángel, y prevaleció; lloró, y rogóle: en Beth-elle halló, y allíhablóconnosotros.","Vencióalángel, y prevaleció; lloró, y rogóle: en Beth-elle halló, y allíhablóconnosotros."],[12,6,"Mas Jehováes Diosde los ejércitos: Jehováes su memorial.","Mas Jehováes Diosde los ejércitos: Jehováes su memorial."],[12,7,"Túpues, conviérteteá tuDios: guardamisericordiay juicio, y entuDiosespera siempre.","Túpues, conviérteteá tuDios: guardamisericordiay juicio, y entuDiosespera siempre."],[12,8,"Esmercaderquetiene en su manopesofalso, amadorde opresión.","Esmercaderquetiene en su manopesofalso, amadorde opresión."],[12,9,"Y dijoEphraim: Ciertamenteyo he enriquecido, halladohe riquezaspara mí: nadiehallaráen mí iniquidad, nipecadoen todos mis trabajos.","Y dijoEphraim: Ciertamenteyo he enriquecido, halladohe riquezaspara mí: nadiehallaráen mí iniquidad, nipecadoen todos mis trabajos."],[12,10,"Empero yosoy Jehovátu Diosdesde la tierrade Egipto: aunte haré moraren tiendas, como en los díasde la fiesta.","Empero yosoy Jehovátu Diosdesde la tierrade Egipto: aunte haré moraren tiendas, como en los díasde la fiesta."],[12,11,"Y habladohe álos profetas, y yo aumentéla profecía, y por manode los profetaspuse semejanzas.","Y habladohe álos profetas, y yo aumentéla profecía, y por manode los profetaspuse semejanzas."],[12,12,"¿Es Galaadiniquidad? Ciertamentevanidadhan sido: en Gilgalsacrificaronbueyes: yaun son sus altarescomo montonesenlos surcosdel campo.","¿Es Galaadiniquidad? Ciertamentevanidadhan sido: en Gilgalsacrificaronbueyes: yaun son sus altarescomo montonesenlos surcosdel campo."],[12,13,"Mas Jacobhuyóá tierrade Aram, y sirvióIsraelpor mujer, y por mujerfué pastor.","Mas Jacobhuyóá tierrade Aram, y sirvióIsraelpor mujer, y por mujerfué pastor."],[12,14,"Y por profetahizo subirJehováá Israelde Egipto, y por profetafué guardado. Enojadoha Ephraim á Dioscon amarguras; por tanto, sus sangresse derramarán sobreél, y su Señorle pagarásu oprobio.","Y por profetahizo subirJehováá Israelde Egipto, y por profetafué guardado. Enojadoha Ephraim á Dioscon amarguras; por tanto, sus sangresse derramarán sobreél, y su Señorle pagarásu oprobio."],[13,1,"CUANDO Ephraimhablaba, hubo temor; fué ensalzadoen Israel; mas pecóen Baal, y murió.","CUANDO Ephraimhablaba, hubo temor; fué ensalzadoen Israel; mas pecóen Baal, y murió."],[13,2,"Y ahoraañadieroná su pecado, y de suplatase han hechosegún suentendimiento, estatuasde fundición, ídolos, todaobrade artífices; acerca de los cualesdicená los hombresque sacrifican, que besenlos becerros.","Y ahoraañadieroná su pecado, y de suplatase han hechosegún suentendimiento, estatuasde fundición, ídolos, todaobrade artífices; acerca de los cualesdicená los hombresque sacrifican, que besenlos becerros."],[13,3,"Por tantoseráncomo la nieblade la mañana, y como el rocíode la madrugadaque se pasa; como el tamoque la tempestadarroja de la era, y como el humoque de la chimeneasale.","Por tantoseráncomo la nieblade la mañana, y como el rocíode la madrugadaque se pasa; como el tamoque la tempestadarroja de la era, y como el humoque de la chimeneasale."],[13,4,"Mas yosoy Jehovátu Diosdesde la tierrade Egipto: noconoceráspues Diosfuera de mí, ni otro Salvadorsinoá mí.","Mas yosoy Jehovátu Diosdesde la tierrade Egipto: noconoceráspues Diosfuera de mí, ni otro Salvadorsinoá mí."],[13,5,"Yote conocíen el desierto, en tierraseca.","Yote conocíen el desierto, en tierraseca."],[13,6,"En sus pastosse hartaron, hartáronse, y ensoberbeciósesu corazón: porestacausa se olvidaronde mí.","En sus pastosse hartaron, hartáronse, y ensoberbeciósesu corazón: porestacausa se olvidaronde mí."],[13,7,"Por tanto, yo serépara ellos como león; como un leopardoenel caminolos espiaré.","Por tanto, yo serépara ellos como león; como un leopardoenel caminolos espiaré."],[13,8,"Como osoque ha perdido los hijoslos encontraré, y romperélas telasde su corazón, y allílos devorarécomo león: bestia del campolos despedazará.","Como osoque ha perdido los hijoslos encontraré, y romperélas telasde su corazón, y allílos devorarécomo león: bestia del campolos despedazará."],[13,9,"Te perdiste, oh Israel, masen mí estátu ayuda.","Te perdiste, oh Israel, masen mí estátu ayuda."],[13,10,"¿Dóndeestá tu rey, para que te guardecon todastus ciudades? ¿y tus jueces, de los cualesdijiste: Damereyy príncipes?","¿Dóndeestá tu rey, para que te guardecon todastus ciudades? ¿y tus jueces, de los cualesdijiste: Damereyy príncipes?"],[13,11,"Díte reyen mi furor, y quitéloen mi ira.","Díte reyen mi furor, y quitéloen mi ira."],[13,12,"Atadaestá la maldadde Ephraim; su pecadoestá guardado.","Atadaestá la maldadde Ephraim; su pecadoestá guardado."],[13,13,"Doloresde mujer de parto le vendrán: es un hijoignorante, que de otra maneranoestuviera tanto tiempoen el rompimientode los hijos.","Doloresde mujer de parto le vendrán: es un hijoignorante, que de otra maneranoestuviera tanto tiempoen el rompimientode los hijos."],[13,14,"De la manodel sepulcrolos redimiré, librarélosde la muerte. Oh muerte, yo seré tu muerte; y seré tu destrucción, oh sepulcro; arrepentimientoserá escondidode mis ojos.","De la manodel sepulcrolos redimiré, librarélosde la muerte. Oh muerte, yo seré tu muerte; y seré tu destrucción, oh sepulcro; arrepentimientoserá escondidode mis ojos."],[13,15,"Aunqueélfructificaráentrelos hermanos, vendráel solano, vientode Jehová, subiendode la parte del desierto, y secarseha suvena, y secarásesumanadero: élsaquearáel tesorode todaslas preciosasalhajas.","Aunqueélfructificaráentrelos hermanos, vendráel solano, vientode Jehová, subiendode la parte del desierto, y secarseha suvena, y secarásesumanadero: élsaquearáel tesorode todaslas preciosasalhajas."],[13,16,"Samariaserá asolada, porquese rebelócontra su Dios: caeráná cuchillo: sus niñosserán estrellados, y sus preñadasserán abiertas.","Samariaserá asolada, porquese rebelócontra su Dios: caeráná cuchillo: sus niñosserán estrellados, y sus preñadasserán abiertas."],[14,1,"CONVIÉRTETE, oh Israel, áJehovátu Dios: porquepor tu pecadohas caído.","CONVIÉRTETE, oh Israel, áJehovátu Dios: porquepor tu pecadohas caído."],[14,2,"Tomadconvosotros palabras, y convertíosáJehová, y decidle: Quitatodainiquidad, y aceptael bien, y daremos becerros de nuestroslabios.","Tomadconvosotros palabras, y convertíosáJehová, y decidle: Quitatodainiquidad, y aceptael bien, y daremos becerros de nuestroslabios."],[14,3,"NonoslibraráAssur; nosubiremossobrecaballos, ninunca másdiremosá la obrade nuestrasmanos: Diosesnuestros: porqueen ti el huérfanoalcanzará misericordia.","NonoslibraráAssur; nosubiremossobrecaballos, ninunca másdiremosá la obrade nuestrasmanos: Diosesnuestros: porqueen ti el huérfanoalcanzará misericordia."],[14,4,"Yo medicinarésu rebelión, amarélosde voluntad: porquemi furorse apartódeellos.","Yo medicinarésu rebelión, amarélosde voluntad: porquemi furorse apartódeellos."],[14,5,"Yo seréá Israelcomo rocío; él florecerácomo lirio, y extenderásus raícescomo el Líbano.","Yo seréá Israelcomo rocío; él florecerácomo lirio, y extenderásus raícescomo el Líbano."],[14,6,"Extendersehan sus ramos, y serásu gloriacomo la de la oliva, y olerácomo el Líbano.","Extendersehan sus ramos, y serásu gloriacomo la de la oliva, y olerácomo el Líbano."],[14,7,"Volverán, y se sentaránbajo de su sombra: serán vivificadoscomotrigo, y floreceráncomo la vid: su olor, como de vinodel Líbano.","Volverán, y se sentaránbajo de su sombra: serán vivificadoscomotrigo, y floreceráncomo la vid: su olor, como de vinodel Líbano."],[14,8,"Ephraim dirá: ¿Quémástendré ya con los ídolos? Yolo oiré, y miraré; yoseré á élcomo la hayaverde: demíserá halladotu fruto.","Ephraim dirá: ¿Quémástendré ya con los ídolos? Yolo oiré, y miraré; yoseré á élcomo la hayaverde: demíserá halladotu fruto."],[14,9,"¿Quiénes sabiopara que entienda esto, y prudentepara que lo sepa? Porquelos caminosde Jehováson derechos, y los justosandaránpor ellos: mas los rebeldesen ellos caerán.","¿Quiénes sabiopara que entienda esto, y prudentepara que lo sepa? Porquelos caminosde Jehováson derechos, y los justosandaránpor ellos: mas los rebeldesen ellos caerán."]],"rus-synodal":[[1,1,"Слово Господне, которое было к Осии, сыну Беериину, во дни Озии, Иоафама, Ахаза, Езекии, царей Иудейских, и во дни Иеровоама, сына Иоасова, царя Израильского.","Slovo Gospodne, kotoroe bylo k Osii, synu Beeriinu, vo dni Ozii, Ioafama, Ahaza, Ezekii, carej Iudejskih, i vo dni Ierovoama, syna Ioasova, carâ Izrailʹskogo."],[1,2,"Начало слова Господня к Осии. И сказал Господь Осии: иди, возьми себе жену блудницу и детей блуда; ибо сильно блудодействует земля сия, отступив от Господа.","Načalo slova Gospodnâ k Osii. I skazal Gospodʹ Osii: idi, vozʹmi sebe ženu bludnicu i detej bluda; ibo silʹno bludodejstvuet zemlâ siâ, otstupiv ot Gospoda."],[1,3,"И пошел он и взял Гомерь, дочь Дивлаима; и она зачала и родила ему сына.","I pošel on i vzâl Gomerʹ, dočʹ Divlaima; i ona začala i rodila emu syna."],[1,4,"И Господь сказал ему: нареки ему имя Изреель, потому что еще немного пройдет, и Я взыщу кровь Изрееля с дома Ииуева, и положу конец царству дома Израилева,","I Gospodʹ skazal emu: nareki emu imâ Izreelʹ, potomu čto eŝe nemnogo projdet, i Â vzyŝu krovʹ Izreelâ s doma Iiueva, i položu konec carstvu doma Izraileva,"],[1,5,"и будет в тот день, Я сокрушу лук Израилев в долине Изреель.","i budet v tot denʹ, Â sokrušu luk Izrailev v doline Izreelʹ."],[1,6,"И зачала еще, и родила дочь, и Он сказал ему: нареки ей имя Лорухама; ибо Я уже не буду более миловать дома Израилева, чтобы прощать им.","I začala eŝe, i rodila dočʹ, i On skazal emu: nareki ej imâ Loruhama; ibo Â uže ne budu bolee milovatʹ doma Izraileva, čtoby proŝatʹ im."],[1,7,"А дом Иудин помилую и спасу их в Господе Боге их, спасу их ни луком, ни мечом, ни войною, ни конями и всадниками.","A dom Iudin pomiluû i spasu ih v Gospode Boge ih, spasu ih ni lukom, ni mečom, ni vojnoû, ni konâmi i vsadnikami."],[1,8,"И, откормив грудью Непомилованную, она зачала и родила сына.","I, otkormiv grudʹû Nepomilovannuû, ona začala i rodila syna."],[1,9,"И сказал Он: нареки ему имя Лоамми, потому что вы не Мой народ, и Я не буду вашим [Богом].","I skazal On: nareki emu imâ Loammi, potomu čto vy ne Moj narod, i Â ne budu vašim [Bogom]."],[1,10,"Но будет число сынов Израилевых как песок морской, которого нельзя ни измерить, ни исчислить; и там, где говорили им: «вы не Мой народ», будут говорить им: «вы сыны Бога живого».","No budet čislo synov Izrailevyh kak pesok morskoj, kotorogo nelʹzâ ni izmeritʹ, ni isčislitʹ; i tam, gde govorili im: «vy ne Moj narod», budut govoritʹ im: «vy syny Boga živogo»."],[1,11,"И соберутся сыны Иудины и сыны Израилевы вместе, и поставят себе одну главу, и выйдут из земли переселения; ибо велик день Изрееля!","I soberutsâ syny Iudiny i syny Izrailevy vmeste, i postavât sebe odnu glavu, i vyjdut iz zemli pereseleniâ; ibo velik denʹ Izreelâ!"],[2,1,"Говорите братьям вашим: «Мой народ», и сестрам вашим: «Помилованная».","Govorite bratʹâm vašim: «Moj narod», i sestram vašim: «Pomilovannaâ»."],[2,2,"Судитесь с вашею матерью, судитесь; ибо она не жена Моя, и Я не муж ее; пусть она удалит блуд от лица своего и прелюбодеяние от грудей своих,","Suditesʹ s vašeû materʹû, suditesʹ; ibo ona ne žena Moâ, i Â ne muž ee; pustʹ ona udalit blud ot lica svoego i prelûbodeânie ot grudej svoih,"],[2,3,"дабы Я не разоблачил ее донага и не выставил ее, как в день рождения ее, не сделал ее пустынею, не обратил ее в землю сухую и не уморил ее жаждою.","daby Â ne razoblačil ee donaga i ne vystavil ee, kak v denʹ roždeniâ ee, ne sdelal ee pustyneû, ne obratil ee v zemlû suhuû i ne umoril ee žaždoû."],[2,4,"И детей ее не помилую, потому что они дети блуда.","I detej ee ne pomiluû, potomu čto oni deti bluda."],[2,5,"Ибо блудодействовала мать их и осрамила себя зачавшая их; ибо говорила: «пойду за любовниками моими, которые дают мне хлеб и воду, шерсть и лен, елей и напитки».","Ibo bludodejstvovala matʹ ih i osramila sebâ začavšaâ ih; ibo govorila: «pojdu za lûbovnikami moimi, kotorye daût mne hleb i vodu, šerstʹ i len, elej i napitki»."],[2,6,"За то вот Я загорожу путь ее тернами и обнесу ее оградою, и она не найдет стезей своих,","Za to vot Â zagorožu putʹ ee ternami i obnesu ee ogradoû, i ona ne najdet stezej svoih,"],[2,7,"и погонится за любовниками своими, но не догонит их, и будет искать их, но не найдет, и скажет: «пойду я и возвращусь к первому мужу моему; ибо тогда лучше было мне, нежели теперь».","i pogonitsâ za lûbovnikami svoimi, no ne dogonit ih, i budet iskatʹ ih, no ne najdet, i skažet: «pojdu â i vozvraŝusʹ k pervomu mužu moemu; ibo togda lučše bylo mne, neželi teperʹ»."],[2,8,"А не знала она, что Я, Я давал ей хлеб и вино и елей и умножил у нее серебро и золото, из которого сделали истукана Ваала.","A ne znala ona, čto Â, Â daval ej hleb i vino i elej i umnožil u nee serebro i zoloto, iz kotorogo sdelali istukana Vaala."],[2,9,"За то Я возьму назад хлеб Мой в его время и вино Мое в его пору и отниму шерсть и лен Мой, чем покрывается нагота ее.","Za to Â vozʹmu nazad hleb Moj v ego vremâ i vino Moe v ego poru i otnimu šerstʹ i len Moj, čem pokryvaetsâ nagota ee."],[2,10,"И ныне открою срамоту ее пред глазами любовников ее, и никто не исторгнет ее из руки Моей.","I nyne otkroû sramotu ee pred glazami lûbovnikov ee, i nikto ne istorgnet ee iz ruki Moej."],[2,11,"И прекращу у нее всякое веселье, праздники ее и новомесячия ее, и субботы ее, и все торжества ее.","I prekraŝu u nee vsâkoe veselʹe, prazdniki ee i novomesâčiâ ee, i subboty ee, i vse toržestva ee."],[2,12,"И опустошу виноградные лозы ее и смоковницы ее, о которых она говорит: «это у меня подарки, которые надарили мне любовники мои»; и Я превращу их в лес, и полевые звери поедят их.","I opustošu vinogradnye lozy ee i smokovnicy ee, o kotoryh ona govorit: «éto u menâ podarki, kotorye nadarili mne lûbovniki moi»; i Â prevraŝu ih v les, i polevye zveri poedât ih."],[2,13,"И накажу ее за дни служения Ваалам, когда она кадила им и, украсив себя серьгами и ожерельями, ходила за любовниками своими, а Меня забывала, говорит Господь.","I nakažu ee za dni služeniâ Vaalam, kogda ona kadila im i, ukrasiv sebâ serʹgami i ožerelʹâmi, hodila za lûbovnikami svoimi, a Menâ zabyvala, govorit Gospodʹ."],[2,14,"Посему вот и Я увлеку ее, приведу ее в пустыню и буду говорить к сердцу ее.","Posemu vot i Â uvleku ee, privedu ee v pustynû i budu govoritʹ k serdcu ee."],[2,15,"И дам ей оттуда виноградники ее и долину Ахор, в преддверие надежды; и она будет петь там, как во дни юности своей и как в день выхода своего из земли Египетской.","I dam ej ottuda vinogradniki ee i dolinu Ahor, v preddverie nadeždy; i ona budet petʹ tam, kak vo dni ûnosti svoej i kak v denʹ vyhoda svoego iz zemli Egipetskoj."],[2,16,"И будет в тот день, говорит Господь, ты будешь звать Меня: «муж мой», и не будешь более звать Меня: «Ваали».","I budet v tot denʹ, govorit Gospodʹ, ty budešʹ zvatʹ Menâ: «muž moj», i ne budešʹ bolee zvatʹ Menâ: «Vaali»."],[2,17,"И удалю имена Ваалов от уст ее, и не будут более вспоминаемы имена их.","I udalû imena Vaalov ot ust ee, i ne budut bolee vspominaemy imena ih."],[2,18,"И заключу в то время для них союз с полевыми зверями, и с птицами небесными, и с пресмыкающимися по земле; и лук, и меч, и войну истреблю от земли той и дам им жить в безопасности.","I zaklûču v to vremâ dlâ nih soûz s polevymi zverâmi, i s pticami nebesnymi, i s presmykaûŝimisâ po zemle; i luk, i meč, i vojnu istreblû ot zemli toj i dam im žitʹ v bezopasnosti."],[2,19,"И обручу тебя Мне навек, и обручу тебя Мне в правде и суде, в благости и милосердии.","I obruču tebâ Mne navek, i obruču tebâ Mne v pravde i sude, v blagosti i miloserdii."],[2,20,"И обручу тебя Мне в верности, и ты познаешь Господа.","I obruču tebâ Mne v vernosti, i ty poznaešʹ Gospoda."],[2,21,"И будет в тот день, Я услышу, говорит Господь, услышу небо, и оно услышит землю,","I budet v tot denʹ, Â uslyšu, govorit Gospodʹ, uslyšu nebo, i ono uslyšit zemlû,"],[2,22,"и земля услышит хлеб и вино и елей; а сии услышат Изреель.","i zemlâ uslyšit hleb i vino i elej; a sii uslyšat Izreelʹ."],[2,23,"И посею ее для Себя на земле, и помилую Непомилованную, и скажу не Моему народу: «ты – Мой народ», а он скажет: «Ты – мой Бог!»","I poseû ee dlâ Sebâ na zemle, i pomiluû Nepomilovannuû, i skažu ne Moemu narodu: «ty – Moj narod», a on skažet: «Ty – moj Bog!»"],[3,1,"И сказал мне Господь: иди еще и полюби женщину, любимую мужем, но прелюбодействующую, подобно тому, как любит Господь сынов Израилевых, а они обращаются к другим богам и любят виноградные лепешки их.","I skazal mne Gospodʹ: idi eŝe i polûbi ženŝinu, lûbimuû mužem, no prelûbodejstvuûŝuû, podobno tomu, kak lûbit Gospodʹ synov Izrailevyh, a oni obraŝaûtsâ k drugim bogam i lûbât vinogradnye lepeški ih."],[3,2,"И приобрел я ее себе за пятнадцать сребреников и за хомер ячменя и полхомера ячменя","I priobrel â ee sebe za pâtnadcatʹ srebrenikov i za homer âčmenâ i polhomera âčmenâ"],[3,3,"и сказал ей: много дней оставайся у меня; не блуди и не будь с другим; так же и я буду для тебя.","i skazal ej: mnogo dnej ostavajsâ u menâ; ne bludi i ne budʹ s drugim; tak že i â budu dlâ tebâ."],[3,4,"Ибо долгое время сыны Израилевы будут оставаться без царя и без князя и без жертвы, без жертвенника, без ефода и терафима.","Ibo dolgoe vremâ syny Izrailevy budut ostavatʹsâ bez carâ i bez knâzâ i bez žertvy, bez žertvennika, bez efoda i terafima."],[3,5,"После того обратятся сыны Израилевы и взыщут Господа Бога своего и Давида, царя своего, и будут благоговеть пред Господом и благостью Его в последние дни.","Posle togo obratâtsâ syny Izrailevy i vzyŝut Gospoda Boga svoego i Davida, carâ svoego, i budut blagogovetʹ pred Gospodom i blagostʹû Ego v poslednie dni."],[4,1,"Слушайте слово Господне, сыны Израилевы; ибо суд у Господа с жителями сей земли, потому что нет ни истины, ни милосердия, ни Богопознания на земле.","Slušajte slovo Gospodne, syny Izrailevy; ibo sud u Gospoda s žitelâmi sej zemli, potomu čto net ni istiny, ni miloserdiâ, ni Bogopoznaniâ na zemle."],[4,2,"Клятва и обман, убийство и воровство, и прелюбодейство крайне распространились, и кровопролитие следует за кровопролитием.","Klâtva i obman, ubijstvo i vorovstvo, i prelûbodejstvo krajne rasprostranilisʹ, i krovoprolitie sleduet za krovoprolitiem."],[4,3,"За то восплачет земля сия, и изнемогут все, живущие на ней, со зверями полевыми и птицами небесными, даже и рыбы морские погибнут.","Za to vosplačet zemlâ siâ, i iznemogut vse, živuŝie na nej, so zverâmi polevymi i pticami nebesnymi, daže i ryby morskie pogibnut."],[4,4,"Но никто не спорь, никто не обличай другого; и твой народ – как спорящие со священником.","No nikto ne sporʹ, nikto ne obličaj drugogo; i tvoj narod – kak sporâŝie so svâŝennikom."],[4,5,"И ты падешь днем, и пророк падет с тобою ночью, и истреблю матерь твою.","I ty padešʹ dnem, i prorok padet s toboû nočʹû, i istreblû materʹ tvoû."],[4,6,"Истреблен будет народ Мой за недостаток ведения: так как ты отверг ведение, то и Я отвергну тебя от священнодействия предо Мною; и как ты забыл закон Бога твоего, то и Я забуду детей твоих.","Istreblen budet narod Moj za nedostatok vedeniâ: tak kak ty otverg vedenie, to i Â otvergnu tebâ ot svâŝennodejstviâ predo Mnoû; i kak ty zabyl zakon Boga tvoego, to i Â zabudu detej tvoih."],[4,7,"Чем больше они умножаются, тем больше грешат против Меня; славу их обращу в бесславие.","Čem bolʹše oni umnožaûtsâ, tem bolʹše grešat protiv Menâ; slavu ih obraŝu v besslavie."],[4,8,"Грехами народа Моего кормятся они, и к беззаконию его стремится душа их.","Grehami naroda Moego kormâtsâ oni, i k bezzakoniû ego stremitsâ duša ih."],[4,9,"И что будет с народом, то и со священником; и накажу его по путям его, и воздам ему по делам его.","I čto budet s narodom, to i so svâŝennikom; i nakažu ego po putâm ego, i vozdam emu po delam ego."],[4,10,"Будут есть и не насытятся; будут блудить и не размножатся; ибо оставили служение Господу.","Budut estʹ i ne nasytâtsâ; budut bluditʹ i ne razmnožatsâ; ibo ostavili služenie Gospodu."],[4,11,"Блуд, вино и напитки завладели сердцем их.","Blud, vino i napitki zavladeli serdcem ih."],[4,12,"Народ Мой вопрошает свое дерево, и жезл его дает ему ответ; ибо дух блуда ввел их в заблуждение, и, блудодействуя, они отступили от Бога своего.","Narod Moj voprošaet svoe derevo, i žezl ego daet emu otvet; ibo duh bluda vvel ih v zabluždenie, i, bludodejstvuâ, oni otstupili ot Boga svoego."],[4,13,"На вершинах гор они приносят жертвы и на холмах совершают каждение под дубом и тополем и теревинфом, потому что хороша от них тень; поэтому любодействуют дочери ваши и прелюбодействуют невестки ваши.","Na veršinah gor oni prinosât žertvy i na holmah soveršaût každenie pod dubom i topolem i terevinfom, potomu čto horoša ot nih tenʹ; poétomu lûbodejstvuût dočeri vaši i prelûbodejstvuût nevestki vaši."],[4,14,"Я оставлю наказывать дочерей ваших, когда они блудодействуют, и невесток ваших, когда они прелюбодействуют, потому что вы сами на стороне блудниц и с любодейцами приносите жертвы, а невежественный народ гибнет.","Â ostavlû nakazyvatʹ dočerej vaših, kogda oni bludodejstvuût, i nevestok vaših, kogda oni prelûbodejstvuût, potomu čto vy sami na storone bludnic i s lûbodejcami prinosite žertvy, a nevežestvennyj narod gibnet."],[4,15,"Если ты, Израиль, блудодействуешь, то пусть не грешил бы Иуда; и не ходите в Галгал, и не восходите в Беф-Авен, и не клянитесь: «жив Господь!»","Esli ty, Izrailʹ, bludodejstvuešʹ, to pustʹ ne grešil by Iuda; i ne hodite v Galgal, i ne voshodite v Bef-Aven, i ne klânitesʹ: «živ Gospodʹ!»"],[4,16,"Ибо, как упрямая телица, упорен стал Израиль; посему будет ли теперь Господь пасти их, как агнцев на пространном пастбище?","Ibo, kak uprâmaâ telica, uporen stal Izrailʹ; posemu budet li teperʹ Gospodʹ pasti ih, kak agncev na prostrannom pastbiŝe?"],[4,17,"Привязался к идолам Ефрем; оставь его!","Privâzalsâ k idolam Efrem; ostavʹ ego!"],[4,18,"Отвратительно пьянство их, совершенно предались блудодеянию; князья их любят постыдное.","Otvratitelʹno pʹânstvo ih, soveršenno predalisʹ bludodeâniû; knâzʹâ ih lûbât postydnoe."],[4,19,"Охватит их ветер своими крыльями, и устыдятся они жертв своих.","Ohvatit ih veter svoimi krylʹâmi, i ustydâtsâ oni žertv svoih."],[5,1,"Слушайте это, священники, и внимайте, дом Израилев, и приклоните ухо, дом царя; ибо вам будет суд, потому что вы были западнею в Массифе и сетью, раскинутою на Фаворе.","Slušajte éto, svâŝenniki, i vnimajte, dom Izrailev, i priklonite uho, dom carâ; ibo vam budet sud, potomu čto vy byli zapadneû v Massife i setʹû, raskinutoû na Favore."],[5,2,"Глубоко погрязли они в распутстве; но Я накажу всех их.","Gluboko pogrâzli oni v rasputstve; no Â nakažu vseh ih."],[5,3,"Ефрема Я знаю, и Израиль не сокрыт от Меня; ибо ты блудодействуешь, Ефрем, и Израиль осквернился.","Efrema Â znaû, i Izrailʹ ne sokryt ot Menâ; ibo ty bludodejstvuešʹ, Efrem, i Izrailʹ oskvernilsâ."],[5,4,"Дела их не допускают их обратиться к Богу своему, ибо дух блуда внутри них, и Господа они не познали.","Dela ih ne dopuskaût ih obratitʹsâ k Bogu svoemu, ibo duh bluda vnutri nih, i Gospoda oni ne poznali."],[5,5,"И гордость Израиля унижена в глазах их; и Израиль и Ефрем падут от нечестия своего; падет и Иуда с ними.","I gordostʹ Izrailâ unižena v glazah ih; i Izrailʹ i Efrem padut ot nečestiâ svoego; padet i Iuda s nimi."],[5,6,"С овцами своими и волами своими пойдут искать Господа и не найдут Его: Он удалился от них.","S ovcami svoimi i volami svoimi pojdut iskatʹ Gospoda i ne najdut Ego: On udalilsâ ot nih."],[5,7,"Господу они изменили, потому что родили чужих детей; ныне новый месяц поест их с их имуществом.","Gospodu oni izmenili, potomu čto rodili čužih detej; nyne novyj mesâc poest ih s ih imuŝestvom."],[5,8,"Вострубите рогом в Гиве, трубою в Раме; возглашайте в Беф-Авене: «за тобою, Вениамин!»","Vostrubite rogom v Give, truboû v Rame; vozglašajte v Bef-Avene: «za toboû, Veniamin!»"],[5,9,"Ефрем сделается пустынею в день наказания; между коленами Израилевыми Я возвестил это.","Efrem sdelaetsâ pustyneû v denʹ nakazaniâ; meždu kolenami Izrailevymi Â vozvestil éto."],[5,10,"Вожди Иудины стали подобны передвигающим межи: изолью на них гнев Мой, как воду.","Voždi Iudiny stali podobny peredvigaûŝim meži: izolʹû na nih gnev Moj, kak vodu."],[5,11,"Угнетен Ефрем, поражен судом; ибо захотел ходить вслед суетных.","Ugneten Efrem, poražen sudom; ibo zahotel hoditʹ vsled suetnyh."],[5,12,"И буду как моль для Ефрема и как червь для дома Иудина.","I budu kak molʹ dlâ Efrema i kak červʹ dlâ doma Iudina."],[5,13,"И увидел Ефрем болезнь свою, и Иуда – свою рану, и пошел Ефрем к Ассуру, и послал к царю Иареву; но он не может исцелить вас и не излечит вас от раны.","I uvidel Efrem boleznʹ svoû, i Iuda – svoû ranu, i pošel Efrem k Assuru, i poslal k carû Iarevu; no on ne možet iscelitʹ vas i ne izlečit vas ot rany."],[5,14,"Ибо Я как лев для Ефрема и как скимен для дома Иудина; Я, Я растерзаю и уйду; унесу, и никто не спасет.","Ibo Â kak lev dlâ Efrema i kak skimen dlâ doma Iudina; Â, Â rasterzaû i ujdu; unesu, i nikto ne spaset."],[5,15,"Пойду, возвращусь в Мое место, доколе они не признают себя виновными и не взыщут лица Моего.","Pojdu, vozvraŝusʹ v Moe mesto, dokole oni ne priznaût sebâ vinovnymi i ne vzyŝut lica Moego."],[6,1,"В скорби своей они с раннего утра будут искать Меня и говорить: «пойдем и возвратимся к Господу! ибо Он уязвил – и Он исцелит нас, поразил – и перевяжет наши раны;","V skorbi svoej oni s rannego utra budut iskatʹ Menâ i govoritʹ: «pojdem i vozvratimsâ k Gospodu! ibo On uâzvil – i On iscelit nas, porazil – i perevâžet naši rany;"],[6,2,"оживит нас через два дня, в третий день восставит нас, и мы будем жить пред лицом Его.","oživit nas čerez dva dnâ, v tretij denʹ vosstavit nas, i my budem žitʹ pred licom Ego."],[6,3,"Итак, познаем, будем стремиться познать Господа; как утренняя заря – явление Его, и Он придет к нам, как дождь, как поздний дождь оросит землю».","Itak, poznaem, budem stremitʹsâ poznatʹ Gospoda; kak utrennââ zarâ – âvlenie Ego, i On pridet k nam, kak doždʹ, kak pozdnij doždʹ orosit zemlû»."],[6,4,"Что сделаю тебе, Ефрем? что сделаю тебе, Иуда? благочестие ваше, как утренний туман и как роса, скоро исчезающая.","Čto sdelaû tebe, Efrem? čto sdelaû tebe, Iuda? blagočestie vaše, kak utrennij tuman i kak rosa, skoro isčezaûŝaâ."],[6,5,"Посему Я поражал через пророков и бил их словами уст Моих, и суд Мой, как восходящий свет.","Posemu Â poražal čerez prorokov i bil ih slovami ust Moih, i sud Moj, kak voshodâŝij svet."],[6,6,"Ибо Я милости хочу, а не жертвы, и Боговедения более, нежели всесожжений.","Ibo Â milosti hoču, a ne žertvy, i Bogovedeniâ bolee, neželi vsesožženij."],[6,7,"Они же, подобно Адаму, нарушили завет и там изменили Мне.","Oni že, podobno Adamu, narušili zavet i tam izmenili Mne."],[6,8,"Галаад – город нечестивцев, запятнанный кровью.","Galaad – gorod nečestivcev, zapâtnannyj krovʹû."],[6,9,"Как разбойники подстерегают человека, так сборище священников убивают на пути в Сихем и совершают мерзости.","Kak razbojniki podsteregaût čeloveka, tak sboriŝe svâŝennikov ubivaût na puti v Sihem i soveršaût merzosti."],[6,10,"В доме Израиля Я вижу ужасное; там блудодеяние у Ефрема, осквернился Израиль.","V dome Izrailâ Â vižu užasnoe; tam bludodeânie u Efrema, oskvernilsâ Izrailʹ."],[6,11,"И тебе, Иуда, назначена жатва, когда Я возвращу плен народа Моего.","I tebe, Iuda, naznačena žatva, kogda Â vozvraŝu plen naroda Moego."],[7,1,"Когда Я врачевал Израиля, открылась неправда Ефрема и злодейство Самарии: ибо они поступают лживо; и входит вор, и разбойник грабит по улицам.","Kogda Â vračeval Izrailâ, otkrylasʹ nepravda Efrema i zlodejstvo Samarii: ibo oni postupaût lživo; i vhodit vor, i razbojnik grabit po ulicam."],[7,2,"Не помышляют они в сердце своем, что Я помню все злодеяния их; теперь окружают их дела их; они пред лицом Моим.","Ne pomyšlâût oni v serdce svoem, čto Â pomnû vse zlodeâniâ ih; teperʹ okružaût ih dela ih; oni pred licom Moim."],[7,3,"Злодейством своим они увеселяют царя и обманами своими – князей.","Zlodejstvom svoim oni uveselâût carâ i obmanami svoimi – knâzej."],[7,4,"Все они пылают прелюбодейством, как печь, растопленная пекарем, который перестает поджигать ее, когда замесит тесто и оно вскиснет.","Vse oni pylaût prelûbodejstvom, kak pečʹ, rastoplennaâ pekarem, kotoryj perestaet podžigatʹ ee, kogda zamesit testo i ono vskisnet."],[7,5,"«День нашего царя!» говорят князья, разгоряченные до болезни вином, а он протягивает руку свою к кощунам.","«Denʹ našego carâ!» govorât knâzʹâ, razgorâčennye do bolezni vinom, a on protâgivaet ruku svoû k koŝunam."],[7,6,"Ибо они коварством своим делают сердце свое подобным печи: пекарь их спит всю ночь, а утром она горит, как пылающий огонь.","Ibo oni kovarstvom svoim delaût serdce svoe podobnym peči: pekarʹ ih spit vsû nočʹ, a utrom ona gorit, kak pylaûŝij ogonʹ."],[7,7,"Все они распалены, как печь, и пожирают судей своих; все цари их падают, и никто из них не взывает ко Мне.","Vse oni raspaleny, kak pečʹ, i požiraût sudej svoih; vse cari ih padaût, i nikto iz nih ne vzyvaet ko Mne."],[7,8,"Ефрем смешался с народами, Ефрем стал как неповороченный хлеб.","Efrem smešalsâ s narodami, Efrem stal kak nepovoročennyj hleb."],[7,9,"Чужие пожирали силу его, и он не замечал; седина покрыла его, а он не знает.","Čužie požirali silu ego, i on ne zamečal; sedina pokryla ego, a on ne znaet."],[7,10,"И гордость Израиля унижена в глазах их, – и при всем том они не обратились к Господу Богу своему и не взыскали Его.","I gordostʹ Izrailâ unižena v glazah ih, – i pri vsem tom oni ne obratilisʹ k Gospodu Bogu svoemu i ne vzyskali Ego."],[7,11,"И стал Ефрем, как глупый голубь, без сердца: зовут Египтян, идут в Ассирию.","I stal Efrem, kak glupyj golubʹ, bez serdca: zovut Egiptân, idut v Assiriû."],[7,12,"Когда они пойдут, Я закину на них сеть Мою; как птиц небесных низвергну их; накажу их, как слышало собрание их.","Kogda oni pojdut, Â zakinu na nih setʹ Moû; kak ptic nebesnyh nizvergnu ih; nakažu ih, kak slyšalo sobranie ih."],[7,13,"Горе им, что они удалились от Меня; гибель им, что они отпали от Меня! Я спасал их, а они ложь говорили на Меня.","Gore im, čto oni udalilisʹ ot Menâ; gibelʹ im, čto oni otpali ot Menâ! Â spasal ih, a oni ložʹ govorili na Menâ."],[7,14,"И не взывали ко Мне сердцем своим, когда вопили на ложах своих; собираются из-за хлеба и вина, а от Меня удаляются.","I ne vzyvali ko Mne serdcem svoim, kogda vopili na ložah svoih; sobiraûtsâ iz-za hleba i vina, a ot Menâ udalâûtsâ."],[7,15,"Я вразумлял их и укреплял мышцы их, а они умышляли злое против Меня.","Â vrazumlâl ih i ukreplâl myšcy ih, a oni umyšlâli zloe protiv Menâ."],[7,16,"Они обращались, но не к Всевышнему, стали – как неверный лук; падут от меча князья их за дерзость языка своего; это будет посмеянием над ними в земле Египетской.","Oni obraŝalisʹ, no ne k Vsevyšnemu, stali – kak nevernyj luk; padut ot meča knâzʹâ ih za derzostʹ âzyka svoego; éto budet posmeâniem nad nimi v zemle Egipetskoj."],[8,1,"Трубу к устам твоим! Как орел налетит на дом Господень за то, что они нарушили завет Мой и преступили закон Мой!","Trubu k ustam tvoim! Kak orel naletit na dom Gospodenʹ za to, čto oni narušili zavet Moj i prestupili zakon Moj!"],[8,2,"Ко Мне будут взывать: «Боже мой! мы познали Тебя, мы – Израиль».","Ko Mne budut vzyvatʹ: «Bože moj! my poznali Tebâ, my – Izrailʹ»."],[8,3,"Отверг Израиль доброе; враг будет преследовать его.","Otverg Izrailʹ dobroe; vrag budet presledovatʹ ego."],[8,4,"Поставляли царей сами, без Меня; ставили князей, но без Моего ведома; из серебра своего и золота своего сделали для себя идолов: оттуда гибель.","Postavlâli carej sami, bez Menâ; stavili knâzej, no bez Moego vedoma; iz serebra svoego i zolota svoego sdelali dlâ sebâ idolov: ottuda gibelʹ."],[8,5,"Оставил тебя телец твой, Самария! воспылал гнев Мой на них; доколе не могут они очиститься?","Ostavil tebâ telec tvoj, Samariâ! vospylal gnev Moj na nih; dokole ne mogut oni očistitʹsâ?"],[8,6,"Ибо и он – дело Израиля: художник сделал его, и потому он не бог; в куски обратится телец Самарийский!","Ibo i on – delo Izrailâ: hudožnik sdelal ego, i potomu on ne bog; v kuski obratitsâ telec Samarijskij!"],[8,7,"Так как они сеяли ветер, то и пожнут бурю: хлеба на корню не будет у него; зерно не даст муки; а если и даст, то чужие проглотят ее.","Tak kak oni seâli veter, to i požnut burû: hleba na kornû ne budet u nego; zerno ne dast muki; a esli i dast, to čužie proglotât ee."],[8,8,"Поглощен Израиль; теперь они будут среди народов, как негодный сосуд.","Pogloŝen Izrailʹ; teperʹ oni budut sredi narodov, kak negodnyj sosud."],[8,9,"Они пошли к Ассуру, как дикий осел, одиноко бродящий; Ефрем приобретал подарками расположение к себе.","Oni pošli k Assuru, kak dikij osel, odinoko brodâŝij; Efrem priobretal podarkami raspoloženie k sebe."],[8,10,"Хотя они и посылали дары к народам, но скоро Я соберу их, и они начнут страдать от бремени царя князей;","Hotâ oni i posylali dary k narodam, no skoro Â soberu ih, i oni načnut stradatʹ ot bremeni carâ knâzej;"],[8,11,"ибо много жертвенников настроил Ефрем для греха, – ко греху послужили ему эти жертвенники.","ibo mnogo žertvennikov nastroil Efrem dlâ greha, – ko grehu poslužili emu éti žertvenniki."],[8,12,"Написал Я ему важные законы Мои, но они сочтены им как бы чужие.","Napisal Â emu važnye zakony Moi, no oni sočteny im kak by čužie."],[8,13,"В жертвоприношениях Мне они приносят мясо и едят его; Господу неугодны они; ныне Он вспомнит нечестие их и накажет их за грехи их: они возвратятся в Египет.","V žertvoprinošeniâh Mne oni prinosât mâso i edât ego; Gospodu neugodny oni; nyne On vspomnit nečestie ih i nakažet ih za grehi ih: oni vozvratâtsâ v Egipet."],[8,14,"Забыл Израиль Создателя своего и устроил капища, и Иуда настроил много укрепленных городов; но Я пошлю огонь на города его, и пожрет чертоги его.","Zabyl Izrailʹ Sozdatelâ svoego i ustroil kapiŝa, i Iuda nastroil mnogo ukreplennyh gorodov; no Â pošlû ogonʹ na goroda ego, i požret čertogi ego."],[9,1,"Не радуйся, Израиль, до восторга, как другие народы, ибо ты блудодействуешь, удалившись от Бога твоего: любишь блудодейные дары на всех гумнах.","Ne radujsâ, Izrailʹ, do vostorga, kak drugie narody, ibo ty bludodejstvuešʹ, udalivšisʹ ot Boga tvoego: lûbišʹ bludodejnye dary na vseh gumnah."],[9,2,"Гумно и точило не будут питать их, и надежда на виноградный сок обманет их.","Gumno i točilo ne budut pitatʹ ih, i nadežda na vinogradnyj sok obmanet ih."],[9,3,"Не будут они жить на земле Господней: Ефрем возвратится в Египет, и в Ассирии будут есть нечистое.","Ne budut oni žitʹ na zemle Gospodnej: Efrem vozvratitsâ v Egipet, i v Assirii budut estʹ nečistoe."],[9,4,"Не будут возливать Господу вина, и неугодны Ему будут жертвы их; они будут для них как хлеб похоронный: все, которые будут есть его, осквернятся, ибо хлеб их – для души их, а в дом Господень он не войдет.","Ne budut vozlivatʹ Gospodu vina, i neugodny Emu budut žertvy ih; oni budut dlâ nih kak hleb pohoronnyj: vse, kotorye budut estʹ ego, oskvernâtsâ, ibo hleb ih – dlâ duši ih, a v dom Gospodenʹ on ne vojdet."],[9,5,"Что будете делать в день торжества и в день праздника Господня?","Čto budete delatʹ v denʹ toržestva i v denʹ prazdnika Gospodnâ?"],[9,6,"Ибо вот, они уйдут по причине опустошения; Египет соберет их, Мемфис похоронит их; драгоценностями их из серебра завладеет крапива, колючий терн будет в шатрах их.","Ibo vot, oni ujdut po pričine opustošeniâ; Egipet soberet ih, Memfis pohoronit ih; dragocennostâmi ih iz serebra zavladeet krapiva, kolûčij tern budet v šatrah ih."],[9,7,"Пришли дни посещения, пришли дни воздаяния; да узнает Израиль, что глуп прорицатель, безумен выдающий себя за вдохновенного, по причине множества беззаконий твоих и великой враждебности.","Prišli dni poseŝeniâ, prišli dni vozdaâniâ; da uznaet Izrailʹ, čto glup proricatelʹ, bezumen vydaûŝij sebâ za vdohnovennogo, po pričine množestva bezzakonij tvoih i velikoj vraždebnosti."],[9,8,"Ефрем – страж подле Бога моего; пророк – сеть птицелова на всех путях его; соблазн в доме Бога его.","Efrem – straž podle Boga moego; prorok – setʹ pticelova na vseh putâh ego; soblazn v dome Boga ego."],[9,9,"Глубоко упали они, развратились, как во дни Гивы; Он вспомнит нечестие их, накажет их за грехи их.","Gluboko upali oni, razvratilisʹ, kak vo dni Givy; On vspomnit nečestie ih, nakažet ih za grehi ih."],[9,10,"Как виноград в пустыне, Я нашел Израиля; как первую ягоду на смоковнице, в первое время ее, увидел Я отцов ваших, – но они пошли к Ваал-Фегору и предались постыдному, и сами стали мерзкими, как те, которых возлюбили.","Kak vinograd v pustyne, Â našel Izrailâ; kak pervuû âgodu na smokovnice, v pervoe vremâ ee, uvidel Â otcov vaših, – no oni pošli k Vaal-Fegoru i predalisʹ postydnomu, i sami stali merzkimi, kak te, kotoryh vozlûbili."],[9,11,"У Ефремлян, как птица, улетит слава [чадородия]: ни рождения, ни беременности, ни зачатия [не будет].","U Efremlân, kak ptica, uletit slava [čadorodiâ]: ni roždeniâ, ni beremennosti, ni začatiâ [ne budet]."],[9,12,"А хотя бы они и воспитали детей своих, отниму их; ибо горе им, когда удалюсь от них!","A hotâ by oni i vospitali detej svoih, otnimu ih; ibo gore im, kogda udalûsʹ ot nih!"],[9,13,"Ефрем, как Я видел его до Тира, насажден на прекрасной местности; однако Ефрем выведет детей своих к убийце.","Efrem, kak Â videl ego do Tira, nasažden na prekrasnoj mestnosti; odnako Efrem vyvedet detej svoih k ubijce."],[9,14,"Дай им, Господи: что Ты дашь им? дай им утробу нерождающую и сухие сосцы.","Daj im, Gospodi: čto Ty dašʹ im? daj im utrobu neroždaûŝuû i suhie soscy."],[9,15,"Все зло их – в Галгале: там Я возненавидел их за злые дела их; изгоню их из дома Моего, не буду больше любить их; все князья их – отступники.","Vse zlo ih – v Galgale: tam Â voznenavidel ih za zlye dela ih; izgonû ih iz doma Moego, ne budu bolʹše lûbitʹ ih; vse knâzʹâ ih – otstupniki."],[9,16,"Поражен Ефрем; иссох корень их, – не будут приносить они плода, а если и будут рождать, Я умерщвлю вожделенный плод утробы их.","Poražen Efrem; issoh korenʹ ih, – ne budut prinositʹ oni ploda, a esli i budut roždatʹ, Â umerŝvlû voždelennyj plod utroby ih."],[9,17,"Отвергнет их Бог мой, потому что они не послушались Его, и будут скитальцами между народами.","Otvergnet ih Bog moj, potomu čto oni ne poslušalisʹ Ego, i budut skitalʹcami meždu narodami."],[10,1,"Израиль – ветвистый виноград, умножает для себя плод: чем более у него плодов, тем более умножает жертвенники; чем лучше земля у него, тем более украшают они кумиры.","Izrailʹ – vetvistyj vinograd, umnožaet dlâ sebâ plod: čem bolee u nego plodov, tem bolee umnožaet žertvenniki; čem lučše zemlâ u nego, tem bolee ukrašaût oni kumiry."],[10,2,"Разделилось сердце их, за то они и будут наказаны: Он разрушит жертвенники их, сокрушит кумиры их.","Razdelilosʹ serdce ih, za to oni i budut nakazany: On razrušit žertvenniki ih, sokrušit kumiry ih."],[10,3,"Теперь они говорят: «нет у нас царя, ибо мы не убоялись Господа; а царь, – что он нам сделает?»","Teperʹ oni govorât: «net u nas carâ, ibo my ne uboâlisʹ Gospoda; a carʹ, – čto on nam sdelaet?»"],[10,4,"Говорят слова пустые, клянутся ложно, заключают союзы; за то явится суд над ними, как ядовитая трава на бороздах поля.","Govorât slova pustye, klânutsâ ložno, zaklûčaût soûzy; za to âvitsâ sud nad nimi, kak âdovitaâ trava na borozdah polâ."],[10,5,"За тельца Беф-Авена вострепещут жители Самарии; восплачет о нем народ его, и жрецы его, радовавшиеся о нем, будут плакать о славе его, потому что она отойдет от него.","Za telʹca Bef-Avena vostrepeŝut žiteli Samarii; vosplačet o nem narod ego, i žrecy ego, radovavšiesâ o nem, budut plakatʹ o slave ego, potomu čto ona otojdet ot nego."],[10,6,"И сам он отнесен будет в Ассирию, в дар царю Иареву; постыжен будет Ефрем, и посрамится Израиль от замысла своего.","I sam on otnesen budet v Assiriû, v dar carû Iarevu; postyžen budet Efrem, i posramitsâ Izrailʹ ot zamysla svoego."],[10,7,"Исчезнет в Самарии царь ее, как пена на поверхности воды.","Isčeznet v Samarii carʹ ee, kak pena na poverhnosti vody."],[10,8,"И истреблены будут высоты Авена, грех Израиля; терние и волчцы вырастут на жертвенниках их, и скажут они горам: «покройте нас», и холмам: «падите на нас».","I istrebleny budut vysoty Avena, greh Izrailâ; ternie i volčcy vyrastut na žertvennikah ih, i skažut oni goram: «pokrojte nas», i holmam: «padite na nas»."],[10,9,"Больше, нежели во дни Гивы, грешил ты, Израиль; там они устояли; война в Гаваоне против сынов нечестия не постигла их.","Bolʹše, neželi vo dni Givy, grešil ty, Izrailʹ; tam oni ustoâli; vojna v Gavaone protiv synov nečestiâ ne postigla ih."],[10,10,"По желанию Моему накажу их, и соберутся против них народы, и они будут связаны за двойное преступление их.","Po želaniû Moemu nakažu ih, i soberutsâ protiv nih narody, i oni budut svâzany za dvojnoe prestuplenie ih."],[10,11,"Ефрем – обученная телица, привычная к молотьбе, и Я Сам возложу ярмо на тучную шею его; на Ефреме будут верхом ездить, Иуда будет пахать, Иаков будет боронить.","Efrem – obučennaâ telica, privyčnaâ k molotʹbe, i Â Sam vozložu ârmo na tučnuû šeû ego; na Efreme budut verhom ezditʹ, Iuda budet pahatʹ, Iakov budet boronitʹ."],[10,12,"Сейте себе в правду и пожнете милость; распахивайте у себя новину, ибо время взыскать Господа, чтобы Он, когда придет, дождем пролил на вас правду.","Sejte sebe v pravdu i požnete milostʹ; raspahivajte u sebâ novinu, ibo vremâ vzyskatʹ Gospoda, čtoby On, kogda pridet, doždem prolil na vas pravdu."],[10,13,"Вы возделывали нечестие, пожинаете беззаконие, едите плод лжи, потому что ты надеялся на путь твой, на множество ратников твоих.","Vy vozdelyvali nečestie, požinaete bezzakonie, edite plod lži, potomu čto ty nadeâlsâ na putʹ tvoj, na množestvo ratnikov tvoih."],[10,14,"И произойдет смятение в народе твоем, и все твердыни твои будут разрушены, как Салман разрушил Бет-Арбел в день брани: мать была убита с детьми.","I proizojdet smâtenie v narode tvoem, i vse tverdyni tvoi budut razrušeny, kak Salman razrušil Bet-Arbel v denʹ brani: matʹ byla ubita s detʹmi."],[10,15,"Вот что причинит вам Вефиль за крайнее нечестие ваше.","Vot čto pričinit vam Vefilʹ za krajnee nečestie vaše."],[11,1,"На заре погибнет царь Израилев! Когда Израиль был юн, Я любил его и из Египта вызвал сына Моего.","Na zare pogibnet carʹ Izrailev! Kogda Izrailʹ byl ûn, Â lûbil ego i iz Egipta vyzval syna Moego."],[11,2,"Звали их, а они уходили прочь от лица их: приносили жертву Ваалам и кадили истуканам.","Zvali ih, a oni uhodili pročʹ ot lica ih: prinosili žertvu Vaalam i kadili istukanam."],[11,3,"Я Сам приучал Ефрема ходить, носил его на руках Своих, а они не сознавали, что Я врачевал их.","Â Sam priučal Efrema hoditʹ, nosil ego na rukah Svoih, a oni ne soznavali, čto Â vračeval ih."],[11,4,"Узами человеческими влек Я их, узами любви, и был для них как бы поднимающий ярмо с челюстей их, и ласково подкладывал пищу им.","Uzami čelovečeskimi vlek Â ih, uzami lûbvi, i byl dlâ nih kak by podnimaûŝij ârmo s čelûstej ih, i laskovo podkladyval piŝu im."],[11,5,"Не возвратится он в Египет, но Ассур – он будет царем его, потому что они не захотели обратиться ко Мне.","Ne vozvratitsâ on v Egipet, no Assur – on budet carem ego, potomu čto oni ne zahoteli obratitʹsâ ko Mne."],[11,6,"И падет меч на города его, и истребит затворы его, и пожрет их за умыслы их.","I padet meč na goroda ego, i istrebit zatvory ego, i požret ih za umysly ih."],[11,7,"Народ Мой закоснел в отпадении от Меня, и хотя призывают его к горнему, он не возвышается единодушно.","Narod Moj zakosnel v otpadenii ot Menâ, i hotâ prizyvaût ego k gornemu, on ne vozvyšaetsâ edinodušno."],[11,8,"Как поступлю с тобою, Ефрем? как предам тебя, Израиль? Поступлю ли с тобою, как с Адамою, сделаю ли тебе, что Севоиму? Повернулось во Мне сердце Мое, возгорелась вся жалость Моя!","Kak postuplû s toboû, Efrem? kak predam tebâ, Izrailʹ? Postuplû li s toboû, kak s Adamoû, sdelaû li tebe, čto Sevoimu? Povernulosʹ vo Mne serdce Moe, vozgorelasʹ vsâ žalostʹ Moâ!"],[11,9,"Не сделаю по ярости гнева Моего, не истреблю Ефрема, ибо Я – Бог, а не человек; среди тебя – Святой; Я не войду в город.","Ne sdelaû po ârosti gneva Moego, ne istreblû Efrema, ibo Â – Bog, a ne čelovek; sredi tebâ – Svâtoj; Â ne vojdu v gorod."],[11,10,"Вслед Господа пойдут они; как лев, Он даст глас Свой; даст глас Свой, и встрепенутся к Нему сыны с запада,","Vsled Gospoda pojdut oni; kak lev, On dast glas Svoj; dast glas Svoj, i vstrepenutsâ k Nemu syny s zapada,"],[11,11,"встрепенутся из Египта, как птицы, и из земли Ассирийской, как голуби, и вселю их в домы их, говорит Господь.","vstrepenutsâ iz Egipta, kak pticy, i iz zemli Assirijskoj, kak golubi, i vselû ih v domy ih, govorit Gospodʹ."],[11,12,"Окружил Меня Ефрем ложью и дом Израилев лукавством; Иуда держался еще Бога и верен был со святыми.","Okružil Menâ Efrem ložʹû i dom Izrailev lukavstvom; Iuda deržalsâ eŝe Boga i veren byl so svâtymi."],[12,1,"Ефрем пасет ветер и гоняется за восточным ветром, каждый день умножает ложь и разорение; заключают они союз с Ассуром, и в Египет отвозится елей.","Efrem paset veter i gonâetsâ za vostočnym vetrom, každyj denʹ umnožaet ložʹ i razorenie; zaklûčaût oni soûz s Assurom, i v Egipet otvozitsâ elej."],[12,2,"Но и с Иудою у Господа суд, и Он посетит Иакова по путям его, воздаст ему по делам его.","No i s Iudoû u Gospoda sud, i On posetit Iakova po putâm ego, vozdast emu po delam ego."],[12,3,"Еще во чреве матери запинал он брата своего, а возмужав – боролся с Богом.","Eŝe vo čreve materi zapinal on brata svoego, a vozmužav – borolsâ s Bogom."],[12,4,"Он боролся с Ангелом – и превозмог; плакал и умолял Его; в Вефиле Он нашел нас и там говорил с нами.","On borolsâ s Angelom – i prevozmog; plakal i umolâl Ego; v Vefile On našel nas i tam govoril s nami."],[12,5,"А Господь есть Бог Саваоф; Сущий [Иегова] – имя Его.","A Gospodʹ estʹ Bog Savaof; Suŝij [Iegova] – imâ Ego."],[12,6,"Обратись и ты к Богу твоему; наблюдай милость и суд и уповай на Бога твоего всегда.","Obratisʹ i ty k Bogu tvoemu; nablûdaj milostʹ i sud i upovaj na Boga tvoego vsegda."],[12,7,"Хананеянин с неверными весами в руке любит обижать;","Hananeânin s nevernymi vesami v ruke lûbit obižatʹ;"],[12,8,"и Ефрем говорит: «однако я разбогател; накопил себе имущества, хотя во всех моих трудах не найдут ничего незаконного, что было бы грехом».","i Efrem govorit: «odnako â razbogatel; nakopil sebe imuŝestva, hotâ vo vseh moih trudah ne najdut ničego nezakonnogo, čto bylo by grehom»."],[12,9,"А Я, Господь Бог твой от самой земли Египетской, опять поселю тебя в кущах, как во дни праздника.","A Â, Gospodʹ Bog tvoj ot samoj zemli Egipetskoj, opâtʹ poselû tebâ v kuŝah, kak vo dni prazdnika."],[12,10,"Я говорил к пророкам, и умножал видения, и чрез пророков употреблял притчи.","Â govoril k prorokam, i umnožal videniâ, i črez prorokov upotreblâl pritči."],[12,11,"Если Галаад сделался Авеном, то они стали суетны, в Галгалах закалали в жертву тельцов, и жертвенники их стояли как груды камней на межах поля.","Esli Galaad sdelalsâ Avenom, to oni stali suetny, v Galgalah zakalali v žertvu telʹcov, i žertvenniki ih stoâli kak grudy kamnej na mežah polâ."],[12,12,"Убежал Иаков на поля Сирийские, и служил Израиль за жену, и за жену стерег овец.","Ubežal Iakov na polâ Sirijskie, i služil Izrailʹ za ženu, i za ženu stereg ovec."],[12,13,"Чрез пророка вывел Господь Израиля из Египта, и чрез пророка Он охранял его.","Črez proroka vyvel Gospodʹ Izrailâ iz Egipta, i črez proroka On ohranâl ego."],[12,14,"Сильно раздражил Ефрем Господа, и за то кровь его оставит на нем, и поношение его обратит Господь на него.","Silʹno razdražil Efrem Gospoda, i za to krovʹ ego ostavit na nem, i ponošenie ego obratit Gospodʹ na nego."],[13,1,"Когда Ефрем говорил, все трепетали. Он был высок в Израиле; но сделался виновным через Ваала и погиб.","Kogda Efrem govoril, vse trepetali. On byl vysok v Izraile; no sdelalsâ vinovnym čerez Vaala i pogib."],[13,2,"И ныне прибавили они ко греху: сделали для себя литых истуканов из серебра своего, по понятию своему, – полная работа художников, – и говорят они приносящим жертву людям: «целуйте тельцов!»","I nyne pribavili oni ko grehu: sdelali dlâ sebâ lityh istukanov iz serebra svoego, po ponâtiû svoemu, – polnaâ rabota hudožnikov, – i govorât oni prinosâŝim žertvu lûdâm: «celujte telʹcov!»"],[13,3,"За то они будут как утренний туман, как роса, скоро исчезающая, как мякина, свеваемая с гумна, и как дым из трубы.","Za to oni budut kak utrennij tuman, kak rosa, skoro isčezaûŝaâ, kak mâkina, svevaemaâ s gumna, i kak dym iz truby."],[13,4,"Но Я – Господь Бог твой от земли Египетской, – и ты не должен знать другого бога, кроме Меня, и нет спасителя, кроме Меня.","No Â – Gospodʹ Bog tvoj ot zemli Egipetskoj, – i ty ne dolžen znatʹ drugogo boga, krome Menâ, i net spasitelâ, krome Menâ."],[13,5,"Я признал тебя в пустыне, в земле жаждущей.","Â priznal tebâ v pustyne, v zemle žažduŝej."],[13,6,"Имея пажити, они были сыты; а когда насыщались, то превозносилось сердце их, и потому они забывали Меня.","Imeâ pažiti, oni byli syty; a kogda nasyŝalisʹ, to prevoznosilosʹ serdce ih, i potomu oni zabyvali Menâ."],[13,7,"И Я буду для них как лев, как скимен буду подстерегать при дороге.","I Â budu dlâ nih kak lev, kak skimen budu podsteregatʹ pri doroge."],[13,8,"Буду нападать на них, как лишенная детей медведица, и раздирать вместилище сердца их, и поедать их там, как львица; полевые звери будут терзать их.","Budu napadatʹ na nih, kak lišennaâ detej medvedica, i razdiratʹ vmestiliŝe serdca ih, i poedatʹ ih tam, kak lʹvica; polevye zveri budut terzatʹ ih."],[13,9,"Погубил ты себя, Израиль, ибо только во Мне опора твоя.","Pogubil ty sebâ, Izrailʹ, ibo tolʹko vo Mne opora tvoâ."],[13,10,"Где царь твой теперь? Пусть он спасает тебя во всех городах твоих! Где судьи твои, о которых говорил ты: «дай нам царя и начальников»?","Gde carʹ tvoj teperʹ? Pustʹ on spasaet tebâ vo vseh gorodah tvoih! Gde sudʹi tvoi, o kotoryh govoril ty: «daj nam carâ i načalʹnikov»?"],[13,11,"И Я дал тебе царя во гневе Моем и отнял в негодовании Моем.","I Â dal tebe carâ vo gneve Moem i otnâl v negodovanii Moem."],[13,12,"Связано в узел беззаконие Ефрема, сбережен его грех.","Svâzano v uzel bezzakonie Efrema, sberežen ego greh."],[13,13,"Муки родильницы постигнут его; он – сын неразумный, иначе не стоял бы долго в положении рождающихся детей.","Muki rodilʹnicy postignut ego; on – syn nerazumnyj, inače ne stoâl by dolgo v položenii roždaûŝihsâ detej."],[13,14,"От власти ада Я искуплю их, от смерти избавлю их. Смерть! где твое жало? ад! где твоя победа? Раскаяния в том не будет у Меня.","Ot vlasti ada Â iskuplû ih, ot smerti izbavlû ih. Smertʹ! gde tvoe žalo? ad! gde tvoâ pobeda? Raskaâniâ v tom ne budet u Menâ."],[13,15,"Хотя Ефрем плодовит между братьями, но придет восточный ветер, поднимется ветер Господень из пустыни, и иссохнет родник его, и иссякнет источник его; он опустошит сокровищницу всех драгоценных сосудов.","Hotâ Efrem plodovit meždu bratʹâmi, no pridet vostočnyj veter, podnimetsâ veter Gospodenʹ iz pustyni, i issohnet rodnik ego, i issâknet istočnik ego; on opustošit sokroviŝnicu vseh dragocennyh sosudov."],[14,1,"Опустошена будет Самария, потому что восстала против Бога своего; от меча падут они; младенцы их будут разбиты, и беременные их будут рассечены.","Opustošena budet Samariâ, potomu čto vosstala protiv Boga svoego; ot meča padut oni; mladency ih budut razbity, i beremennye ih budut rassečeny."],[14,2,"Обратись, Израиль, к Господу Богу твоему; ибо ты упал от нечестия твоего.","Obratisʹ, Izrailʹ, k Gospodu Bogu tvoemu; ibo ty upal ot nečestiâ tvoego."],[14,3,"Возьмите с собою молитвенные слова и обратитесь к Господу; говорите Ему: «отними всякое беззаконие и прими во благо, и мы принесем жертву уст наших.","Vozʹmite s soboû molitvennye slova i obratitesʹ k Gospodu; govorite Emu: «otnimi vsâkoe bezzakonie i primi vo blago, i my prinesem žertvu ust naših."],[14,4,"Ассур не будет уже спасать нас; не станем садиться на коня и не будем более говорить изделию рук наших: боги наши; потому что у Тебя милосердие для сирот».","Assur ne budet uže spasatʹ nas; ne stanem saditʹsâ na konâ i ne budem bolee govoritʹ izdeliû ruk naših: bogi naši; potomu čto u Tebâ miloserdie dlâ sirot»."],[14,5,"Уврачую отпадение их, возлюблю их по благоволению; ибо гнев Мой отвратился от них.","Uvračuû otpadenie ih, vozlûblû ih po blagovoleniû; ibo gnev Moj otvratilsâ ot nih."],[14,6,"Я буду росою для Израиля; он расцветет, как лилия, и пустит корни свои, как Ливан.","Â budu rosoû dlâ Izrailâ; on rascvetet, kak liliâ, i pustit korni svoi, kak Livan."],[14,7,"Расширятся ветви его, и будет красота его, как маслины, и благоухание от него, как от Ливана.","Rasširâtsâ vetvi ego, i budet krasota ego, kak masliny, i blagouhanie ot nego, kak ot Livana."],[14,8,"Возвратятся сидевшие под тенью его, будут изобиловать хлебом и расцветут, как виноградная лоза, славны будут, как вино Ливанское.","Vozvratâtsâ sidevšie pod tenʹû ego, budut izobilovatʹ hlebom i rascvetut, kak vinogradnaâ loza, slavny budut, kak vino Livanskoe."],[14,9,"«Что мне еще за дело до идолов?» – скажет Ефрем. Я услышу его и призрю на него; Я буду как зеленеющий кипарис; от Меня будут тебе плоды.","«Čto mne eŝe za delo do idolov?» – skažet Efrem. Â uslyšu ego i prizrû na nego; Â budu kak zeleneûŝij kiparis; ot Menâ budut tebe plody."],[14,10,"Кто мудр, чтобы разуметь это? кто разумен, чтобы познать это? Ибо правы пути Господни, и праведники ходят по ним, а беззаконные падут на них.","Kto mudr, čtoby razumetʹ éto? kto razumen, čtoby poznatʹ éto? Ibo pravy puti Gospodni, i pravedniki hodât po nim, a bezzakonnye padut na nih."]],"cmn-cuv-hant":[[1,1,"當 烏西雅、 約坦、 亞哈斯、 希西家作 猶大王， 約阿施的兒子 耶羅波安作 以色列王的時候，耶和華的話臨到 備利的兒子 何西阿。","dāng wū xī yǎ, yuē tǎn, yà hā sī, xī xī jiā zuò yóu dà wáng， yuē ā shī de ér zǐ yé luó bō ān zuò yǐ sè liè wáng de shí hòu， yé hé huá de huà lín dào bèi lì de ér zǐ hé xī ā."],[1,2,"耶和華初次與 何西阿說話，對他說：「你去娶淫婦為妻，也收那從淫亂所生的兒女；因為這地大行淫亂，離棄耶和華。」","yé hé huá chū cì yǔ hé xī ā shuō huà， duì tā shuō：‘nǐ qù qǔ yín fù wèi qī， yě shōu nà cóng yín luàn suǒ shēng de ér nǚ； yīn wèi zhè de dà xíng yín luàn， lí qì yé hé huá.’"],[1,3,"於是， 何西阿去娶了 滴拉音的女兒 歌篾。這婦人懷孕，給他生了一個兒子。","yú shì， hé xī ā qù qǔ le dī lā yīn de nǚ ér gē miè. zhè fù rén huái yùn， gěi tā shēng le yī gè ér zǐ."],[1,4,"耶和華對 何西阿說：「給他起名叫 耶斯列；因為再過片時，我必討 耶戶家在 耶斯列殺人流血的罪，也必使 以色列家的國滅絕。","yé hé huá duì hé xī ā shuō：‘gěi tā qǐ míng jiào yé sī liè； yīn wèi zài guò piàn shí， wǒ bì tǎo yé hù jiā zài yé sī liè shā rén liú xuè de zuì， yě bì shǐ yǐ sè liè jiā de guó miè jué."],[1,5,"到那日，我必在 耶斯列平原折斷 以色列的弓。」","dào nà rì， wǒ bì zài yé sī liè píng yuán zhé duàn yǐ sè liè de gōng.’"],[1,6,"歌篾又懷孕生了一個女兒， 耶和華對 何西阿說：「給她起名叫 羅‧路哈瑪；因為我必不再憐憫 以色列家，決不赦免他們。","gē miè yòu huái yùn shēng le yī gè nǚ ér， yé hé huá duì hé xī ā shuō：‘gěi tā qǐ míng jiào luó‧lù hā mǎ； yīn wèi wǒ bì bù zài lián mǐn yǐ sè liè jiā， jué bù shè miǎn tā men."],[1,7,"我卻要憐憫 猶大家，使他們靠耶和華－他們的神得救，不使他們靠弓、刀、爭戰、馬匹，與馬兵得救。」","wǒ què yào lián mǐn yóu dà jiā， shǐ tā men kào yé hé huá－tā men de shén dé jiù， bù shǐ tā men kào gōng, dāo, zhēng zhàn, mǎ pǐ， yǔ mǎ bīng dé jiù.’"],[1,8,"歌篾給 羅‧路哈瑪斷奶以後，又懷孕生了一個兒子。","gē miè gěi luó‧lù hā mǎ duàn nǎi yǐ hòu， yòu huái yùn shēng le yī gè ér zǐ."],[1,9,"耶和華說：「給他起名叫 羅‧阿米；因為你們不作我的子民，我也不作你們的 神。」","yé hé huá shuō：‘gěi tā qǐ míng jiào luó‧ā mǐ； yīn wèi nǐ men bù zuò wǒ de zǐ mín， wǒ yě bù zuò nǐ men de shén.’"],[1,10,"然而， 以色列的人數必如海沙，不可量，不可數。從前在甚麼地方對他們說「你們不是我的子民」，將來在那裏必對他們說「 你們是永生神的兒子」。","rán ér， yǐ sè liè de rén shù bì rú hǎi shā， bù kě liàng， bù kě shù. cóng qián zài shèn me de fāng duì tā men shuō‘nǐ men bù shì wǒ de zǐ mín’， jiāng lái zài nà lǐ bì duì tā men shuō‘ nǐ men shì yǒng shēng shén de ér zǐ’."],[1,11,"猶大人和 以色列人必一同聚集，為自己立一個首領，從這地上去，因為 耶斯列的日子必為大日。","yóu dà rén hé yǐ sè liè rén bì yī tóng jù jí， wèi zì jǐ lì yī gè shǒu lǐng， cóng zhè de shàng qù， yīn wèi yé sī liè de rì zǐ bì wèi dà rì."],[2,1,"你們要稱你們的弟兄為 阿米，稱你們的姊妹為 路哈瑪。","nǐ men yào chēng nǐ men de dì xiōng wèi ā mǐ， chēng nǐ men de zǐ mèi wèi lù hā mǎ."],[2,2,"你們要與你們的母親大大爭辯； 因為她不是我的妻子， 我也不是她的丈夫。 叫她除掉臉上的淫像 和胸間的淫態，","nǐ men yào yǔ nǐ men de mǔ qīn dà dà zhēng biàn； yīn wèi tā bù shì wǒ de qī zǐ， wǒ yě bù shì tā de zhàng fū. jiào tā chú diào liǎn shàng de yín xiàng hé xiōng jiān de yín tài，"],[2,3,"免得我剝她的衣服， 使她赤體，與才生的時候一樣， 使她如曠野，如乾旱之地， 因渴而死。","miǎn dé wǒ bō tā de yī fú， shǐ tā chì tǐ， yǔ cái shēng de shí hòu yī yàng， shǐ tā rú kuàng yě， rú qián hàn zhī de， yīn kě ér sǐ."],[2,4,"我必不憐憫她的兒女， 因為他們是從淫亂而生的。","wǒ bì bù lián mǐn tā de ér nǚ， yīn wèi tā men shì cóng yín luàn ér shēng de."],[2,5,"他們的母親行了淫亂， 懷他們的 母做了可羞恥的事， 因為她說：我要隨從所愛的； 我的餅、水、羊毛、麻、油、酒 都是他們給的。","tā men de mǔ qīn xíng le yín luàn， huái tā men de mǔ zuò le kě xiū chǐ de shì， yīn wèi tā shuō： wǒ yào suí cóng suǒ ài de； wǒ de bǐng, shuǐ, yáng máo, má, yóu, jiǔ dōu shì tā men gěi de."],[2,6,"因此，我必用荊棘堵塞她的道， 築牆擋住她， 使她找不着路。","yīn cǐ， wǒ bì yòng jīng jí dǔ sāi tā de dào， zhú qiáng dǎng zhù tā， shǐ tā zhǎo bù zhe lù."],[2,7,"她必追隨所愛的，卻追不上； 她必尋找他們，卻尋不見， 便說：我要歸回前夫， 因我那時的光景比如今還好。","tā bì zhuī suí suǒ ài de， què zhuī bù shàng； tā bì xún zhǎo tā men， què xún bù jiàn， biàn shuō： wǒ yào guī huí qián fū， yīn wǒ nà shí de guāng jǐng bǐ rú jīn hái hǎo."],[2,8,"她不知道是我給她五穀、新酒，和油， 又加增她的金銀； 她卻以此供奉 巴力。","tā bù zhī dào shì wǒ gěi tā wǔ gǔ, xīn jiǔ， hé yóu， yòu jiā zēng tā de jīn yín； tā què yǐ cǐ gōng fèng bā lì."],[2,9,"因此到了收割的日子， 出酒的時候， 我必將我的五穀、新酒收回， 也必將她應當遮體的羊毛和麻奪回來。","yīn cǐ dào le shōu gē de rì zǐ， chū jiǔ de shí hòu， wǒ bì jiāng wǒ de wǔ gǔ, xīn jiǔ shōu huí， yě bì jiāng tā yīng dāng zhē tǐ de yáng máo hé má duó huí lái."],[2,10,"如今我必在她所愛的眼前顯露她的醜態； 必無人能救她脫離我的手。","rú jīn wǒ bì zài tā suǒ ài de yǎn qián xiǎn lù tā de chǒu tài； bì wú rén néng jiù tā tuō lí wǒ de shǒu."],[2,11,"我也必使她的宴樂、節期、月朔、安息日， 並她的一切大會都止息了。","wǒ yě bì shǐ tā de yàn lè, jié qī, yuè shuò, ān xī rì， bìng tā de yī qiè dà huì dōu zhǐ xī le."],[2,12,"我也必毀壞她的葡萄樹和無花果樹， 就是她說「這是我所愛的給我為賞賜」的。 我必使這些樹變為荒林， 為田野的走獸所吃。","wǒ yě bì huǐ huài tā de pú táo shù hé wú huā guǒ shù， jiù shì tā shuō‘zhè shì wǒ suǒ ài de gěi wǒ wèi shǎng cì’ de. wǒ bì shǐ zhè xiē shù biàn wèi huāng lín， wèi tián yě de zǒu shòu suǒ chī."],[2,13,"我必追討她素日給諸 巴力燒香的罪； 那時她佩帶耳環和別樣妝飾， 隨從她所愛的，卻忘記我。 這是耶和華說的。","wǒ bì zhuī tǎo tā sù rì gěi zhū bā lì shāo xiāng de zuì； nà shí tā pèi dài ěr huán hé bié yàng zhuāng shì， suí cóng tā suǒ ài de， què wàng jì wǒ. zhè shì yé hé huá shuō de."],[2,14,"後來我必勸導她，領她到曠野， 對她說安慰的話。","hòu lái wǒ bì quàn dǎo tā， lǐng tā dào kuàng yě， duì tā shuō ān wèi de huà."],[2,15,"她從那裏出來，我必賜她葡萄園， 又賜她 亞割谷作為指望的門。 她必在那裏應聲， 與幼年的日子一樣， 與從 埃及地上來的時候相同。","tā cóng nà lǐ chū lái， wǒ bì cì tā pú táo yuán， yòu cì tā yà gē gǔ zuò wèi zhǐ wàng de mén. tā bì zài nà lǐ yīng shēng， yǔ yòu nián de rì zǐ yī yàng， yǔ cóng āi jí de shàng lái de shí hòu xiāng tóng."],[2,16,"耶和華說：「那日你必稱呼我伊施，不再稱呼我 巴力；","yé hé huá shuō：‘nà rì nǐ bì chēng hū wǒ yī shī， bù zài chēng hū wǒ bā lì；"],[2,17,"因為我必從我民的口中除掉諸 巴力的名號，這名號不再提起。","yīn wèi wǒ bì cóng wǒ mín de kǒu zhōng chú diào zhū bā lì de míng hào， zhè míng hào bù zài tí qǐ."],[2,18,"當那日，我必為我的民，與田野的走獸和空中的飛鳥，並地上的昆蟲立約；又必在國中折斷弓刀，止息爭戰，使他們安然躺臥。","dāng nà rì， wǒ bì wèi wǒ de mín， yǔ tián yě de zǒu shòu hé kōng zhōng de fēi niǎo， bìng de shàng de kūn chóng lì yuē； yòu bì zài guó zhōng zhé duàn gōng dāo， zhǐ xī zhēng zhàn， shǐ tā men ān rán tǎng wò."],[2,19,"我必聘你永遠歸我為妻，以仁義、公平、慈愛、憐憫聘你歸我；","wǒ bì pìn nǐ yǒng yuǎn guī wǒ wèi qī， yǐ rén yì, gōng píng, cí ài, lián mǐn pìn nǐ guī wǒ；"],[2,20,"也以誠實聘你歸我，你就必認識 我－耶和華。","yě yǐ chéng shí pìn nǐ guī wǒ， nǐ jiù bì rèn shí wǒ－yé hé huá."],[2,21,"耶和華說：那日我必應允， 我必應允天，天必應允地；","yé hé huá shuō： nà rì wǒ bì yīng yǔn， wǒ bì yīng yǔn tiān， tiān bì yīng yǔn de；"],[2,22,"地必應允五穀、新酒，和油， 這些必應允 耶斯列 民。","de bì yīng yǔn wǔ gǔ, xīn jiǔ， hé yóu， zhè xiē bì yīng yǔn yé sī liè mín."],[2,23,"我必將她種在這地。 素不蒙憐憫的，我必憐憫； 本非我民的，我必對他說： 你是我的民； 他必說： 你是我的神。」","wǒ bì jiāng tā zhǒng zài zhè de. sù bù méng lián mǐn de， wǒ bì lián mǐn； běn fēi wǒ mín de， wǒ bì duì tā shuō： nǐ shì wǒ de mín； tā bì shuō： nǐ shì wǒ de shén.’"],[3,1,"耶和華對我說：「你再去愛一個淫婦，就是她情人所愛的；好像 以色列人，雖然偏向別神，喜愛葡萄餅，耶和華還是愛他們。」","yé hé huá duì wǒ shuō：‘nǐ zài qù ài yī gè yín fù， jiù shì tā qíng rén suǒ ài de； hǎo xiàng yǐ sè liè rén， suī rán piān xiàng bié shén， xǐ ài pú táo bǐng， yé hé huá hái shì ài tā men.’"],[3,2,"我便用銀子十五舍客勒，大麥一賀梅珥半，買她歸我。","wǒ biàn yòng yín zǐ shí wǔ shě kè lēi， dà mài yī hè méi ěr bàn， mǎi tā guī wǒ."],[3,3,"我對她說：「你當多日為我獨居，不可行淫，不可歸別人為妻，我向你也必這樣。」","wǒ duì tā shuō：‘nǐ dāng duō rì wèi wǒ dú jū， bù kě xíng yín， bù kě guī bié rén wèi qī， wǒ xiàng nǐ yě bì zhè yàng.’"],[3,4,"以色列人也必多日獨居，無君王，無首領，無祭祀，無柱像，無以弗得，無家中的神像。","yǐ sè liè rén yě bì duō rì dú jū， wú jūn wáng， wú shǒu lǐng， wú jì sì， wú zhù xiàng， wú yǐ fú dé， wú jiā zhōng de shén xiàng."],[3,5,"後來 以色列人必歸回，尋求他們的神－耶和華和他們的王 大衛。在末後的日子，必以敬畏的心歸向耶和華，領受他的恩惠。","hòu lái yǐ sè liè rén bì guī huí， xún qiú tā men de shén－yé hé huá hé tā men de wáng dà wèi. zài mò hòu de rì zǐ， bì yǐ jìng wèi de xīn guī xiàng yé hé huá， lǐng shòu tā de ēn huì."],[4,1,"以色列人哪，你們當聽耶和華的話。 耶和華與這地的居民爭辯， 因這地上無誠實， 無良善，無人認識神。","yǐ sè liè rén nǎ， nǐ men dāng tīng yé hé huá de huà. yé hé huá yǔ zhè de de jū mín zhēng biàn， yīn zhè de shàng wú chéng shí， wú liáng shàn， wú rén rèn shí shén."],[4,2,"但起 假誓，不踐前言， 殺害，偷盜，姦淫，行強暴， 殺人流血，接連不斷。","dàn qǐ jiǎ shì， bù jiàn qián yán， shā hài， tōu dào， jiān yín， xíng qiáng bào， shā rén liú xuè， jiē lián bù duàn."],[4,3,"因此，這地悲哀， 其上的民、田野的獸、 空中的鳥必都衰微， 海中的魚也必消滅。","yīn cǐ， zhè de bēi āi， qí shàng de mín, tián yě de shòu, kōng zhōng de niǎo bì dōu shuāi wēi， hǎi zhōng de yú yě bì xiāo miè."],[4,4,"然而，人都不必爭辯，也不必指責， 因為這民與抗拒祭司的人一樣。","rán ér， rén dōu bù bì zhēng biàn， yě bù bì zhǐ zé， yīn wèi zhè mín yǔ kàng jù jì sī de rén yī yàng."],[4,5,"你這祭司必日間跌倒； 先知也必夜間與你一同跌倒； 我必滅絕你的母親。","nǐ zhè jì sī bì rì jiān diē dào； xiān zhī yě bì yè jiān yǔ nǐ yī tóng diē dào； wǒ bì miè jué nǐ de mǔ qīn."],[4,6,"我的民因無知識而滅亡。 你棄掉知識， 我也必棄掉你， 使你不再給我作祭司。 你既忘了你神的律法， 我也必忘記你的兒女。","wǒ de mín yīn wú zhī shí ér miè wáng. nǐ qì diào zhī shí， wǒ yě bì qì diào nǐ， shǐ nǐ bù zài gěi wǒ zuò jì sī. nǐ jì wàng le nǐ shén de lǜ fǎ， wǒ yě bì wàng jì nǐ de ér nǚ."],[4,7,"祭司越發增多，就越發得罪我； 我必使他們的榮耀變為羞辱。","jì sī yuè fā zēng duō， jiù yuè fā dé zuì wǒ； wǒ bì shǐ tā men de róng yào biàn wèi xiū rǔ."],[4,8,"他們吃我民的 贖罪 祭， 滿心願意我民犯罪。","tā men chī wǒ mín de shú zuì jì， mǎn xīn yuàn yì wǒ mín fàn zuì."],[4,9,"將來民如何， 祭司也必如何； 我必因他們所行的懲罰他們， 照他們所做的報應他們。","jiāng lái mín rú hé， jì sī yě bì rú hé； wǒ bì yīn tā men suǒ xíng de chéng fá tā men， zhào tā men suǒ zuò de bào yīng tā men."],[4,10,"他們吃，卻不得飽； 行淫，而不得立後； 因為他們離棄耶和華， 不遵 他的命。","tā men chī， què bù dé bǎo； xíng yín， ér bù dé lì hòu； yīn wèi tā men lí qì yé hé huá， bù zūn tā de mìng."],[4,11,"姦淫和酒，並新酒， 奪去人的心。","jiān yín hé jiǔ， bìng xīn jiǔ， duó qù rén de xīn."],[4,12,"我的民求問木偶， 以為木杖能指示他們； 因為他們的淫心使他們失迷， 他們就行淫離棄神， 不守約束，","wǒ de mín qiú wèn mù ǒu， yǐ wèi mù zhàng néng zhǐ shì tā men； yīn wèi tā men de yín xīn shǐ tā men shī mí， tā men jiù xíng yín lí qì shén， bù shǒu yuē shù，"],[4,13,"在各山頂，各高岡的橡樹、 楊樹、栗樹之下，獻祭燒香， 因為樹影美好。 所以，你們的女兒淫亂， 你們的新婦行淫。","zài gè shān dǐng， gè gāo gāng de xiàng shù, yáng shù, lì shù zhī xià， xiàn jì shāo xiāng， yīn wèi shù yǐng měi hǎo. suǒ yǐ， nǐ men de nǚ ér yín luàn， nǐ men de xīn fù xíng yín."],[4,14,"你們的女兒淫亂， 你們的新婦行淫， 我卻不懲罰她們； 因為你們自己離群與娼妓同居， 與妓女一同獻祭。 這無知的民必致傾倒。","nǐ men de nǚ ér yín luàn， nǐ men de xīn fù xíng yín， wǒ què bù chéng fá tā men； yīn wèi nǐ men zì jǐ lí qún yǔ chāng jì tóng jū， yǔ jì nǚ yī tóng xiàn jì. zhè wú zhī de mín bì zhì qīng dào."],[4,15,"以色列啊，你雖然行淫， 猶大卻不可犯罪。 不要往 吉甲去， 不要上到 伯‧亞文， 也不要指着永生的耶和華起誓。","yǐ sè liè a， nǐ suī rán xíng yín， yóu dà què bù kě fàn zuì. bù yào wǎng jí jiǎ qù， bù yào shàng dào bó‧yà wén， yě bù yào zhǐ zhe yǒng shēng de yé hé huá qǐ shì."],[4,16,"以色列倔強， 猶如倔強的母牛； 現在耶和華要放他們， 如同放羊羔在寬闊之地。","yǐ sè liè jué qiáng， yóu rú jué qiáng de mǔ niú； xiàn zài yé hé huá yào fàng tā men， rú tóng fàng yáng gāo zài kuān kuò zhī de."],[4,17,"以法蓮親近偶像， 任憑他吧！","yǐ fǎ lián qīn jìn ǒu xiàng， rèn píng tā ba！"],[4,18,"他們所喝的已經發酸， 他們時常行淫， 他們的官長最愛羞恥的事。","tā men suǒ hē de yǐ jīng fā suān， tā men shí cháng xíng yín， tā men de guān zhǎng zuì ài xiū chǐ de shì."],[4,19,"風把他們裹在翅膀裏； 他們因所獻的祭必致蒙羞。","fēng bǎ tā men guǒ zài chì bǎng lǐ； tā men yīn suǒ xiàn de jì bì zhì méng xiū."],[5,1,"眾祭司啊，要聽我的話！ 以色列家啊，要留心聽！ 王家啊，要側耳而聽！ 審判要臨到你們， 因你們在 米斯巴如網羅， 在 他泊山如鋪張的網。","zhòng jì sī a， yào tīng wǒ de huà！ yǐ sè liè jiā a， yào liú xīn tīng！ wáng jiā a， yào cè ěr ér tīng！ shěn pàn yào lín dào nǐ men， yīn nǐ men zài mǐ sī bā rú wǎng luó， zài tā pō shān rú pù zhāng de wǎng."],[5,2,"這些悖逆的人肆行殺戮， 罪孽極深； 我卻斥責他們眾人。","zhè xiē bèi nì de rén sì xíng shā lù， zuì niè jí shēn； wǒ què chì zé tā men zhòng rén."],[5,3,"以法蓮為我所知； 以色列不能向我隱藏。 以法蓮哪，現在你行淫了， 以色列被玷污了。","yǐ fǎ lián wèi wǒ suǒ zhī； yǐ sè liè bù néng xiàng wǒ yǐn cáng. yǐ fǎ lián nǎ， xiàn zài nǐ xíng yín le， yǐ sè liè bèi diàn wū le."],[5,4,"他們所行的使他們不能歸向神； 因有淫心在他們裏面， 他們也不認識耶和華。","tā men suǒ xíng de shǐ tā men bù néng guī xiàng shén； yīn yǒu yín xīn zài tā men lǐ miàn， tā men yě bù rèn shí yé hé huá."],[5,5,"以色列的驕傲當面見證自己。 故此， 以色列和 以法蓮必因自己的罪孽跌倒； 猶大也必與他們一同跌倒。","yǐ sè liè de jiāo ào dāng miàn jiàn zhèng zì jǐ. gù cǐ， yǐ sè liè hé yǐ fǎ lián bì yīn zì jǐ de zuì niè diē dào； yóu dà yě bì yǔ tā men yī tóng diē dào."],[5,6,"他們必牽着牛羊去尋求耶和華，卻尋不見； 他已經轉去離開他們。","tā men bì qiān zhe niú yáng qù xún qiú yé hé huá， què xún bù jiàn； tā yǐ jīng zhuǎn qù lí kāi tā men."],[5,7,"他們向耶和華行事詭詐，生了私子。 到了月朔，他們與他們的地業必被吞滅。","tā men xiàng yé hé huá xíng shì guǐ zhà， shēng le sī zǐ. dào le yuè shuò， tā men yǔ tā men de de yè bì bèi tūn miè."],[5,8,"你們當在 基比亞吹角， 在 拉瑪吹號， 在 伯‧亞文吹出大聲， 說： 便雅憫哪， 有仇敵在你後頭！","nǐ men dāng zài jī bǐ yà chuī jiǎo， zài lā mǎ chuī hào， zài bó‧yà wén chuī chū dà shēng， shuō： biàn yǎ mǐn nǎ， yǒu chóu dí zài nǐ hòu tóu！"],[5,9,"在責罰的日子， 以法蓮必變為荒場； 我在 以色列支派中，指示將來必成的事。","zài zé fá de rì zǐ， yǐ fǎ lián bì biàn wèi huāng chǎng； wǒ zài yǐ sè liè zhī pài zhōng， zhǐ shì jiāng lái bì chéng de shì."],[5,10,"猶大的首領如同挪移地界的人， 我必將忿怒倒在他們身上，如水一般。","yóu dà de shǒu lǐng rú tóng nuó yí de jiè de rén， wǒ bì jiāng fèn nù dào zài tā men shēn shàng， rú shuǐ yī bān."],[5,11,"以法蓮因樂從 人的命令， 就受欺壓，被審判壓碎。","yǐ fǎ lián yīn lè cóng rén de mìng lìng， jiù shòu qī yā， bèi shěn pàn yā suì."],[5,12,"我使 以法蓮如蟲蛀之物， 使 猶大家如朽爛之木。","wǒ shǐ yǐ fǎ lián rú chóng zhù zhī wù， shǐ yóu dà jiā rú xiǔ làn zhī mù."],[5,13,"以法蓮見自己有病， 猶大見自己有傷， 他們就打發人往 亞述去見 耶雷布王， 他卻不能醫治你們， 不能治好你們的傷。","yǐ fǎ lián jiàn zì jǐ yǒu bìng， yóu dà jiàn zì jǐ yǒu shāng， tā men jiù dǎ fā rén wǎng yà shù qù jiàn yé léi bù wáng， tā què bù néng yī zhì nǐ men， bù néng zhì hǎo nǐ men de shāng."],[5,14,"我必向 以法蓮如獅子， 向 猶大家如少壯獅子。 我必撕裂而去， 我要奪去，無人搭救。","wǒ bì xiàng yǐ fǎ lián rú shī zǐ， xiàng yóu dà jiā rú shǎo zhuàng shī zǐ. wǒ bì sī liè ér qù， wǒ yào duó qù， wú rén dā jiù."],[5,15,"我要回到原處， 等他們自覺有罪，尋求我面； 他們在急難的時候必切切尋求我。","wǒ yào huí dào yuán chù， děng tā men zì jué yǒu zuì， xún qiú wǒ miàn； tā men zài jí nán de shí hòu bì qiè qiè xún qiú wǒ."],[6,1,"來吧，我們歸向耶和華！ 他撕裂我們，也必醫治； 他打傷我們，也必纏裹。","lái ba， wǒ men guī xiàng yé hé huá！ tā sī liè wǒ men， yě bì yī zhì； tā dǎ shāng wǒ men， yě bì chán guǒ."],[6,2,"過兩天他必使我們甦醒， 第三天他必使我們興起， 我們就在他面前得以存活。","guò liǎng tiān tā bì shǐ wǒ men sū xǐng， dì sān tiān tā bì shǐ wǒ men xìng qǐ， wǒ men jiù zài tā miàn qián dé yǐ cún huó."],[6,3,"我們務要認識耶和華， 竭力追求認識他。 他出現確如晨 光； 他必臨到我們像甘雨， 像滋潤田地的春雨。","wǒ men wù yào rèn shí yé hé huá， jié lì zhuī qiú rèn shí tā. tā chū xiàn què rú chén guāng； tā bì lín dào wǒ men xiàng gān yǔ， xiàng zī rùn tián de de chūn yǔ."],[6,4,"主說： 以法蓮哪，我可向你怎樣行呢？ 猶大啊，我可向你怎樣做呢？ 因為你們的良善如同早晨的雲霧， 又如速散的甘露。","zhǔ shuō： yǐ fǎ lián nǎ， wǒ kě xiàng nǐ zěn yàng xíng ne？ yóu dà a， wǒ kě xiàng nǐ zěn yàng zuò ne？ yīn wèi nǐ men de liáng shàn rú tóng zǎo chén de yún wù， yòu rú sù sàn de gān lù."],[6,5,"因此，我藉先知砍伐他們， 以我口中的話殺戮他們； 我施行的審判如光發出。","yīn cǐ， wǒ jí xiān zhī kǎn fá tā men， yǐ wǒ kǒu zhōng de huà shā lù tā men； wǒ shī xíng de shěn pàn rú guāng fā chū."],[6,6,"我喜愛良善，不喜愛祭祀； 喜愛認識神，勝於燔祭。","wǒ xǐ ài liáng shàn， bù xǐ ài jì sì； xǐ ài rèn shí shén， shèng yú fán jì."],[6,7,"他們卻如 亞當背約， 在境內向我行事詭詐。","tā men què rú yà dāng bèi yuē， zài jìng nèi xiàng wǒ xíng shì guǐ zhà."],[6,8,"基列是作孽之人的城， 被血沾染。","jī liè shì zuò niè zhī rén de chéng， bèi xuè zhān rǎn."],[6,9,"強盜成群，怎樣埋伏殺人， 祭司結黨，也照樣在 示劍的路上殺戮， 行了邪惡。","qiáng dào chéng qún， zěn yàng mái fú shā rén， jì sī jié dǎng， yě zhào yàng zài shì jiàn de lù shàng shā lù， xíng le xié è."],[6,10,"在 以色列家，我見了可憎的事； 在 以法蓮那裏有淫行， 以色列被玷污。","zài yǐ sè liè jiā， wǒ jiàn le kě zēng de shì； zài yǐ fǎ lián nà lǐ yǒu yín xíng， yǐ sè liè bèi diàn wū."],[6,11,"猶大啊，我使被擄之民歸回的時候， 必有為你所命定的收場。","yóu dà a， wǒ shǐ bèi lǔ zhī mín guī huí de shí hòu， bì yǒu wèi nǐ suǒ mìng dìng de shōu chǎng."],[7,1,"我想醫治 以色列的時候， 以法蓮的罪孽和 撒馬利亞的罪惡就顯露出來。 他們行事虛謊， 內有賊人入室 偷竊， 外有強盜成群騷擾。","wǒ xiǎng yī zhì yǐ sè liè de shí hòu， yǐ fǎ lián de zuì niè hé sā mǎ lì yà de zuì è jiù xiǎn lù chū lái. tā men xíng shì xū huǎng， nèi yǒu zéi rén rù shì tōu qiè， wài yǒu qiáng dào chéng qún sāo rǎo."],[7,2,"他們心裏並不思想我記念他們的一切惡； 他們所行的現在纏繞他們，都在我面前。","tā men xīn lǐ bìng bù sī xiǎng wǒ jì niàn tā men de yī qiè è； tā men suǒ xíng de xiàn zài chán rào tā men， dōu zài wǒ miàn qián."],[7,3,"他們行惡使君王歡喜， 說謊使首領喜樂。","tā men xíng è shǐ jūn wáng huān xǐ， shuō huǎng shǐ shǒu lǐng xǐ lè."],[7,4,"他們都是行淫的， 像火爐被烤餅的燒熱， 從摶麵到發麵的時候， 暫不使 火着旺。","tā men dōu shì xíng yín de， xiàng huǒ lú bèi kǎo bǐng de shāo rè， cóng tuán miàn dào fā miàn de shí hòu， zàn bù shǐ huǒ zhe wàng."],[7,5,"在我們王 宴樂的日子， 首領因酒的烈性成病； 王與褻慢人拉手。","zài wǒ men wáng yàn lè de rì zǐ， shǒu lǐng yīn jiǔ de liè xìng chéng bìng； wáng yǔ xiè màn rén lā shǒu."],[7,6,"首領埋伏的時候，心中熱如火爐， 就如烤餅的整夜睡臥， 到了早晨火氣炎炎。","shǒu lǐng mái fú de shí hòu， xīn zhōng rè rú huǒ lú， jiù rú kǎo bǐng de zhěng yè shuì wò， dào le zǎo chén huǒ qì yán yán."],[7,7,"眾民也熱如火爐， 燒滅他們的官長。 他們的君王都仆倒而死； 他們中間無一人求告我。","zhòng mín yě rè rú huǒ lú， shāo miè tā men de guān zhǎng. tā men de jūn wáng dōu pū dào ér sǐ； tā men zhōng jiān wú yī rén qiú gào wǒ."],[7,8,"以法蓮與列邦人攙雜； 以法蓮是沒有翻過的餅。","yǐ fǎ lián yǔ liè bāng rén chān zá； yǐ fǎ lián shì méi yǒu fān guò de bǐng."],[7,9,"外邦人吞吃他勞力得來的，他卻不知道； 頭髮斑白，他也不覺得。","wài bāng rén tūn chī tā láo lì dé lái de， tā què bù zhī dào； tóu fà bān bái， tā yě bù jué dé."],[7,10,"以色列的驕傲當面見證自己， 雖遭遇這一切， 他們仍不歸向耶和華－他們的神， 也不尋求他。","yǐ sè liè de jiāo ào dāng miàn jiàn zhèng zì jǐ， suī zāo yù zhè yī qiè， tā men réng bù guī xiàng yé hé huá－tā men de shén， yě bù xún qiú tā."],[7,11,"以法蓮好像鴿子愚蠢無知； 他們求告 埃及，投奔 亞述。","yǐ fǎ lián hǎo xiàng gē zǐ yú chǔn wú zhī； tā men qiú gào āi jí， tóu bēn yà shù."],[7,12,"他們去的時候，我必將我的網撒在他們身上； 我要打下他們，如同空中的鳥。 我必按他們會眾所聽見的懲罰他們。","tā men qù de shí hòu， wǒ bì jiāng wǒ de wǎng sā zài tā men shēn shàng； wǒ yào dǎ xià tā men， rú tóng kōng zhōng de niǎo. wǒ bì àn tā men huì zhòng suǒ tīng jiàn de chéng fá tā men."],[7,13,"他們因離棄我，必定有禍； 因違背我，必被毀滅。 我雖要救贖他們，他們卻向我說謊。","tā men yīn lí qì wǒ， bì dìng yǒu huò； yīn wéi bèi wǒ， bì bèi huǐ miè. wǒ suī yào jiù shú tā men， tā men què xiàng wǒ shuō huǎng."],[7,14,"他們並不誠心哀求我， 乃在床上呼號； 他們為求五穀新酒聚集， 仍然悖逆我。","tā men bìng bù chéng xīn āi qiú wǒ， nǎi zài chuáng shàng hū hào； tā men wèi qiú wǔ gǔ xīn jiǔ jù jí， réng rán bèi nì wǒ."],[7,15,"我雖教導他們，堅固他們的膀臂， 他們竟圖謀抗拒我。","wǒ suī jiào dǎo tā men， jiān gù tā men de bǎng bì， tā men jìng tú móu kàng jù wǒ."],[7,16,"他們歸向，卻不歸向至上者； 他們如同翻背的弓。 他們的首領必因舌頭的狂傲倒在刀下； 這在 埃及地必作人的譏笑。","tā men guī xiàng， què bù guī xiàng zhì shàng zhě； tā men rú tóng fān bèi de gōng. tā men de shǒu lǐng bì yīn shé tóu de kuáng ào dào zài dāo xià； zhè zài āi jí de bì zuò rén de jī xiào."],[8,1,"你用口吹角吧！ 敵人如鷹來攻打耶和華的家； 因為這民違背我的約， 干犯我的律法。","nǐ yòng kǒu chuī jiǎo ba！ dí rén rú yīng lái gōng dǎ yé hé huá de jiā； yīn wèi zhè mín wéi bèi wǒ de yuē， gàn fàn wǒ de lǜ fǎ."],[8,2,"他們必呼叫我說： 我的神啊，我們 以色列認識你了。","tā men bì hū jiào wǒ shuō： wǒ de shén a， wǒ men yǐ sè liè rèn shí nǐ le."],[8,3,"以色列丟棄良善； 仇敵必追逼他。","yǐ sè liè diū qì liáng shàn； chóu dí bì zhuī bī tā."],[8,4,"他們立君王，卻不由我； 他們立首領，我卻不認。 他們用金銀為自己製造偶像， 以致被剪除。","tā men lì jūn wáng， què bù yóu wǒ； tā men lì shǒu lǐng， wǒ què bù rèn. tā men yòng jīn yín wèi zì jǐ zhì zào ǒu xiàng， yǐ zhì bèi jiǎn chú."],[8,5,"撒馬利亞啊，耶和華已經丟棄你的牛犢； 我的怒氣向拜牛犢的人發作。 他們到幾時方能無罪呢？","sā mǎ lì yà a， yé hé huá yǐ jīng diū qì nǐ de niú dú； wǒ de nù qì xiàng bài niú dú de rén fā zuò. tā men dào jǐ shí fāng néng wú zuì ne？"],[8,6,"這 牛犢出於 以色列， 是匠人所造的，並不是神。 撒馬利亞的牛犢必被打碎。","zhè niú dú chū yú yǐ sè liè， shì jiàng rén suǒ zào de， bìng bù shì shén. sā mǎ lì yà de niú dú bì bèi dǎ suì."],[8,7,"他們所種的是風，所收的是暴風； 所種的不成禾稼，就是發苗也不結實； 即便結實，外邦人必吞吃。","tā men suǒ zhǒng de shì fēng， suǒ shōu de shì bào fēng； suǒ zhǒng de bù chéng hé jià， jiù shì fā miáo yě bù jié shí； jí biàn jié shí， wài bāng rén bì tūn chī."],[8,8,"以色列被吞吃； 現今在列國中，好像人不喜悅的器皿。","yǐ sè liè bèi tūn chī； xiàn jīn zài liè guó zhōng， hǎo xiàng rén bù xǐ yuè de qì mǐn."],[8,9,"他們投奔 亞述，如同獨行的野驢； 以法蓮賄買朋黨。","tā men tóu bēn yà shù， rú tóng dú xíng de yě lǘ； yǐ fǎ lián huì mǎi péng dǎng."],[8,10,"他們雖在列邦中賄買人， 現在我卻要聚集 懲罰他們； 他們因君王和首領所加的重擔日漸衰微。","tā men suī zài liè bāng zhōng huì mǎi rén， xiàn zài wǒ què yào jù jí chéng fá tā men； tā men yīn jūn wáng hé shǒu lǐng suǒ jiā de zhòng dān rì jiàn shuāi wēi."],[8,11,"以法蓮增添祭壇取罪； 因此，祭壇使他犯罪。","yǐ fǎ lián zēng tiān jì tán qǔ zuì； yīn cǐ， jì tán shǐ tā fàn zuì."],[8,12,"我為他寫了律法萬條， 他卻以為與他毫無關涉。","wǒ wèi tā xiě le lǜ fǎ wàn tiáo， tā què yǐ wèi yǔ tā háo wú guān shè."],[8,13,"至於獻給我的祭物， 他們自食其肉， 耶和華卻不悅納他們。 現在必記念他們的罪孽， 追討他們的罪惡； 他們必歸回 埃及。","zhì yú xiàn gěi wǒ de jì wù， tā men zì shí qí ròu， yé hé huá què bù yuè nà tā men. xiàn zài bì jì niàn tā men de zuì niè， zhuī tǎo tā men de zuì è； tā men bì guī huí āi jí."],[8,14,"以色列忘記造他的主，建造宮殿； 猶大多造堅固城， 我卻要降火焚燒他的城邑， 燒滅其中的宮殿。","yǐ sè liè wàng jì zào tā de zhǔ， jiàn zào gōng diàn； yóu dà duō zào jiān gù chéng， wǒ què yào jiàng huǒ fén shāo tā de chéng yì， shāo miè qí zhōng de gōng diàn."],[9,1,"以色列啊，不要像外邦人歡喜快樂； 因為你行邪淫離棄你的神， 在各穀場上 如妓女喜愛賞賜。","yǐ sè liè a， bù yào xiàng wài bāng rén huān xǐ kuài lè； yīn wèi nǐ xíng xié yín lí qì nǐ de shén， zài gè gǔ chǎng shàng rú jì nǚ xǐ ài shǎng cì."],[9,2,"穀場和酒醡都不夠 以色列人使用； 新酒也必缺乏。","gǔ chǎng hé jiǔ zhà dōu bù gòu yǐ sè liè rén shǐ yòng； xīn jiǔ yě bì quē fá."],[9,3,"他們必不得住耶和華的地； 以法蓮卻要歸回 埃及， 必在 亞述吃不潔淨的食物。","tā men bì bù dé zhù yé hé huá de de； yǐ fǎ lián què yào guī huí āi jí， bì zài yà shù chī bù jié jìng de shí wù."],[9,4,"他們必不得向耶和華奠酒， 即便奠酒也不蒙悅納。 他們的祭物必如居喪者的食物， 凡吃的必被玷污； 因他們的食物只為自己的口腹， 必不奉入耶和華的殿。","tā men bì bù dé xiàng yé hé huá diàn jiǔ， jí biàn diàn jiǔ yě bù méng yuè nà. tā men de jì wù bì rú jū sàng zhě de shí wù， fán chī de bì bèi diàn wū； yīn tā men de shí wù zhǐ wèi zì jǐ de kǒu fù， bì bù fèng rù yé hé huá de diàn."],[9,5,"在大會的日子， 到耶和華的節期，你們怎樣行呢？","zài dà huì de rì zǐ， dào yé hé huá de jié qī， nǐ men zěn yàng xíng ne？"],[9,6,"看哪，他們逃避災難； 埃及人必收殮他們的屍首， 摩弗人必葬埋他們的骸骨。 他們用銀子做的美物上必長蒺藜； 他們的帳棚中必生荊棘。","kàn nǎ， tā men táo bì zāi nán； āi jí rén bì shōu liàn tā men de shī shǒu， mó fú rén bì zàng mái tā men de hái gǔ. tā men yòng yín zǐ zuò de měi wù shàng bì zhǎng jí lí； tā men de zhàng péng zhōng bì shēng jīng jí."],[9,7,"以色列人必知道降罰的日子臨近， 報應的時候來到。 民說：作先知的是愚昧； 受靈感的是狂妄， 皆因他們多多作孽，大懷怨恨。","yǐ sè liè rén bì zhī dào jiàng fá de rì zǐ lín jìn， bào yīng de shí hòu lái dào. mín shuō： zuò xiān zhī de shì yú mèi； shòu líng gǎn de shì kuáng wàng， jiē yīn tā men duō duō zuò niè， dà huái yuàn hèn."],[9,8,"以法蓮曾作我神守望的； 至於先知，在他一切的道上作為捕鳥人的網羅， 在他神的家中懷怨恨。","yǐ fǎ lián céng zuò wǒ shén shǒu wàng de； zhì yú xiān zhī， zài tā yī qiè de dào shàng zuò wèi bǔ niǎo rén de wǎng luó， zài tā shén de jiā zhōng huái yuàn hèn."],[9,9,"以法蓮深深地敗壞， 如在 基比亞的日子一樣。 耶和華必記念他們的罪孽， 追討他們的罪惡。","yǐ fǎ lián shēn shēn de bài huài， rú zài jī bǐ yà de rì zǐ yī yàng. yé hé huá bì jì niàn tā men de zuì niè， zhuī tǎo tā men de zuì è."],[9,10,"主說：我遇見 以色列如葡萄在曠野； 我看見你們的列祖如無花果樹上春季初熟的果子。 他們卻來到 巴力‧毗珥專拜那可羞恥的， 就成為可憎惡的， 與他們所愛的一樣。","zhǔ shuō： wǒ yù jiàn yǐ sè liè rú pú táo zài kuàng yě； wǒ kàn jiàn nǐ men de liè zǔ rú wú huā guǒ shù shàng chūn jì chū shú de guǒ zǐ. tā men què lái dào bā lì‧pí ěr zhuān bài nà kě xiū chǐ de， jiù chéng wèi kě zēng è de， yǔ tā men suǒ ài de yī yàng."],[9,11,"至於 以法蓮人，他們的榮耀必如鳥飛去， 必不生產，不懷胎，不成孕。","zhì yú yǐ fǎ lián rén， tā men de róng yào bì rú niǎo fēi qù， bì bù shēng chǎn， bù huái tāi， bù chéng yùn."],[9,12,"縱然養大兒女， 我卻必使他們喪子，甚至不留一個。 我離棄他們，他們就有禍了。","zòng rán yǎng dà ér nǚ， wǒ què bì shǐ tā men sàng zǐ， shèn zhì bù liú yī gè. wǒ lí qì tā men， tā men jiù yǒu huò le."],[9,13,"我看 以法蓮如 泰爾栽於美地。 以法蓮卻要將自己的兒女帶出來， 交與行殺戮的人。","wǒ kàn yǐ fǎ lián rú tài ěr zāi yú měi de. yǐ fǎ lián què yào jiāng zì jǐ de ér nǚ dài chū lái， jiāo yǔ xíng shā lù de rén."],[9,14,"耶和華啊，求你加給他們－ 加甚麼呢？ 要使他們胎墜乳乾。","yé hé huá a， qiú nǐ jiā gěi tā men－ jiā shèn me ne？ yào shǐ tā men tāi zhuì rǔ qián."],[9,15,"耶和華說：他們一切的惡事都在 吉甲； 我在那裏憎惡他們。 因他們所行的惡， 我必從我地上趕出他們去， 不再憐愛他們； 他們的首領都是悖逆的。","yé hé huá shuō： tā men yī qiè de è shì dōu zài jí jiǎ； wǒ zài nà lǐ zēng è tā men. yīn tā men suǒ xíng de è， wǒ bì cóng wǒ de shàng gǎn chū tā men qù， bù zài lián ài tā men； tā men de shǒu lǐng dōu shì bèi nì de."],[9,16,"以法蓮受責罰， 根本枯乾，必不能結果， 即或生產， 我必殺他們所生的愛子。","yǐ fǎ lián shòu zé fá， gēn běn kū qián， bì bù néng jié guǒ， jí huò shēng chǎn， wǒ bì shā tā men suǒ shēng de ài zǐ."],[9,17,"我的神必棄絕他們， 因為他們不聽從他； 他們也必飄流在列國中。","wǒ de shén bì qì jué tā men， yīn wèi tā men bù tīng cóng tā； tā men yě bì piāo liú zài liè guó zhōng."],[10,1,"以色列是茂盛的葡萄樹，結果繁多。 果子越多，就越增添祭壇； 地土越肥美，就越造美麗的柱像。","yǐ sè liè shì mào shèng de pú táo shù， jié guǒ fán duō. guǒ zǐ yuè duō， jiù yuè zēng tiān jì tán； de tǔ yuè féi měi， jiù yuè zào měi lì de zhù xiàng."],[10,2,"他們心懷二意， 現今要定為有罪。 耶和華必拆毀他們的祭壇， 毀壞他們的柱像。","tā men xīn huái èr yì， xiàn jīn yào dìng wèi yǒu zuì. yé hé huá bì chāi huǐ tā men de jì tán， huǐ huài tā men de zhù xiàng."],[10,3,"他們必說：我們沒有王， 因為我們不敬畏耶和華。 王能為我們做甚麼呢？","tā men bì shuō： wǒ men méi yǒu wáng， yīn wèi wǒ men bù jìng wèi yé hé huá. wáng néng wèi wǒ men zuò shèn me ne？"],[10,4,"他們為立約說 謊言，起假誓； 因此，災罰如苦菜滋生在田間的誆溝中。","tā men wèi lì yuē shuō huǎng yán， qǐ jiǎ shì； yīn cǐ， zāi fá rú kǔ cài zī shēng zài tián jiān de kuāng gōu zhōng."],[10,5,"撒馬利亞的居民必因 伯‧亞文的牛犢驚恐； 崇拜牛犢的民和喜愛牛犢的祭司 都必因榮耀離開它，為它悲哀。","sā mǎ lì yà de jū mín bì yīn bó‧yà wén de niú dú jīng kǒng； chóng bài niú dú de mín hé xǐ ài niú dú de jì sī dōu bì yīn róng yào lí kāi tā， wèi tā bēi āi."],[10,6,"人必將牛犢帶到 亞述當作禮物， 獻給 耶雷布王。 以法蓮必蒙羞； 以色列必因自己的計謀慚愧。","rén bì jiāng niú dú dài dào yà shù dāng zuò lǐ wù， xiàn gěi yé léi bù wáng. yǐ fǎ lián bì méng xiū； yǐ sè liè bì yīn zì jǐ de jì móu cán kuì."],[10,7,"至於 撒馬利亞，她的王必滅沒， 如水面的沫子一樣。","zhì yú sā mǎ lì yà， tā de wáng bì miè méi， rú shuǐ miàn de mò zǐ yī yàng."],[10,8,"伯‧亞文的邱壇－ 就是 以色列取罪 的地方必被毀滅； 荊棘和蒺藜必長在他們的祭壇上。 他們必對大山說：遮蓋我們！ 對小山說：倒在我們身上！","bó‧yà wén de qiū tán－ jiù shì yǐ sè liè qǔ zuì de de fāng bì bèi huǐ miè； jīng jí hé jí lí bì zhǎng zài tā men de jì tán shàng. tā men bì duì dà shān shuō： zhē gài wǒ men！ duì xiǎo shān shuō： dào zài wǒ men shēn shàng！"],[10,9,"以色列啊， 你從 基比亞的日子以來時常犯罪。 你們的先人曾站在那裏， 現今住 基比亞的人 以為攻擊罪孽之輩的戰事臨不到自己。","yǐ sè liè a， nǐ cóng jī bǐ yà de rì zǐ yǐ lái shí cháng fàn zuì. nǐ men de xiān rén céng zhàn zài nà lǐ， xiàn jīn zhù jī bǐ yà de rén yǐ wèi gōng jī zuì niè zhī bèi de zhàn shì lín bù dào zì jǐ."],[10,10,"我必隨意懲罰他們。 他們為兩樣的罪所纏； 列邦的民必聚集攻擊他們。","wǒ bì suí yì chéng fá tā men. tā men wèi liǎng yàng de zuì suǒ chán； liè bāng de mín bì jù jí gōng jī tā men."],[10,11,"以法蓮是馴良的母牛犢，喜愛踹 穀， 我卻將軛加在牠肥美的頸項上， 我要使 以法蓮拉套。 猶大必耕田； 雅各必耙地。","yǐ fǎ lián shì xún liáng de mǔ niú dú， xǐ ài chuài gǔ， wǒ què jiāng è jiā zài tā féi měi de jǐng xiàng shàng， wǒ yào shǐ yǐ fǎ lián lā tào. yóu dà bì gēng tián； yǎ gè bì bà de."],[10,12,"你們要為自己栽種公義， 就能收割慈愛。 現今正是尋求耶和華的時候； 你們要開墾荒地，等他臨到， 使公義如雨降在你們身上。","nǐ men yào wèi zì jǐ zāi zhǒng gōng yì， jiù néng shōu gē cí ài. xiàn jīn zhèng shì xún qiú yé hé huá de shí hòu； nǐ men yào kāi kěn huāng de， děng tā lín dào， shǐ gōng yì rú yǔ jiàng zài nǐ men shēn shàng."],[10,13,"你們耕種的是奸惡， 收割的是罪孽， 吃的是謊話的果子。 因你倚靠自己的行為， 仰賴勇士眾多，","nǐ men gēng zhǒng de shì jiān è， shōu gē de shì zuì niè， chī de shì huǎng huà de guǒ zǐ. yīn nǐ yǐ kào zì jǐ de xíng wèi， yǎng lài yǒng shì zhòng duō，"],[10,14,"所以在這民中必有鬨嚷之聲， 你一切的保障必被拆毀， 就如 沙勒幔在爭戰的日子拆毀 伯‧亞比勒， 將其中的母子一同摔死。","suǒ yǐ zài zhè mín zhōng bì yǒu hòng rǎng zhī shēng， nǐ yī qiè de bǎo zhàng bì bèi chāi huǐ， jiù rú shā lēi màn zài zhēng zhàn de rì zǐ chāi huǐ bó‧yà bǐ lēi， jiāng qí zhōng de mǔ zǐ yī tóng shuāi sǐ."],[10,15,"因他們的大惡， 伯特利必使你們遭遇如此。 到了黎明， 以色列的王必全然滅絕。","yīn tā men de dà è， bó tè lì bì shǐ nǐ men zāo yù rú cǐ. dào le lí míng， yǐ sè liè de wáng bì quán rán miè jué."],[11,1,"以色列年幼的時候，我愛他， 就從 埃及召出我的兒子來。","yǐ sè liè nián yòu de shí hòu， wǒ ài tā， jiù cóng āi jí zhào chū wǒ de ér zǐ lái."],[11,2,"先知越發招呼他們， 他們越發走開， 向諸 巴力獻祭， 給雕刻的偶像燒香。","xiān zhī yuè fā zhāo hū tā men， tā men yuè fā zǒu kāi， xiàng zhū bā lì xiàn jì， gěi diāo kè de ǒu xiàng shāo xiāng."],[11,3,"我原教導 以法蓮行走， 用膀臂抱着他們， 他們卻不知道是我醫治他們。","wǒ yuán jiào dǎo yǐ fǎ lián xíng zǒu， yòng bǎng bì bào zhe tā men， tā men què bù zhī dào shì wǒ yī zhì tā men."],[11,4,"我用慈繩愛索牽引他們； 我待他們如人放鬆 牛的兩腮夾板， 把糧食放在他們面前。","wǒ yòng cí shéng ài suǒ qiān yǐn tā men； wǒ dài tā men rú rén fàng sōng niú de liǎng sāi jiā bǎn， bǎ liáng shí fàng zài tā men miàn qián."],[11,5,"他們必不歸回 埃及地， 亞述人卻要作他們的王， 因他們不肯歸向 我。","tā men bì bù guī huí āi jí de， yà shù rén què yào zuò tā men de wáng， yīn tā men bù kěn guī xiàng wǒ."],[11,6,"刀劍必臨到他們的城邑， 毀壞門閂，把人吞滅， 都因他們 隨從自己的計謀。","dāo jiàn bì lín dào tā men de chéng yì， huǐ huài mén shuān， bǎ rén tūn miè， dōu yīn tā men suí cóng zì jǐ de jì móu."],[11,7,"我的民偏要背道離開我； 眾先知雖然招呼他們歸向至上的 主， 卻無人尊崇 主。","wǒ de mín piān yào bèi dào lí kāi wǒ； zhòng xiān zhī suī rán zhāo hū tā men guī xiàng zhì shàng de zhǔ， què wú rén zūn chóng zhǔ."],[11,8,"以法蓮哪，我怎能捨棄你？ 以色列啊，我怎能棄絕你？ 我怎能使你如 押瑪？ 怎能使你如 洗扁？ 我回心轉意， 我的憐愛大大發動。","yǐ fǎ lián nǎ， wǒ zěn néng shě qì nǐ？ yǐ sè liè a， wǒ zěn néng qì jué nǐ？ wǒ zěn néng shǐ nǐ rú yā mǎ？ zěn néng shǐ nǐ rú xǐ biǎn？ wǒ huí xīn zhuǎn yì， wǒ de lián ài dà dà fā dòng."],[11,9,"我必不發猛烈的怒氣， 也不再毀滅 以法蓮。 因我是神，並非世人， 是你們中間的聖者； 我必不在怒中臨到你們。","wǒ bì bù fā měng liè de nù qì， yě bù zài huǐ miè yǐ fǎ lián. yīn wǒ shì shén， bìng fēi shì rén， shì nǐ men zhōng jiān de shèng zhě； wǒ bì bù zài nù zhōng lín dào nǐ men."],[11,10,"耶和華必如獅子吼叫， 子民必跟隨他。 他一吼叫， 他們就從西方急速而來。","yé hé huá bì rú shī zǐ hǒu jiào， zǐ mín bì gēn suí tā. tā yī hǒu jiào， tā men jiù cóng xī fāng jí sù ér lái."],[11,11,"他們必如雀鳥從 埃及急速而來， 又如鴿子從 亞述地來到。 我必使他們住自己的房屋。 這是耶和華說的。","tā men bì rú què niǎo cóng āi jí jí sù ér lái， yòu rú gē zǐ cóng yà shù de lái dào. wǒ bì shǐ tā men zhù zì jǐ de fáng wū. zhè shì yé hé huá shuō de."],[11,12,"以法蓮用謊話， 以色列家用詭計圍繞我； 猶大卻靠神掌權， 向聖者有忠心。","yǐ fǎ lián yòng huǎng huà， yǐ sè liè jiā yòng guǐ jì wéi rào wǒ； yóu dà què kào shén zhǎng quán， xiàng shèng zhě yǒu zhōng xīn."],[12,1,"以法蓮吃風，且追趕東風， 時常增添虛謊和強暴， 與 亞述立約，把油送到 埃及。","yǐ fǎ lián chī fēng， qiě zhuī gǎn dōng fēng， shí cháng zēng tiān xū huǎng hé qiáng bào， yǔ yà shù lì yuē， bǎ yóu sòng dào āi jí."],[12,2,"耶和華與 猶大爭辯， 必照 雅各所行的懲罰他， 按他所做的報應他。","yé hé huá yǔ yóu dà zhēng biàn， bì zhào yǎ gè suǒ xíng de chéng fá tā， àn tā suǒ zuò de bào yīng tā."],[12,3,"他在腹中抓住哥哥的腳跟， 壯年的時候與神較力，","tā zài fù zhōng zhuā zhù gē gē de jiǎo gēn， zhuàng nián de shí hòu yǔ shén jiào lì，"],[12,4,"與天使較力，並且得勝， 哭泣懇求， 在 伯特利遇見耶和華。 耶和華－萬軍之神在那裏曉諭我們 以色列人； 耶和華是他可記念的 名。","yǔ tiān shǐ jiào lì， bìng qiě dé shèng， kū qì kěn qiú， zài bó tè lì yù jiàn yé hé huá. yé hé huá－wàn jūn zhī shén zài nà lǐ xiǎo yù wǒ men yǐ sè liè rén； yé hé huá shì tā kě jì niàn de míng."],[12,6,"所以你當歸向你的神， 謹守仁愛、公平，常常等候你的神。","suǒ yǐ nǐ dāng guī xiàng nǐ de shén， jǐn shǒu rén ài, gōng píng， cháng cháng děng hòu nǐ de shén."],[12,7,"以法蓮是商人， 手裏有詭詐的天平，愛行欺騙。","yǐ fǎ lián shì shāng rén， shǒu lǐ yǒu guǐ zhà de tiān píng， ài xíng qī piàn."],[12,8,"以法蓮說： 我果然成了富足，得了財寶； 我所勞碌得來的， 人必不見有甚麼不義，可算為罪的。","yǐ fǎ lián shuō： wǒ guǒ rán chéng le fù zú， dé le cái bǎo； wǒ suǒ láo lù dé lái de， rén bì bù jiàn yǒu shèn me bù yì， kě suàn wèi zuì de."],[12,9,"自從你出 埃及地以來， 我就是耶和華－你的神； 我必使你再住帳棚，如在大會的日子一樣。","zì cóng nǐ chū āi jí de yǐ lái， wǒ jiù shì yé hé huá－nǐ de shén； wǒ bì shǐ nǐ zài zhù zhàng péng， rú zài dà huì de rì zǐ yī yàng."],[12,10,"我已曉諭眾先知， 並且加增默示， 藉先知設立比喻。","wǒ yǐ xiǎo yù zhòng xiān zhī， bìng qiě jiā zēng mò shì， jí xiān zhī shè lì bǐ yù."],[12,11,"基列人沒有罪孽嗎？ 他們全然是虛假的。 人在 吉甲獻牛犢為祭， 他們的祭壇好像田間誆溝中的亂堆。","jī liè rén méi yǒu zuì niè ma？ tā men quán rán shì xū jiǎ de. rén zài jí jiǎ xiàn niú dú wèi jì， tā men de jì tán hǎo xiàng tián jiān kuāng gōu zhōng de luàn duī."],[12,12,"從前 雅各逃到 亞蘭地， 以色列為得妻服事人， 為得妻與人放羊。","cóng qián yǎ gè táo dào yà lán de， yǐ sè liè wèi dé qī fú shì rén， wèi dé qī yǔ rén fàng yáng."],[12,13,"耶和華藉先知領 以色列從 埃及上來； 以色列也藉先知而得保存。","yé hé huá jí xiān zhī lǐng yǐ sè liè cóng āi jí shàng lái； yǐ sè liè yě jí xiān zhī ér dé bǎo cún."],[12,14,"以法蓮大大惹動 主怒， 所以他流血的罪必歸在他身上。 主必將那因 以法蓮所受的羞辱歸還他。","yǐ fǎ lián dà dà rě dòng zhǔ nù， suǒ yǐ tā liú xuè de zuì bì guī zài tā shēn shàng. zhǔ bì jiāng nà yīn yǐ fǎ lián suǒ shòu de xiū rǔ guī hái tā."],[13,1,"從前 以法蓮說話，人都戰兢， 他在 以色列中居處高位； 但他在 事奉 巴力的事上犯罪就死了。","cóng qián yǐ fǎ lián shuō huà， rén dōu zhàn jīng， tā zài yǐ sè liè zhōng jū chù gāo wèi； dàn tā zài shì fèng bā lì de shì shàng fàn zuì jiù sǐ le."],[13,2,"現今他們罪上加罪， 用銀子為自己鑄造偶像， 就是照自己的聰明製造， 都是匠人的工作。 有人論說， 獻祭的人可以向牛犢親嘴。","xiàn jīn tā men zuì shàng jiā zuì， yòng yín zǐ wèi zì jǐ zhù zào ǒu xiàng， jiù shì zhào zì jǐ de cōng míng zhì zào， dōu shì jiàng rén de gōng zuò. yǒu rén lùn shuō， xiàn jì de rén kě yǐ xiàng niú dú qīn zuǐ."],[13,3,"因此，他們必如早晨的雲霧， 又如速散的甘露， 像場上的糠詷被狂風吹去， 又像煙氣騰於窗外。","yīn cǐ， tā men bì rú zǎo chén de yún wù， yòu rú sù sàn de gān lù， xiàng chǎng shàng de kāng tóng bèi kuáng fēng chuī qù， yòu xiàng yān qì téng yú chuāng wài."],[13,4,"自從你出 埃及地以來， 我就是耶和華－你的神。 在我以外，你不可認識別神； 除我以外並沒有救主。","zì cóng nǐ chū āi jí de yǐ lái， wǒ jiù shì yé hé huá－nǐ de shén. zài wǒ yǐ wài， nǐ bù kě rèn shí bié shén； chú wǒ yǐ wài bìng méi yǒu jiù zhǔ."],[13,5,"我曾在曠野乾旱之地認識你。","wǒ céng zài kuàng yě qián hàn zhī de rèn shí nǐ."],[13,6,"這些民照 我所賜的食物得了飽足； 既得飽足，心就高傲， 忘記了我。","zhè xiē mín zhào wǒ suǒ cì de shí wù dé le bǎo zú； jì dé bǎo zú， xīn jiù gāo ào， wàng jì le wǒ."],[13,7,"因此，我向他們如獅子， 又如豹伏在道旁。","yīn cǐ， wǒ xiàng tā men rú shī zǐ， yòu rú bào fú zài dào páng."],[13,8,"我遇見他們必像丟崽子的母熊， 撕裂他們的胸膛。 在那裏，我必像母獅吞吃他們； 野獸必撕裂他們。","wǒ yù jiàn tā men bì xiàng diū zǎi zǐ de mǔ xióng， sī liè tā men de xiōng táng. zài nà lǐ， wǒ bì xiàng mǔ shī tūn chī tā men； yě shòu bì sī liè tā men."],[13,9,"以色列啊，你與我反對， 就是反對幫助你的，自取敗壞。","yǐ sè liè a， nǐ yǔ wǒ fǎn duì， jiù shì fǎn duì bāng zhù nǐ de， zì qǔ bài huài."],[13,10,"你曾求我說： 給我立王和首領。 現在你的王在哪裏呢？ 治理你的在哪裏呢？ 讓他在你所有的城中拯救你吧！","nǐ céng qiú wǒ shuō： gěi wǒ lì wáng hé shǒu lǐng. xiàn zài nǐ de wáng zài nǎ lǐ ne？ zhì lǐ nǐ de zài nǎ lǐ ne？ ràng tā zài nǐ suǒ yǒu de chéng zhōng zhěng jiù nǐ ba！"],[13,11,"我在怒氣中將王賜你， 又在烈怒中將王廢去。","wǒ zài nù qì zhōng jiāng wáng cì nǐ， yòu zài liè nù zhōng jiāng wáng fèi qù."],[13,12,"以法蓮的罪孽包裹； 他的罪惡收藏。","yǐ fǎ lián de zuì niè bāo guǒ； tā de zuì è shōu cáng."],[13,13,"產婦的疼痛必臨到他身上； 他是無智慧之子， 到了產期不當遲延。","chǎn fù de téng tòng bì lín dào tā shēn shàng； tā shì wú zhì huì zhī zǐ， dào le chǎn qī bù dāng chí yán."],[13,14,"我必救贖他們脫離陰間， 救贖他們脫離死亡。 死亡啊，你的災害在哪裏呢？ 陰間哪，你的毀滅在哪裏呢？ 在我眼前絕無後悔之事。","wǒ bì jiù shú tā men tuō lí yīn jiān， jiù shú tā men tuō lí sǐ wáng. sǐ wáng a， nǐ de zāi hài zài nǎ lǐ ne？ yīn jiān nǎ， nǐ de huǐ miè zài nǎ lǐ ne？ zài wǒ yǎn qián jué wú hòu huǐ zhī shì."],[13,15,"他在弟兄中雖然茂盛， 必有東風颳來， 就是耶和華的風從曠野上來。 他的泉源必乾； 他的源頭必竭； 仇敵必擄掠他所積蓄的一切寶器。","tā zài dì xiōng zhōng suī rán mào shèng， bì yǒu dōng fēng guā lái， jiù shì yé hé huá de fēng cóng kuàng yě shàng lái. tā de quán yuán bì qián； tā de yuán tóu bì jié； chóu dí bì lǔ lüè tā suǒ jī xù de yī qiè bǎo qì."],[13,16,"撒馬利亞必擔當自己的罪， 因為悖逆她的神。 她必倒在刀下； 嬰孩必被摔死； 孕婦必被剖開。","sā mǎ lì yà bì dān dāng zì jǐ de zuì， yīn wèi bèi nì tā de shén. tā bì dào zài dāo xià； yīng hái bì bèi shuāi sǐ； yùn fù bì bèi pōu kāi."],[14,1,"以色列啊，你要歸向耶和華－你的神； 你是因自己的罪孽跌倒了。","yǐ sè liè a， nǐ yào guī xiàng yé hé huá－nǐ de shén； nǐ shì yīn zì jǐ de zuì niè diē dào le."],[14,2,"當歸向耶和華， 用言語禱告他說： 求你除淨罪孽，悅納善行； 這樣，我們就把嘴唇 的祭 代替牛犢獻上。","dāng guī xiàng yé hé huá， yòng yán yǔ dǎo gào tā shuō： qiú nǐ chú jìng zuì niè， yuè nà shàn xíng； zhè yàng， wǒ men jiù bǎ zuǐ chún de jì dài tì niú dú xiàn shàng."],[14,3,"我們不向 亞述求救， 不騎 埃及的馬， 也不再對我們手所造的說： 你是我們的神。 因為孤兒在你－ 耶和華那裏得蒙憐憫。","wǒ men bù xiàng yà shù qiú jiù， bù qí āi jí de mǎ， yě bù zài duì wǒ men shǒu suǒ zào de shuō： nǐ shì wǒ men de shén. yīn wèi gū ér zài nǐ－ yé hé huá nà lǐ dé méng lián mǐn."],[14,4,"我必醫治他們背道的病， 甘心愛他們； 因為我的怒氣向他們轉消。","wǒ bì yī zhì tā men bèi dào de bìng， gān xīn ài tā men； yīn wèi wǒ de nù qì xiàng tā men zhuǎn xiāo."],[14,5,"我必向 以色列如甘露； 他必如百合花開放， 如 黎巴嫩 的樹木扎根。","wǒ bì xiàng yǐ sè liè rú gān lù； tā bì rú bǎi hé huā kāi fàng， rú lí bā nèn de shù mù zhā gēn."],[14,6,"他的枝條必延長； 他的榮華如橄欖樹； 他的香氣如 黎巴嫩 的香柏樹。","tā de zhī tiáo bì yán zhǎng； tā de róng huá rú gǎn lǎn shù； tā de xiāng qì rú lí bā nèn de xiāng bǎi shù."],[14,7,"曾住在他蔭下的必歸回， 發旺如五穀，開花如葡萄樹。 他的香氣如 黎巴嫩的酒。","céng zhù zài tā yīn xià de bì guī huí， fā wàng rú wǔ gǔ， kāi huā rú pú táo shù. tā de xiāng qì rú lí bā nèn de jiǔ."],[14,8,"以法蓮 必說： 我與偶像還有甚麼關涉呢？ 我－ 耶和華回答他，也必顧念他。 我如青翠的松樹； 你的果子從我而得。","yǐ fǎ lián bì shuō： wǒ yǔ ǒu xiàng hái yǒu shèn me guān shè ne？ wǒ－ yé hé huá huí dá tā， yě bì gù niàn tā. wǒ rú qīng cuì de sōng shù； nǐ de guǒ zǐ cóng wǒ ér dé."],[14,9,"誰是智慧人？可以明白這些事； 誰是通達人？可以知道這一切。 因為，耶和華的道是正直的； 義人必在其中行走， 罪人卻在其上跌倒。","shuí shì zhì huì rén？ kě yǐ míng bái zhè xiē shì； shuí shì tōng dá rén？ kě yǐ zhī dào zhè yī qiè. yīn wèi， yé hé huá de dào shì zhèng zhí de； yì rén bì zài qí zhōng xíng zǒu， zuì rén què zài qí shàng diē dào."]],"arb-vandyck":[[1,1,"قَوْلُ ٱلرَّبِّ ٱلَّذِي صَارَ إِلَى هُوشَعَ بْنِ بِئِيرِي، فِي أَيَّامِ عُزِّيَّا وَيُوثَامَ وَآحَازَ وَحَزَقِيَّا مُلُوكِ يَهُوذَا، وَفِي أَيَّامِ يَرُبْعَامَ بْنِ يُوآشَ مَلِكِ إِسْرَائِيلَ.","qaẘlu ٱlrãbĩ ٱlãdẖī ṣāra ại̹lay̱ hūsẖaʿa b̊ni bīỉyrī, fī ạảyãạmi ʿuzĩyãạ wayūtẖāma wā̂ḥāza waḥazaqīãạ mulūki yahūdẖā, wafī ạảyãạmi yarub̊ʿāma b̊ni yūậsẖa maliki ại̹s̊rāyỉyla."],[1,2,"أَوَّلَ مَا كَلَّمَ ٱلرَّبُّ هُوشَعَ، قَالَ ٱلرَّبُّ لِهُوشَعَ: «ٱذْهَبْ خُذْ لِنَفْسِكَ ٱمْرَأَةَ زِنًى وَأَوْلَادَ زِنًى، لِأَنَّ ٱلْأَرْضَ قَدْ زَنَتْ زِنًى تَارِكَةً ٱلرَّبَّ».","ạảwãla mā kalãma ٱlrãbũ hūsẖaʿa, qāla ٱlrãbũ lihūsẖaʿa: «ٱdẖ̊hab̊ kẖudẖ̊ linaf̊sika ٱm̊rāảẗa zinaⁿy̱ wāảẘlāda zinaⁿy̱, liạảnã ٱl̊ạảr̊ḍa qad̊ zanat̊ zinaⁿy̱ tārikaẗaⁿ ٱlrãbã»."],[1,3,"فَذَهَبَ وَأَخَذَ جُومَرَ بِنْتَ دِبْلَايِمَ، فَحَبِلَتْ وَوَلَدَتْ لَهُ ٱبْنًا،","fadẖahaba wāảkẖadẖa jūmara bin̊ta dib̊lāyima, faḥabilat̊ wawaladat̊ lahu ٱb̊naⁿạ,"],[1,4,"فَقَالَ لَهُ ٱلرَّبُّ: «ٱدْعُ ٱسْمَهُ يَزْرَعِيلَ، لِأَنَّنِي بَعْدَ قَلِيلٍ أُعَاقِبُ بَيْتَ يَاهُو عَلَى دَمِ يَزْرَعِيلَ، وَأُبِيدُ مَمْلَكَةَ بَيْتِ إِسْرَائِيلَ.","faqāla lahu ٱlrãbũ: «ٱd̊ʿu ٱs̊mahu yaz̊raʿīla, liạảnãnī baʿ̊da qalīliⁿ ạủʿāqibu baẙta yāhū ʿalay̱ dami yaz̊raʿīla, wāủbīdu mam̊lakaẗa baẙti ại̹s̊rāyỉyla."],[1,5,"وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ أَنِّي أَكْسِرُ قَوْسَ إِسْرَائِيلَ فِي وَادِي يَزْرَعِيلَ».","wayakūnu fī dẖalika ٱl̊yaẘmi ạảnĩy ạảk̊siru qaẘsa ại̹s̊rāyỉyla fī wādī yaz̊raʿīla»."],[1,6,"ثُمَّ حَبِلَتْ أَيْضًا وَوَلَدَتْ بِنْتًا، فَقَالَ لَهُ: «ٱدْعُ ٱسْمَهَا لُورُحَامَةَ، لِأَنِّي لَا أَعُودُ أَرْحَمُ بَيْتَ إِسْرَائِيلَ أَيْضًا، بَلْ أَنْزِعُهُمْ نَزْعًا.","tẖumã ḥabilat̊ ạảẙḍaⁿạ wawaladat̊ bin̊taⁿạ, faqāla lahu: «ٱd̊ʿu ٱs̊mahā lūruḥāmaẗa, liạảnĩy lā ạảʿūdu ạảr̊ḥamu baẙta ại̹s̊rāyỉyla ạảẙḍaⁿạ, bal̊ ạản̊ziʿuhum̊ naz̊ʿaⁿạ."],[1,7,"وَأَمَّا بَيْتُ يَهُوذَا فَأَرْحَمُهُمْ وَأُخَلِّصُهُمْ بِٱلرَّبِّ إِلَهِهِمْ، وَلَا أُخَلِّصُهُمْ بِقَوْسٍ وَبِسَيْفٍ وَبِحَرْبٍ وَبِخَيْلٍ وَبِفُرْسَانٍ».","wāảmãạ baẙtu yahūdẖā fāảr̊ḥamuhum̊ wāủkẖalĩṣuhum̊ biٱlrãbĩ ại̹lahihim̊, walā ạủkẖalĩṣuhum̊ biqaẘsiⁿ wabisaẙfiⁿ wabiḥar̊biⁿ wabikẖaẙliⁿ wabifur̊sāniⁿ»."],[1,8,"ثُمَّ فَطَمَتْ لُورُحَامَةَ وَحَبِلَتْ فَوَلَدَتِ ٱبْنًا،","tẖumã faṭamat̊ lūruḥāmaẗa waḥabilat̊ fawaladati ٱb̊naⁿạ,"],[1,9,"فَقَالَ: «ٱدْعُ ٱسْمَهُ لُوعَمِّي، لِأَنَّكُمْ لَسْتُمْ شَعْبِي وَأَنَا لَا أَكُونُ لَكُمْ.","faqāla: «ٱd̊ʿu ٱs̊mahu lūʿamĩy, liạảnãkum̊ las̊tum̊ sẖaʿ̊bī wāảnā lā ạảkūnu lakum̊."],[1,10,"لَكِنْ يَكُونُ عَدَدُ بَنِي إِسْرَائِيلَ كَرَمْلِ ٱلْبَحْرِ ٱلَّذِي لَا يُكَالُ وَلَا يُعَدُّ، وَيَكُونُ عِوَضًا عَنْ أَنْ يُقَالَ لَهُمْ: لَسْتُمْ شَعْبِي، يُقَالُ لَهُمْ: أَبْنَاءُ ٱللهِ ٱلْحَيِّ.","lakin̊ yakūnu ʿadadu banī ại̹s̊rāyỉyla karam̊li ٱl̊baḥ̊ri ٱlãdẖī lā yukālu walā yuʿadũ, wayakūnu ʿiwaḍaⁿạ ʿan̊ ạản̊ yuqāla lahum̊: las̊tum̊ sẖaʿ̊bī, yuqālu lahum̊: ạảb̊nāʾu ٱllhi ٱl̊ḥayĩ."],[1,11,"وَيُجْمَعُ بَنُو يَهُوذَا وَبَنُو إِسْرَائِيلَ مَعًا وَيَجْعَلُونَ لِأَنْفُسِهِمْ رَأْسًا وَاحِدًا، وَيَصْعَدُونَ مِنَ ٱلْأَرْضِ، لِأَنَّ يَوْمَ يَزْرَعِيلَ عَظِيمٌ.","wayuj̊maʿu banū yahūdẖā wabanū ại̹s̊rāyỉyla maʿaⁿạ wayaj̊ʿalūna liạản̊fusihim̊ rā̊̉saⁿạ wāḥidaⁿạ, wayaṣ̊ʿadūna mina ٱl̊ạảr̊ḍi, liạảnã yaẘma yaz̊raʿīla ʿaẓīmuⁿ."],[2,1,"«قُولُوا لِإِخْوَتِكُمْ «عَمِّي» وَلِأَخَوَاتِكُمْ «رُحَامَةَ».","«qūlūạ liại̹kẖ̊watikum̊ «ʿamĩy» waliạảkẖawātikum̊ «ruḥāmaẗa»."],[2,2,"حَاكِمُوا أُمَّكُمْ حَاكِمُوا، لِأَنَّهَا لَيْسَتِ ٱمْرَأَتِي وَأَنَا لَسْتُ رَجُلَهَا، لِكَيْ تَعْزِلَ زِنَاهَا عَنْ وَجْهِهَا وَفِسْقَهَا مِنْ بَيْنِ ثَدْيَيْهَا،","ḥākimūạ ạủmãkum̊ ḥākimūạ, liạảnãhā laẙsati ٱm̊rāảtī wāảnā las̊tu rajulahā, likaẙ taʿ̊zila zināhā ʿan̊ waj̊hihā wafis̊qahā min̊ baẙni tẖad̊yaẙhā,"],[2,3,"لِئَلَّا أُجَرِّدَهَا عُرْيَانَةً وَأَوْقِفَهَا كَيَوْمِ وِلَادَتِهَا، وَأَجْعَلَهَا كَقَفْرٍ، وَأُصَيِّرَهَا كَأَرْضٍ يَابِسَةٍ، وَأُمِيتَهَا بِٱلْعَطَشِ.","līảlãạ ạủjarĩdahā ʿur̊yānaẗaⁿ wāảẘqifahā kayaẘmi wilādatihā, wāảj̊ʿalahā kaqaf̊riⁿ, wāủṣayĩrahā kāảr̊ḍiⁿ yābisaẗiⁿ, wāủmītahā biٱl̊ʿaṭasẖi."],[2,4,"وَلَا أَرْحَمُ أَوْلَادَهَا لِأَنَّهُمْ أَوْلَادُ زِنًى.","walā ạảr̊ḥamu ạảẘlādahā liạảnãhum̊ ạảẘlādu zinaⁿy̱."],[2,5,"«لِأَنَّ أُمَّهُمْ قَدْ زَنَتِ. ٱلَّتِي حَبِلَتْ بِهِمْ صَنَعَتْ خِزْيًا. لِأَنَّهَا قَالَتْ: أَذْهَبُ وَرَاءَ مُحِبِّيَّ ٱلَّذِينَ يُعْطُونَ خُبْزِي وَمَائِي، صُوفِي وَكَتَّانِي، زَيْتِي وَأَشْرِبَتِي.","«liạảnã ạủmãhum̊ qad̊ zanati. ٱlãtī ḥabilat̊ bihim̊ ṣanaʿat̊ kẖiz̊yaⁿạ. liạảnãhā qālat̊: ạảdẖ̊habu warāʾa muḥibĩyã ٱlãdẖīna yuʿ̊ṭūna kẖub̊zī wamāyỉy, ṣūfī wakatãạnī, zaẙtī wāảsẖ̊ribatī."],[2,6,"لِذَلِكَ هَأَنَذَا أُسَيِّجُ طَرِيقَكِ بِٱلشَّوْكِ، وَأَبْنِي حَائِطَهَا حَتَّى لَا تَجِدَ مَسَالِكَهَا.","lidẖalika hāảnadẖā ạủsayĩju ṭarīqaki biٱlsẖãẘki, wāảb̊nī ḥāyỉṭahā ḥatãy̱ lā tajida masālikahā."],[2,7,"فَتَتْبَعُ مُحِبِّيهَا وَلَا تُدْرِكُهُمْ، وَتُفَتِّشُ عَلَيْهِمْ وَلَا تَجِدُهُمْ. فَتَقُولُ: أَذْهَبُ وَأَرْجِعُ إِلَى رَجُلِي ٱلْأَوَّلِ، لِأَنَّهُ حِينَئِذٍ كَانَ خَيْرٌ لِي مِنَ ٱلْآنَ.","fatat̊baʿu muḥibĩyhā walā tud̊rikuhum̊, watufatĩsẖu ʿalaẙhim̊ walā tajiduhum̊. fataqūlu: ạảdẖ̊habu wāảr̊jiʿu ại̹lay̱ rajulī ٱl̊ạảwãli, liạảnãhu ḥīnayỉdẖiⁿ kāna kẖaẙruⁿ lī mina ٱl̊ậna."],[2,8,"«وَهِيَ لَمْ تَعْرِفْ أَنِّي أَنَا أَعْطَيْتُهَا ٱلْقَمْحَ وَٱلْمِسْطَارَ وَٱلزَّيْتَ، وَكَثَّرْتُ لَهَا فِضَّةً وَذَهَبًا جَعَلُوهُ لِبَعْلٍ.","«wahīa lam̊ taʿ̊rif̊ ạảnĩy ạảnā ạảʿ̊ṭaẙtuhā ٱl̊qam̊ḥa waٱl̊mis̊ṭāra waٱlzãẙta, wakatẖãr̊tu lahā fiḍãẗaⁿ wadẖahabaⁿạ jaʿalūhu libaʿ̊liⁿ."],[2,9,"لِذَلِكَ أَرْجِعُ وَآخُذُ قَمْحِي فِي حِينِهِ، وَمِسْطَارِي فِي وَقْتِهِ، وَأَنْزِعُ صُوفِي وَكَتَّانِي ٱللَّذَيْنِ لِسَتْرِ عَوْرَتِهَا.","lidẖalika ạảr̊jiʿu wā̂kẖudẖu qam̊ḥī fī ḥīnihi, wamis̊ṭārī fī waq̊tihi, wāản̊ziʿu ṣūfī wakatãạnī ٱllãdẖaẙni lisat̊ri ʿaẘratihā."],[2,10,"وَٱلْآنَ أَكْشِفُ عَوْرَتَهَا أَمَامَ عُيُونِ مُحِبِّيهَا وَلَا يُنْقِذُهَا أَحَدٌ مِنْ يَدِي.","waٱl̊ậna ạảk̊sẖifu ʿaẘratahā ạảmāma ʿuyūni muḥibĩyhā walā yun̊qidẖuhā ạảḥaduⁿ min̊ yadī."],[2,11,"وَأُبَطِّلُ كُلَّ أَفْرَاحِهَا: أَعْيَادَهَا وَرُؤُوسَ شُهُورِهَا وَسُبُوتَهَا وَجَمِيعَ مَوَاسِمِهَا.","wāủbaṭĩlu kulã ạảf̊rāḥihā: ạảʿ̊yādahā warūủwsa sẖuhūrihā wasubūtahā wajamīʿa mawāsimihā."],[2,12,"وَأُخَرِّبُ كَرْمَهَا وَتِينَهَا ٱللَّذَيْنِ قَالَتْ: هُمَا أُجْرَتِي ٱلَّتِي أَعْطَانِيهَا مُحِبِّيَّ، وَأَجْعَلُهُمَا وَعْرًا فَيَأْكُلُهُمَا حَيَوَانُ ٱلْبَرِّيَّةِ.","wāủkẖarĩbu kar̊mahā watīnahā ٱllãdẖaẙni qālat̊: humā ạủj̊ratī ٱlãtī ạảʿ̊ṭānīhā muḥibĩyã, wāảj̊ʿaluhumā waʿ̊raⁿạ fayā̊̉kuluhumā ḥayawānu ٱl̊barĩyãẗi."],[2,13,"وَأُعَاقِبُهَا عَلَى أَيَّامِ بَعْلِيمَ ٱلَّتِي فِيهَا كَانَتْ تُبَخِّرُ لَهُمْ وَتَتَزَيَّنُ بِخَزَائِمِهَا وَحُلِيهَا وَتَذْهَبُ وَرَاءَ مُحِبِّيهَا وَتَنْسَانِي أَنَا، يَقُولُ ٱلرَّبُّ.","wāủʿāqibuhā ʿalay̱ ạảyãạmi baʿ̊līma ٱlãtī fīhā kānat̊ tubakẖĩru lahum̊ watatazayãnu bikẖazāyỉmihā waḥulīhā watadẖ̊habu warāʾa muḥibĩyhā watan̊sānī ạảnā, yaqūlu ٱlrãbũ."],[2,14,"«لَكِنْ هَأَنَذَا أَتَمَلَّقُهَا وَأَذْهَبُ بِهَا إِلَى ٱلْبَرِّيَّةِ وَأُلَاطِفُهَا،","«lakin̊ hāảnadẖā ạảtamalãquhā wāảdẖ̊habu bihā ại̹lay̱ ٱl̊barĩyãẗi wāủlāṭifuhā,"],[2,15,"وَأُعْطِيهَا كُرُومَهَا مِنْ هُنَاكَ، وَوَادِي عَخُورَ بَابًا لِلرَّجَاءِ. وَهِيَ تُغَنِّي هُنَاكَ كَأَيَّامِ صِبَاهَا، وَكَيَوْمِ صُعُودِهَا مِنْ أَرْضِ مِصْرَ.","wāủʿ̊ṭīhā kurūmahā min̊ hunāka, wawādī ʿakẖūra bābaⁿạ lilrãjāʾi. wahīa tugẖanĩy hunāka kāảyãạmi ṣibāhā, wakayaẘmi ṣuʿūdihā min̊ ạảr̊ḍi miṣ̊ra."],[2,16,"وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ ٱلرَّبُّ، أَنَّكِ تَدْعِينَنِي: رَجُلِي، وَلَا تَدْعِينَنِي بَعْدُ بَعْلِي.","wayakūnu fī dẖalika ٱl̊yaẘmi, yaqūlu ٱlrãbũ, ạảnãki tad̊ʿīnanī: rajulī, walā tad̊ʿīnanī baʿ̊du baʿ̊lī."],[2,17,"وَأَنْزِعُ أَسْمَاءَ ٱلْبَعْلِيمِ مِنْ فَمِهَا، فَلَا تُذْكَرُ أَيْضًا بِأَسْمَائِهَا.","wāản̊ziʿu ạảs̊māʾa ٱl̊baʿ̊līmi min̊ famihā, falā tudẖ̊karu ạảẙḍaⁿạ biạảs̊māyỉhā."],[2,18,"وَأَقْطَعُ لَهُمْ عَهْدًا فِي ذَلِكَ ٱلْيَوْمِ مَعَ حَيَوَانِ ٱلْبَرِّيَّةِ وَطُيُورِ ٱلسَّمَاءِ وَدَبَّابَاتِ ٱلْأَرْضِ، وَأَكْسِرُ ٱلْقَوْسَ وَٱلسَّيْفَ وَٱلْحَرْبَ مِنَ ٱلْأَرْضِ، وَأَجْعَلُهُمْ يَضْطَجِعُونَ آمِنِينَ.","wāảq̊ṭaʿu lahum̊ ʿah̊daⁿạ fī dẖalika ٱl̊yaẘmi maʿa ḥayawāni ٱl̊barĩyãẗi waṭuyūri ٱlsãmāʾi wadabãạbāti ٱl̊ạảr̊ḍi, wāảk̊siru ٱl̊qaẘsa waٱlsãẙfa waٱl̊ḥar̊ba mina ٱl̊ạảr̊ḍi, wāảj̊ʿaluhum̊ yaḍ̊ṭajiʿūna ậminīna."],[2,19,"وَأَخْطُبُكِ لِنَفْسِي إِلَى ٱلْأَبَدِ. وَأَخْطُبُكِ لِنَفْسِي بِٱلْعَدْلِ وَٱلْحَقِّ وَٱلْإِحْسَانِ وَٱلْمَرَاحِمِ.","wāảkẖ̊ṭubuki linaf̊sī ại̹lay̱ ٱl̊ạảbadi. wāảkẖ̊ṭubuki linaf̊sī biٱl̊ʿad̊li waٱl̊ḥaqĩ waٱl̊ại̹ḥ̊sāni waٱl̊marāḥimi."],[2,20,"أَخْطُبُكِ لِنَفْسِي بِٱلْأَمَانَةِ فَتَعْرِفِينَ ٱلرَّبَّ.","ạảkẖ̊ṭubuki linaf̊sī biٱl̊ạảmānaẗi fataʿ̊rifīna ٱlrãbã."],[2,21,"وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ أَنِّي أَسْتَجِيبُ، يَقُولُ ٱلرَّبُّ، أَسْتَجِيبُ ٱلسَّمَاوَاتِ وَهِيَ تَسْتَجِيبُ ٱلْأَرْضَ،","wayakūnu fī dẖalika ٱl̊yaẘmi ạảnĩy ạảs̊tajību, yaqūlu ٱlrãbũ, ạảs̊tajību ٱlsãmāwāti wahīa tas̊tajību ٱl̊ạảr̊ḍa,"],[2,22,"وَٱلْأَرْضُ تَسْتَجِيبُ ٱلْقَمْحَ وَٱلْمِسْطَارَ وَٱلزَّيْتَ، وَهِيَ تَسْتَجِيبُ يَزْرَعِيلَ.","waٱl̊ạảr̊ḍu tas̊tajību ٱl̊qam̊ḥa waٱl̊mis̊ṭāra waٱlzãẙta, wahīa tas̊tajību yaz̊raʿīla."],[2,23,"وَأَزْرَعُهَا لِنَفْسِي فِي ٱلْأَرْضِ، وَأَرْحَمُ لُورُحَامَةَ، وَأَقُولُ لِلُوعَمِّي: أَنْتَ شَعْبِي، وَهُوَ يَقُولُ: أَنْتَ إِلَهِي».","wāảz̊raʿuhā linaf̊sī fī ٱl̊ạảr̊ḍi, wāảr̊ḥamu lūruḥāmaẗa, wāảqūlu lilūʿamĩy: ạản̊ta sẖaʿ̊bī, wahūa yaqūlu: ạản̊ta ại̹lahī»."],[3,1,"وَقَالَ ٱلرَّبُّ لِي: «ٱذْهَبْ أَيْضًا أَحْبِبِ ٱمْرَأَةً حَبِيبَةَ صَاحِبٍ وَزَانِيَةً، كَمَحَبَّةِ ٱلرَّبِّ لِبَنِي إِسْرَائِيلَ وَهُمْ مُلْتَفِتُونَ إِلَى آلِهَةٍ أُخْرَى وَمُحِبُّونَ لِأَقْرَاصِ ٱلزَّبِيبِ».","waqāla ٱlrãbũ lī: «ٱdẖ̊hab̊ ạảẙḍaⁿạ ạảḥ̊bibi ٱm̊rāảẗaⁿ ḥabībaẗa ṣāḥibiⁿ wazānīaẗaⁿ, kamaḥabãẗi ٱlrãbĩ libanī ại̹s̊rāyỉyla wahum̊ mul̊tafitūna ại̹lay̱ ậlihaẗiⁿ ạủkẖ̊ray̱ wamuḥibũwna liạảq̊rāṣi ٱlzãbībi»."],[3,2,"فَٱشْتَرَيْتُهَا لِنَفْسِي بِخَمْسَةَ عَشَرَ شَاقِلَ فِضَّةٍ وَبِحُومَرَ وَلَثَكِ شَعِيرٍ.","faٱsẖ̊taraẙtuhā linaf̊sī bikẖam̊saẗa ʿasẖara sẖāqila fiḍãẗiⁿ wabiḥūmara walatẖaki sẖaʿīriⁿ."],[3,3,"وَقُلْتُ لَهَا: «تَقْعُدِينَ أَيَّامًا كَثِيرَةً لَا تَزْنِي وَلَا تَكُونِي لِرَجُلٍ، وَأَنَا كَذَلِكَ لَكِ».","waqul̊tu lahā: «taq̊ʿudīna ạảyãạmaⁿạ katẖīraẗaⁿ lā taz̊nī walā takūnī lirajuliⁿ, wāảnā kadẖalika laki»."],[3,4,"لِأَنَّ بَنِي إِسْرَائِيلَ سَيَقْعُدُونَ أَيَّامًا كَثِيرَةً بِلَا مَلِكٍ، وَبِلَا رَئِيسٍ، وَبِلَا ذَبِيحَةٍ، وَبِلَا تِمْثَالٍ، وَبِلَا أَفُودٍ وَتَرَافِيمَ.","liạảnã banī ại̹s̊rāyỉyla sayaq̊ʿudūna ạảyãạmaⁿạ katẖīraẗaⁿ bilā malikiⁿ, wabilā rayỉysiⁿ, wabilā dẖabīḥaẗiⁿ, wabilā tim̊tẖāliⁿ, wabilā ạảfūdiⁿ watarāfīma."],[3,5,"بَعْدَ ذَلِكَ يَعُودُ بَنُو إِسْرَائِيلَ وَيَطْلُبُونَ ٱلرَّبَّ إِلَهَهُمْ وَدَاوُدَ مَلِكَهُمْ، وَيَفْزَعُونَ إِلَى ٱلرَّبِّ وَإِلَى جُودِهِ فِي آخِرِ ٱلْأَيَّامِ.","baʿ̊da dẖalika yaʿūdu banū ại̹s̊rāyỉyla wayaṭ̊lubūna ٱlrãbã ại̹lahahum̊ wadāwuda malikahum̊, wayaf̊zaʿūna ại̹lay̱ ٱlrãbĩ wāi̹lay̱ jūdihi fī ậkẖiri ٱl̊ạảyãạmi."],[4,1,"اِسْمَعُوا قَوْلَ ٱلرَّبِّ يَا بَنِي إِسْرَائِيلَ: «إِنَّ لِلرَّبِّ مُحَاكَمَةً مَعَ سُكَّانِ ٱلْأَرْضِ، لِأَنَّهُ لَا أَمَانَةَ وَلَا إِحْسَانَ وَلَا مَعْرِفَةَ ٱللهِ فِي ٱلْأَرْضِ.","ạis̊maʿūạ qaẘla ٱlrãbĩ yā banī ại̹s̊rāyỉyla: «ại̹nã lilrãbĩ muḥākamaẗaⁿ maʿa sukãạni ٱl̊ạảr̊ḍi, liạảnãhu lā ạảmānaẗa walā ại̹ḥ̊sāna walā maʿ̊rifaẗa ٱllhi fī ٱl̊ạảr̊ḍi."],[4,2,"لَعْنٌ وَكَذِبٌ وَقَتْلٌ وَسِرْقَةٌ وَفِسْقٌ. يَعْتَنِفُونَ، وَدِمَاءٌ تَلْحَقُ دِمَاءً.","laʿ̊nuⁿ wakadẖibuⁿ waqat̊luⁿ wasir̊qaẗuⁿ wafis̊quⁿ. yaʿ̊tanifūna, wadimāʾuⁿ tal̊ḥaqu dimāʾaⁿ."],[4,3,"لِذَلِكَ تَنُوحُ ٱلْأَرْضُ وَيَذْبُلُ كُلُّ مَنْ يَسْكُنُ فِيهَا مَعَ حَيَوَانِ ٱلْبَرِّيَّةِ وَطُيُورِ ٱلسَّمَاءِ، وَأَسْمَاكِ ٱلْبَحْرِ أَيْضًا تَنْتَزِعُ.","lidẖalika tanūḥu ٱl̊ạảr̊ḍu wayadẖ̊bulu kulũ man̊ yas̊kunu fīhā maʿa ḥayawāni ٱl̊barĩyãẗi waṭuyūri ٱlsãmāʾi, wāảs̊māki ٱl̊baḥ̊ri ạảẙḍaⁿạ tan̊taziʿu."],[4,4,"«وَلَكِنْ لَا يُحَاكِمْ أَحَدٌ وَلَا يُعَاتِبْ أَحَدٌ. وَشَعْبُكَ كَمَنْ يُخَاصِمُ كَاهِنًا.","«walakin̊ lā yuḥākim̊ ạảḥaduⁿ walā yuʿātib̊ ạảḥaduⁿ. wasẖaʿ̊buka kaman̊ yukẖāṣimu kāhinaⁿạ."],[4,5,"فَتَتَعَثَّرُ فِي ٱلنَّهَارِ وَيَتَعَثَّرُ أَيْضًا ٱلنَّبِيُّ مَعَكَ فِي ٱللَّيْلِ، وَأَنَا أُخْرِبُ أُمَّكَ.","fatataʿatẖãru fī ٱlnãhāri wayataʿatẖãru ạảẙḍaⁿạ ٱlnãbīũ maʿaka fī ٱllãẙli, wāảnā ạủkẖ̊ribu ạủmãka."],[4,6,"قَدْ هَلَكَ شَعْبِي مِنْ عَدَمِ ٱلْمَعْرِفَةِ. لِأَنَّكَ أَنْتَ رَفَضْتَ ٱلْمَعْرِفَةَ أَرْفُضُكَ أَنَا حَتَّى لَا تَكْهَنَ لِي. وَلِأَنَّكَ نَسِيتَ شَرِيعَةَ إِلَهِكَ أَنْسَى أَنَا أَيْضًا بَنِيكَ.","qad̊ halaka sẖaʿ̊bī min̊ ʿadami ٱl̊maʿ̊rifaẗi. liạảnãka ạản̊ta rafaḍ̊ta ٱl̊maʿ̊rifaẗa ạảr̊fuḍuka ạảnā ḥatãy̱ lā tak̊hana lī. waliạảnãka nasīta sẖarīʿaẗa ại̹lahika ạản̊say̱ ạảnā ạảẙḍaⁿạ banīka."],[4,7,"عَلَى حَسْبَمَا كَثُرُوا، هَكَذَا أَخْطَأُوا إِلَيَّ، فَأُبْدِلُ كَرَامَتَهُمْ بِهَوَانٍ.","ʿalay̱ ḥas̊bamā katẖurūạ, hakadẖā ạảkẖ̊ṭāủwạ ại̹layã, fāủb̊dilu karāmatahum̊ bihawāniⁿ."],[4,8,"يَأْكُلُونَ خَطِيَّةَ شَعْبِي وَإِلَى إِثْمِهِمْ يَحْمِلُونَ نُفُوسَهُمْ.","yā̊̉kulūna kẖaṭīãẗa sẖaʿ̊bī wāi̹lay̱ ại̹tẖ̊mihim̊ yaḥ̊milūna nufūsahum̊."],[4,9,"فَيَكُونُ كَمَا ٱلشَّعْبُ هَكَذَا ٱلْكَاهِنُ. وَأُعَاقِبُهُمْ عَلَى طُرُقِهِمْ وَأَرُدُّ أَعْمَالَهُمْ عَلَيْهِمْ.","fayakūnu kamā ٱlsẖãʿ̊bu hakadẖā ٱl̊kāhinu. wāủʿāqibuhum̊ ʿalay̱ ṭuruqihim̊ wāảrudũ ạảʿ̊mālahum̊ ʿalaẙhim̊."],[4,10,"فَيَأْكُلُونَ وَلَا يَشْبَعُونَ، وَيَزْنُونَ وَلَا يَكْثُرُونَ، لِأَنَّهُمْ قَدْ تَرَكُوا عِبَادَةَ ٱلرَّبِّ.","fayā̊̉kulūna walā yasẖ̊baʿūna, wayaz̊nūna walā yak̊tẖurūna, liạảnãhum̊ qad̊ tarakūạ ʿibādaẗa ٱlrãbĩ."],[4,11,"«اَلزِّنَى وَٱلْخَمْرُ وَٱلسُّلَافَةُ تَخْلِبُ ٱلْقَلْبَ.","«ạalzĩnay̱ waٱl̊kẖam̊ru waٱlsũlāfaẗu takẖ̊libu ٱl̊qal̊ba."],[4,12,"شَعْبِي يَسْأَلُ خَشَبَهُ، وَعَصَاهُ تُخْبِرُهُ، لِأَنَّ رُوحَ ٱلزِّنَى قَدْ أَضَلَّهُمْ فَزَنَوْا مِنْ تَحْتِ إِلَهِهِمْ.","sẖaʿ̊bī yas̊ạảlu kẖasẖabahu, waʿaṣāhu tukẖ̊biruhu, liạảnã rūḥa ٱlzĩnay̱ qad̊ ạảḍalãhum̊ fazanaẘạ min̊ taḥ̊ti ại̹lahihim̊."],[4,13,"يَذْبَحُونَ عَلَى رُؤُوسِ ٱلْجِبَالِ، وَيُبَخِّرُونَ عَلَى ٱلتِّلَالِ تَحْتَ ٱلْبَلُّوطِ وَٱللُّبْنَى وَٱلْبُطْمِ لِأَنَّ ظِلَّهَا حَسَنٌ! لِذَلِكَ تَزْنِي بَنَاتُكُمْ وَتَفْسِقُ كَنَّاتُكُمْ.","yadẖ̊baḥūna ʿalay̱ rūủwsi ٱl̊jibāli, wayubakẖĩrūna ʿalay̱ ٱltĩlāli taḥ̊ta ٱl̊balũwṭi waٱllũb̊nay̱ waٱl̊buṭ̊mi liạảnã ẓilãhā ḥasanuⁿ! lidẖalika taz̊nī banātukum̊ wataf̊siqu kanãạtukum̊."],[4,14,"لَا أُعَاقِبُ بَنَاتِكُمْ لِأَنَّهُنَّ يَزْنِينَ، وَلَا كَنَّاتِكُمْ لِأَنَّهُنَّ يَفْسِقْنَ. لِأَنَّهُمْ يَعْتَزِلُونَ مَعَ ٱلزَّانِيَاتِ وَيَذْبَحُونَ مَعَ ٱلنَّاذِرَاتِ ٱلزِّنَى. وَشَعْبٌ لَا يَعْقِلُ يُصْرَعُ.","lā ạủʿāqibu banātikum̊ liạảnãhunã yaz̊nīna, walā kanãạtikum̊ liạảnãhunã yaf̊siq̊na. liạảnãhum̊ yaʿ̊tazilūna maʿa ٱlzãạnīāti wayadẖ̊baḥūna maʿa ٱlnãạdẖirāti ٱlzĩnay̱. wasẖaʿ̊buⁿ lā yaʿ̊qilu yuṣ̊raʿu."],[4,15,"«إِنْ كُنْتَ أَنْتَ زَانِيًا يَا إِسْرَائِيلُ فَلَا يَأْثَمُ يَهُوذَا. وَلَا تَأْتُوا إِلَى ٱلْجِلْجَالِ وَلَا تَصْعَدُوا إِلَى بَيْتِ آوَنَ وَلَا تَحْلِفُوا: حَيٌّ هُوَ ٱلرَّبُّ.","«ại̹n̊ kun̊ta ạản̊ta zānīaⁿạ yā ại̹s̊rāyỉylu falā yā̊̉tẖamu yahūdẖā. walā tā̊̉tūạ ại̹lay̱ ٱl̊jil̊jāli walā taṣ̊ʿadūạ ại̹lay̱ baẙti ậwana walā taḥ̊lifūạ: ḥayuⁿ̃ hūa ٱlrãbũ."],[4,16,"إِنَّهُ قَدْ جَمَحَ إِسْرَائِيلُ كَبَقَرَةٍ جَامِحَةٍ. اَلْآنَ يَرْعَاهُمُ ٱلرَّبُّ كَخَرُوفٍ فِي مَكَانٍ وَاسِعٍ.","ại̹nãhu qad̊ jamaḥa ại̹s̊rāyỉylu kabaqaraẗiⁿ jāmiḥaẗiⁿ. ạal̊ậna yar̊ʿāhumu ٱlrãbũ kakẖarūfiⁿ fī makāniⁿ wāsiʿiⁿ."],[4,17,"أَفْرَايِمُ مُوثَقٌ بِٱلْأَصْنَامِ. ٱتْرُكُوهُ.","ạảf̊rāyimu mūtẖaquⁿ biٱl̊ạảṣ̊nāmi. ٱt̊rukūhu."],[4,18,"مَتَى ٱنْتَهَتْ مُنَادَمَتُهُمْ زَنَوْا زِنًى. أَحَبَّ مَجَانُّهَا، أَحَبُّوا ٱلْهَوَانَ.","matay̱ ٱn̊tahat̊ munādamatuhum̊ zanaẘạ zinaⁿy̱. ạảḥabã majānũhā, ạảḥabũwạ ٱl̊hawāna."],[4,19,"قَدْ صَرَّتْهَا ٱلرِّيحُ فِي أَجْنِحَتِهَا، وَخَجِلُوا مِنْ ذَبَائِحِهِمْ.","qad̊ ṣarãt̊hā ٱlrĩyḥu fī ạảj̊niḥatihā, wakẖajilūạ min̊ dẖabāyỉḥihim̊."],[5,1,"«اِسْمَعُوا هَذَا أَيُّهَا ٱلْكَهَنَةُ! وَٱنْصِتُوا يَا بَيْتَ إِسْرَائِيلَ! وَأَصْغُوا يَا بَيْتَ ٱلْمَلِكِ! لِأَنَّ عَلَيْكُمُ ٱلْقَضَاءَ، إِذْ صِرْتُمْ فَخًّا فِي مِصْفَاةَ، وَشَبَكَةً مَبْسُوطَةً عَلَى تَابُورَ.","«ạis̊maʿūạ hadẖā ạảyũhā ٱl̊kahanaẗu! waٱn̊ṣitūạ yā baẙta ại̹s̊rāyỉyla! wāảṣ̊gẖūạ yā baẙta ٱl̊maliki! liạảnã ʿalaẙkumu ٱl̊qaḍāʾa, ại̹dẖ̊ ṣir̊tum̊ fakẖaⁿ̃ạ fī miṣ̊fāẗa, wasẖabakaẗaⁿ mab̊sūṭaẗaⁿ ʿalay̱ tābūra."],[5,2,"وَقَدْ تَوَغَّلُوا فِي ذَبَائِحِ ٱلزَّيَغَانِ، فَأَنَا تَأْدِيبٌ لِجَمِيعِهِمْ.","waqad̊ tawagẖãlūạ fī dẖabāyỉḥi ٱlzãyagẖāni, fāảnā tā̊̉dībuⁿ lijamīʿihim̊."],[5,3,"أَنَا أَعْرِفُ أَفْرَايِمَ. وَإِسْرَائِيلُ لَيْسَ مَخْفِيًّا عَنِّي. إِنَّكَ ٱلْآنَ زَنَيْتَ يَا أَفْرَايِمُ. قَدْ تَنَجَّسَ إِسْرَائِيلُ.","ạảnā ạảʿ̊rifu ạảf̊rāyima. wāi̹s̊rāyỉylu laẙsa makẖ̊fīaⁿ̃ạ ʿanĩy. ại̹nãka ٱl̊ậna zanaẙta yā ạảf̊rāyimu. qad̊ tanajãsa ại̹s̊rāyỉylu."],[5,4,"أَفْعَالُهُمْ لَا تَدَعُهُمْ يَرْجِعُونَ إِلَى إِلَهِهِمْ، لِأَنَّ رُوحَ ٱلزِّنَى فِي بَاطِنِهِمْ، وَهُمْ لَا يَعْرِفُونَ ٱلرَّبَّ.","ạảf̊ʿāluhum̊ lā tadaʿuhum̊ yar̊jiʿūna ại̹lay̱ ại̹lahihim̊, liạảnã rūḥa ٱlzĩnay̱ fī bāṭinihim̊, wahum̊ lā yaʿ̊rifūna ٱlrãbã."],[5,5,"وَقَدْ أُذِلَّتْ عَظَمَةُ إِسْرَائِيلَ فِي وَجْهِهِ، فَيَتَعَثَّرُ إِسْرَائِيلُ وَأَفْرَايِمُ فِي إِثْمِهِمَا، وَيَتَعَثَّرُ يَهُوذَا أَيْضًا مَعَهُمَا.","waqad̊ ạủdẖilãt̊ ʿaẓamaẗu ại̹s̊rāyỉyla fī waj̊hihi, fayataʿatẖãru ại̹s̊rāyỉylu wāảf̊rāyimu fī ại̹tẖ̊mihimā, wayataʿatẖãru yahūdẖā ạảẙḍaⁿạ maʿahumā."],[5,6,"يَذْهَبُونَ بِغَنَمِهِمْ وَبَقَرِهِمْ لِيَطْلُبُوا ٱلرَّبَّ وَلَا يَجِدُونَهُ. قَدْ تَنَحَّى عَنْهُمْ.","yadẖ̊habūna bigẖanamihim̊ wabaqarihim̊ līaṭ̊lubūạ ٱlrãbã walā yajidūnahu. qad̊ tanaḥãy̱ ʿan̊hum̊."],[5,7,"قَدْ غَدَرُوا بِٱلرَّبِّ. لِأَنَّهُمْ وَلَدُوا أَوْلَادًا أَجْنَبِيِّينَ، اَلْآنَ يَأْكُلُهُمْ شَهْرٌ مَعَ أَنْصِبَتِهِمْ.","qad̊ gẖadarūạ biٱlrãbĩ. liạảnãhum̊ waladūạ ạảẘlādaⁿạ ạảj̊nabīĩyna, ạal̊ậna yā̊̉kuluhum̊ sẖah̊ruⁿ maʿa ạản̊ṣibatihim̊."],[5,8,"«اِضْرِبُوا بِٱلْبُوقِ فِي جِبْعَةَ، بِٱلْقَرْنِ فِي ٱلرَّامَةِ. ٱصْرُخُوا فِي بَيْتِ آوَنَ. وَرَاءَكَ يَا بَنْيَامِينُ.","«ạiḍ̊ribūạ biٱl̊būqi fī jib̊ʿaẗa, biٱl̊qar̊ni fī ٱlrãạmaẗi. ٱṣ̊rukẖūạ fī baẙti ậwana. warāʾaka yā ban̊yāmīnu."],[5,9,"يَصِيرُ أَفْرَايِمُ خَرَابًا فِي يَوْمِ ٱلتَّأْدِيبِ. فِي أَسْبَاطِ إِسْرَائِيلَ أَعْلَمْتُ ٱلْيَقِينَ.","yaṣīru ạảf̊rāyimu kẖarābaⁿạ fī yaẘmi ٱltãạ̊̉dībi. fī ạảs̊bāṭi ại̹s̊rāyỉyla ạảʿ̊lam̊tu ٱl̊yaqīna."],[5,10,"صَارَتْ رُؤَسَاءُ يَهُوذَا كَنَاقِلِي ٱلتُّخُومِ. فَأَسْكُبُ عَلَيْهِمْ سَخَطِي كَٱلْمَاءِ.","ṣārat̊ rūảsāʾu yahūdẖā kanāqilī ٱltũkẖūmi. fāảs̊kubu ʿalaẙhim̊ sakẖaṭī kaٱl̊māʾi."],[5,11,"أَفْرَايِمُ مَظْلُومٌ مَسْحُوقُ ٱلْقَضَاءِ، لِأَنَّهُ ٱرْتَضَى أَنْ يَمْضِيَ وَرَاءَ ٱلْوَصِيَّةِ.","ạảf̊rāyimu maẓ̊lūmuⁿ mas̊ḥūqu ٱl̊qaḍāʾi, liạảnãhu ٱr̊taḍay̱ ạản̊ yam̊ḍīa warāʾa ٱl̊waṣīãẗi."],[5,12,"فَأَنَا لِأَفْرَايِمَ كَٱلْعُثِّ، وَلِبَيْتِ يَهُوذَا كَٱلسُّوسِ.","fāảnā liạảf̊rāyima kaٱl̊ʿutẖĩ, walibaẙti yahūdẖā kaٱlsũwsi."],[5,13,"«وَرَأَى أَفْرَايِمُ مَرَضَهُ وَيَهُوذَا جُرْحَهُ، فَمَضَى أَفْرَايِمُ إِلَى أَشُّورَ، وَأَرْسَلَ إِلَى مَلِكٍ عَدُوٍّ. وَلَكِنَّهُ لَا يَسْتَطِيعُ أَنْ يَشْفِيَكُمْ وَلَا أَنْ يُزِيلَ مِنْكُمُ ٱلْجُرْحَ.","«warāảy̱ ạảf̊rāyimu maraḍahu wayahūdẖā jur̊ḥahu, famaḍay̱ ạảf̊rāyimu ại̹lay̱ ạảsẖũwra, wāảr̊sala ại̹lay̱ malikiⁿ ʿadūiⁿ̃. walakinãhu lā yas̊taṭīʿu ạản̊ yasẖ̊fīakum̊ walā ạản̊ yuzīla min̊kumu ٱl̊jur̊ḥa."],[5,14,"لِأَنِّي لِأَفْرَايِمَ كَٱلْأَسَدِ، وَلِبَيْتِ يَهُوذَا كَشِبْلِ ٱلْأَسَدِ. فَإِنِّي أَنَا أَفْتَرِسُ وَأَمْضِي وَآخُذُ وَلَا مُنْقِذٌ.","liạảnĩy liạảf̊rāyima kaٱl̊ạảsadi, walibaẙti yahūdẖā kasẖib̊li ٱl̊ạảsadi. fāi̹nĩy ạảnā ạảf̊tarisu wāảm̊ḍī wā̂kẖudẖu walā mun̊qidẖuⁿ."],[5,15,"أَذْهَبُ وَأَرْجِعُ إِلَى مَكَانِي حَتَّى يُجَازَوْا وَيَطْلُبُوا وَجْهِي. فِي ضِيقِهِمْ يُبَكِّرُونَ إِلَيَّ».","ạảdẖ̊habu wāảr̊jiʿu ại̹lay̱ makānī ḥatãy̱ yujāzaẘạ wayaṭ̊lubūạ waj̊hī. fī ḍīqihim̊ yubakĩrūna ại̹layã»."],[6,1,"هَلُمَّ نَرْجِعُ إِلَى ٱلرَّبِّ لِأَنَّهُ هُوَ ٱفْتَرَسَ فَيَشْفِينَا، ضَرَبَ فَيَجْبِرُنَا.","halumã nar̊jiʿu ại̹lay̱ ٱlrãbĩ liạảnãhu hūa ٱf̊tarasa fayasẖ̊fīnā, ḍaraba fayaj̊birunā."],[6,2,"يُحْيِينَا بَعْدَ يَوْمَيْنِ. فِي ٱلْيَوْمِ ٱلثَّالِثِ يُقِيمُنَا فَنَحْيَا أَمَامَهُ.","yuḥ̊yīnā baʿ̊da yaẘmaẙni. fī ٱl̊yaẘmi ٱltẖãạlitẖi yuqīmunā fanaḥ̊yā ạảmāmahu."],[6,3,"لِنَعْرِفْ فَلْنَتَتَبَّعْ لِنَعْرِفَ ٱلرَّبَّ. خُرُوجُهُ يَقِينٌ كَٱلْفَجْرِ. يَأْتِي إِلَيْنَا كَٱلْمَطَرِ. كَمَطَرٍ مُتَأَخِّرٍ يَسْقِي ٱلْأَرْضَ.","linaʿ̊rif̊ fal̊natatabãʿ̊ linaʿ̊rifa ٱlrãbã. kẖurūjuhu yaqīnuⁿ kaٱl̊faj̊ri. yā̊̉tī ại̹laẙnā kaٱl̊maṭari. kamaṭariⁿ mutāảkẖĩriⁿ yas̊qī ٱl̊ạảr̊ḍa."],[6,4,"«مَاذَا أَصْنَعُ بِكَ يَا أَفْرَايِمُ؟ مَاذَا أَصْنَعُ بِكَ يَا يَهُوذَا؟ فَإِنَّ إِحْسَانَكُمْ كَسَحَابِ ٱلصُّبْحِ، وَكَالنَّدَى ٱلْمَاضِي بَاكِرًا.","«mādẖā ạảṣ̊naʿu bika yā ạảf̊rāyimu? mādẖā ạảṣ̊naʿu bika yā yahūdẖā? fāi̹nã ại̹ḥ̊sānakum̊ kasaḥābi ٱlṣũb̊ḥi, wakālnãday̱ ٱl̊māḍī bākiraⁿạ."],[6,5,"لِذَلِكَ أَقْرِضُهُمْ بِٱلْأَنْبِيَاءِ. أَقْتُلُهُمْ بِأَقْوَالِ فَمِي. وَٱلْقَضَاءُ عَلَيْكَ كَنُورٍ قَدْ خَرَجَ.","lidẖalika ạảq̊riḍuhum̊ biٱl̊ạản̊bīāʾi. ạảq̊tuluhum̊ biạảq̊wāli famī. waٱl̊qaḍāʾu ʿalaẙka kanūriⁿ qad̊ kẖaraja."],[6,6,"«إِنِّي أُرِيدُ رَحْمَةً لَا ذَبِيحَةً، وَمَعْرِفَةَ ٱللهِ أَكْثَرَ مِنْ مُحْرَقَاتٍ.","«ại̹nĩy ạủrīdu raḥ̊maẗaⁿ lā dẖabīḥaẗaⁿ, wamaʿ̊rifaẗa ٱllhi ạảk̊tẖara min̊ muḥ̊raqātiⁿ."],[6,7,"وَلَكِنَّهُمْ كَآدَمَ تَعَدَّوْا ٱلْعَهْدَ. هُنَاكَ غَدَرُوا بِي.","walakinãhum̊ kā̂dama taʿadãẘạ ٱl̊ʿah̊da. hunāka gẖadarūạ bī."],[6,8,"جَلْعَادُ قَرْيَةُ فَاعِلِي ٱلْإِثْمِ مَدُوسَةٌ بِٱلدَّمِ.","jal̊ʿādu qar̊yaẗu fāʿilī ٱl̊ại̹tẖ̊mi madūsaẗuⁿ biٱldãmi."],[6,9,"وَكَمَا يَكْمُنُ لُصُوصٌ لِإِنْسَانٍ، كَذَلِكَ زُمْرَةُ ٱلْكَهَنَةِ فِي ٱلطَّرِيقِ يَقْتُلُونَ نَحْوَ شَكِيمَ. إِنَّهُمْ قَدْ صَنَعُوا فَاحِشَةً.","wakamā yak̊munu luṣūṣuⁿ liại̹n̊sāniⁿ, kadẖalika zum̊raẗu ٱl̊kahanaẗi fī ٱlṭãrīqi yaq̊tulūna naḥ̊wa sẖakīma. ại̹nãhum̊ qad̊ ṣanaʿūạ fāḥisẖaẗaⁿ."],[6,10,"في بَيْتِ إِسْرَائِيلَ رَأَيْتُ أَمْرًا فَظِيعًا. هُنَاكَ زَنَى أَفْرَايِمُ. تَنَجَّسَ إِسْرَائِيلُ.","fy baẙti ại̹s̊rāyỉyla rāảẙtu ạảm̊raⁿạ faẓīʿaⁿạ. hunāka zanay̱ ạảf̊rāyimu. tanajãsa ại̹s̊rāyỉylu."],[6,11,"وَأَنْتَ أَيْضًا يَا يَهُوذَا قَدْ أُعِدَّ لَكَ حَصَادٌ، عِنْدَمَا أَرُدُّ سَبْيَ شَعْبِي.","wāản̊ta ạảẙḍaⁿạ yā yahūdẖā qad̊ ạủʿidã laka ḥaṣāduⁿ, ʿin̊damā ạảrudũ sab̊ya sẖaʿ̊bī."],[7,1,"«حِينَمَا كُنْتُ أَشْفِي إِسْرَائِيلَ، أُعْلِنَ إِثْمُ أَفْرَايِمَ وَشُرُورُ ٱلسَّامِرَةِ، فَإِنَّهُمْ قَدْ صَنَعُوا غِشًّا. ٱلسَّارِقُ دَخَلَ وَٱلْغُزَاةُ نَهَبُوا فِي ٱلْخَارِجِ.","«ḥīnamā kun̊tu ạảsẖ̊fī ại̹s̊rāyỉyla, ạủʿ̊lina ại̹tẖ̊mu ạảf̊rāyima wasẖurūru ٱlsãạmiraẗi, fāi̹nãhum̊ qad̊ ṣanaʿūạ gẖisẖaⁿ̃ạ. ٱlsãạriqu dakẖala waٱl̊gẖuzāẗu nahabūạ fī ٱl̊kẖāriji."],[7,2,"وَلَا يَفْتَكِرُونَ فِي قُلُوبِهِمْ أَنِّي قَدْ تَذَكَّرْتُ كُلَّ شَرِّهِمْ. اَلْآنَ قَدْ أَحَاطَتْ بِهِمْ أَفْعَالُهُمْ. صَارَتْ أَمَامَ وَجْهِي.","walā yaf̊takirūna fī qulūbihim̊ ạảnĩy qad̊ tadẖakãr̊tu kulã sẖarĩhim̊. ạal̊ậna qad̊ ạảḥāṭat̊ bihim̊ ạảf̊ʿāluhum̊. ṣārat̊ ạảmāma waj̊hī."],[7,3,"«بِشَرِّهِمْ يُفَرِّحُونَ ٱلْمَلِكَ، وَبِكَذِبِهِمِ ٱلرُّؤَسَاءَ.","«bisẖarĩhim̊ yufarĩḥūna ٱl̊malika, wabikadẖibihimi ٱlrũwảsāʾa."],[7,4,"كُلُّهُمْ فَاسِقُونَ كَتَنُّورٍ مُحْمًى مِنَ ٱلْخَبَّازِ. يُبَطِّلُ ٱلْإِيقَادَ مِنْ وَقْتِمَا يَعْجِنُ ٱلْعَجِينَ إِلَى أَنْ يَخْتَمِرَ.","kulũhum̊ fāsiqūna katanũwriⁿ muḥ̊maⁿy̱ mina ٱl̊kẖabãạzi. yubaṭĩlu ٱl̊ại̹yqāda min̊ waq̊timā yaʿ̊jinu ٱl̊ʿajīna ại̹lay̱ ạản̊ yakẖ̊tamira."],[7,5,"يَوْمُ مَلِكِنَا يَمْرَضُ ٱلرُّؤَسَاءُ مِنْ سَوْرَةِ ٱلْخَمْرِ. يَبْسُطُ يَدَهُ مَعَ ٱلْمُسْتَهْزِئِينَ.","yaẘmu malikinā yam̊raḍu ٱlrũwảsāʾu min̊ saẘraẗi ٱl̊kẖam̊ri. yab̊suṭu yadahu maʿa ٱl̊mus̊tah̊zīỉyna."],[7,6,"لِأَنَّهُمْ يُقَرِّبُونَ قُلُوبَهُمْ فِي مَكِيدَتِهِمْ كَٱلتَّنُّورِ. كُلَّ ٱللَّيْلِ يَنَامُ خَبَّازُهُمْ، وَفِي ٱلصَّبَاحِ يَكُونُ مُحْمًى كَنَارٍ مُلْتَهِبَةٍ.","liạảnãhum̊ yuqarĩbūna qulūbahum̊ fī makīdatihim̊ kaٱltãnũwri. kulã ٱllãẙli yanāmu kẖabãạzuhum̊, wafī ٱlṣãbāḥi yakūnu muḥ̊maⁿy̱ kanāriⁿ mul̊tahibaẗiⁿ."],[7,7,"كُلُّهُمْ حَامُونَ كَٱلتَّنُّورِ وَأَكَلُوا قُضَاتَهُمْ. جَمِيعُ مُلُوكِهِمْ سَقَطُوا. لَيْسَ بَيْنَهُمْ مَنْ يَدْعُو إِلَيَّ.","kulũhum̊ ḥāmūna kaٱltãnũwri wāảkalūạ quḍātahum̊. jamīʿu mulūkihim̊ saqaṭūạ. laẙsa baẙnahum̊ man̊ yad̊ʿū ại̹layã."],[7,8,"«أَفْرَايِمُ يَخْتَلِطُ بِٱلشُّعُوبِ. أَفْرَايِمُ صَارَ خُبْزَ مَلَّةٍ لَمْ يُقْلَبْ.","«ạảf̊rāyimu yakẖ̊taliṭu biٱlsẖũʿūbi. ạảf̊rāyimu ṣāra kẖub̊za malãẗiⁿ lam̊ yuq̊lab̊."],[7,9,"أَكَلَ ٱلْغُرَبَاءُ ثَرْوَتَهُ وَهُوَ لَا يَعْرِفُ، وَقَدْ رُشَّ عَلَيْهِ ٱلشَّيْبُ وَهُوَ لَا يَعْرِفُ.","ạảkala ٱl̊gẖurabāʾu tẖar̊watahu wahūa lā yaʿ̊rifu, waqad̊ rusẖã ʿalaẙhi ٱlsẖãẙbu wahūa lā yaʿ̊rifu."],[7,10,"وَقَدْ أُذِلَّتْ عَظَمَةُ إِسْرَائِيلَ فِي وَجْهِهِ، وَهُمْ لَا يَرْجِعُونَ إِلَى ٱلرَّبِّ إِلَهِهِمْ وَلَا يَطْلُبُونَهُ مَعَ كُلِّ هَذَا.","waqad̊ ạủdẖilãt̊ ʿaẓamaẗu ại̹s̊rāyỉyla fī waj̊hihi, wahum̊ lā yar̊jiʿūna ại̹lay̱ ٱlrãbĩ ại̹lahihim̊ walā yaṭ̊lubūnahu maʿa kulĩ hadẖā."],[7,11,"وَصَارَ أَفْرَايِمُ كَحَمَامَةٍ رَعْنَاءَ بِلَا قَلْبٍ. يَدْعُونَ مِصْرَ. يَمْضُونَ إِلَى أَشُّورَ.","waṣāra ạảf̊rāyimu kaḥamāmaẗiⁿ raʿ̊nāʾa bilā qal̊biⁿ. yad̊ʿūna miṣ̊ra. yam̊ḍūna ại̹lay̱ ạảsẖũwra."],[7,12,"عِنْدَمَا يَمْضُونَ أَبْسُطُ عَلَيْهِمْ شَبَكَتِي. أُلْقِيهِمْ كَطُيُورِ ٱلسَّمَاءِ. أُؤَدِّبُهُمْ بِحَسَبِ خَبَرِ جَمَاعَتِهِمْ.","ʿin̊damā yam̊ḍūna ạảb̊suṭu ʿalaẙhim̊ sẖabakatī. ạủl̊qīhim̊ kaṭuyūri ٱlsãmāʾi. ạủwảdĩbuhum̊ biḥasabi kẖabari jamāʿatihim̊."],[7,13,"«وَيْلٌ لَهُمْ لِأَنَّهُمْ هَرَبُوا عَنِّي. تَبًّا لَهُمْ لِأَنَّهُمْ أَذْنَبُوا إِلَيَّ. أَنَا أَفْدِيهِمْ وَهُمْ تَكَلَّمُوا عَلَيَّ بِكَذِبٍ.","«waẙluⁿ lahum̊ liạảnãhum̊ harabūạ ʿanĩy. tabaⁿ̃ạ lahum̊ liạảnãhum̊ ạảdẖ̊nabūạ ại̹layã. ạảnā ạảf̊dīhim̊ wahum̊ takalãmūạ ʿalayã bikadẖibiⁿ."],[7,14,"وَلَا يَصْرُخُونَ إِلَيَّ بِقُلُوبِهِمْ حِينَمَا يُوَلْوِلُونَ عَلَى مَضَاجِعِهِمْ. يَتَجَمَّعُونَ لِأَجْلِ ٱلْقَمْحِ وَٱلْخَمْرِ، وَيَرْتَدُّونَ عَنِّي.","walā yaṣ̊rukẖūna ại̹layã biqulūbihim̊ ḥīnamā yūal̊wilūna ʿalay̱ maḍājiʿihim̊. yatajamãʿūna liạảj̊li ٱl̊qam̊ḥi waٱl̊kẖam̊ri, wayar̊tadũwna ʿanĩy."],[7,15,"وَأَنَا أَنْذَرْتُهُمْ وَشَدَّدْتُ أَذْرُعَهُمْ، وَهُمْ يُفَكِّرُونَ عَلَيَّ بِٱلشَّرِّ.","wāảnā ạản̊dẖar̊tuhum̊ wasẖadãd̊tu ạảdẖ̊ruʿahum̊, wahum̊ yufakĩrūna ʿalayã biٱlsẖãrĩ."],[7,16,"يَرْجِعُونَ لَيْسَ إِلَى ٱلْعَلِيِّ. قَدْ صَارُوا كَقَوْسٍ مُخْطِئَةٍ. يَسْقُطُ رُؤَسَاؤُهُمْ بِٱلسَّيْفِ مِنْ أَجْلِ سَخَطِ أَلْسِنَتِهِمْ. هَذَا هُزْؤُهُمْ فِي أَرْضِ مِصْرَ.","yar̊jiʿūna laẙsa ại̹lay̱ ٱl̊ʿalīĩ. qad̊ ṣārūạ kaqaẘsiⁿ mukẖ̊ṭīảẗiⁿ. yas̊quṭu rūảsāwủhum̊ biٱlsãẙfi min̊ ạảj̊li sakẖaṭi ạảl̊sinatihim̊. hadẖā huz̊wủhum̊ fī ạảr̊ḍi miṣ̊ra."],[8,1,"«إِلَى فَمِكَ بِٱلْبُوقِ! كَٱلنَّسْرِ عَلَى بَيْتِ ٱلرَّبِّ. لِأَنَّهُمْ قَدْ تَجَاوَزُوا عَهْدِي وَتَعَدَّوْا عَلَى شَرِيعَتِي.","«ại̹lay̱ famika biٱl̊būqi! kaٱlnãs̊ri ʿalay̱ baẙti ٱlrãbĩ. liạảnãhum̊ qad̊ tajāwazūạ ʿah̊dī wataʿadãẘạ ʿalay̱ sẖarīʿatī."],[8,2,"إِلَيَّ يَصْرُخُونَ: يَا إِلَهِي، نَعْرِفُكَ نَحْنُ إِسْرَائِيلَ.","ại̹layã yaṣ̊rukẖūna: yā ại̹lahī, naʿ̊rifuka naḥ̊nu ại̹s̊rāyỉyla."],[8,3,"«قَدْ كَرِهَ إِسْرَائِيلُ ٱلصَّلَاحَ فَيَتْبَعُهُ ٱلْعَدُوُّ.","«qad̊ kariha ại̹s̊rāyỉylu ٱlṣãlāḥa fayat̊baʿuhu ٱl̊ʿadūũ."],[8,4,"هُمْ أَقَامُوا مُلُوكًا وَلَيْسَ مِنِّي. أَقَامُوا رُؤَسَاءَ وَأَنَا لَمْ أَعْرِفْ. صَنَعُوا لِأَنْفُسِهِمْ مِنْ فِضَّتِهِمْ وَذَهَبِهِمْ أَصْنَامًا لِكَيْ يَنْقَرِضُوا.","hum̊ ạảqāmūạ mulūkaⁿạ walaẙsa minĩy. ạảqāmūạ rūảsāʾa wāảnā lam̊ ạảʿ̊rif̊. ṣanaʿūạ liạản̊fusihim̊ min̊ fiḍãtihim̊ wadẖahabihim̊ ạảṣ̊nāmaⁿạ likaẙ yan̊qariḍūạ."],[8,5,"قَدْ زَنِخَ عِجْلُكِ يَا سَامِرَةُ. حَمِيَ غَضَبِي عَلَيْهِمْ. إِلَى مَتَى لَا يَسْتَطِيعُونَ ٱلنَّقَاوَةَ!","qad̊ zanikẖa ʿij̊luki yā sāmiraẗu. ḥamīa gẖaḍabī ʿalaẙhim̊. ại̹lay̱ matay̱ lā yas̊taṭīʿūna ٱlnãqāwaẗa!"],[8,6,"إِنَّهُ هُوَ أَيْضًا مِنْ إِسْرَائِيلَ. صَنَعَهُ ٱلصَّانِعُ وَلَيْسَ هُوَ إِلَهًا. إِنَّ عِجْلَ ٱلسَّامِرَةِ يَصِيرُ كِسَرًا.","ại̹nãhu hūa ạảẙḍaⁿạ min̊ ại̹s̊rāyỉyla. ṣanaʿahu ٱlṣãạniʿu walaẙsa hūa ại̹lahaⁿạ. ại̹nã ʿij̊la ٱlsãạmiraẗi yaṣīru kisaraⁿạ."],[8,7,"«إِنَّهُمْ يَزْرَعُونَ ٱلرِّيحَ وَيَحْصُدُونَ ٱلزَّوْبَعَةَ. زَرْعٌ لَيْسَ لَهُ غَلَّةٌ لَا يَصْنَعُ دَقِيقًا. وَإِنْ صَنَعَ، فَٱلْغُرَبَاءُ تَبْتَلِعُهُ.","«ại̹nãhum̊ yaz̊raʿūna ٱlrĩyḥa wayaḥ̊ṣudūna ٱlzãẘbaʿaẗa. zar̊ʿuⁿ laẙsa lahu gẖalãẗuⁿ lā yaṣ̊naʿu daqīqaⁿạ. wāi̹n̊ ṣanaʿa, faٱl̊gẖurabāʾu tab̊taliʿuhu."],[8,8,"قَدِ ٱبْتُلِعَ إِسْرَائِيلُ. ٱلْآنَ صَارُوا بَيْنَ ٱلْأُمَمِ كَإِنَاءٍ لَا مَسَرَّةَ فِيهِ.","qadi ٱb̊tuliʿa ại̹s̊rāyỉylu. ٱl̊ậna ṣārūạ baẙna ٱl̊ạủmami kāi̹nāʾiⁿ lā masarãẗa fīhi."],[8,9,"لِأَنَّهُمْ صَعِدُوا إِلَى أَشُّورَ مِثْلَ حِمَارٍ وَحْشِيٍّ مُعْتَزِلٍ بِنَفْسِهِ. ٱسْتَأْجَرَ أَفْرَايِمُ مُحِبِّينَ.","liạảnãhum̊ ṣaʿidūạ ại̹lay̱ ạảsẖũwra mitẖ̊la ḥimāriⁿ waḥ̊sẖīiⁿ̃ muʿ̊taziliⁿ binaf̊sihi. ٱs̊tā̊̉jara ạảf̊rāyimu muḥibĩyna."],[8,10,"إِنِّي وَإِنْ كَانُوا يَسْتَأْجِرُونَ بَيْنَ ٱلْأُمَمِ، ٱلْآنَ أَجْمَعُهُمْ فَيَنْفَكُّونَ قَلِيلًا مِنْ ثِقْلِ مَلِكِ ٱلرُّؤَسَاءِ.","ại̹nĩy wāi̹n̊ kānūạ yas̊tā̊̉jirūna baẙna ٱl̊ạủmami, ٱl̊ậna ạảj̊maʿuhum̊ fayan̊fakũwna qalīlaⁿạ min̊ tẖiq̊li maliki ٱlrũwảsāʾi."],[8,11,"«لِأَنَّ أَفْرَايِمَ كَثَّرَ مَذَابِحَ لِلْخَطِيَّةِ، صَارَتْ لَهُ ٱلْمَذَابِحُ لِلْخَطِيَّةِ.","«liạảnã ạảf̊rāyima katẖãra madẖābiḥa lil̊kẖaṭīãẗi, ṣārat̊ lahu ٱl̊madẖābiḥu lil̊kẖaṭīãẗi."],[8,12,"أَكْتُبُ لَهُ كَثْرَةَ شَرَائِعِي، فَهِيَ تُحْسَبُ أَجْنَبِيَّةً.","ạảk̊tubu lahu katẖ̊raẗa sẖarāyỉʿī, fahīa tuḥ̊sabu ạảj̊nabīãẗaⁿ."],[8,13,"أَمَّا ذَبَائِحُ تَقْدِمَاتِي فَيَذْبَحُونَ لَحْمًا وَيَأْكُلُونَ. ٱلرَّبُّ لَا يَرْتَضِيهَا. ٱلْآنَ يَذْكُرُ إِثْمَهُمْ وَيُعَاقِبُ خَطِيَّتَهُمْ. إِنَّهُمْ إِلَى مِصْرَ يَرْجِعُونَ.","ạảmãạ dẖabāyỉḥu taq̊dimātī fayadẖ̊baḥūna laḥ̊maⁿạ wayā̊̉kulūna. ٱlrãbũ lā yar̊taḍīhā. ٱl̊ậna yadẖ̊kuru ại̹tẖ̊mahum̊ wayuʿāqibu kẖaṭīãtahum̊. ại̹nãhum̊ ại̹lay̱ miṣ̊ra yar̊jiʿūna."],[8,14,"وَقَدْ نَسِيَ إِسْرَائِيلُ صَانِعَهُ وَبَنَى قُصُورًا، وَكَثَّرَ يَهُوذَا مُدُنًا حَصِينَةً. لَكِنِّي أُرْسِلُ عَلَى مُدُنِهِ نَارًا فَتَأْكُلُ قُصُورَهُ».","waqad̊ nasīa ại̹s̊rāyỉylu ṣāniʿahu wabanay̱ quṣūraⁿạ, wakatẖãra yahūdẖā mudunaⁿạ ḥaṣīnaẗaⁿ. lakinĩy ạủr̊silu ʿalay̱ mudunihi nāraⁿạ fatā̊̉kulu quṣūrahu»."],[9,1,"لَا تَفْرَحْ يَا إِسْرَائِيلُ طَرَبًا كَٱلشُّعُوبِ، لِأَنَّكَ قَدْ زَنَيْتَ عَنْ إِلَهِكَ. أَحْبَبْتَ ٱلْأُجْرَةَ عَلَى جَمِيعِ بَيَادِرِ ٱلْحِنْطَةِ.","lā taf̊raḥ̊ yā ại̹s̊rāyỉylu ṭarabaⁿạ kaٱlsẖũʿūbi, liạảnãka qad̊ zanaẙta ʿan̊ ại̹lahika. ạảḥ̊bab̊ta ٱl̊ạủj̊raẗa ʿalay̱ jamīʿi bayādiri ٱl̊ḥin̊ṭaẗi."],[9,2,"لَا يُطْعِمُهُمُ ٱلْبَيْدَرُ وَٱلْمِعْصَرَةُ، وَيَكْذِبُ عَلَيْهِمِ ٱلْمِسْطَارُ.","lā yuṭ̊ʿimuhumu ٱl̊baẙdaru waٱl̊miʿ̊ṣaraẗu, wayak̊dẖibu ʿalaẙhimi ٱl̊mis̊ṭāru."],[9,3,"لَا يَسْكُنُونَ فِي أَرْضِ ٱلرَّبِّ، بَلْ يَرْجِعُ أَفْرَايِمُ إِلَى مِصْرَ، وَيَأْكُلُونَ ٱلنَّجِسَ فِي أَشُّورَ.","lā yas̊kunūna fī ạảr̊ḍi ٱlrãbĩ, bal̊ yar̊jiʿu ạảf̊rāyimu ại̹lay̱ miṣ̊ra, wayā̊̉kulūna ٱlnãjisa fī ạảsẖũwra."],[9,4,"لَا يَسْكُبُونَ لِلرَّبِّ خَمْرًا وَلَا تَسُرُّهُ ذَبَائِحُهُمْ. إِنَّهَا لَهُمْ كَخُبْزِ ٱلْحُزْنِ. كُلُّ مَنْ أَكَلَهُ يَتَنَجَّسُ. إِنَّ خُبْزَهُمْ لِنَفْسِهِمْ. لَا يَدْخُلُ بَيْتَ ٱلرَّبِّ.","lā yas̊kubūna lilrãbĩ kẖam̊raⁿạ walā tasurũhu dẖabāyỉḥuhum̊. ại̹nãhā lahum̊ kakẖub̊zi ٱl̊ḥuz̊ni. kulũ man̊ ạảkalahu yatanajãsu. ại̹nã kẖub̊zahum̊ linaf̊sihim̊. lā yad̊kẖulu baẙta ٱlrãbĩ."],[9,5,"مَاذَا تَصْنَعُونَ فِي يَوْمِ ٱلْمَوْسِمِ، وَفِي يَوْمِ عِيدِ ٱلرَّبِّ؟","mādẖā taṣ̊naʿūna fī yaẘmi ٱl̊maẘsimi, wafī yaẘmi ʿīdi ٱlrãbĩ?"],[9,6,"إِنَّهُمْ قَدْ ذَهَبُوا مِنَ ٱلْخَرَابِ. تَجْمَعُهُمْ مِصْرُ. تَدْفِنُهُمْ مُوفُ. يَرِثُ ٱلْقَرِيصُ نَفَائِسَ فِضَّتِهِمْ. يَكُونُ ٱلْعَوْسَجُ فِي مَنَازِلِهِمْ.","ại̹nãhum̊ qad̊ dẖahabūạ mina ٱl̊kẖarābi. taj̊maʿuhum̊ miṣ̊ru. tad̊finuhum̊ mūfu. yaritẖu ٱl̊qarīṣu nafāyỉsa fiḍãtihim̊. yakūnu ٱl̊ʿaẘsaju fī manāzilihim̊."],[9,7,"جَاءَتْ أَيَّامُ ٱلْعِقَابِ. جَاءَتْ أَيَّامُ ٱلْجَزَاءِ. سَيَعْرِفُ إِسْرَائِيلُ. اَلنَّبِيُّ أَحْمَقُ. إِنْسَانُ ٱلرُّوحِ مَجْنُونٌ مِنْ كَثْرَةِ إِثْمِكَ وَكَثْرَةِ ٱلْحِقْدِ.","jāʾat̊ ạảyãạmu ٱl̊ʿiqābi. jāʾat̊ ạảyãạmu ٱl̊jazāʾi. sayaʿ̊rifu ại̹s̊rāyỉylu. ạalnãbīũ ạảḥ̊maqu. ại̹n̊sānu ٱlrũwḥi maj̊nūnuⁿ min̊ katẖ̊raẗi ại̹tẖ̊mika wakatẖ̊raẗi ٱl̊ḥiq̊di."],[9,8,"أَفْرَايِمُ مُنْتَظَرٌ عِنْدَ إِلَهِي. اَلنَّبِيُّ فَخُّ صَيَّادٍ عَلَى جَمِيعِ طُرُقِهِ. حِقْدٌ فِي بَيْتِ إِلَهِهِ.","ạảf̊rāyimu mun̊taẓaruⁿ ʿin̊da ại̹lahī. ạalnãbīũ fakẖũ ṣayãạdiⁿ ʿalay̱ jamīʿi ṭuruqihi. ḥiq̊duⁿ fī baẙti ại̹lahihi."],[9,9,"قَدْ تَوَغَّلُوا، فَسَدُوا كَأَيَّامِ جِبْعَةَ. سَيَذْكُرُ إِثْمَهُمْ. سَيُعَاقِبُ خَطَايَاهُمْ.","qad̊ tawagẖãlūạ, fasadūạ kāảyãạmi jib̊ʿaẗa. sayadẖ̊kuru ại̹tẖ̊mahum̊. sayuʿāqibu kẖaṭāyāhum̊."],[9,10,"«وَجَدْتُ إِسْرَائِيلَ كَعِنَبٍ فِي ٱلْبَرِّيَّةِ. رَأَيْتُ آبَاءَكُمْ كَبَاكُورَةٍ عَلَى تِينَةٍ فِي أَوَّلِهَا. أَمَّا هُمْ فَجَاءُوا إِلَى بَعْلِ فَغُورَ، وَنَذَرُوا أَنْفُسَهُمْ لِلْخِزْيِ، وَصَارُوا رِجْسًا كَمَا أَحَبُّوا.","«wajad̊tu ại̹s̊rāyỉyla kaʿinabiⁿ fī ٱl̊barĩyãẗi. rāảẙtu ậbāʾakum̊ kabākūraẗiⁿ ʿalay̱ tīnaẗiⁿ fī ạảwãlihā. ạảmãạ hum̊ fajāʾūạ ại̹lay̱ baʿ̊li fagẖūra, wanadẖarūạ ạản̊fusahum̊ lil̊kẖiz̊yi, waṣārūạ rij̊saⁿạ kamā ạảḥabũwạ."],[9,11,"أَفْرَايِمُ تَطِيرُ كَرَامَتُهُمْ كَطَائِرٍ مِنَ ٱلْوِلَادَةِ وَمِنَ ٱلْبَطْنِ وَمِنَ ٱلْحَبَلِ.","ạảf̊rāyimu taṭīru karāmatuhum̊ kaṭāyỉriⁿ mina ٱl̊wilādaẗi wamina ٱl̊baṭ̊ni wamina ٱl̊ḥabali."],[9,12,"وَإِنْ رَبَّوْا أَوْلَادَهُمْ أُثْكِلُهُمْ إِيَّاهُمْ حَتَّى لَا يَكُونَ إِنْسَانٌ. وَيْلٌ لَهُمْ أَيْضًا مَتَى ٱنْصَرَفْتُ عَنْهُمْ!","wāi̹n̊ rabãẘạ ạảẘlādahum̊ ạủtẖ̊kiluhum̊ ại̹yãạhum̊ ḥatãy̱ lā yakūna ại̹n̊sānuⁿ. waẙluⁿ lahum̊ ạảẙḍaⁿạ matay̱ ٱn̊ṣaraf̊tu ʿan̊hum̊!"],[9,13,"أَفْرَايِمُ كَمَا أَرَى كَصُورٍ مَغْرُوسٍ فِي مَرْعًى، وَلَكِنَّ أَفْرَايِمَ سَيُخْرِجُ بَنِيهِ إِلَى ٱلْقَاتِلِ».","ạảf̊rāyimu kamā ạảray̱ kaṣūriⁿ magẖ̊rūsiⁿ fī mar̊ʿaⁿy̱, walakinã ạảf̊rāyima sayukẖ̊riju banīhi ại̹lay̱ ٱl̊qātili»."],[9,14,"أَعْطِهِمْ يَارَبُّ. مَاذَا تُعْطِي؟ أَعْطِهِمْ رَحِمًا مُسْقِطًا وَثَدْيَيْنِ يَبِسَيْنِ.","ạảʿ̊ṭihim̊ yārabũ. mādẖā tuʿ̊ṭī? ạảʿ̊ṭihim̊ raḥimaⁿạ mus̊qiṭaⁿạ watẖad̊yaẙni yabisaẙni."],[9,15,"«كُلُّ شَرِّهِمْ فِي ٱلْجِلْجَالِ. إِنِّي هُنَاكَ أَبْغَضْتُهُمْ. مِنْ أَجْلِ سُوءِ أَفْعَالِهِمْ أَطْرُدُهُمْ مِنْ بَيْتِي. لَا أَعُودُ أُحِبُّهُمْ. جَمِيعُ رُؤَسَائِهِمْ مُتَمَرِّدُونَ.","«kulũ sẖarĩhim̊ fī ٱl̊jil̊jāli. ại̹nĩy hunāka ạảb̊gẖaḍ̊tuhum̊. min̊ ạảj̊li sūʾi ạảf̊ʿālihim̊ ạảṭ̊ruduhum̊ min̊ baẙtī. lā ạảʿūdu ạủḥibũhum̊. jamīʿu rūảsāyỉhim̊ mutamarĩdūna."],[9,16,"أَفْرَايِمُ مَضْرُوبٌ. أَصْلُهُمْ قَدْ جَفَّ. لَا يَصْنَعُونَ ثَمَرًا. وَإِنْ وَلَدُوا أُمِيتُ مُشْتَهَيَاتِ بُطُونِهِمْ».","ạảf̊rāyimu maḍ̊rūbuⁿ. ạảṣ̊luhum̊ qad̊ jafã. lā yaṣ̊naʿūna tẖamaraⁿạ. wāi̹n̊ waladūạ ạủmītu musẖ̊tahayāti buṭūnihim̊»."],[9,17,"يَرْفُضُهُمْ إِلَهِي لِأَنَّهُمْ لَمْ يَسْمَعُوا لَهُ، فَيَكُونُونَ تَائِهِينَ بَيْنَ ٱلْأُمَمِ.","yar̊fuḍuhum̊ ại̹lahī liạảnãhum̊ lam̊ yas̊maʿūạ lahu, fayakūnūna tāyỉhīna baẙna ٱl̊ạủmami."],[10,1,"إِسْرَائِيلُ جَفْنَةٌ مُمْتَدَّةٌ. يُخْرِجُ ثَمَرًا لِنَفْسِهِ. عَلَى حَسَبِ كَثْرَةِ ثَمَرِهِ قَدْ كَثَّرَ ٱلْمَذَابِحَ. عَلَى حَسَبِ جُودَةِ أَرْضِهِ أَجَادَ ٱلْأَنْصَابَ.","ại̹s̊rāyỉylu jaf̊naẗuⁿ mum̊tadãẗuⁿ. yukẖ̊riju tẖamaraⁿạ linaf̊sihi. ʿalay̱ ḥasabi katẖ̊raẗi tẖamarihi qad̊ katẖãra ٱl̊madẖābiḥa. ʿalay̱ ḥasabi jūdaẗi ạảr̊ḍihi ạảjāda ٱl̊ạản̊ṣāba."],[10,2,"قَدْ قَسَمُوا قُلُوبَهُمْ. اَلْآنَ يُعَاقَبُونَ. هُوَ يُحَطِّمُ مَذَابِحَهُمْ، يُخْرِبُ أَنْصَابَهُمْ.","qad̊ qasamūạ qulūbahum̊. ạal̊ậna yuʿāqabūna. hūa yuḥaṭĩmu madẖābiḥahum̊, yukẖ̊ribu ạản̊ṣābahum̊."],[10,3,"إِنَّهُمُ ٱلْآنَ يَقُولُونَ: «لَا مَلِكَ لَنَا لِأَنَّنَا لَا نَخَافُ ٱلرَّبَّ، فَٱلْمَلِكُ مَاذَا يَصْنَعُ بِنَا؟».","ại̹nãhumu ٱl̊ậna yaqūlūna: «lā malika lanā liạảnãnā lā nakẖāfu ٱlrãbã, faٱl̊maliku mādẖā yaṣ̊naʿu binā?»."],[10,4,"يَتَكَلَّمُونَ كَلَامًا بِأَقْسَامٍ بَاطِلَةٍ. يَقْطَعُونَ عَهْدًا فَيَنْبُتُ ٱلْقَضَاءُ عَلَيْهِمْ كَٱلْعَلْقَمِ فِي أَتْلَامِ ٱلْحَقْلِ.","yatakalãmūna kalāmaⁿạ biạảq̊sāmiⁿ bāṭilaẗiⁿ. yaq̊ṭaʿūna ʿah̊daⁿạ fayan̊butu ٱl̊qaḍāʾu ʿalaẙhim̊ kaٱl̊ʿal̊qami fī ạảt̊lāmi ٱl̊ḥaq̊li."],[10,5,"عَلَى عُجُولِ بَيْتِ آوَنَ يَخَافُ سُكَّانُ ٱلسَّامِرَةِ. إِنَّ شَعْبَهُ يَنُوحُ عَلَيْهِ، وَكَهَنَتَهُ عَلَيْهِ يَرْتَعِدُونَ عَلَى مَجْدِهِ، لِأَنَّهُ ٱنْتَفَى عَنْهُ.","ʿalay̱ ʿujūli baẙti ậwana yakẖāfu sukãạnu ٱlsãạmiraẗi. ại̹nã sẖaʿ̊bahu yanūḥu ʿalaẙhi, wakahanatahu ʿalaẙhi yar̊taʿidūna ʿalay̱ maj̊dihi, liạảnãhu ٱn̊tafay̱ ʿan̊hu."],[10,6,"وَهُوَ أَيْضًا يُجْلَبُ إِلَى أَشُّورَ هَدِيَّةً لِمَلِكٍ عَدُوٍّ. يَأْخُذُ أَفْرَايِمُ خِزْيًا، وَيَخْجَلُ إِسْرَائِيلُ عَلَى رَأْيِهِ.","wahūa ạảẙḍaⁿạ yuj̊labu ại̹lay̱ ạảsẖũwra hadīãẗaⁿ limalikiⁿ ʿadūiⁿ̃. yā̊̉kẖudẖu ạảf̊rāyimu kẖiz̊yaⁿạ, wayakẖ̊jalu ại̹s̊rāyỉylu ʿalay̱ rā̊̉yihi."],[10,7,"اَلسَّامِرَةُ مَلِكُهَا يَبِيدُ كَغُثَاءٍ عَلَى وَجْهِ ٱلْمَاءِ،","ạalsãạmiraẗu malikuhā yabīdu kagẖutẖāʾiⁿ ʿalay̱ waj̊hi ٱl̊māʾi,"],[10,8,"وَتُخْرَبُ شَوَامِخُ آوَنَ، خَطِيَّةُ إِسْرَائِيلَ. يَطْلُعُ ٱلشَّوْكُ وَٱلْحَسَكُ عَلَى مَذَابِحِهِمْ، وَيَقُولُونَ لِلْجِبَالِ: غَطِّينَا، وَلِلتِّلَالِ: ٱسْقُطِي عَلَيْنَا.","watukẖ̊rabu sẖawāmikẖu ậwana, kẖaṭīãẗu ại̹s̊rāyỉyla. yaṭ̊luʿu ٱlsẖãẘku waٱl̊ḥasaku ʿalay̱ madẖābiḥihim̊, wayaqūlūna lil̊jibāli: gẖaṭĩynā, waliltĩlāli: ٱs̊quṭī ʿalaẙnā."],[10,9,"«مِنْ أَيَّامِ جِبْعَةَ أَخْطَأْتَ يَا إِسْرَائِيلُ. هُنَاكَ وَقَفُوا. لَمْ تُدْرِكْهُمْ فِي جِبْعَةَ ٱلْحَرْبُ عَلَى بَنِي ٱلْإِثْمِ.","«min̊ ạảyãạmi jib̊ʿaẗa ạảkẖ̊ṭā̊̉ta yā ại̹s̊rāyỉylu. hunāka waqafūạ. lam̊ tud̊rik̊hum̊ fī jib̊ʿaẗa ٱl̊ḥar̊bu ʿalay̱ banī ٱl̊ại̹tẖ̊mi."],[10,10,"حِينَمَا أُرِيدُ أُؤَدِّبُهُمْ، وَيَجْتَمِعُ عَلَيْهِمْ شُعُوبٌ فِي ٱرْتِبَاطِهِمْ بِإِثْمَيْهِمْ.","ḥīnamā ạủrīdu ạủwảdĩbuhum̊, wayaj̊tamiʿu ʿalaẙhim̊ sẖuʿūbuⁿ fī ٱr̊tibāṭihim̊ biại̹tẖ̊maẙhim̊."],[10,11,"وَأَفْرَايِمُ عِجْلَةٌ مُتَمَرِّنَةٌ تُحِبُّ ٱلدِّرَاسَ، وَلَكِنِّي أَجْتَازُ عَلَى عُنُقِهَا ٱلْحَسَنِ. أُرْكِبُ عَلَى أَفْرَايِمَ. يَفْلَحُ يَهُوذَا. يُمَهِّدُ يَعْقُوبُ.","wāảf̊rāyimu ʿij̊laẗuⁿ mutamarĩnaẗuⁿ tuḥibũ ٱldĩrāsa, walakinĩy ạảj̊tāzu ʿalay̱ ʿunuqihā ٱl̊ḥasani. ạủr̊kibu ʿalay̱ ạảf̊rāyima. yaf̊laḥu yahūdẖā. yumahĩdu yaʿ̊qūbu."],[10,12,"«اِزْرَعُوا لِأَنْفُسِكُمْ بِٱلْبِرِّ. ٱحْصُدُوا بِحَسَبِ ٱلصَّلَاحِ. ٱحْرُثُوا لِأَنْفُسِكُمْ حَرْثًا، فَإِنَّهُ وَقْتٌ لِطَلَبِ ٱلرَّبِّ حَتَّى يَأْتِيَ وَيُعَلِّمَكُمُ ٱلْبِرَّ.","«ạiz̊raʿūạ liạản̊fusikum̊ biٱl̊birĩ. ٱḥ̊ṣudūạ biḥasabi ٱlṣãlāḥi. ٱḥ̊rutẖūạ liạản̊fusikum̊ ḥar̊tẖaⁿạ, fāi̹nãhu waq̊tuⁿ liṭalabi ٱlrãbĩ ḥatãy̱ yā̊̉tīa wayuʿalĩmakumu ٱl̊birã."],[10,13,"قَدْ حَرَثْتُمُ ٱلنِّفَاقَ، حَصَدْتُمُ ٱلْإِثْمَ، أَكَلْتُمْ ثَمَرَ ٱلْكَذِبِ. لِأَنَّكَ وَثَقْتَ بِطَرِيقِكَ، بِكَثْرَةِ أَبْطَالِكَ.","qad̊ ḥaratẖ̊tumu ٱlnĩfāqa, ḥaṣad̊tumu ٱl̊ại̹tẖ̊ma, ạảkal̊tum̊ tẖamara ٱl̊kadẖibi. liạảnãka watẖaq̊ta biṭarīqika, bikatẖ̊raẗi ạảb̊ṭālika."],[10,14,"يَقُومُ ضَجِيجٌ فِي شُعُوبِكَ، وَتُخْرَبُ جَمِيعُ حُصُونِكَ كَإِخْرَابِ شَلْمَانَ بَيْتَ أَرَبْئِيلَ فِي يَوْمِ ٱلْحَرْبِ. اَلْأُمُّ مَعَ ٱلْأَوْلَادِ حُطِّمَتْ.","yaqūmu ḍajījuⁿ fī sẖuʿūbika, watukẖ̊rabu jamīʿu ḥuṣūnika kāi̹kẖ̊rābi sẖal̊māna baẙta ạảrab̊yỉyla fī yaẘmi ٱl̊ḥar̊bi. ạal̊ạủmũ maʿa ٱl̊ạảẘlādi ḥuṭĩmat̊."],[10,15,"هَكَذَا تَصْنَعُ بِكُمْ بَيْتُ إِيلَ مِنْ أَجْلِ رَدَاءَةِ شَرِّكُمْ. فِي ٱلصُّبْحِ يَهْلِكُ مَلِكُ إِسْرَائِيلَ هَلَاكًا.","hakadẖā taṣ̊naʿu bikum̊ baẙtu ại̹yla min̊ ạảj̊li radāʾaẗi sẖarĩkum̊. fī ٱlṣũb̊ḥi yah̊liku maliku ại̹s̊rāyỉyla halākaⁿạ."],[11,1,"«لَمَّا كَانَ إِسْرَائِيلُ غُلَامًا أَحْبَبْتُهُ، وَمِنْ مِصْرَ دَعَوْتُ ٱبْنِي.","«lamãạ kāna ại̹s̊rāyỉylu gẖulāmaⁿạ ạảḥ̊bab̊tuhu, wamin̊ miṣ̊ra daʿaẘtu ٱb̊nī."],[11,2,"كُلَّ مَا دَعَوْهُمْ ذَهَبُوا مِنْ أَمَامِهِمْ يَذْبَحُونَ لِلْبَعْلِيمِ، وَيُبَخِّرُونَ لِلتَّمَاثِيلِ ٱلْمَنْحُوتَةِ.","kulã mā daʿaẘhum̊ dẖahabūạ min̊ ạảmāmihim̊ yadẖ̊baḥūna lil̊baʿ̊līmi, wayubakẖĩrūna liltãmātẖīli ٱl̊man̊ḥūtaẗi."],[11,3,"وَأَنَا دَرَّجْتُ أَفْرَايِمَ مُمْسِكًا إِيَّاهُمْ بِأَذْرُعِهِمْ، فَلَمْ يَعْرِفُوا أَنِّي شَفَيْتُهُمْ.","wāảnā darãj̊tu ạảf̊rāyima mum̊sikaⁿạ ại̹yãạhum̊ biạảdẖ̊ruʿihim̊, falam̊ yaʿ̊rifūạ ạảnĩy sẖafaẙtuhum̊."],[11,4,"كُنْتُ أَجْذِبُهُمْ بِحِبَالِ ٱلْبَشَرِ، بِرُبُطِ ٱلْمَحَبَّةِ، وَكُنْتُ لَهُمْ كَمَنْ يَرْفَعُ ٱلنِّيرَ عَنْ أَعْنَاقِهِمْ، وَمَدَدْتُ إِلَيْهِ مُطْعِمًا إِيَّاهُ.","kun̊tu ạảj̊dẖibuhum̊ biḥibāli ٱl̊basẖari, birubuṭi ٱl̊maḥabãẗi, wakun̊tu lahum̊ kaman̊ yar̊faʿu ٱlnĩyra ʿan̊ ạảʿ̊nāqihim̊, wamadad̊tu ại̹laẙhi muṭ̊ʿimaⁿạ ại̹yãạhu."],[11,5,"«لَا يَرْجِعُ إِلَى أَرْضِ مِصْرَ، بَلْ أَشُّورُ هُوَ مَلِكُهُ، لِأَنَّهُمْ أَبَوْا أَنْ يَرْجِعُوا.","«lā yar̊jiʿu ại̹lay̱ ạảr̊ḍi miṣ̊ra, bal̊ ạảsẖũwru hūa malikuhu, liạảnãhum̊ ạảbaẘạ ạản̊ yar̊jiʿūạ."],[11,6,"يَثُورُ ٱلسَّيْفُ فِي مُدُنِهِمْ وَيُتْلِفُ عِصِيَّهَا، وَيَأْكُلُهُمْ مِنْ أَجْلِ آرَائِهِمْ.","yatẖūru ٱlsãẙfu fī mudunihim̊ wayut̊lifu ʿiṣīãhā, wayā̊̉kuluhum̊ min̊ ạảj̊li ậrāyỉhim̊."],[11,7,"وَشَعْبِي جَانِحُونَ إِلَى ٱلِٱرْتِدَادِ عَنِّي، فَيَدْعُونَهُمْ إِلَى ٱلْعَلِيِّ وَلَا أَحَدٌ يَرْفَعُهُ.","wasẖaʿ̊bī jāniḥūna ại̹lay̱ ٱliٱr̊tidādi ʿanĩy, fayad̊ʿūnahum̊ ại̹lay̱ ٱl̊ʿalīĩ walā ạảḥaduⁿ yar̊faʿuhu."],[11,8,"كَيْفَ أَجْعَلُكَ يَا أَفْرَايِمُ، أُصَيِّرُكَ يَا إِسْرَائِيلُ؟! كَيْفَ أَجْعَلُكَ كَأَدَمَةَ، أَصْنَعُكَ كَصَبُويِيمَ؟! قَدِ ٱنْقَلَبَ عَلَيَّ قَلْبِي. ٱضْطَرَمَتْ مَرَاحِمِي جَمِيعًا.","kaẙfa ạảj̊ʿaluka yā ạảf̊rāyimu, ạủṣayĩruka yā ại̹s̊rāyỉylu?! kaẙfa ạảj̊ʿaluka kāảdamaẗa, ạảṣ̊naʿuka kaṣabūyīma?! qadi ٱn̊qalaba ʿalayã qal̊bī. ٱḍ̊ṭaramat̊ marāḥimī jamīʿaⁿạ."],[11,9,"«لَا أُجْرِي حُمُوَّ غَضَبِي. لَا أَعُودُ أَخْرِبُ أَفْرَايِمَ، لِأَنِّي ٱللهُ لَا إِنْسَانٌ، ٱلْقُدُّوسُ فِي وَسَطِكَ فَلَا آتِي بِسَخَطٍ.","«lā ạủj̊rī ḥumūã gẖaḍabī. lā ạảʿūdu ạảkẖ̊ribu ạảf̊rāyima, liạảnĩy ٱllhu lā ại̹n̊sānuⁿ, ٱl̊qudũwsu fī wasaṭika falā ậtī bisakẖaṭiⁿ."],[11,10,"«وَرَاءَ ٱلرَّبِّ يَمْشُونَ. كَأَسَدٍ يُزَمْجِرُ. فَإِنَّهُ يُزَمْجِرُ فَيُسْرِعُ ٱلْبَنُونَ مِنَ ٱلْبَحْرِ.","«warāʾa ٱlrãbĩ yam̊sẖūna. kāảsadiⁿ yuzam̊jiru. fāi̹nãhu yuzam̊jiru fayus̊riʿu ٱl̊banūna mina ٱl̊baḥ̊ri."],[11,11,"يُسْرِعُونَ كَعُصْفُورٍ مِنْ مِصْرَ، وَكَحَمَامَةٍ مِنْ أَرْضِ أَشُّورَ، فَأُسْكِنُهُمْ فِي بُيُوتِهِمْ، يَقُولُ ٱلرَّبُّ.","yus̊riʿūna kaʿuṣ̊fūriⁿ min̊ miṣ̊ra, wakaḥamāmaẗiⁿ min̊ ạảr̊ḍi ạảsẖũwra, fāủs̊kinuhum̊ fī buyūtihim̊, yaqūlu ٱlrãbũ."],[11,12,"قَدْ أَحَاطَ بِي أَفْرَايِمُ بِٱلْكَذِبِ، وَبَيْتُ إِسْرَائِيلَ بِٱلْمَكْرِ، وَلَمْ يَزَلْ يَهُوذَا شَارِدًا عَنِ ٱللهِ وَعَنِ ٱلْقُدُّوسِ ٱلْأَمِينِ.","qad̊ ạảḥāṭa bī ạảf̊rāyimu biٱl̊kadẖibi, wabaẙtu ại̹s̊rāyỉyla biٱl̊mak̊ri, walam̊ yazal̊ yahūdẖā sẖāridaⁿạ ʿani ٱllhi waʿani ٱl̊qudũwsi ٱl̊ạảmīni."],[12,1,"«أَفْرَايِمُ رَاعِي ٱلرِّيحِ، وَتَابِعُ ٱلرِّيحِ ٱلشَّرْقِيَّةِ. كُلَّ يَوْمٍ يُكَثِّرُ ٱلْكَذِبَ وَٱلِٱغْتِصَابَ، وَيَقْطَعُونَ مَعَ أَشُّورَ عَهْدًا، وَٱلزَّيْتُ إِلَى مِصْرَ يُجْلَبُ.","«ạảf̊rāyimu rāʿī ٱlrĩyḥi, watābiʿu ٱlrĩyḥi ٱlsẖãr̊qīãẗi. kulã yaẘmiⁿ yukatẖĩru ٱl̊kadẖiba waٱliٱgẖ̊tiṣāba, wayaq̊ṭaʿūna maʿa ạảsẖũwra ʿah̊daⁿạ, waٱlzãẙtu ại̹lay̱ miṣ̊ra yuj̊labu."],[12,2,"فَلِلرَّبِّ خِصَامٌ مَعَ يَهُوذَا، وَهُوَ مُزْمِعٌ أَنْ يُعَاقِبَ يَعْقُوبَ بِحَسَبِ طُرُقِهِ. بِحَسَبِ أَفْعَالِهِ يَرُدُّ عَلَيْهِ.","falilrãbĩ kẖiṣāmuⁿ maʿa yahūdẖā, wahūa muz̊miʿuⁿ ạản̊ yuʿāqiba yaʿ̊qūba biḥasabi ṭuruqihi. biḥasabi ạảf̊ʿālihi yarudũ ʿalaẙhi."],[12,3,"«فِي ٱلْبَطْنِ قَبَضَ بِعَقِبِ أَخِيهِ، وَبِقُوَّتِهِ جَاهَدَ مَعَ ٱللهِ.","«fī ٱl̊baṭ̊ni qabaḍa biʿaqibi ạảkẖīhi, wabiqūãtihi jāhada maʿa ٱllhi."],[12,4,"جَاهَدَ مَعَ ٱلْمَلَاكِ وَغَلَبَ. بَكَى وَٱسْتَرْحَمَهُ. وَجَدَهُ فِي بَيْتِ إِيلَ وَهُنَاكَ تَكَلَّمَ مَعَنَا.","jāhada maʿa ٱl̊malāki wagẖalaba. bakay̱ waٱs̊tar̊ḥamahu. wajadahu fī baẙti ại̹yla wahunāka takalãma maʿanā."],[12,5,"وَٱلرَّبُّ إِلَهُ ٱلْجُنُودِ يَهْوَهُ ٱسْمُهُ.","waٱlrãbũ ại̹lahu ٱl̊junūdi yah̊wahu ٱs̊muhu."],[12,6,"وَأَنْتَ فَٱرْجِعْ إِلَى إِلَهِكَ. اِحْفَظِ ٱلرَّحْمَةَ وَٱلْحَقَّ، وَٱنْتَظِرْ إِلَهَكَ دَائِمًا.","wāản̊ta faٱr̊jiʿ̊ ại̹lay̱ ại̹lahika. ạiḥ̊faẓi ٱlrãḥ̊maẗa waٱl̊ḥaqã, waٱn̊taẓir̊ ại̹lahaka dāyỉmaⁿạ."],[12,7,"«مِثْلُ ٱلْكَنْعَانِيِّ فِي يَدِهِ مَوَازِينُ ٱلْغِشِّ. يُحِبُّ أَنْ يَظْلِمَ.","«mitẖ̊lu ٱl̊kan̊ʿānīĩ fī yadihi mawāzīnu ٱl̊gẖisẖĩ. yuḥibũ ạản̊ yaẓ̊lima."],[12,8,"فَقَالَ أَفْرَايِمُ: إِنِّي صِرْتُ غَنِيًّا. وَجَدْتُ لِنَفْسِي ثَرْوَةً. جَمِيعُ أَتْعَابِي لَا يَجِدُونَ لِي فِيهَا ذَنْبًا هُوَ خَطِيَّةٌ.","faqāla ạảf̊rāyimu: ại̹nĩy ṣir̊tu gẖanīaⁿ̃ạ. wajad̊tu linaf̊sī tẖar̊waẗaⁿ. jamīʿu ạảt̊ʿābī lā yajidūna lī fīhā dẖan̊baⁿạ hūa kẖaṭīãẗuⁿ."],[12,9,"وَأَنَا ٱلرَّبُّ إِلَهُكَ مِنْ أَرْضِ مِصْرَ حَتَّى أُسْكِنَكَ ٱلْخِيَامَ كَأَيَّامِ ٱلْمَوْسِمِ.","wāảnā ٱlrãbũ ại̹lahuka min̊ ạảr̊ḍi miṣ̊ra ḥatãy̱ ạủs̊kinaka ٱl̊kẖīāma kāảyãạmi ٱl̊maẘsimi."],[12,10,"وَكَلَّمْتُ ٱلْأَنْبِيَاءَ وَكَثَّرْتُ ٱلرُّؤَى، وَبِيَدِ ٱلْأَنْبِيَاءِ مَثَّلْتُ أَمْثَالًا».","wakalãm̊tu ٱl̊ạản̊bīāʾa wakatẖãr̊tu ٱlrũwảy̱, wabīadi ٱl̊ạản̊bīāʾi matẖãl̊tu ạảm̊tẖālaⁿạ»."],[12,11,"إِنَّهُمْ فِي جِلْعَادَ قَدْ صَارُوا إِثْمًا، بُطْلًا لَا غَيْرُ. فِي ٱلْجِلْجَالِ ذَبَحُوا ثِيرَانًا، وَمَذَابِحُهُمْ كَرُجَمٍ فِي أَتْلَامِ ٱلْحَقْلِ.","ại̹nãhum̊ fī jil̊ʿāda qad̊ ṣārūạ ại̹tẖ̊maⁿạ, buṭ̊laⁿạ lā gẖaẙru. fī ٱl̊jil̊jāli dẖabaḥūạ tẖīrānaⁿạ, wamadẖābiḥuhum̊ karujamiⁿ fī ạảt̊lāmi ٱl̊ḥaq̊li."],[12,12,"وَهَرَبَ يَعْقُوبُ إِلَى صَحْرَاءِ أَرَامَ، وَخَدَمَ إِسْرَائِيلُ لِأَجْلِ ٱمْرَأَةٍ، وَلِأَجْلِ ٱمْرَأَةٍ رَعَى.","waharaba yaʿ̊qūbu ại̹lay̱ ṣaḥ̊rāʾi ạảrāma, wakẖadama ại̹s̊rāyỉylu liạảj̊li ٱm̊rāảẗiⁿ, waliạảj̊li ٱm̊rāảẗiⁿ raʿay̱."],[12,13,"وَبِنَبِيٍّ أَصْعَدَ ٱلرَّبُّ إِسْرَائِيلَ مِنْ مِصْرَ، وَبِنَبِيٍّ حُفِظَ.","wabinabīiⁿ̃ ạảṣ̊ʿada ٱlrãbũ ại̹s̊rāyỉyla min̊ miṣ̊ra, wabinabīiⁿ̃ ḥufiẓa."],[12,14,"أَغَاظَهُ إِسْرَائِيلُ بِمَرَارَةٍ، فَيَتْرُكُ دِمَاءَهُ عَلَيْهِ، وَيَرُدُّ سَيِّدُهُ عَارَهُ عَلَيْهِ.","ạảgẖāẓahu ại̹s̊rāyỉylu bimarāraẗiⁿ, fayat̊ruku dimāʾahu ʿalaẙhi, wayarudũ sayĩduhu ʿārahu ʿalaẙhi."],[13,1,"لَمَّا تَكَلَّمَ أَفْرَايِمُ بِرَعْدَةٍ، تَرَفَّعَ فِي إِسْرَائِيلَ. وَلَمَّا أَثِمَ بِبَعْلٍ مَاتَ.","lamãạ takalãma ạảf̊rāyimu biraʿ̊daẗiⁿ, tarafãʿa fī ại̹s̊rāyỉyla. walamãạ ạảtẖima bibaʿ̊liⁿ māta."],[13,2,"وَٱلْآنَ يَزْدَادُونَ خَطِيَّةً، وَيَصْنَعُونَ لِأَنْفُسِهِمْ تَمَاثِيلَ مَسْبُوكَةً مِنْ فِضَّتِهِمْ، أَصْنَامًا بِحَذَاقَتِهِمْ، كُلُّهَا عَمَلُ ٱلصُّنَّاعِ. عَنْهَا هُمْ يَقُولُونَ: «ذَابِحُو ٱلنَّاسِ يُقَبِّلُونَ ٱلْعُجُولَ».","waٱl̊ậna yaz̊dādūna kẖaṭīãẗaⁿ, wayaṣ̊naʿūna liạản̊fusihim̊ tamātẖīla mas̊būkaẗaⁿ min̊ fiḍãtihim̊, ạảṣ̊nāmaⁿạ biḥadẖāqatihim̊, kulũhā ʿamalu ٱlṣũnãạʿi. ʿan̊hā hum̊ yaqūlūna: «dẖābiḥū ٱlnãạsi yuqabĩlūna ٱl̊ʿujūla»."],[13,3,"لِذَلِكَ يَكُونُونَ كَسَحَابِ ٱلصُّبْحِ، وَكَالنَّدَى ٱلْمَاضِي بَاكِرًا. كَعُصَافَةٍ تُخْطَفُ مِنَ ٱلْبَيْدَرِ، وَكَدُخَانٍ مِنَ ٱلْكُوَّةِ.","lidẖalika yakūnūna kasaḥābi ٱlṣũb̊ḥi, wakālnãday̱ ٱl̊māḍī bākiraⁿạ. kaʿuṣāfaẗiⁿ tukẖ̊ṭafu mina ٱl̊baẙdari, wakadukẖāniⁿ mina ٱl̊kūãẗi."],[13,4,"«وَأَنَا ٱلرَّبُّ إِلَهُكَ مِنْ أَرْضِ مِصْرَ، وَإِلَهًا سُوَايَ لَسْتَ تَعْرِفُ، وَلَا مُخَلِّصَ غَيْرِي.","«wāảnā ٱlrãbũ ại̹lahuka min̊ ạảr̊ḍi miṣ̊ra, wāi̹lahaⁿạ sūāya las̊ta taʿ̊rifu, walā mukẖalĩṣa gẖaẙrī."],[13,5,"أَنَا عَرَفْتُكَ فِي ٱلْبَرِّيَّةِ فِي أَرْضِ ٱلْعَطَشِ.","ạảnā ʿaraf̊tuka fī ٱl̊barĩyãẗi fī ạảr̊ḍi ٱl̊ʿaṭasẖi."],[13,6,"لَمَّا رَعَوْا شَبِعُوا. شَبِعُوا وَٱرْتَفَعَتْ قُلُوبُهُمْ، لِذَلِكَ نَسُونِي.","lamãạ raʿaẘạ sẖabiʿūạ. sẖabiʿūạ waٱr̊tafaʿat̊ qulūbuhum̊, lidẖalika nasūnī."],[13,7,"«فَأَكُونُ لَهُمْ كَأَسَدٍ. أَرْصُدُ عَلَى ٱلطَّرِيقِ كَنَمِرٍ.","«fāảkūnu lahum̊ kāảsadiⁿ. ạảr̊ṣudu ʿalay̱ ٱlṭãrīqi kanamiriⁿ."],[13,8,"أَصْدِمُهُمْ كَدُبَّةٍ مُثْكِلٍ، وَأَشُقُّ شَغَافَ قَلْبِهِمْ، وَآكُلُهُمْ هُنَاكَ كَلَبْوَةٍ. يُمَزِّقُهُمْ وَحْشُ ٱلْبَرِّيَّةِ.","ạảṣ̊dimuhum̊ kadubãẗiⁿ mutẖ̊kiliⁿ, wāảsẖuqũ sẖagẖāfa qal̊bihim̊, wā̂kuluhum̊ hunāka kalab̊waẗiⁿ. yumazĩquhum̊ waḥ̊sẖu ٱl̊barĩyãẗi."],[13,9,"«هَلَاكُكَ يَا إِسْرَائِيلُ أَنَّكَ عَلَيَّ، عَلَى عَوْنِكَ.","«halākuka yā ại̹s̊rāyỉylu ạảnãka ʿalayã, ʿalay̱ ʿaẘnika."],[13,10,"فَأَيْنَ هُوَ مَلِكُكَ حَتَّى يُخَلِّصَكَ فِي جَمِيعِ مُدُنِكَ؟ وَقُضَاتُكَ حَيْثُ قُلْتَ: أَعْطِنِي مَلِكًا وَرُؤَسَاءَ؟","fāảẙna hūa malikuka ḥatãy̱ yukẖalĩṣaka fī jamīʿi mudunika? waquḍātuka ḥaẙtẖu qul̊ta: ạảʿ̊ṭinī malikaⁿạ warūảsāʾa?"],[13,11,"أَنَا أَعْطَيْتُكَ مَلِكًا بِغَضَبِي وَأَخَذْتُهُ بِسَخَطِي.","ạảnā ạảʿ̊ṭaẙtuka malikaⁿạ bigẖaḍabī wāảkẖadẖ̊tuhu bisakẖaṭī."],[13,12,"«إِثْمُ أَفْرَايِمَ مَصْرُورٌ. خَطِيَّتُهُ مَكْنُوزَةٌ.","«ại̹tẖ̊mu ạảf̊rāyima maṣ̊rūruⁿ. kẖaṭīãtuhu mak̊nūzaẗuⁿ."],[13,13,"مَخَاضُ ٱلْوَالِدَةِ يَأْتِي عَلَيْهِ. هُوَ ٱبْنٌ غَيْرُ حَكِيمٍ، إِذْ لَمْ يَقِفْ فِي ٱلْوَقْتِ فِي مَوْلِدِ ٱلْبَنِينَ.","makẖāḍu ٱl̊wālidaẗi yā̊̉tī ʿalaẙhi. hūa ٱb̊nuⁿ gẖaẙru ḥakīmiⁿ, ại̹dẖ̊ lam̊ yaqif̊ fī ٱl̊waq̊ti fī maẘlidi ٱl̊banīna."],[13,14,"«مِنْ يَدِ ٱلْهَاوِيَةِ أَفْدِيهِمْ. مِنَ ٱلْمَوْتِ أُخَلِّصُهُمْ. أَيْنَ أَوْبَاؤُكَ يَا مَوْتُ؟ أَيْنَ شَوْكَتُكِ يَا هَاوِيَةُ؟ تَخْتَفِي ٱلنَّدَامَةُ عَنْ عَيْنَيَّ».","«min̊ yadi ٱl̊hāwīaẗi ạảf̊dīhim̊. mina ٱl̊maẘti ạủkẖalĩṣuhum̊. ạảẙna ạảẘbāwủka yā maẘtu? ạảẙna sẖaẘkatuki yā hāwīaẗu? takẖ̊tafī ٱlnãdāmaẗu ʿan̊ ʿaẙnayã»."],[13,15,"وَإِنْ كَانَ مُثْمِرًا بَيْنَ إِخْوَةٍ، تَأْتِي رِيحٌ شَرْقِيَّةٌ، رِيحُ ٱلرَّبِّ طَالِعَةً مِنَ ٱلْقَفْرِ فَتَجِفُّ عَيْنُهُ وَيَيْبَسُ يَنْبُوعُهُ. هِيَ تَنْهَبُ كَنْزَ كُلِّ مَتَاعٍ شَهِيٍّ.","wāi̹n̊ kāna mutẖ̊miraⁿạ baẙna ại̹kẖ̊waẗiⁿ, tā̊̉tī rīḥuⁿ sẖar̊qīãẗuⁿ, rīḥu ٱlrãbĩ ṭāliʿaẗaⁿ mina ٱl̊qaf̊ri fatajifũ ʿaẙnuhu wayaẙbasu yan̊būʿuhu. hīa tan̊habu kan̊za kulĩ matāʿiⁿ sẖahīiⁿ̃."],[13,16,"تُجَازَى ٱلسَّامِرَةُ لِأَنَّهَا قَدْ تَمَرَّدَتْ عَلَى إِلَهِهَا. بِٱلسَّيْفِ يَسْقُطُونَ. تُحَطَّمُ أَطْفَالُهُمْ، وَٱلْحَوَامِلُ تُشَقُّ.","tujāzay̱ ٱlsãạmiraẗu liạảnãhā qad̊ tamarãdat̊ ʿalay̱ ại̹lahihā. biٱlsãẙfi yas̊quṭūna. tuḥaṭãmu ạảṭ̊fāluhum̊, waٱl̊ḥawāmilu tusẖaqũ."],[14,1,"اِرْجِعْ يَا إِسْرَائِيلُ إِلَى ٱلرَّبِّ إِلَهِكَ، لِأَنَّكَ قَدْ تَعَثَّرْتَ بِإِثْمِكَ.","ạir̊jiʿ̊ yā ại̹s̊rāyỉylu ại̹lay̱ ٱlrãbĩ ại̹lahika, liạảnãka qad̊ taʿatẖãr̊ta biại̹tẖ̊mika."],[14,2,"خُذُوا مَعَكُمْ كَلَامًا وَٱرْجِعُوا إِلَى ٱلرَّبِّ. قُولُوا لَهُ: «ٱرْفَعْ كُلَّ إِثْمٍ وَٱقْبَلْ حَسَنًا، فَنُقَدِّمَ عُجُولَ شِفَاهِنَا.","kẖudẖūạ maʿakum̊ kalāmaⁿạ waٱr̊jiʿūạ ại̹lay̱ ٱlrãbĩ. qūlūạ lahu: «ٱr̊faʿ̊ kulã ại̹tẖ̊miⁿ waٱq̊bal̊ ḥasanaⁿạ, fanuqadĩma ʿujūla sẖifāhinā."],[14,3,"لَا يُخَلِّصُنَا أَشُّورُ. لَا نَرْكَبُ عَلَى ٱلْخَيْلِ، وَلَا نَقُولُ أَيْضًا لِعَمَلِ أَيْدِينَا: آلِهَتَنَا. إِنَّهُ بِكَ يُرْحَمُ ٱلْيَتِيمُ».","lā yukẖalĩṣunā ạảsẖũwru. lā nar̊kabu ʿalay̱ ٱl̊kẖaẙli, walā naqūlu ạảẙḍaⁿạ liʿamali ạảẙdīnā: ậlihatanā. ại̹nãhu bika yur̊ḥamu ٱl̊yatīmu»."],[14,4,"«أَنَا أَشْفِي ٱرْتِدَادَهُمْ. أُحِبُّهُمْ فَضْلًا، لِأَنَّ غَضَبِي قَدِ ٱرْتَدَّ عَنْهُ.","«ạảnā ạảsẖ̊fī ٱr̊tidādahum̊. ạủḥibũhum̊ faḍ̊laⁿạ, liạảnã gẖaḍabī qadi ٱr̊tadã ʿan̊hu."],[14,5,"أَكُونُ لِإِسْرَائِيلَ كَٱلنَّدَى. يُزْهِرُ كَٱلسَّوْسَنِ، وَيَضْرِبُ أُصُولَهُ كَلُبْنَانَ.","ạảkūnu liại̹s̊rāyỉyla kaٱlnãday̱. yuz̊hiru kaٱlsãẘsani, wayaḍ̊ribu ạủṣūlahu kalub̊nāna."],[14,6,"تَمْتَدُّ خَرَاعِيبُهُ، وَيَكُونُ بَهَاؤُهُ كَٱلزَّيْتُونَةِ، وَلَهُ رَائِحَةٌ كَلُبْنَانَ.","tam̊tadũ kẖarāʿībuhu, wayakūnu bahāwủhu kaٱlzãẙtūnaẗi, walahu rāyỉḥaẗuⁿ kalub̊nāna."],[14,7,"يَعُودُ ٱلسَّاكِنُونَ فِي ظِلِّهِ يُحْيُونَ حِنْطَةً وَيُزْهِرُونَ كَجَفْنَةٍ. يَكُونُ ذِكْرُهُمْ كَخَمْرِ لُبْنَانَ.","yaʿūdu ٱlsãạkinūna fī ẓilĩhi yuḥ̊yūna ḥin̊ṭaẗaⁿ wayuz̊hirūna kajaf̊naẗiⁿ. yakūnu dẖik̊ruhum̊ kakẖam̊ri lub̊nāna."],[14,8,"يَقُولُ أَفْرَايِمُ: مَا لِي أَيْضًا وَلِلْأَصْنَامِ؟ أَنَا قَدْ أَجَبْتُ فَأُلَاحِظُهُ. أَنَا كَسَرْوَةٍ خَضْرَاءَ. مِنْ قِبَلِي يُوجَدُ ثَمَرُكِ».","yaqūlu ạảf̊rāyimu: mā lī ạảẙḍaⁿạ walil̊ạảṣ̊nāmi? ạảnā qad̊ ạảjab̊tu fāủlāḥiẓuhu. ạảnā kasar̊waẗiⁿ kẖaḍ̊rāʾa. min̊ qibalī yūjadu tẖamaruki»."],[14,9,"مَنْ هُوَ حَكِيمٌ حَتَّى يَفْهَمَ هَذِهِ ٱلْأُمُورَ، وَفَهِيمٌ حَتَّى يَعْرِفَهَا! فَإِنَّ طُرُقَ ٱلرَّبِّ مُسْتَقِيمَةٌ، وَٱلْأَبْرَارَ يَسْلُكُونَ فِيهَا، وَأَمَّا ٱلْمُنَافِقُونَ فَيَعْثُرُونَ فِيهَا.","man̊ hūa ḥakīmuⁿ ḥatãy̱ yaf̊hama hadẖihi ٱl̊ạủmūra, wafahīmuⁿ ḥatãy̱ yaʿ̊rifahā! fāi̹nã ṭuruqa ٱlrãbĩ mus̊taqīmaẗuⁿ, waٱl̊ạảb̊rāra yas̊lukūna fīhā, wāảmãạ ٱl̊munāfiqūna fayaʿ̊tẖurūna fīhā."]],"bis-obbr":[[1,1,"Ol tok blong buk ya, Hae God i stap givim long Profet Hosea we papa blong hem Beheri, long taem blong King Usia, mo long taem blong King Jotam, mo long taem blong King Ahas, mo long taem blong King Hesekia, we olgeta i king long Juda,* mo long taem ya we King Jeroboam we papa blong hem King Jehoas, hem i king long Isrel.*","Ol tok blong buk ya, Hae God i stap givim long Profet Hosea we papa blong hem Beheri, long taem blong King Usia, mo long taem blong King Jotam, mo long taem blong King Ahas, mo long taem blong King Hesekia, we olgeta i king long Juda,* mo long taem ya we King Jeroboam we papa blong hem King Jehoas, hem i king long Isrel.*"],[1,2,"Long taem ya we Hae God i stat blong talem ol tok blong hem long Profet Hosea blong i go talemaot long ol man ples blong hem, fas tok we hem i talem long hem, i olsem. Hem i talem se, “Hosea. Yu go, yu mared. Be taem yutufala i mared finis, bambae woman ya blong yu i girap, i go stap mekem i krangke wetem ol narafala man. Mo ol pikinini blong yutufala, fasin blong olgeta bambae i sem mak nomo olsem fasin blong mama blong olgeta. Yu mas tekem wan woman olsem, from we ol man ples blong yu oli lego mi, oli biaen long ol narafala god.”","Long taem ya we Hae God i stat blong talem ol tok blong hem long Profet Hosea blong i go talemaot long ol man ples blong hem, fas tok we hem i talem long hem, i olsem. Hem i talem se, “Hosea. Yu go, yu mared. Be taem yutufala i mared finis, bambae woman ya blong yu i girap, i go stap mekem i krangke wetem ol narafala man. Mo ol pikinini blong yutufala, fasin blong olgeta bambae i sem mak nomo olsem fasin blong mama blong olgeta. Yu mas tekem wan woman olsem, from we ol man ples blong yu oli lego mi, oli biaen long ol narafala god.”"],[1,3,"Nao profet i go tekem wan woman, nem blong hem Goma, we papa blong hem Diblaem, nao i mared long hem. Tufala i stap gogo, nao hem i bonem fasbon pikinini blong tufala we i boe.","Nao profet i go tekem wan woman, nem blong hem Goma, we papa blong hem Diblaem, nao i mared long hem. Tufala i stap gogo, nao hem i bonem fasbon pikinini blong tufala we i boe."],[1,4,"Nao Hae God i talem long profet se, “Yu putum nem blong pikinini ya, se Jisrehel, from we i no longtaem, mi bambae mi givim panis long King Jeroboam ya we i king blong yufala. Bambae mi mi mekem olsem, from we bubu blong hem King Jehu we i king blong Isrel* bifo, hem i kilim tumas man oli ded long bigfala levelples ya Jisrehel long medel blong ol hil. Olgeta we oli laen blong King Jehu ya, mi bambae mi kilim olgeta evriwan oli ded, nao kantri ya Isrel bambae i no moa gat king long hem. Mo long ples ya Jisrehel, bambae mi spolem ol soldia blong yufala tu.”","Nao Hae God i talem long profet se, “Yu putum nem blong pikinini ya, se Jisrehel, from we i no longtaem, mi bambae mi givim panis long King Jeroboam ya we i king blong yufala. Bambae mi mi mekem olsem, from we bubu blong hem King Jehu we i king blong Isrel* bifo, hem i kilim tumas man oli ded long bigfala levelples ya Jisrehel long medel blong ol hil. Olgeta we oli laen blong King Jehu ya, mi bambae mi kilim olgeta evriwan oli ded, nao kantri ya Isrel bambae i no moa gat king long hem. Mo long ples ya Jisrehel, bambae mi spolem ol soldia blong yufala tu.”",5],[1,6,"Nao biaen, Goma i bonem wan gel. Nao Hae God i talem long profet se, “Yu putum nem blong gel ya, se “No Lavem”, from we i no longtaem bambae mi soemaot long ol man ples blong yu we mi no moa lavem olgeta, mo mi mi no save fogivim olgeta from ol sin blong olgeta.","Nao biaen, Goma i bonem wan gel. Nao Hae God i talem long profet se, “Yu putum nem blong gel ya, se “No Lavem”, from we i no longtaem bambae mi soemaot long ol man ples blong yu we mi no moa lavem olgeta, mo mi mi no save fogivim olgeta from ol sin blong olgeta."],[1,7,"Be ol man Juda* ya, bambae mi soemaot long olgeta we mi mi lavem olgeta tumas. Mi Hae God, mi God blong olgeta, mo mi bambae mi sevem olgeta, mi lukaot gud long olgeta. Be bambae mi no save yusum man blong faet, no wan samting blong faet olsem naef, no bonara, no hos mo man blong faet we i ron long hos, blong sevem olgeta. Mi nomo bambae mi sevem olgeta.”","Be ol man Juda* ya, bambae mi soemaot long olgeta we mi mi lavem olgeta tumas. Mi Hae God, mi God blong olgeta, mo mi bambae mi sevem olgeta, mi lukaot gud long olgeta. Be bambae mi no save yusum man blong faet, no wan samting blong faet olsem naef, no bonara, no hos mo man blong faet we i ron long hos, blong sevem olgeta. Mi nomo bambae mi sevem olgeta.”"],[1,8,"Taem dota ya blong tufala i livim titi finis, mama blong hem i gat bel bakegen, nao i bonem wan boe bakegen.","Taem dota ya blong tufala i livim titi finis, mama blong hem i gat bel bakegen, nao i bonem wan boe bakegen."],[1,9,"Nao Hae God i talem long profet se, “Bambae yu putum nem blong boe ya, se “I no Man blong Mi”, from we ol man ples ya blong yu oli no moa man blong mi, mo mi mi no moa God blong olgeta.”","Nao Hae God i talem long profet se, “Bambae yu putum nem blong boe ya, se “I no Man blong Mi”, from we ol man ples ya blong yu oli no moa man blong mi, mo mi mi no moa God blong olgeta.”"],[1,10,"Nao Profet Hosea i talem long ol man Isrel* se, “Olgeta. Bambae yumi kam plante we plante, olsem sanbij long solwota, we man i no save kaontem. Naoia Hae God i stap talem se, ‘Yufala i no moa man blong mi,’ be i gat dei i stap kam we bambae hem i talem long yumi se, ‘Mi mi God we mi laef, mi stap we mi stap, mo yufala i pikinini blong mi.’","Nao Profet Hosea i talem long ol man Isrel* se, “Olgeta. Bambae yumi kam plante we plante, olsem sanbij long solwota, we man i no save kaontem. Naoia Hae God i stap talem se, ‘Yufala i no moa man blong mi,’ be i gat dei i stap kam we bambae hem i talem long yumi se, ‘Mi mi God we mi laef, mi stap we mi stap, mo yufala i pikinini blong mi.’"],[1,11,"Long taem ya, ol man Juda* wetem yumi ol man Isrel bambae yumi evriwan i joen wanples bakegen, nao yumi save jusumaot wan lida nomo blong yumi. Mo ples blong yumi bambae i kam gud bakegen. Dei ya blong Jisrehel hem i wan dei we God bambae i mekem i gud tumas long plante man blong hem.","Long taem ya, ol man Juda* wetem yumi ol man Isrel bambae yumi evriwan i joen wanples bakegen, nao yumi save jusumaot wan lida nomo blong yumi. Mo ples blong yumi bambae i kam gud bakegen. Dei ya blong Jisrehel hem i wan dei we God bambae i mekem i gud tumas long plante man blong hem."],[2,1,"Long taem ya, bambae yumi putum nem blong ol brata blong yumi, se ‘Man blong God’, mo nem blong ol sista blong yumi, se ‘Masta* blong yumi i gat sore’.”","Long taem ya, bambae yumi putum nem blong ol brata blong yumi, se ‘Man blong God’, mo nem blong ol sista blong yumi, se ‘Masta* blong yumi i gat sore’.”"],[2,2,"Nao profet i talemaot we Hae God i talem se, “Ol pikinini blong mi. Yufala i mas krae strong long mama blong yufala blong i jenisim fasin blong hem. Nating we hem i no moa woman blong mi, mo mi tu mi no moa man blong hem, be yufala i mas krae strong long hem blong i lego ol rabis fasin ya blong hem, we i stap slip wetem ol narafala man, mo i stap salem hem olbaot.","Nao profet i talemaot we Hae God i talem se, “Ol pikinini blong mi. Yufala i mas krae strong long mama blong yufala blong i jenisim fasin blong hem. Nating we hem i no moa woman blong mi, mo mi tu mi no moa man blong hem, be yufala i mas krae strong long hem blong i lego ol rabis fasin ya blong hem, we i stap slip wetem ol narafala man, mo i stap salem hem olbaot."],[2,3,"Sipos hem i no lego fasin ya blong hem, bambae mi mi terem olgeta klos blong hem, nao bambae hem i stap neked nomo olsem bifo, taem we hem i jes bon. Mo bambae mi letem hem i kam olsem wan draeples we i no gat wan samting nating long hem, mo bambae i stap tosta gogo i ded from.","Sipos hem i no lego fasin ya blong hem, bambae mi mi terem olgeta klos blong hem, nao bambae hem i stap neked nomo olsem bifo, taem we hem i jes bon. Mo bambae mi letem hem i kam olsem wan draeples we i no gat wan samting nating long hem, mo bambae i stap tosta gogo i ded from."],[2,4,"Bambae mi mi no gat sore long ol narafala pikinini ya we hem i stap bonem, from we mama blong olgeta i woman blong rod, we i no gat sem nating. Hem i stap talem se, ‘Bambae mi mi go luk olgeta ya we oli laekem mi. Olgeta ya oli stap givim kakae mo wota long mi, mo oli stap givim wul mo kaliko, mo olifoel,* mo waen tu long mi.’","Bambae mi mi no gat sore long ol narafala pikinini ya we hem i stap bonem, from we mama blong olgeta i woman blong rod, we i no gat sem nating. Hem i stap talem se, ‘Bambae mi mi go luk olgeta ya we oli laekem mi. Olgeta ya oli stap givim kakae mo wota long mi, mo oli stap givim wul mo kaliko, mo olifoel,* mo waen tu long mi.’",5],[2,6,"“Bambae mi tekem ol ropnil, mi wokem wan fenis i goraon long woman ya, mo bambae mi wokem wan bigfala stonwol i goraon long hem blong blokem hem, blong i no ronwe.","“Bambae mi tekem ol ropnil, mi wokem wan fenis i goraon long woman ya, mo bambae mi wokem wan bigfala stonwol i goraon long hem blong blokem hem, blong i no ronwe."],[2,7,"Sipos hem i wantem ronwe i go long ol man we hem i stap go wetem olgeta, be bambae hem i no save faenem olgeta. Bambae hem i go long evri ples blong traem lukaot olgeta, be neva bambae i save faenem olgeta. Nao biaen, bambae hem i talem se, ‘Naoia bambae mi gobak long stret man blong mi. Laef ya bifo we mi stap wetem hem, i moa gud i winim laef ya we mi stap long hem naoia.’","Sipos hem i wantem ronwe i go long ol man we hem i stap go wetem olgeta, be bambae hem i no save faenem olgeta. Bambae hem i go long evri ples blong traem lukaot olgeta, be neva bambae i save faenem olgeta. Nao biaen, bambae hem i talem se, ‘Naoia bambae mi gobak long stret man blong mi. Laef ya bifo we mi stap wetem hem, i moa gud i winim laef ya we mi stap long hem naoia.’"],[2,8,"“Hem i tok olsem, be neva hem i luksave se ol kakae, mo waen, mo olifoel blong hem, mi nomo mi stap givim olgeta long hem. Mo ol silva, mo gol ya we hem i stap yusum blong mekem wosip long god ya Bal,* be neva hem i save talemaot we mi nomo mi stap givim olgeta long hem.","“Hem i tok olsem, be neva hem i luksave se ol kakae, mo waen, mo olifoel blong hem, mi nomo mi stap givim olgeta long hem. Mo ol silva, mo gol ya we hem i stap yusum blong mekem wosip long god ya Bal,* be neva hem i save talemaot we mi nomo mi stap givim olgeta long hem."],[2,9,"Be long taem blong tekemaot kakae long garen, mi bambae mi tekembak ol kakae blong garen blong hem, wetem ol frut blong plantesen blong grep* blong hem we mi stap givim long hem. Mo ol wul mo linen* ya we hem i stap yusum blong kavremap hem long hem, bambae mi mi tekemaot olgeta evriwan i gowe long hem.","Be long taem blong tekemaot kakae long garen, mi bambae mi tekembak ol kakae blong garen blong hem, wetem ol frut blong plantesen blong grep* blong hem we mi stap givim long hem. Mo ol wul mo linen* ya we hem i stap yusum blong kavremap hem long hem, bambae mi mi tekemaot olgeta evriwan i gowe long hem."],[2,10,"Bambae mi mi tekemaot olgeta klos blong hem long fes blong ol man ya we hem i stap go wetem olgeta, mo bambae i no gat man i save tekemaot hem bakegen long paoa blong mi.","Bambae mi mi tekemaot olgeta klos blong hem long fes blong ol man ya we hem i stap go wetem olgeta, mo bambae i no gat man i save tekemaot hem bakegen long paoa blong mi."],[2,11,"Oltaem hem i stap mekem ol lafet* we i blong mekem evri yia, mo i stap mekem ol Lafet blong Niumun, mo blong Sabat* dei, mo ol narafala lafet olsem blong mekem wosip, be olgeta lafet ya, mi bambae mi blokem evriwan.","Oltaem hem i stap mekem ol lafet* we i blong mekem evri yia, mo i stap mekem ol Lafet blong Niumun, mo blong Sabat* dei, mo ol narafala lafet olsem blong mekem wosip, be olgeta lafet ya, mi bambae mi blokem evriwan."],[2,12,"Ol figtri* blong hem, mo ol plantesen blong grep blong hem, we hem i stap talem se ol man ya oli givim long hem from we hem i stap givhan long olgeta, mi bambae mi spolem olgeta evriwan. Olgeta plantesen ya blong hem, bambae mi mekem i kam olsem draeples, mo ol wael anamol bambae oli spolem olgeta.","Ol figtri* blong hem, mo ol plantesen blong grep blong hem, we hem i stap talem se ol man ya oli givim long hem from we hem i stap givhan long olgeta, mi bambae mi spolem olgeta evriwan. Olgeta plantesen ya blong hem, bambae mi mekem i kam olsem draeples, mo ol wael anamol bambae oli spolem olgeta."],[2,13,"Bambae mi givim panis long hem from we bifo hem i fogetem mi, nao i stap go bonem insens* long god ya Bal blong mekem sakrefaes long hem. Mo oltaem hem i stap putum ol gudgudfala samting blong flasem hem, nao i stap go biaen long ol man blong hem. Mi mi Hae God, mo hemia tok blong mi.”","Bambae mi givim panis long hem from we bifo hem i fogetem mi, nao i stap go bonem insens* long god ya Bal blong mekem sakrefaes long hem. Mo oltaem hem i stap putum ol gudgudfala samting blong flasem hem, nao i stap go biaen long ol man blong hem. Mi mi Hae God, mo hemia tok blong mi.”"],[2,14,"Nao Profet Hosea i talemaot we Hae God i talem se, “Naoia bambae mi tekem woman ya blong mi i gobak long draeples bakegen. Long ples ya, bambae mi save toktok gud long hem, blong pulum tingting blong hem i kambak long mi bakegen.","Nao Profet Hosea i talemaot we Hae God i talem se, “Naoia bambae mi tekem woman ya blong mi i gobak long draeples bakegen. Long ples ya, bambae mi save toktok gud long hem, blong pulum tingting blong hem i kambak long mi bakegen."],[2,15,"Ol plantesen blong grep* ya blong hem, we mi tekemaot long hem bifo, bambae mi givim i gobak long hem bakegen. Mo ol rabis fasin ya blong hem we i olsem rod we i pastru long medel blong ol hil, we i ples blong kasem trabol, bambae mi mekem i kam olsem get blong gudfala rod, we i ples blong mekem tingting i strong blong kasem ol gudgudfala samting bakegen. Nao sipos mi talem sam samting long hem, hem bambae i save lesin gud long mi olsem we hem i stap lesin long mi bifo, long taem ya we hem i yangfala yet, mo hem i aot long Ijip i kam.","Ol plantesen blong grep* ya blong hem, we mi tekemaot long hem bifo, bambae mi givim i gobak long hem bakegen. Mo ol rabis fasin ya blong hem we i olsem rod we i pastru long medel blong ol hil, we i ples blong kasem trabol, bambae mi mekem i kam olsem get blong gudfala rod, we i ples blong mekem tingting i strong blong kasem ol gudgudfala samting bakegen. Nao sipos mi talem sam samting long hem, hem bambae i save lesin gud long mi olsem we hem i stap lesin long mi bifo, long taem ya we hem i yangfala yet, mo hem i aot long Ijip i kam."],[2,16,"Nao bambae hem i save singaot mi, se ‘Yu yu man blong mi’. Bambae hem i no moa save singaot mi long nem blong god ya Bal,* se ‘Yu yu Bal blong mi’, olsem we i stap mekem fastaem.","Nao bambae hem i save singaot mi, se ‘Yu yu man blong mi’. Bambae hem i no moa save singaot mi long nem blong god ya Bal,* se ‘Yu yu Bal blong mi’, olsem we i stap mekem fastaem."],[2,17,"Bambae mi blokem hem blong hem i no moa save talem nem blong god ya Bal bakegen samtaem.","Bambae mi blokem hem blong hem i no moa save talem nem blong god ya Bal bakegen samtaem."],[2,18,"“Ol man blong mi. Long taem ya, mi bambae mi mekem promes wetem ol wael anamol, mo ol pijin, blong oli no moa kam spolem yufala. Mo olgeta samting blong faet, we ol man i stap yusum long ples ya, mi bambae mi spolem evriwan. Bambae mi mekem yufala i stap gud, mo yufala i gat pis long ples blong yufala.","“Ol man blong mi. Long taem ya, mi bambae mi mekem promes wetem ol wael anamol, mo ol pijin, blong oli no moa kam spolem yufala. Mo olgeta samting blong faet, we ol man i stap yusum long ples ya, mi bambae mi spolem evriwan. Bambae mi mekem yufala i stap gud, mo yufala i gat pis long ples blong yufala."],[2,19,"“Ol man Isrel.* Mi bambae mi save singaot yufala, se ‘Yufala i woman blong mi’. Oltaem tingting blong mi bambae i stap strong long yufala, bambae mi no save lego yufala samtaem. Mi bambae mi soemaot long yufala we oltaem mi mi lavem yufala tumas, mo mi gat sore long yufala. Bambae yufala i woman blong mi olwe, gogo i no save finis.","“Ol man Isrel.* Mi bambae mi save singaot yufala, se ‘Yufala i woman blong mi’. Oltaem tingting blong mi bambae i stap strong long yufala, bambae mi no save lego yufala samtaem. Mi bambae mi soemaot long yufala we oltaem mi mi lavem yufala tumas, mo mi gat sore long yufala. Bambae yufala i woman blong mi olwe, gogo i no save finis."],[2,20,"Promes* ya we mi mekem wetem yufala, bambae mi holemstrong, mi no save brekem. Mo bambae yufala i savegud mi, yufala i save talemaot we mi mi Hae God blong yufala.","Promes* ya we mi mekem wetem yufala, bambae mi holemstrong, mi no save brekem. Mo bambae yufala i savegud mi, yufala i save talemaot we mi mi Hae God blong yufala."],[2,21,"Long taem ya, taem yufala i prea long mi, mi bambae mi save harem yufala. Nao mi bambae mi sanem ren i kam, mo ol garen blong yufala bambae i karem plante kakae, mo bambae yufala i kasem plante waen mo oel long ol plantesen blong yufala.","Long taem ya, taem yufala i prea long mi, mi bambae mi save harem yufala. Nao mi bambae mi sanem ren i kam, mo ol garen blong yufala bambae i karem plante kakae, mo bambae yufala i kasem plante waen mo oel long ol plantesen blong yufala.",22],[2,23,"Bambae mi mekem yufala i stap gud long ples ya, we yufala i gat plante samting. Bifo, mi mi stap singaot yufala, se ‘No Lavem’, be bambae mi soemaot long yufala we mi lavem yufala tumas. Fastaem yufala i gat nem ya, se ‘I No Man Blong Mi’, be bambae mi mi talem long yufala se, ‘Yufala i man blong mi.’ Mo bambae yufala i save talem long mi se, ‘Yu yu God blong mifala.’ ”","Bambae mi mekem yufala i stap gud long ples ya, we yufala i gat plante samting. Bifo, mi mi stap singaot yufala, se ‘No Lavem’, be bambae mi soemaot long yufala we mi lavem yufala tumas. Fastaem yufala i gat nem ya, se ‘I No Man Blong Mi’, be bambae mi mi talem long yufala se, ‘Yufala i man blong mi.’ Mo bambae yufala i save talem long mi se, ‘Yu yu God blong mifala.’ ”"],[3,1,"Nao Profet Hosea i talemaot we Hae God i talem long hem se, “Hosea. Yu go luk woman blong yu bakegen. Nating we hem i stap mekem i krangke wetem narafala man, be yu mas soemaotgud long hem we yu yu lavem hem. Yu mas lavem hem mo yu mas mekem i gud long hem, stret olsem we mi mi lavem yufala. Nating we ol man ples blong yu oli stap folem ol narafala god, mo oli stap tekem ol grep* we oli sandrae long hem, oli givim i go long olgeta olsem presen blong olgeta, be mi mi stap lavem yufala yet, mo oltaem mi stap mekem i gud tumas long yufala.”","Nao Profet Hosea i talemaot we Hae God i talem long hem se, “Hosea. Yu go luk woman blong yu bakegen. Nating we hem i stap mekem i krangke wetem narafala man, be yu mas soemaotgud long hem we yu yu lavem hem. Yu mas lavem hem mo yu mas mekem i gud long hem, stret olsem we mi mi lavem yufala. Nating we ol man ples blong yu oli stap folem ol narafala god, mo oli stap tekem ol grep* we oli sandrae long hem, oli givim i go long olgeta olsem presen blong olgeta, be mi mi stap lavem yufala yet, mo oltaem mi stap mekem i gud tumas long yufala.”"],[3,2,"Nao profet i talem se, “Nao mi tekem seven taosen faef handred vatu* wetem wan handred fifti kilo bale,* nao mi go pemaot woman ya bakegen, i blong mi.","Nao profet i talem se, “Nao mi tekem seven taosen faef handred vatu* wetem wan handred fifti kilo bale,* nao mi go pemaot woman ya bakegen, i blong mi."],[3,3,"Nao mi talem long hem, se hem i mas lego fasin ya blong hem, we i stap mekem i krangke wetem ol narafala man, mo i stap salem hem olbaot, mo i mas wet long mi longtaem, we i stap kwaet nomo, mo mi promes long hem, se long taem ya, mi bambae mi stap wet long hem.","Nao mi talem long hem, se hem i mas lego fasin ya blong hem, we i stap mekem i krangke wetem ol narafala man, mo i stap salem hem olbaot, mo i mas wet long mi longtaem, we i stap kwaet nomo, mo mi promes long hem, se long taem ya, mi bambae mi stap wet long hem."],[3,4,"“Olgeta. Long sem fasin, bambae yumi mas stap longtaem lelebet, we bambae yumi no moa gat king blong yumi, no lida blong yumi. Mo bambae yufala i stap we yufala i no moa mekem sakrefaes long ol narafala god, mo yufala i no moa stanemap ol longlongfala ston blong mekem wosip long olgeta, mo we yufala i no moa yusum ol aedol, mo ol narafala samting blong traem faenemaot ol samting we bambae i kamtru. Olgeta fasin ya bambae i mas finis evriwan.","“Olgeta. Long sem fasin, bambae yumi mas stap longtaem lelebet, we bambae yumi no moa gat king blong yumi, no lida blong yumi. Mo bambae yufala i stap we yufala i no moa mekem sakrefaes long ol narafala god, mo yufala i no moa stanemap ol longlongfala ston blong mekem wosip long olgeta, mo we yufala i no moa yusum ol aedol, mo ol narafala samting blong traem faenemaot ol samting we bambae i kamtru. Olgeta fasin ya bambae i mas finis evriwan."],[3,5,"Mo biaen, bambae yufala i tanem tingting blong yufala, yufala i kambak long Hae God bakegen, from we hem nao i God blong yumi. Mo bambae yufala i kambak tu long man we i laen blong King Deved ya bifo, blong hem i king blong yumi. Nao bambae yumi ona gud long Hae God, mo bambae yumi glad blong karem ol presen we hem i givim long yumi.”","Mo biaen, bambae yufala i tanem tingting blong yufala, yufala i kambak long Hae God bakegen, from we hem nao i God blong yumi. Mo bambae yufala i kambak tu long man we i laen blong King Deved ya bifo, blong hem i king blong yumi. Nao bambae yumi ona gud long Hae God, mo bambae yumi glad blong karem ol presen we hem i givim long yumi.”"],[4,1,"Bakegen Profet Hosea i talem long ol man Isrel* se, “Olgeta. Hae God i gat poen finis blong talemaot agens long yufala. Yufala i mas lesin long tok blong hem. Hem i tok long yufala, i talem se, ‘Yufala blong kantri ya, tingting blong yufala i olbaot. Fasin blong holem promes mo fasin blong lavem man i no gat nating long yufala, mo yufala i no save nating we mi mi God.","Bakegen Profet Hosea i talem long ol man Isrel* se, “Olgeta. Hae God i gat poen finis blong talemaot agens long yufala. Yufala i mas lesin long tok blong hem. Hem i tok long yufala, i talem se, ‘Yufala blong kantri ya, tingting blong yufala i olbaot. Fasin blong holem promes mo fasin blong lavem man i no gat nating long yufala, mo yufala i no save nating we mi mi God."],[4,2,"Oltaem yufala i stap mekem promes, be yufala nomo i stap brekem ol promes ya bakegen. Yufala i man blong giaman, yufala i man blong kilim man i ded, yufala i man blong stil, mo yufala i man blong stilim woman blong narafala man. Fasin ya blong brekem loa i stap kam bigwan tumas long ples ya, mo fasin ya blong kilim man i ded i no finis nating long yufala.","Oltaem yufala i stap mekem promes, be yufala nomo i stap brekem ol promes ya bakegen. Yufala i man blong giaman, yufala i man blong kilim man i ded, yufala i man blong stil, mo yufala i man blong stilim woman blong narafala man. Fasin ya blong brekem loa i stap kam bigwan tumas long ples ya, mo fasin ya blong kilim man i ded i no finis nating long yufala."],[4,3,"Nao from samting ya, bambae mi mekem evri samting long ples ya i kam drae, mo olgeta samting we i stap long hem bambae oli ded. Olgeta anamol wetem ol pijin mo ol fis we oli stap long ples ya bambae oli ded evriwan.’ ”","Nao from samting ya, bambae mi mekem evri samting long ples ya i kam drae, mo olgeta samting we i stap long hem bambae oli ded. Olgeta anamol wetem ol pijin mo ol fis we oli stap long ples ya bambae oli ded evriwan.’ ”"],[4,4,"Mo Profet Hosea i gohed i talemaot we Hae God i talem se, “Yufala ol pris.* I nogud yufala i stap tok nogud long ol man ya, mo i nogud yufala i stap jajem olgeta. Mi mi gat poen agens long yufala we i bigwan moa.","Mo Profet Hosea i gohed i talemaot we Hae God i talem se, “Yufala ol pris.* I nogud yufala i stap tok nogud long ol man ya, mo i nogud yufala i stap jajem olgeta. Mi mi gat poen agens long yufala we i bigwan moa."],[4,5,"Oltaem, long dei mo long naet, yufala i stap wokbaot olsem we yufala i stap long tudak, mo ol profet tu oli sem mak nomo long yufala. Naoia bambae mi flatemgud kantri ya Isrel,* we i olsem mama blong yufala.","Oltaem, long dei mo long naet, yufala i stap wokbaot olsem we yufala i stap long tudak, mo ol profet tu oli sem mak nomo long yufala. Naoia bambae mi flatemgud kantri ya Isrel,* we i olsem mama blong yufala."],[4,6,"Ol man ya blong mi, bambae oli go lus, from we oli no save mi. Be yufala ol pris, yufala i mowas olgeta. Yufala i no wantem save mi nating. Yufala i tanem baksaed long mi, mo yufala i no save harem ol tok blong mi we mi stap tijim yufala long hem. Nao from samting ya, mi mi tanem baksaed long yufala, yufala i no moa pris blong mi, mo bambae mi no moa save makem ol pikinini blong yufala se oli pris blong mi.","Ol man ya blong mi, bambae oli go lus, from we oli no save mi. Be yufala ol pris, yufala i mowas olgeta. Yufala i no wantem save mi nating. Yufala i tanem baksaed long mi, mo yufala i no save harem ol tok blong mi we mi stap tijim yufala long hem. Nao from samting ya, mi mi tanem baksaed long yufala, yufala i no moa pris blong mi, mo bambae mi no moa save makem ol pikinini blong yufala se oli pris blong mi."],[4,7,"“Ol pris. Taem yufala i stap kam plante moa, be fasin blong yufala blong mekem sin agens long mi i stap kam mowas olgeta. Yufala i gat hae nem, be bambae mi mekem yufala i sem bigwan.","“Ol pris. Taem yufala i stap kam plante moa, be fasin blong yufala blong mekem sin agens long mi i stap kam mowas olgeta. Yufala i gat hae nem, be bambae mi mekem yufala i sem bigwan."],[4,8,"Taem ol man blong mi oli mekem sin, yufala i stap winim mane from, mo taem yufala i luk we oli mekem olsem, be yufala i glad nomo.","Taem ol man blong mi oli mekem sin, yufala i stap winim mane from, mo taem yufala i luk we oli mekem olsem, be yufala i glad nomo."],[4,9,"Panis blong yufala, bambae i sem mak nomo long panis blong olgeta. Bambae mi mas panisim yufala from ol rabis fasin ya we yufala i stap mekem.","Panis blong yufala, bambae i sem mak nomo long panis blong olgeta. Bambae mi mas panisim yufala from ol rabis fasin ya we yufala i stap mekem."],[4,10,"Nating we yufala i stap kakae haf blong ol mit ya we yufala i stap bonem blong mekem sakrefaes, be neva bambae yufala i save fulap long hem, oltaem nomo bambae yufala i stap hanggri. Mo bambae yufala i stap mekem wosip long ol narafala god ya we ol man oli talem se oli stap mekem woman i bonem pikinini, be neva bambae yufala i gat plante pikinini, from we yufala i tanem baksaed finis long mi blong go biaen long ol narafala god ya.”","Nating we yufala i stap kakae haf blong ol mit ya we yufala i stap bonem blong mekem sakrefaes, be neva bambae yufala i save fulap long hem, oltaem nomo bambae yufala i stap hanggri. Mo bambae yufala i stap mekem wosip long ol narafala god ya we ol man oli talem se oli stap mekem woman i bonem pikinini, be neva bambae yufala i gat plante pikinini, from we yufala i tanem baksaed finis long mi blong go biaen long ol narafala god ya.”"],[4,11,"Mo Profet Hosea i talemaot bakegen we Hae God i talem se, “!Ol man blong mi! Ol waen ya we yufala i stap dring, nating we i olfala, no i niuwan yet, be i stap mekem hed blong yufala i krangke nomo.","Mo Profet Hosea i talemaot bakegen we Hae God i talem se, “!Ol man blong mi! Ol waen ya we yufala i stap dring, nating we i olfala, no i niuwan yet, be i stap mekem hed blong yufala i krangke nomo."],[4,12,"Yufala i stap askem long wan wud nomo we yufala i stanemap, blong i soemaot mining blong ol drim blong yufala, nao yufala i stap talem se wud ya i stap soemaot ol samting long yufala we yufala i wantem save. Yufala i lego mi finis, olsem woman we i lego man blong hem, i stap salem hem olbaot. Yufala i mekem ol narafala god ya oli kam bos blong yufala.","Yufala i stap askem long wan wud nomo we yufala i stanemap, blong i soemaot mining blong ol drim blong yufala, nao yufala i stap talem se wud ya i stap soemaot ol samting long yufala we yufala i wantem save. Yufala i lego mi finis, olsem woman we i lego man blong hem, i stap salem hem olbaot. Yufala i mekem ol narafala god ya oli kam bos blong yufala."],[4,13,"Yufala i stap go long ol tabu ples antap long ol bigfala hil, yufala i mekem sakrefaes long ol god ya. Mo antap long ol smosmol hil, yufala i stap bonem insens* long olgeta aninit long ol bigbigfala tri olbaot, we sed blong olgeta i gud tumas. “Nao from we yufala i stap mekem olsem, taswe ol gel blong yufala oli stap salem olgeta olbaot, mo ol woman blong ol pikinini blong yufala oli ronwe, oli go biaen long ol narafala man.","Yufala i stap go long ol tabu ples antap long ol bigfala hil, yufala i mekem sakrefaes long ol god ya. Mo antap long ol smosmol hil, yufala i stap bonem insens* long olgeta aninit long ol bigbigfala tri olbaot, we sed blong olgeta i gud tumas. “Nao from we yufala i stap mekem olsem, taswe ol gel blong yufala oli stap salem olgeta olbaot, mo ol woman blong ol pikinini blong yufala oli ronwe, oli go biaen long ol narafala man."],[4,14,"Be mi mi no save givim panis long olgeta, from we yufala nao i stamba blong samting ya. Yufala i stap go long ol haos blong ol narafala god ya, yufala i stap slip wetem ol woman pris blong olgeta, mo yufala i stap joen wetem ol pris ya blong mekem sakrefaes long ol god ya. I olsem wan tok we i talem se, ‘Ol man blong wan kantri we oli no gat tingting, bambae oli lus.’","Be mi mi no save givim panis long olgeta, from we yufala nao i stamba blong samting ya. Yufala i stap go long ol haos blong ol narafala god ya, yufala i stap slip wetem ol woman pris blong olgeta, mo yufala i stap joen wetem ol pris ya blong mekem sakrefaes long ol god ya. I olsem wan tok we i talem se, ‘Ol man blong wan kantri we oli no gat tingting, bambae oli lus.’"],[4,15,"“Ol man Juda.* Nating we ol man Isrel* ya oli ronwe long mi blong go lukaot ol narafala god, be yufala i no mas folem fasin blong olgeta. Bambae yufala i no mas go long Gilgal, mo long Betaven, blong mekem wosip long ol narafala god, mo blong mekem promes long olgeta se, ‘Hae God i laef, i stap we i stap, mo mifala i mekem promes ya long nem blong hem.’","“Ol man Juda.* Nating we ol man Isrel* ya oli ronwe long mi blong go lukaot ol narafala god, be yufala i no mas folem fasin blong olgeta. Bambae yufala i no mas go long Gilgal, mo long Betaven, blong mekem wosip long ol narafala god, mo blong mekem promes long olgeta se, ‘Hae God i laef, i stap we i stap, mo mifala i mekem promes ya long nem blong hem.’"],[4,16,"Ol man Isrel ya, hed blong olgeta i strong tumas, olsem ston. ?Bambae mi lukaot gud long olgeta olsem wanem? Mi wantem givhan gud long olgeta, olsem we man i stap givim gudfala kakae long ol pikinini blong sipsip, be oli no wantem.","Ol man Isrel ya, hed blong olgeta i strong tumas, olsem ston. ?Bambae mi lukaot gud long olgeta olsem wanem? Mi wantem givhan gud long olgeta, olsem we man i stap givim gudfala kakae long ol pikinini blong sipsip, be oli no wantem."],[4,17,"Oli stap finis long han blong ol narafala god ya. I moa gud oli gohed blong folem olgeta olsem we oli wantem.","Oli stap finis long han blong ol narafala god ya. I moa gud oli gohed blong folem olgeta olsem we oli wantem."],[4,18,"Taem oli stap dring waen, oli wantem tumas blong lukaot ol woman blong rod. Oli wantem mekem ol fasin blong sem nomo, i winim we oli wantem mekem stret fasin we man i save ona long olgeta from.","Taem oli stap dring waen, oli wantem tumas blong lukaot ol woman blong rod. Oli wantem mekem ol fasin blong sem nomo, i winim we oli wantem mekem stret fasin we man i save ona long olgeta from."],[4,19,"Olgeta ya bambae oli go lus, olsem doti we win i blu long hem, mo bambae oli sem long ol sakrefaes ya we oli stap mekem long ol narafala god ya.","Olgeta ya bambae oli go lus, olsem doti we win i blu long hem, mo bambae oli sem long ol sakrefaes ya we oli stap mekem long ol narafala god ya."],[5,1,"“Ol man Isrel. !Yufala i lesin! !Ol pris*! !Yufala i lesin long ol tok ya! !Ol famle blong king! !Yufala i harem tok ya blong mi! Wok blong yufala i blong jajem man long stret fasin, be yufala i no mekem nating. Nao from samting ya, i stret blong mi mi givim panis long yufala from ol rabis fasin ya blong yufala. Long ples ya Mispa, fasin blong yufala i olsem trap we i stap holem ol man, mo long bigfala hil ya Taboro, i olsem net we i hang long ples ya, blong ol man oli stap fas long hem.","“Ol man Isrel. !Yufala i lesin! !Ol pris*! !Yufala i lesin long ol tok ya! !Ol famle blong king! !Yufala i harem tok ya blong mi! Wok blong yufala i blong jajem man long stret fasin, be yufala i no mekem nating. Nao from samting ya, i stret blong mi mi givim panis long yufala from ol rabis fasin ya blong yufala. Long ples ya Mispa, fasin blong yufala i olsem trap we i stap holem ol man, mo long bigfala hil ya Taboro, i olsem net we i hang long ples ya, blong ol man oli stap fas long hem."],[5,2,"Mo long taon ya Kasis, fasin ya i olsem bigfala hol we ol man oli stap foldaon long hem. Bambae mi panisim yufala evriwan from ol rabis fasin ya we yufala i stap mekem.","Mo long taon ya Kasis, fasin ya i olsem bigfala hol we ol man oli stap foldaon long hem. Bambae mi panisim yufala evriwan from ol rabis fasin ya we yufala i stap mekem."],[5,3,"Mi mi savegud yufala. Yufala i no save haed nating long fes blong mi. Yufala i no moa stret blong mekem wosip long mi, from we yufala i lego mi finis blong biaen long ol narafala god.”","Mi mi savegud yufala. Yufala i no save haed nating long fes blong mi. Yufala i no moa stret blong mekem wosip long mi, from we yufala i lego mi finis blong biaen long ol narafala god.”"],[5,4,"Nao Profet Hosea i talemaot long ol man Isrel* we Hae God i talem se, “Mi mi Hae God, mo yufala i man blong mi, be yufala i no save kambak long mi, from we ol rabis fasin blong yufala i stap blokem yufala. Fasin blong mekem wosip long ol narafala god ya i fulap gud long tingting blong yufala, nao from samting ya yufala i no moa luksave se mi mi Hae God.","Nao Profet Hosea i talemaot long ol man Isrel* we Hae God i talem se, “Mi mi Hae God, mo yufala i man blong mi, be yufala i no save kambak long mi, from we ol rabis fasin blong yufala i stap blokem yufala. Fasin blong mekem wosip long ol narafala god ya i fulap gud long tingting blong yufala, nao from samting ya yufala i no moa luksave se mi mi Hae God."],[5,5,"Fasin ya we tingting blong yufala i go antap tumas bambae i stap jajem yufala bakegen. Mo ol sin blong yufala i stap mekem yufala i stambol, yufala i stap folfoldaon. Mo ol man Juda* oli folem fasin blong yufala, nao olgeta tu oli foldaon.","Fasin ya we tingting blong yufala i go antap tumas bambae i stap jajem yufala bakegen. Mo ol sin blong yufala i stap mekem yufala i stambol, yufala i stap folfoldaon. Mo ol man Juda* oli folem fasin blong yufala, nao olgeta tu oli foldaon."],[5,6,"Yufala i stap tekem ol sipsip mo ol buluk blong yufala i kam, mo yufala i bonem blong mekem sakrefaes long mi, be yufala i no save faenem mi, from we mi mi lego yufala finis.","Yufala i stap tekem ol sipsip mo ol buluk blong yufala i kam, mo yufala i bonem blong mekem sakrefaes long mi, be yufala i no save faenem mi, from we mi mi lego yufala finis."],[5,7,"Tingting blong yufala i no stap strong long mi nating. Yufala i ronwe long mi, yufala i go stap wetem ol narafala god ya, nao ol pikinini blong yufala oli pikinini blong rod nomo. From samting ya, bambae i no longtaem, mi mi spolem kantri ya blong yufala.”","Tingting blong yufala i no stap strong long mi nating. Yufala i ronwe long mi, yufala i go stap wetem ol narafala god ya, nao ol pikinini blong yufala oli pikinini blong rod nomo. From samting ya, bambae i no longtaem, mi mi spolem kantri ya blong yufala.”"],[5,8,"Mo Profet Hosea i talemaot bakegen we Hae God i talem se, “Ol laen* blong Benjamin.* Yufala i mas rere blong go mekem faet. Yufala i mas blu pupu, blong ol man Gibea oli kam. Mo yufala i mas blu long trampet blong ol man Rama oli harem, oli kam. Yufala i mas sanem tok i go long ol man Betaven, blong oli kam joen wetem yufala.","Mo Profet Hosea i talemaot bakegen we Hae God i talem se, “Ol laen* blong Benjamin.* Yufala i mas rere blong go mekem faet. Yufala i mas blu pupu, blong ol man Gibea oli kam. Mo yufala i mas blu long trampet blong ol man Rama oli harem, oli kam. Yufala i mas sanem tok i go long ol man Betaven, blong oli kam joen wetem yufala."],[5,9,"Ol man Isrel.* I gat dei blong yufala i stap kam, we mi bambae mi panisim yufala long hem, mo long dei ya, bambae mi mi spolemgud yufala. Mi talem stret long yufala, se dei ya bambae i mas kamtru.","Ol man Isrel.* I gat dei blong yufala i stap kam, we mi bambae mi panisim yufala long hem, mo long dei ya, bambae mi mi spolemgud yufala. Mi talem stret long yufala, se dei ya bambae i mas kamtru."],[5,10,"“Mo mi mi kros tu long ol lida blong Juda,* from we oli kam insaed long ples blong yufala, nao oli stilim graon blong yufala. Panis we olgeta ya bambae oli kasem, bambae mi letem i kam bigwan long olgeta olsem reva we i ron bigwan.","“Mo mi mi kros tu long ol lida blong Juda,* from we oli kam insaed long ples blong yufala, nao oli stilim graon blong yufala. Panis we olgeta ya bambae oli kasem, bambae mi letem i kam bigwan long olgeta olsem reva we i ron bigwan."],[5,11,"Naoia yufala i stap harem nogud tumas, from we yufala i lusum graon ya we i blong yufala stret. Be yufala i lusum from we yufala i mekem hed, yufala i stap folem tumas ol man ya we oli no gat paoa blong givhan long yufala.","Naoia yufala i stap harem nogud tumas, from we yufala i lusum graon ya we i blong yufala stret. Be yufala i lusum from we yufala i mekem hed, yufala i stap folem tumas ol man ya we oli no gat paoa blong givhan long yufala."],[5,12,"Bambae mi spolemgud ples blong yufala, mo mi mekem ples blong ol man Juda tu i kam nogud olgeta.","Bambae mi spolemgud ples blong yufala, mo mi mekem ples blong ol man Juda tu i kam nogud olgeta."],[5,13,"“Taem yufala i luk we sik i kasem kantri blong yufala, mo ol man Juda oli luk we kantri blong olgeta i gat fulap soa long hem, yufala i girap, yufala i go long Asiria, yufala i askem long king blong ples ya blong i givhan long yufala. Be hem i no save tekemaot sik ya blong yufala, mo i no save mekem ol soa blong Juda i kam gud bakegen tu.","“Taem yufala i luk we sik i kasem kantri blong yufala, mo ol man Juda oli luk we kantri blong olgeta i gat fulap soa long hem, yufala i girap, yufala i go long Asiria, yufala i askem long king blong ples ya blong i givhan long yufala. Be hem i no save tekemaot sik ya blong yufala, mo i no save mekem ol soa blong Juda i kam gud bakegen tu."],[5,14,"Bambae mi mi kam spolemgud yufala, mo bambae mi spolem ol man Juda tu. Bambae mi kakae yufala evriwan olsem laeon, we bambae mi tereterem yufala long ol smosmol pis, mi livim yufala i stap. Mo taem mi kam blong pulum yufala i go, bambae i no gat man i save sevem yufala.","Bambae mi mi kam spolemgud yufala, mo bambae mi spolem ol man Juda tu. Bambae mi kakae yufala evriwan olsem laeon, we bambae mi tereterem yufala long ol smosmol pis, mi livim yufala i stap. Mo taem mi kam blong pulum yufala i go, bambae i no gat man i save sevem yufala."],[5,15,"“Nating we yufala i man blong mi, be bambae mi mi lego yufala, mi livim yufala i stap harem nogud longtaem from ol sin ya blong yufala, gogo yufala i save girap, yufala i save kam lukaot mi bakegen. Taem we yufala i stap harem nogud tumas olsem, hemia bambae i save mekem yufala i kam lukaot mi bakegen.”","“Nating we yufala i man blong mi, be bambae mi mi lego yufala, mi livim yufala i stap harem nogud longtaem from ol sin ya blong yufala, gogo yufala i save girap, yufala i save kam lukaot mi bakegen. Taem we yufala i stap harem nogud tumas olsem, hemia bambae i save mekem yufala i kam lukaot mi bakegen.”"],[6,1,"Nao ol laen* blong Isrel* oli talem se, “Olgeta. I moa gud yumi gobak long Hae God. Hem nao i tekem sik ya i kam spolem yumi, be hem bambae i save tekemaot long yumi, blong yumi kam gud bakegen. Hem nomo i mekem yumi gat ol soa ya, be bambae hem i save mekem ol soa ya i kam gud bakegen.","Nao ol laen* blong Isrel* oli talem se, “Olgeta. I moa gud yumi gobak long Hae God. Hem nao i tekem sik ya i kam spolem yumi, be hem bambae i save tekemaot long yumi, blong yumi kam gud bakegen. Hem nomo i mekem yumi gat ol soa ya, be bambae hem i save mekem ol soa ya i kam gud bakegen."],[6,2,"Sipos yumi mekem olsem, long tutri dei, hem bambae i tekembak yumi, nao bambae yumi stap wetem hem oltaem.","Sipos yumi mekem olsem, long tutri dei, hem bambae i tekembak yumi, nao bambae yumi stap wetem hem oltaem."],[6,3,"Naoia yumi mas traehad blong save hem. Bambae hem i mas kamtru long yumi, olsem we san i stap kamtru long eli moning. Bambae hem i kam mekem laef blong yumi i kam gud bakegen, stret olsem we ren i kam long taem blong planem garen, blong mekem graon i wetwet gud.”","Naoia yumi mas traehad blong save hem. Bambae hem i mas kamtru long yumi, olsem we san i stap kamtru long eli moning. Bambae hem i kam mekem laef blong yumi i kam gud bakegen, stret olsem we ren i kam long taem blong planem garen, blong mekem graon i wetwet gud.”"],[6,4,"Be Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel, mo ol man Juda.* ?Bambae mi mekem olsem wanem long yufala? Fasin blong yufala blong lavem mi i blong wan dei nomo, i stap lus olsem smok blong hil long eli moning. Hem i olsem wota blong naet, we taem san i girap, be kwiktaem nomo i mekem i kam drae.","Be Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel, mo ol man Juda.* ?Bambae mi mekem olsem wanem long yufala? Fasin blong yufala blong lavem mi i blong wan dei nomo, i stap lus olsem smok blong hil long eli moning. Hem i olsem wota blong naet, we taem san i girap, be kwiktaem nomo i mekem i kam drae."],[6,5,"From samting ya, mi mi bin sanem ol profet blong mi i kam, blong oli talemaot tok blong mi, se bambae mi jajem yufala, mi panisim yufala. Fasin we mi wantem tumas blong yufala i mekem, hem i stap long klia ples nomo.","From samting ya, mi mi bin sanem ol profet blong mi i kam, blong oli talemaot tok blong mi, se bambae mi jajem yufala, mi panisim yufala. Fasin we mi wantem tumas blong yufala i mekem, hem i stap long klia ples nomo."],[6,6,"Mi mi no wantem fasin ya we yufala i stap kilim anamol blong mekem sakrefaes long mi, mi wantem we oltaem, yufala i stap lavem mi. Mi wantem we yufala i save mi long laef blong yufala. Fasin ya i gud tumas long mi, i winim we yufala i stap bonem sakrefaes blong givim presen i kam long mi.","Mi mi no wantem fasin ya we yufala i stap kilim anamol blong mekem sakrefaes long mi, mi wantem we oltaem, yufala i stap lavem mi. Mi wantem we yufala i save mi long laef blong yufala. Fasin ya i gud tumas long mi, i winim we yufala i stap bonem sakrefaes blong givim presen i kam long mi."],[6,7,"“Taem ol bubu blong yufala bifo oli kamtru long kantri ya long taon ya Adam, oli brekem promes* blong mi we mi mi mekem wetem olgeta.","“Taem ol bubu blong yufala bifo oli kamtru long kantri ya long taon ya Adam, oli brekem promes* blong mi we mi mi mekem wetem olgeta."],[6,8,"Mo naoia taon ya Gilead i fulap gud long ol man nogud, mo ol man blong kilim man i ded.","Mo naoia taon ya Gilead i fulap gud long ol man nogud, mo ol man blong kilim man i ded."],[6,9,"Ol pris blong olgeta oli olsem ol man blong stil, we oltaem oli stap haed long saed blong rod blong kilim man. Oli stap kilim man i ded long rod we i pas i go long tabu ples ya Sekem. Oli stap mekem ol rabis fasin ya we oli no gat sem nating.","Ol pris blong olgeta oli olsem ol man blong stil, we oltaem oli stap haed long saed blong rod blong kilim man. Oli stap kilim man i ded long rod we i pas i go long tabu ples ya Sekem. Oli stap mekem ol rabis fasin ya we oli no gat sem nating."],[6,10,"Mi mi luk finis we i gat wan fasin we i nogud we i nogud, we ol man Isrel oli stap mekem. Olgeta ya oli man blong mi, be oli lego mi, mo oli stap mekem wosip long ol narafala god, nao oli kam doti long fes blong mi.","Mi mi luk finis we i gat wan fasin we i nogud we i nogud, we ol man Isrel oli stap mekem. Olgeta ya oli man blong mi, be oli lego mi, mo oli stap mekem wosip long ol narafala god, nao oli kam doti long fes blong mi."],[6,11,"“Ol man Juda. Yufala tu, mi mi makem taem blong yufala finis blong panisim yufala, from ol samting nogud ya we yufala i stap mekem.","“Ol man Juda. Yufala tu, mi mi makem taem blong yufala finis blong panisim yufala, from ol samting nogud ya we yufala i stap mekem."],[7,1,"“Ol man Isrel. Yufala i man blong mi, mo mi mi wantem tumas blong mekem yufala i kam gud bakegen, blong laef blong yufala i gohed gud, mo yufala i kam rijman. Be oltaem, taem mi lukluk i kam long yufala, mi stap luk ol sin blong yufala nomo. Oltaem nomo yufala i stap ravravem yufala, mo yufala i stap go insaed long ol haos blong yufala blong stil long yufala. Yufala i stap kilim ol man long klia ples nomo blong stilim olgeta.","“Ol man Isrel. Yufala i man blong mi, mo mi mi wantem tumas blong mekem yufala i kam gud bakegen, blong laef blong yufala i gohed gud, mo yufala i kam rijman. Be oltaem, taem mi lukluk i kam long yufala, mi stap luk ol sin blong yufala nomo. Oltaem nomo yufala i stap ravravem yufala, mo yufala i stap go insaed long ol haos blong yufala blong stil long yufala. Yufala i stap kilim ol man long klia ples nomo blong stilim olgeta."],[7,2,"Yufala i no gat tingting nating, yufala i no save nating we mi mi stap luk evri samting we yufala i stap mekem. Taem mi lukluk i kam, mi luk ol sin blong yufala nomo i stap hivap raon long yufala.”","Yufala i no gat tingting nating, yufala i no save nating we mi mi stap luk evri samting we yufala i stap mekem. Taem mi lukluk i kam, mi luk ol sin blong yufala nomo i stap hivap raon long yufala.”"],[7,3,"Bakegen, Profet Hosea i talemaot we Hae God i talem se, “Yufala i stap mekem plan agens long king wetem ol haeman blong hem, blong trikim hem long ol rabis fasin blong yufala.","Bakegen, Profet Hosea i talemaot we Hae God i talem se, “Yufala i stap mekem plan agens long king wetem ol haeman blong hem, blong trikim hem long ol rabis fasin blong yufala."],[7,4,"Tingting blong yufala i no stap strong long king ya nating. Yufala i stap ona long hem, be yufala i stap giaman, yufala i stap pasraon long baksaed blong hem nomo blong spolem hem. Fasin ya we yufala i no laekem hem, yufala i agensem hem tumas, hem i olsem ol stikfaea we oli stap laet smosmol. Taem man i rere blong kukum kakae, hem i pusum olgeta i kam wanples, nao wantaem nomo faea i laet bigwan.","Tingting blong yufala i no stap strong long king ya nating. Yufala i stap ona long hem, be yufala i stap giaman, yufala i stap pasraon long baksaed blong hem nomo blong spolem hem. Fasin ya we yufala i no laekem hem, yufala i agensem hem tumas, hem i olsem ol stikfaea we oli stap laet smosmol. Taem man i rere blong kukum kakae, hem i pusum olgeta i kam wanples, nao wantaem nomo faea i laet bigwan."],[7,5,"Long dei ya we king i mekem lafet blong hem, yufala i stap givim waen long hem wetem ol haeman ya blong hem, gogo olgeta oli drong, hed blong olgeta i krangke.","Long dei ya we king i mekem lafet blong hem, yufala i stap givim waen long hem wetem ol haeman ya blong hem, gogo olgeta oli drong, hed blong olgeta i krangke."],[7,6,"Ol rabis plan blong yufala i stap hot insaed long tingting blong yufala olsem faea blong kukum bred. Long naet, kros blong yufala i stap hot, nao long moning kros ya i faerap, i laet strong, i mekem yufala i wantem faet.","Ol rabis plan blong yufala i stap hot insaed long tingting blong yufala olsem faea blong kukum bred. Long naet, kros blong yufala i stap hot, nao long moning kros ya i faerap, i laet strong, i mekem yufala i wantem faet."],[7,7,"Taem yufala i kros tumas olsem, yufala i stap kilim ol lida blong yufala oli ded. Oltaem yufala i stap kilim ol king blong yufala oli ded, be i no gat wan long yufala nating we i save askem long mi blong mi givhan long yufala.”","Taem yufala i kros tumas olsem, yufala i stap kilim ol lida blong yufala oli ded. Oltaem yufala i stap kilim ol king blong yufala oli ded, be i no gat wan long yufala nating we i save askem long mi blong mi givhan long yufala.”"],[7,8,"Nao Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel.* Yufala i olsem bred we i haftan. Yufala i stap flas long paoa blong ol narafala kantri we oli stap raonabaot long yufala,","Nao Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel.* Yufala i olsem bred we i haftan. Yufala i stap flas long paoa blong ol narafala kantri we oli stap raonabaot long yufala,"],[7,9,"be yufala i no luksave nating we taem yufala i stap dipen long olgeta olsem, be yufala i stap lusum paoa blong yufala tu. I gat ol saen i stap soemaot we bambae yufala i lus, be yufala i no luksave nating.","be yufala i no luksave nating we taem yufala i stap dipen long olgeta olsem, be yufala i stap lusum paoa blong yufala tu. I gat ol saen i stap soemaot we bambae yufala i lus, be yufala i no luksave nating."],[7,10,"Fasin ya we yufala i stap leftemap yufala tumas, hem i stap witnes agens long yufala. Mi mi Hae God, mi God blong yufala, be yufala i no wantem nating blong kambak long mi.","Fasin ya we yufala i stap leftemap yufala tumas, hem i stap witnes agens long yufala. Mi mi Hae God, mi God blong yufala, be yufala i no wantem nating blong kambak long mi."],[7,11,"Yufala i stap go olbaot olsem pijin we i pas long net, i fraet i lusum hed, nao i stap flae i go olbaot. Fastaem, yufala i askem long kantri ya Ijip blong i kam givhan long yufala, mo biaen, yufala i resis i go long kantri ya Asiria blong i givhan long yufala.","Yufala i stap go olbaot olsem pijin we i pas long net, i fraet i lusum hed, nao i stap flae i go olbaot. Fastaem, yufala i askem long kantri ya Ijip blong i kam givhan long yufala, mo biaen, yufala i resis i go long kantri ya Asiria blong i givhan long yufala."],[7,12,"Yufala i stap resis i go olbaot, be bambae mi putum wan net, mi kasem yufala long hem. Bambae mi mi panisim yufala from ol rabis fasin we yufala i stap mekem.","Yufala i stap resis i go olbaot, be bambae mi putum wan net, mi kasem yufala long hem. Bambae mi mi panisim yufala from ol rabis fasin we yufala i stap mekem."],[7,13,"“Naoia, yufala i stap finis long rod blong lus. Yufala i tanem baksaed finis long mi, mo yufala i stap girap agens long mi bakegen. Bambae mi mi kilim yufala evriwan i ded. Fastaem, mi mi wantem tumas blong sevem yufala, be fasin blong yufala blong mekem wosip long mi i blong giaman nomo.","“Naoia, yufala i stap finis long rod blong lus. Yufala i tanem baksaed finis long mi, mo yufala i stap girap agens long mi bakegen. Bambae mi mi kilim yufala evriwan i ded. Fastaem, mi mi wantem tumas blong sevem yufala, be fasin blong yufala blong mekem wosip long mi i blong giaman nomo."],[7,14,"Yufala i stap prea long mi, be long maot nomo, i no kamaot nating long tingting blong yufala. Taem yufala i stap prea long mi, yufala i stap krae, yufala i stap sakem yufala i go long graon, stret olsem we ol hiten man oli stap mekem. Taem yufala i stap prea long mi blong mi givim kakae mo waen long yufala, yufala i stap katkatem bodi blong yufala, olsem we ol man blong ol narafala god oli stap mekem, be semtaem nomo, yufala i stap girap agens long mi.","Yufala i stap prea long mi, be long maot nomo, i no kamaot nating long tingting blong yufala. Taem yufala i stap prea long mi, yufala i stap krae, yufala i stap sakem yufala i go long graon, stret olsem we ol hiten man oli stap mekem. Taem yufala i stap prea long mi blong mi givim kakae mo waen long yufala, yufala i stap katkatem bodi blong yufala, olsem we ol man blong ol narafala god oli stap mekem, be semtaem nomo, yufala i stap girap agens long mi."],[7,15,"Mi nomo mi stap lukaot long yufala, mi stap tijim yufala, mo mi stap mekem yufala i strong, be oltaem yufala i stap mekem plan agens long mi.","Mi nomo mi stap lukaot long yufala, mi stap tijim yufala, mo mi stap mekem yufala i strong, be oltaem yufala i stap mekem plan agens long mi."],[7,16,"Oltaem yufala i stap tanem baksaed long mi, blong go biaen long narafala god ya we i no gat paoa nating. Yufala i olsem bonara we man i no save trastem. Ol lida blong yufala oli stap leftemap olgeta tumas, be wan samting bambae i kam kasem olgeta we wantaem nomo bambae oli ded from, mo ol man Ijip bambae oli laf bigwan long yufala from.”","Oltaem yufala i stap tanem baksaed long mi, blong go biaen long narafala god ya we i no gat paoa nating. Yufala i olsem bonara we man i no save trastem. Ol lida blong yufala oli stap leftemap olgeta tumas, be wan samting bambae i kam kasem olgeta we wantaem nomo bambae oli ded from, mo ol man Ijip bambae oli laf bigwan long yufala from.”"],[8,1,"Bakegen, Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel.* !Faet i kam nao! !Yufala i blu pupu! Ol enemi blong yufala oli stap kamdaon blong holem kantri blong mi, olsem we bigfala pijin ya igel* i sut i kamdaon blong holem faol. Yufala i man blong mi, be yufala i brekem promes* ya we mi mekem wetem yufala, mo yufala i no wantem harem tok blong mi, yufala i stap agens long hem.","Bakegen, Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel.* !Faet i kam nao! !Yufala i blu pupu! Ol enemi blong yufala oli stap kamdaon blong holem kantri blong mi, olsem we bigfala pijin ya igel* i sut i kamdaon blong holem faol. Yufala i man blong mi, be yufala i brekem promes* ya we mi mekem wetem yufala, mo yufala i no wantem harem tok blong mi, yufala i stap agens long hem."],[8,2,"Yufala i stap singaot i kam long mi se, ‘God blong mifala. Mifala i man blong yu, mifala i savegud yu.’","Yufala i stap singaot i kam long mi se, ‘God blong mifala. Mifala i man blong yu, mifala i savegud yu.’"],[8,3,"Be yufala i no wantem nating blong folem ol gudfala fasin. Nao from samting ya, ol enemi blong yufala bambae oli kam ronem yufala.","Be yufala i no wantem nating blong folem ol gudfala fasin. Nao from samting ya, ol enemi blong yufala bambae oli kam ronem yufala."],[8,4,"“Yufala i stap jusumaot ol man ya we oli kam king blong yufala, be yufala i stap mekem long tingting blong yufala nomo. Ol lida ya blong yufala we yufala i stap putumap olgeta, be yufala i no stap askem long mi fastaem. Mo yufala i stap tekem ol silva mo gol blong yufala i kam wanples, yufala i stap wokem ol aedol long hem, be ol aedol ya i blong spolem yufala nomo.","“Yufala i stap jusumaot ol man ya we oli kam king blong yufala, be yufala i stap mekem long tingting blong yufala nomo. Ol lida ya blong yufala we yufala i stap putumap olgeta, be yufala i no stap askem long mi fastaem. Mo yufala i stap tekem ol silva mo gol blong yufala i kam wanples, yufala i stap wokem ol aedol long hem, be ol aedol ya i blong spolem yufala nomo."],[8,5,"Yufala long Sameria,* yufala i wokem wan pija blong bul long gol, mo yufala i stap mekem wosip long hem, be mi mi no wantem fasin ya nating, mi agens long hem. Mo mi kros tumas long yufala from samting ya. ?Fasin ya bambae i stap gogo kasem wetaem?","Yufala long Sameria,* yufala i wokem wan pija blong bul long gol, mo yufala i stap mekem wosip long hem, be mi mi no wantem fasin ya nating, mi agens long hem. Mo mi kros tumas long yufala from samting ya. ?Fasin ya bambae i stap gogo kasem wetaem?"],[8,6,"Pija ya, wan long yufala we i gat gudhan i wokem, be hem i no god nating. Bambae mi smasem, mi brebrekem long ol smosmol pis.","Pija ya, wan long yufala we i gat gudhan i wokem, be hem i no god nating. Bambae mi smasem, mi brebrekem long ol smosmol pis."],[8,7,"Fasin nogud blong yufala i olsem smol win nomo, be samting we i kamaot long hem, bambae i olsem wan bigfala waelwin we i save spolem evri samting. Ol garen ya blong yufala we yufala i planem, bambae oli no karem kakae, be sipos oli karem, bambae ol man blong narafala kantri oli kam kakae ol frut blong olgeta.","Fasin nogud blong yufala i olsem smol win nomo, be samting we i kamaot long hem, bambae i olsem wan bigfala waelwin we i save spolem evri samting. Ol garen ya blong yufala we yufala i planem, bambae oli no karem kakae, be sipos oli karem, bambae ol man blong narafala kantri oli kam kakae ol frut blong olgeta."],[8,8,"Naoia, yufala i kam olsem ol man blong ol narafala kantri nomo we fasin blong olgeta i nogud. Yufala i olsem graonpot we i brok finis, we man i no moa save yusum blong wan samting.","Naoia, yufala i kam olsem ol man blong ol narafala kantri nomo we fasin blong olgeta i nogud. Yufala i olsem graonpot we i brok finis, we man i no moa save yusum blong wan samting."],[8,9,"Yufala i stronghed tumas, yufala i olsem wael dongki stret. Yufala i stap folem tingting blong yufala nomo. Yufala i girap, yufala i go long kantri ya Asiria, yufala i askem long hem blong i givhan long yufala, mo yufala i stap pem ol narafala kantri tu blong oli kam blokemgud yufala.","Yufala i stronghed tumas, yufala i olsem wael dongki stret. Yufala i stap folem tingting blong yufala nomo. Yufala i girap, yufala i go long kantri ya Asiria, yufala i askem long hem blong i givhan long yufala, mo yufala i stap pem ol narafala kantri tu blong oli kam blokemgud yufala."],[8,10,"Naoia bambae mi tekem yufala i kam wanples, mi panisim yufala. I no longtaem bambae king blong Asiria i girap, i kam mekem i strong tumas long yufala, we bambae i mekem yufala i harem nogud tumas.","Naoia bambae mi tekem yufala i kam wanples, mi panisim yufala. I no longtaem bambae king blong Asiria i girap, i kam mekem i strong tumas long yufala, we bambae i mekem yufala i harem nogud tumas."],[8,11,"“Ol man Isrel. Mi mi Hae God. Yufala i stap wokem plante olta blong tekemaot sin, be taem yufala i bonem sakrefaes long olgeta, yufala i stap mekem sin agens long mi nomo. Taem namba blong ol olta ya i stap kam plante moa, be ol sin blong yufala tu oli stap kam plante moa long fes blong mi.","“Ol man Isrel. Mi mi Hae God. Yufala i stap wokem plante olta blong tekemaot sin, be taem yufala i bonem sakrefaes long olgeta, yufala i stap mekem sin agens long mi nomo. Taem namba blong ol olta ya i stap kam plante moa, be ol sin blong yufala tu oli stap kam plante moa long fes blong mi."],[8,12,"Mi mi raetemdaon plante tok blong mi blong tijim yufala, be yufala i stap lukluk ol tok ya se oli rabis nomo, oli tok blong man blong narafala kantri.","Mi mi raetemdaon plante tok blong mi blong tijim yufala, be yufala i stap lukluk ol tok ya se oli rabis nomo, oli tok blong man blong narafala kantri."],[8,13,"Yufala i stap kilim ol anamol blong mekem sakrefaes blong mekem wosip long mi, mo yufala i stap kakae mit blong olgeta, be mi mi no glad nating long yufala from ol sakrefaes ya. Naoia bambae mi panisim yufala from ol sin blong yufala. !Bambae mi sanem yufala i gobak long Ijip bakegen!","Yufala i stap kilim ol anamol blong mekem sakrefaes blong mekem wosip long mi, mo yufala i stap kakae mit blong olgeta, be mi mi no glad nating long yufala from ol sakrefaes ya. Naoia bambae mi panisim yufala from ol sin blong yufala. !Bambae mi sanem yufala i gobak long Ijip bakegen!"],[8,14,"“Yufala i stap wokem ol bigbigfala haos blong king blong yufala, be yufala i fogetemgud mi, we mi mi mekem yufala. Mo ol man Juda* tu, oli stap wokem ol bigbigfala taon blong olgeta we bigfala stonwol i goraon long olgeta. Be ol haos ya blong king we yufala i wokem, mo ol bigbigfala taon ya we olgeta oli wokem, mi bambae mi sanem faea i kam we bambae i bonem olgeta evriwan.”","“Yufala i stap wokem ol bigbigfala haos blong king blong yufala, be yufala i fogetemgud mi, we mi mi mekem yufala. Mo ol man Juda* tu, oli stap wokem ol bigbigfala taon blong olgeta we bigfala stonwol i goraon long olgeta. Be ol haos ya blong king we yufala i wokem, mo ol bigbigfala taon ya we olgeta oli wokem, mi bambae mi sanem faea i kam we bambae i bonem olgeta evriwan.”"],[9,1,"Nao Profet Hosea i talem long ol man Isrel* se, “Olgeta. Bambae yufala i no stap mekem lafet oltaem, olsem we ol hiten man ya oli stap mekem. Yufala i mas lego fasin ya. Hae God i God blong yumi, be yufala i gowe finis long hem, mo tingting blong yufala i no moa stap strong long hem nating. Olbaot long kantri ya, yufala i stap salem yufala long god ya Bal,* olsem we woman blong rod i stap salem hem long ol man. Mo yufala i laekem tumas ol gudfala kakae blong garen ya we yufala i ting se hem i stap pem yufala long hem.","Nao Profet Hosea i talem long ol man Isrel* se, “Olgeta. Bambae yufala i no stap mekem lafet oltaem, olsem we ol hiten man ya oli stap mekem. Yufala i mas lego fasin ya. Hae God i God blong yumi, be yufala i gowe finis long hem, mo tingting blong yufala i no moa stap strong long hem nating. Olbaot long kantri ya, yufala i stap salem yufala long god ya Bal,* olsem we woman blong rod i stap salem hem long ol man. Mo yufala i laekem tumas ol gudfala kakae blong garen ya we yufala i ting se hem i stap pem yufala long hem."],[9,2,"Be bambae i no longtaem yufala i no moa gat kakae mo olifoel* mo waen blong yufala, olgeta samting ya bambae i finis evriwan.","Be bambae i no longtaem yufala i no moa gat kakae mo olifoel* mo waen blong yufala, olgeta samting ya bambae i finis evriwan."],[9,3,"Graon ya i blong Hae God, be from rabis fasin ya blong yufala, bambae yufala i no moa save stap long hem. Bambae yufala i gobak long Ijip bakegen, mo bambae yufala i go stap long kantri ya Asiria, we bambae yufala i stap kakae ol kakae ya we i tabu blong yufala i kakae.","Graon ya i blong Hae God, be from rabis fasin ya blong yufala, bambae yufala i no moa save stap long hem. Bambae yufala i gobak long Ijip bakegen, mo bambae yufala i go stap long kantri ya Asiria, we bambae yufala i stap kakae ol kakae ya we i tabu blong yufala i kakae."],[9,4,"Taem we yufala i stap long ol kantri ya, neva bambae yufala i gat waen blong givim i go long Hae God. Mo neva bambae yufala i gat anamol blong mekem sakrefaes i go long hem. Ol kakae blong yufala bambae i mekem yufala i kam doti long fes blong hem, olsem kakae ya blong mekem lafet blong dedman. Ol kakae olsem bambae i blong fulumap bel blong yufala nomo, i tabu blong yufala i tekem blong givim i go long Hae God.","Taem we yufala i stap long ol kantri ya, neva bambae yufala i gat waen blong givim i go long Hae God. Mo neva bambae yufala i gat anamol blong mekem sakrefaes i go long hem. Ol kakae blong yufala bambae i mekem yufala i kam doti long fes blong hem, olsem kakae ya blong mekem lafet blong dedman. Ol kakae olsem bambae i blong fulumap bel blong yufala nomo, i tabu blong yufala i tekem blong givim i go long Hae God."],[9,5,"Long taem blong mekem ol lafet* ya we oli tabu, oli blong hem, bambae yufala i sem bigwan, from we yufala i no save mekem.","Long taem blong mekem ol lafet* ya we oli tabu, oli blong hem, bambae yufala i sem bigwan, from we yufala i no save mekem."],[9,6,"Taem bigfala trabol ya i kamtru, bambae yufala i go wanwan, be ol man Ijip bambae oli kam hivimap yufala wanples. Bambae ol man Memfis we i kaptel blong Ijip, oli kam berem yufala wetem ol gudgudfala samting blong yufala we yufala i wokem long silva. Nao bus bambae i kam kavremap ples blong yufala, ropnil bambae i kavremapgud ol haos blong yufala.”","Taem bigfala trabol ya i kamtru, bambae yufala i go wanwan, be ol man Ijip bambae oli kam hivimap yufala wanples. Bambae ol man Memfis we i kaptel blong Ijip, oli kam berem yufala wetem ol gudgudfala samting blong yufala we yufala i wokem long silva. Nao bus bambae i kam kavremap ples blong yufala, ropnil bambae i kavremapgud ol haos blong yufala.”"],[9,7,"“Taem i kam finis blong yufala i kasem panis. Mo panis we bambae yufala i kasem, bambae i stret long mak blong ol samting nogud ya we yufala i stap mekem. Mo taem panis ya i kasem yufala, bambae yufala i save rod. Yufala i stap talem se, ‘Profet ya i krangke ya. Devel i stap long hem, i mekem hed blong hem i krangke.’ Ol sin blong yufala i plante tumas, taswe yufala i stap tok agens long mi olsem.","“Taem i kam finis blong yufala i kasem panis. Mo panis we bambae yufala i kasem, bambae i stret long mak blong ol samting nogud ya we yufala i stap mekem. Mo taem panis ya i kasem yufala, bambae yufala i save rod. Yufala i stap talem se, ‘Profet ya i krangke ya. Devel i stap long hem, i mekem hed blong hem i krangke.’ Ol sin blong yufala i plante tumas, taswe yufala i stap tok agens long mi olsem."],[9,8,"Hae God i sanem mi mi kam blong toktok long yufala, blong wonem yufala. Be long olgeta ples we mi stap pas long hem, yufala i stap trikim mi, olsem we man i putum snea blong holem faol. Kantri ya i blong Hae God, be long evri ples yufala i stap faet agens long hem.","Hae God i sanem mi mi kam blong toktok long yufala, blong wonem yufala. Be long olgeta ples we mi stap pas long hem, yufala i stap trikim mi, olsem we man i putum snea blong holem faol. Kantri ya i blong Hae God, be long evri ples yufala i stap faet agens long hem."],[9,9,"Oltaem nomo, yufala i stap mekem ol samting nogud. Fasin blong yufala i sem mak long fasin blong ol bubu blong yumi bifo we oli mekem sin long Gibea. Ol sin ya blong yufala, bambae Hae God i no save fogetem, bambae hem i mas givim panis long yufala from.”","Oltaem nomo, yufala i stap mekem ol samting nogud. Fasin blong yufala i sem mak long fasin blong ol bubu blong yumi bifo we oli mekem sin long Gibea. Ol sin ya blong yufala, bambae Hae God i no save fogetem, bambae hem i mas givim panis long yufala from.”"],[9,10,"Nao Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel.* Bifo, taem mi mi jes luk ol bubu blong yufala fastaem, olgeta oli gud tumas, oli olsem ol gudgudfala grep* we man i faenem long draeples we i no ples blong hem. Long taem ya, olgeta ya oli olsem ol fas kakae blong figtri* we oli jes raep. Be biaen, oli kam long ples ya, nao oli go long hil ya Peoro, mo oli stat mekem wosip long god ya Bal.* Oli stap mekem gogo, fasin blong olgeta i kam nogud we i nogud, i olsem fasin blong Bal ya we oli laekem hem tumas.","Nao Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel.* Bifo, taem mi mi jes luk ol bubu blong yufala fastaem, olgeta oli gud tumas, oli olsem ol gudgudfala grep* we man i faenem long draeples we i no ples blong hem. Long taem ya, olgeta ya oli olsem ol fas kakae blong figtri* we oli jes raep. Be biaen, oli kam long ples ya, nao oli go long hil ya Peoro, mo oli stat mekem wosip long god ya Bal.* Oli stap mekem gogo, fasin blong olgeta i kam nogud we i nogud, i olsem fasin blong Bal ya we oli laekem hem tumas."],[9,11,"Yufala i karem hae nem from ol bubu ya blong yufala fastaem, be bambae yufala i lusum. Nem ya bambae i flae i go olsem pijin. Bambae yufala i no moa save gat pikinini blong yufala. Ol woman blong yufala bambae oli no moa save gat bel.","Yufala i karem hae nem from ol bubu ya blong yufala fastaem, be bambae yufala i lusum. Nem ya bambae i flae i go olsem pijin. Bambae yufala i no moa save gat pikinini blong yufala. Ol woman blong yufala bambae oli no moa save gat bel."],[9,12,"Mo sipos yufala i gat ol pikinini blong lukaot long olgeta, be mi bambae mi kilim olgeta oli ded, bambae i no gat wan i stap. Taem mi mi lego yufala, ol samting we bambae oli kam kasem yufala bambae oli nogud we i nogud.”","Mo sipos yufala i gat ol pikinini blong lukaot long olgeta, be mi bambae mi kilim olgeta oli ded, bambae i no gat wan i stap. Taem mi mi lego yufala, ol samting we bambae oli kam kasem yufala bambae oli nogud we i nogud.”"],[9,13,"Nao profet i prea i talem se, “Hae God. Naoia mi luk we ol enemi blong mifala oli stap ronem ol pikinini blong mifala, oli stap kilim olgeta i ded.","Nao profet i prea i talem se, “Hae God. Naoia mi luk we ol enemi blong mifala oli stap ronem ol pikinini blong mifala, oli stap kilim olgeta i ded."],[9,14,"?Wanem stret samting we mi save askem, blong yu mekem long mifala? I moa gud yu mekem we ol woman blong mifala oli no moa save karem pikinini, mo yu mekem we titi blong olgeta i kam drae.”","?Wanem stret samting we mi save askem, blong yu mekem long mifala? I moa gud yu mekem we ol woman blong mifala oli no moa save karem pikinini, mo yu mekem we titi blong olgeta i kam drae.”"],[9,15,"Mo profet i talemaot bakegen we Hae God i talem se, “Yes. Olgeta ya, ol rabis fasin ya we oli stap mekem i stat bifo finis long Gilgal. Nao i stat long taem ya, mi mi no moa wantem luk olgeta. Mo from samting ya, mi bambae mi ronemaot olgeta long kantri ya blong mi. Bambae mi no moa lavem olgeta from we oltaem nomo ol lida blong olgeta oli stap girap agens long mi.","Mo profet i talemaot bakegen we Hae God i talem se, “Yes. Olgeta ya, ol rabis fasin ya we oli stap mekem i stat bifo finis long Gilgal. Nao i stat long taem ya, mi mi no moa wantem luk olgeta. Mo from samting ya, mi bambae mi ronemaot olgeta long kantri ya blong mi. Bambae mi no moa lavem olgeta from we oltaem nomo ol lida blong olgeta oli stap girap agens long mi."],[9,16,"Olgeta ya oli olsem wan smol tri we rus blong hem i drae evriwan finis, i no moa save karem kakae. Bambae oli no moa save gat pikinini. Mo sipos oli bonem ol pikinini blong olgeta we oli lavem olgeta tumas, be mi bambae mi kilim olgeta oli ded bakegen.”","Olgeta ya oli olsem wan smol tri we rus blong hem i drae evriwan finis, i no moa save karem kakae. Bambae oli no moa save gat pikinini. Mo sipos oli bonem ol pikinini blong olgeta we oli lavem olgeta tumas, be mi bambae mi kilim olgeta oli ded bakegen.”"],[9,17,"Nao Profet Hosea i talem long ol man Isrel* se, “Olgeta. God ya blong yumi we mi mi stap wok blong hem, bambae hem i tanem baksaed long yufala, from we yufala i no save harem tok blong hem. Yufala i man blong hem, be bambae yufala i stap go wanwan olbaot long evri ples.","Nao Profet Hosea i talem long ol man Isrel* se, “Olgeta. God ya blong yumi we mi mi stap wok blong hem, bambae hem i tanem baksaed long yufala, from we yufala i no save harem tok blong hem. Yufala i man blong hem, be bambae yufala i stap go wanwan olbaot long evri ples."],[10,1,"“Bifo, yufala i olsem wan rop blong grep,* we i stap karem plante frut. Yufala i rijman, be taem yufala i stap kam rij moa, yufala i girap, yufala i go wokem plante olta moa blong ol narafala god ya blong yufala. Graon blong yufala i stap karem plante kakae, be taem yufala i gat plante kakae olsem, ol longlongfala ston ya we yufala i stanemap blong mekem wosip long ol narafala god ya, yufala i go flasem olgeta blong oli kam flas moa.","“Bifo, yufala i olsem wan rop blong grep,* we i stap karem plante frut. Yufala i rijman, be taem yufala i stap kam rij moa, yufala i girap, yufala i go wokem plante olta moa blong ol narafala god ya blong yufala. Graon blong yufala i stap karem plante kakae, be taem yufala i gat plante kakae olsem, ol longlongfala ston ya we yufala i stanemap blong mekem wosip long ol narafala god ya, yufala i go flasem olgeta blong oli kam flas moa."],[10,2,"Tingting blong yufala i fulap long ol fasin blong giaman, nao from samting ya, bambae yufala i mas kasem panis from ol sin ya we yufala i stap mekem. Bambae i no longtaem, God i brebrekem ol olta ya blong yufala, mo i spolemgud ol longlongfala ston ya blong yufala.","Tingting blong yufala i fulap long ol fasin blong giaman, nao from samting ya, bambae yufala i mas kasem panis from ol sin ya we yufala i stap mekem. Bambae i no longtaem, God i brebrekem ol olta ya blong yufala, mo i spolemgud ol longlongfala ston ya blong yufala."],[10,3,"“I no longtaem bambae yufala i save talem se, ‘Naoia yumi no moa gat king blong yumi, from we yumi no moa ona long Hae God. ?Be sipos yumi gat king, bambae hem i save mekem wanem blong givhan long yumi?’","“I no longtaem bambae yufala i save talem se, ‘Naoia yumi no moa gat king blong yumi, from we yumi no moa ona long Hae God. ?Be sipos yumi gat king, bambae hem i save mekem wanem blong givhan long yumi?’"],[10,4,"Oltaem tok blong yufala i no save stanap. Yufala i stap mekem ol promes wetem ol man, mo yufala i stap saenem ol promes wetem ol king blong ol narafala kantri blong wok wanples wetem olgeta, be oltaem yufala i stap giaman nomo. Stret fasin blong jajem man, yufala i kafsaedem i kam fasin nogud, mo i stap gru olsem rabis gras ya we i stap gru bigwan long garen we man i brebrekem graon blong hem finis.","Oltaem tok blong yufala i no save stanap. Yufala i stap mekem ol promes wetem ol man, mo yufala i stap saenem ol promes wetem ol king blong ol narafala kantri blong wok wanples wetem olgeta, be oltaem yufala i stap giaman nomo. Stret fasin blong jajem man, yufala i kafsaedem i kam fasin nogud, mo i stap gru olsem rabis gras ya we i stap gru bigwan long garen we man i brebrekem graon blong hem finis."],[10,5,"“Yufala long taon ya Sameria,* bambae yufala i fraet, from we bambae yufala i lusum bul ya we yufala i wokem long gol, we yufala i stap mekem wosip long hem long Betaven. Taem hem i go lus, bambae yufala i harem nogud, yufala i krae bigwan from. Mo taem ol pris blong hem we oli stap mekem wosip long hem oltaem, oli luk we hem i no moa gat paoa, bambae oli krae bigwan moa.","“Yufala long taon ya Sameria,* bambae yufala i fraet, from we bambae yufala i lusum bul ya we yufala i wokem long gol, we yufala i stap mekem wosip long hem long Betaven. Taem hem i go lus, bambae yufala i harem nogud, yufala i krae bigwan from. Mo taem ol pris blong hem we oli stap mekem wosip long hem oltaem, oli luk we hem i no moa gat paoa, bambae oli krae bigwan moa."],[10,6,"Bambae ol man Asiria oli kam tekemaot bul ya, oli karem i go blong givim long king blong olgeta. Nao nem blong yufala bambae i kam nogud, mo bambae yufala i sem tumas, from we yufala i stap folem ol tok ya we ol narafala man oli stap givim long yufala.","Bambae ol man Asiria oli kam tekemaot bul ya, oli karem i go blong givim long king blong olgeta. Nao nem blong yufala bambae i kam nogud, mo bambae yufala i sem tumas, from we yufala i stap folem ol tok ya we ol narafala man oli stap givim long yufala."],[10,7,"Mo bambae king blong yufala tu i lus wantaem, olsem drae lif we wota i karem i go.","Mo bambae king blong yufala tu i lus wantaem, olsem drae lif we wota i karem i go."],[10,8,"Ol man Isrel. Ol ples ya antap long ol hil olbaot long Aven, we yufala i stap kam mekem wosip long ol narafala god ya long hem, bambae oli kam nogud evriwan. Ol olta blong ol ples ya, ropnil bambae i kavremapgud olgeta. Nao bambae yufala i singaot long ol bigbigfala hil ya se, ‘Yufala i kam kavremap mifala.’ Mo bambae yufala i krae long ol hil se, ‘Yufala i kam haedem mifala.’ ”","Ol man Isrel. Ol ples ya antap long ol hil olbaot long Aven, we yufala i stap kam mekem wosip long ol narafala god ya long hem, bambae oli kam nogud evriwan. Ol olta blong ol ples ya, ropnil bambae i kavremapgud olgeta. Nao bambae yufala i singaot long ol bigbigfala hil ya se, ‘Yufala i kam kavremap mifala.’ Mo bambae yufala i krae long ol hil se, ‘Yufala i kam haedem mifala.’ ”"],[10,9,"Bakegen, Profet Hosea i talemaot we Hae God i talem se, “Ol laen* blong Isrel.* Bifo, ol bubu blong yufala we oli stap long taon ya Gibea, oli mekem sin agens long mi, be fasin blong olgeta i stap yet long yufala kam kasem tede. ?Yufala i ting se faet bambae i no save kam kasem yufala bakegen, olsem we i kasem olgeta ya long Gibea bifo? !Yufala i krangke!","Bakegen, Profet Hosea i talemaot we Hae God i talem se, “Ol laen* blong Isrel.* Bifo, ol bubu blong yufala we oli stap long taon ya Gibea, oli mekem sin agens long mi, be fasin blong olgeta i stap yet long yufala kam kasem tede. ?Yufala i ting se faet bambae i no save kam kasem yufala bakegen, olsem we i kasem olgeta ya long Gibea bifo? !Yufala i krangke!"],[10,10,"Yufala i man nogud, mo mi bambae mi kam mekem faet long yufala, blong panisim yufala. Ol narafala kantri bambae oli joen wanples, oli kam faet agens long yufala, mo long fasin ya, bambae yufala i kasem panis from ol sin ya blong yufala, we i plante tumas.","Yufala i man nogud, mo mi bambae mi kam mekem faet long yufala, blong panisim yufala. Ol narafala kantri bambae oli joen wanples, oli kam faet agens long yufala, mo long fasin ya, bambae yufala i kasem panis from ol sin ya blong yufala, we i plante tumas."],[10,11,"“Ol man Isrel. Fastaem, fasin blong ol olfala blong yufala i gudfala tumas. Olgeta i olsem wan woman buluk we man i lanemgud hem, mo oltaem hem i rere blong purumpurumbut long hed blong wit* blong mekem kakae blong hem i kamaot. Be naoia, mi mekem olsem we mi putum yok* long nek blong woman buluk ya, blong fosem hem blong i wok strong moa. Mi mi makem finis, se ol man Juda* bambae oli olsem buluk we i pulum plao blong brebrekem graon fastaem. Mo mi makem yufala, se bambae yufala i olsem buluk we i kam biaen, i pulum narafala aean bakegen blong mekem graon ya i sofsof gud.","“Ol man Isrel. Fastaem, fasin blong ol olfala blong yufala i gudfala tumas. Olgeta i olsem wan woman buluk we man i lanemgud hem, mo oltaem hem i rere blong purumpurumbut long hed blong wit* blong mekem kakae blong hem i kamaot. Be naoia, mi mekem olsem we mi putum yok* long nek blong woman buluk ya, blong fosem hem blong i wok strong moa. Mi mi makem finis, se ol man Juda* bambae oli olsem buluk we i pulum plao blong brebrekem graon fastaem. Mo mi makem yufala, se bambae yufala i olsem buluk we i kam biaen, i pulum narafala aean bakegen blong mekem graon ya i sofsof gud."],[10,12,"Mi mi talem long yufala se, ‘Mi mi Hae God, mi God blong yufala, mo yufala i mas lego ol rabis fasin blong yufala, yufala i mas mekem ol fasin we i stret gud. Mo yufala i mas lavem mi, mo tingting blong yufala i mas stap strong long mi, blong yufala i save karem ol gudfala frut long laef blong yufala. Fasin ya i olsem we man i wokem wan niufala garen, we i brebrekem graon blong hem, mo i planem ol gudfala sid long hem, mo biaen, i karem ol gudgudfala frut blong hem. Naoia i taem blong yufala i kambak long mi bakegen, mo sipos yufala i mekem olsem, bambae mi mi blesem yufala.’","Mi mi talem long yufala se, ‘Mi mi Hae God, mi God blong yufala, mo yufala i mas lego ol rabis fasin blong yufala, yufala i mas mekem ol fasin we i stret gud. Mo yufala i mas lavem mi, mo tingting blong yufala i mas stap strong long mi, blong yufala i save karem ol gudfala frut long laef blong yufala. Fasin ya i olsem we man i wokem wan niufala garen, we i brebrekem graon blong hem, mo i planem ol gudfala sid long hem, mo biaen, i karem ol gudgudfala frut blong hem. Naoia i taem blong yufala i kambak long mi bakegen, mo sipos yufala i mekem olsem, bambae mi mi blesem yufala.’"],[10,13,"Be yufala i girap, yufala i go mekem ol rabis fasin, olsem we yufala i planem rabis sid. Mo from samting ya, yufala i stap kasem frut blong hem. Mo naoia yufala i stap kakae bakegen frut blong ol giaman toktok blong yufala. “Taem yufala i luk we yufala i gat plante kat blong faet, mo yufala i gat plante soldia blong yufala, yufala i girap, yufala i stap trastem ol samting ya.","Be yufala i girap, yufala i go mekem ol rabis fasin, olsem we yufala i planem rabis sid. Mo from samting ya, yufala i stap kasem frut blong hem. Mo naoia yufala i stap kakae bakegen frut blong ol giaman toktok blong yufala. “Taem yufala i luk we yufala i gat plante kat blong faet, mo yufala i gat plante soldia blong yufala, yufala i girap, yufala i stap trastem ol samting ya."],[10,14,"Nao from we yufala i mekem olsem, bambae faet i mas kasem yufala. Ol enemi blong yufala bambae oli kam spolemgud ol taon ya blong yufala we bigfala stonwol i goraon long olgeta, stret olsem we King Salman i spolemgud taon ya Betarabel. Long taem blong faet ya, oli kilim ol woman wetem ol pikinini blong olgeta, we oli brebrekemgud bodi blong olgeta.","Nao from we yufala i mekem olsem, bambae faet i mas kasem yufala. Ol enemi blong yufala bambae oli kam spolemgud ol taon ya blong yufala we bigfala stonwol i goraon long olgeta, stret olsem we King Salman i spolemgud taon ya Betarabel. Long taem blong faet ya, oli kilim ol woman wetem ol pikinini blong olgeta, we oli brebrekemgud bodi blong olgeta."],[10,15,"Ol man Betel. Ol samting we bambae i kasem yufala from ol rabis fasin we yufala i stap mekem, bambae i olsemia nao. Mo wantaem nomo, taem faet i stat, king blong yufala bambae i ded.”","Ol man Betel. Ol samting we bambae i kasem yufala from ol rabis fasin we yufala i stap mekem, bambae i olsemia nao. Mo wantaem nomo, taem faet i stat, king blong yufala bambae i ded.”"],[11,1,"Nao Profet Hosea i talemaot we Hae God i talem se, “Ol laen* blong Isrel.* Bifo, taem ol bubu blong yufala oli olsem smol pikinini yet, mi mi lavem olgeta tumas. Mi mi stap singaot olgeta, se “Pikinini blong mi”, mo mi singaot olgeta oli aot long Ijip i kam.","Nao Profet Hosea i talemaot we Hae God i talem se, “Ol laen* blong Isrel.* Bifo, taem ol bubu blong yufala oli olsem smol pikinini yet, mi mi lavem olgeta tumas. Mi mi stap singaot olgeta, se “Pikinini blong mi”, mo mi singaot olgeta oli aot long Ijip i kam."],[11,2,"Be taem mi singaot olgeta, oli stap tanem baksaed long mi. Mo taem mi gohed blong singaot olgeta olsem, olgeta oli go moa. Oli go bonem sakrefaes long god ya Bal,* mo oli stap bonem insens* long ol narafala god.","Be taem mi singaot olgeta, oli stap tanem baksaed long mi. Mo taem mi gohed blong singaot olgeta olsem, olgeta oli go moa. Oli go bonem sakrefaes long god ya Bal,* mo oli stap bonem insens* long ol narafala god."],[11,3,"Mi nomo mi lanem olgeta blong wokbaot, mo mi stap karemgud olgeta long han blong mi, be oli no luksave nating we mi nomo mi stap lukaot gud long olgeta.","Mi nomo mi lanem olgeta blong wokbaot, mo mi stap karemgud olgeta long han blong mi, be oli no luksave nating we mi nomo mi stap lukaot gud long olgeta."],[11,4,"Mi mi stap mekem long olgeta olsem wan pikinini blong mi, we mi lavem hem, mo mi sore tumas long hem, nao oltaem mi stap pulum hem i kam long mi. Oltaem mi stap leftemap hem blong karem long han blong mi, mi stap holemtaet hem long jes blong mi, mo mi stap bendaon blong givim kakae long hem.","Mi mi stap mekem long olgeta olsem wan pikinini blong mi, we mi lavem hem, mo mi sore tumas long hem, nao oltaem mi stap pulum hem i kam long mi. Oltaem mi stap leftemap hem blong karem long han blong mi, mi stap holemtaet hem long jes blong mi, mo mi stap bendaon blong givim kakae long hem."],[11,5,"“Ol man Isrel. Yufala i no wantem nating blong kambak long mi, nao from samting ya, bambae yufala i mas gobak long Ijip bakegen, nao Asiria bambae i rulum yufala.","“Ol man Isrel. Yufala i no wantem nating blong kambak long mi, nao from samting ya, bambae yufala i mas gobak long Ijip bakegen, nao Asiria bambae i rulum yufala."],[11,6,"Bambae bigfala faet i kam, i flatemgud ol taon ya blong yufala. Ol doa* blong ol bigfala stonwol blong ol taon ya bambae oli brobrok, mo yufala bambae i go lus, from we yufala i stap folem tingting blong yufala nomo.","Bambae bigfala faet i kam, i flatemgud ol taon ya blong yufala. Ol doa* blong ol bigfala stonwol blong ol taon ya bambae oli brobrok, mo yufala bambae i go lus, from we yufala i stap folem tingting blong yufala nomo."],[11,7,"Yufala i stronghed tumas, oltaem yufala i wantem tanem baksaed long mi. Yok* ya we i stap long nek blong yufala, bambae yufala i harem nogud tumas long hem, bambae yufala i stap krae blong man i kam tekemaot, be bambae i no gat man i kam.","Yufala i stronghed tumas, oltaem yufala i wantem tanem baksaed long mi. Yok* ya we i stap long nek blong yufala, bambae yufala i harem nogud tumas long hem, bambae yufala i stap krae blong man i kam tekemaot, be bambae i no gat man i kam."],[11,8,"“Ol man Isrel. ?Bambae mi finis long yufala olsem wanem? Yufala i man blong mi. ?Bambae mi lego yufala olsem wanem? Mi no save kilim yufala evriwan i ded olsem we mi mekem long taon ya Admaha bifo. Mo mi no save mekem i strong long yufala, olsem we mi mekem long ol man Jeboeim bifo. Long tingting blong mi, mi no wantem nating blong mekem yufala olsem. Mi mi lavem yufala tumas, mo mi no save mekem olsem long yufala.","“Ol man Isrel. ?Bambae mi finis long yufala olsem wanem? Yufala i man blong mi. ?Bambae mi lego yufala olsem wanem? Mi no save kilim yufala evriwan i ded olsem we mi mekem long taon ya Admaha bifo. Mo mi no save mekem i strong long yufala, olsem we mi mekem long ol man Jeboeim bifo. Long tingting blong mi, mi no wantem nating blong mekem yufala olsem. Mi mi lavem yufala tumas, mo mi no save mekem olsem long yufala."],[11,9,"Sipos mi kros long yufala, bambae mi no moa save panisim yufala, mi no moa save spolem yufala olsem bakegen. Mi mi God, mo fasin blong mi i no olsem fasin blong man. Mi mi tabu, fasin blong mi i stret olgeta. Oltaem bambae mi mi stap wetem yufala. Taem mi kros long yufala, bambae mi no moa save lukaot yufala blong panisim yufala.","Sipos mi kros long yufala, bambae mi no moa save panisim yufala, mi no moa save spolem yufala olsem bakegen. Mi mi God, mo fasin blong mi i no olsem fasin blong man. Mi mi tabu, fasin blong mi i stret olgeta. Oltaem bambae mi mi stap wetem yufala. Taem mi kros long yufala, bambae mi no moa save lukaot yufala blong panisim yufala."],[11,10,"“Ol man blong mi, bambae mi mi singaot bigwan agens long ol enemi blong yufala olsem laeon we i kros, mo long taem ya bambae yufala i kam biaen long mi bakegen. Wantaem nomo, bambae yufala i aot long wes, yufala i resis i kam long mi.","“Ol man blong mi, bambae mi mi singaot bigwan agens long ol enemi blong yufala olsem laeon we i kros, mo long taem ya bambae yufala i kam biaen long mi bakegen. Wantaem nomo, bambae yufala i aot long wes, yufala i resis i kam long mi."],[11,11,"Bambae yufala i aot long Ijip, yufala i kam kwiktaem olsem pijin we i flae i kam. Bambae yufala i aot long Asiria, yufala i kambak stret long ples blong yufala, olsem pijin we i stap kambak stret long nes blong hem. Bambae mi mi tekem yufala i kamhom bakegen long stret ples blong yufala. Mi mi Hae God, mo hemia tok blong mi.”","Bambae yufala i aot long Ijip, yufala i kam kwiktaem olsem pijin we i flae i kam. Bambae yufala i aot long Asiria, yufala i kambak stret long ples blong yufala, olsem pijin we i stap kambak stret long nes blong hem. Bambae mi mi tekem yufala i kamhom bakegen long stret ples blong yufala. Mi mi Hae God, mo hemia tok blong mi.”"],[11,12,"Bakegen, Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel.* Mi mi God we mi tabu, fasin blong mi i stret olgeta, mo oltaem tingting blong mi i stap strong long yufala. Be taem yufala i kam long mi, yufala i stap giaman nomo long ol toktok mo long ol fasin blong yufala. Mo ol man Juda* oli stap girap agens long mi yet, we oli no lego fasin ya nating.","Bakegen, Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel.* Mi mi God we mi tabu, fasin blong mi i stret olgeta, mo oltaem tingting blong mi i stap strong long yufala. Be taem yufala i kam long mi, yufala i stap giaman nomo long ol toktok mo long ol fasin blong yufala. Mo ol man Juda* oli stap girap agens long mi yet, we oli no lego fasin ya nating."],[12,1,"Olgeta samting we yufala i stap mekem, i stat long moning, i go kasem long sapa, oli blong nating nomo. Oli stap spolem yufala nomo. Yufala i stap pasraon long baksaed blong ol fren blong yufala blong spolem olgeta bakegen, mo oltaem yufala i stap mekem faet, we yufala i stap kilkilim yufala. Yufala i stap saenem ol promes wetem king blong Asiria blong wok wanples wetem hem, mo yufala i stap mekem bisnes wetem ol man Ijip.”","Olgeta samting we yufala i stap mekem, i stat long moning, i go kasem long sapa, oli blong nating nomo. Oli stap spolem yufala nomo. Yufala i stap pasraon long baksaed blong ol fren blong yufala blong spolem olgeta bakegen, mo oltaem yufala i stap mekem faet, we yufala i stap kilkilim yufala. Yufala i stap saenem ol promes wetem king blong Asiria blong wok wanples wetem hem, mo yufala i stap mekem bisnes wetem ol man Ijip.”"],[12,2,"Nao profet i talem long ol man Isrel se, “Olgeta. Hae God i gat poen agens long ol man Juda, be bambae hem i panisim yufala tu from ol rabis fasin ya we yufala i stap mekem. Bambae hem i givim stret pei long yufala from ol samting nogud ya we yufala i stap mekem.","Nao profet i talem long ol man Isrel se, “Olgeta. Hae God i gat poen agens long ol man Juda, be bambae hem i panisim yufala tu from ol rabis fasin ya we yufala i stap mekem. Bambae hem i givim stret pei long yufala from ol samting nogud ya we yufala i stap mekem."],[12,3,"Bifo, taem olfala bubu ya blong yumi Jekob* wetem Esao, tufala i stap yet long bel blong mama blong tufala, tufala i stap faet tumas, mo taem Jekob i kam bigfala, oltaem hem i stap faet agens long God.","Bifo, taem olfala bubu ya blong yumi Jekob* wetem Esao, tufala i stap yet long bel blong mama blong tufala, tufala i stap faet tumas, mo taem Jekob i kam bigfala, oltaem hem i stap faet agens long God."],[12,4,"Wan taem, hem i faet agens long wan enjel,* mo i winim enjel ya. Hem i krae long fes blong enjel ya mo i askem long hem blong i blesem hem. Nao taem hem i stap long Betel, God i kamtru long hem, mo i toktok wetem hem.","Wan taem, hem i faet agens long wan enjel,* mo i winim enjel ya. Hem i krae long fes blong enjel ya mo i askem long hem blong i blesem hem. Nao taem hem i stap long Betel, God i kamtru long hem, mo i toktok wetem hem."],[12,5,"God ya, hem i Hae God, mo hem i gat olgeta paoa. Mo taem yumi mekem wosip long hem, yumi mas singaot hem se “Hae God”.","God ya, hem i Hae God, mo hem i gat olgeta paoa. Mo taem yumi mekem wosip long hem, yumi mas singaot hem se “Hae God”."],[12,6,"Yumi ya, yumi ol laen* blong Jekob, mo yufala i mas tanem tingting blong yufala, yufala i kambak long God blong yumi bakegen. Tingting blong yufala i mas stap strong long hem, yufala i mas folem ol stret fasin, mo yufala i mas wet blong luk ol samting we hem bambae i mekem blong sevem yufala.”","Yumi ya, yumi ol laen* blong Jekob, mo yufala i mas tanem tingting blong yufala, yufala i kambak long God blong yumi bakegen. Tingting blong yufala i mas stap strong long hem, yufala i mas folem ol stret fasin, mo yufala i mas wet blong luk ol samting we hem bambae i mekem blong sevem yufala.”"],[12,7,"Nao Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel.* Yufala i sem mak nomo long ol man Kenan,* yufala i man blong stil. Yufala i wantem tumas blong yusum skel* we i blong giaman blong ravem ol man.","Nao Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel.* Yufala i sem mak nomo long ol man Kenan,* yufala i man blong stil. Yufala i wantem tumas blong yusum skel* we i blong giaman blong ravem ol man."],[12,8,"Yufala i stap talem se, ‘Naoia yumi kam rijman finis. Yumi gat plante samting we yumi wantem. ?Hu bambae i tok agens long yumi, se yumi kam rijman long fasin we i no stret?’","Yufala i stap talem se, ‘Naoia yumi kam rijman finis. Yumi gat plante samting we yumi wantem. ?Hu bambae i tok agens long yumi, se yumi kam rijman long fasin we i no stret?’"],[12,9,"Be mi mi Hae God, mi God blong yufala, we bifo, taem ol bubu blong yufala oli stap long Ijip, mi mi tekemaot olgeta oli kam. Mo mi bambae mi fosem yufala, blong yufala i slip long haos tapolen bakegen, olsem we ol bubu ya blong yufala bifo, oli stap mekem long draeples.","Be mi mi Hae God, mi God blong yufala, we bifo, taem ol bubu blong yufala oli stap long Ijip, mi mi tekemaot olgeta oli kam. Mo mi bambae mi fosem yufala, blong yufala i slip long haos tapolen bakegen, olsem we ol bubu ya blong yufala bifo, oli stap mekem long draeples."],[12,10,"“Bifo, mi mi stap toktok long ol profet, mo mi stap soemaot ol vison* long olgeta, nao oli stap talemaot ol samting ya blong wekemap yufala.","“Bifo, mi mi stap toktok long ol profet, mo mi stap soemaot ol vison* long olgeta, nao oli stap talemaot ol samting ya blong wekemap yufala."],[12,11,"Nating we mi stap mekem olsem, be plante long yufala oli stap mekem wosip yet long ol narafala god ya long Gilead. Be olgeta we oli stap mekem olsem, bambae oli ded evriwan. Oltaem, yufala i stap kilim ol bul long Gilgal, yufala i stap bonem blong mekem sakrefaes. Ol olta ya blong yufala bambae oli brobrok, oli folfoldaon evriwan, oli kam olsem ol hip ston nating nomo, olbaot long open ples.”","Nating we mi stap mekem olsem, be plante long yufala oli stap mekem wosip yet long ol narafala god ya long Gilead. Be olgeta we oli stap mekem olsem, bambae oli ded evriwan. Oltaem, yufala i stap kilim ol bul long Gilgal, yufala i stap bonem blong mekem sakrefaes. Ol olta ya blong yufala bambae oli brobrok, oli folfoldaon evriwan, oli kam olsem ol hip ston nating nomo, olbaot long open ples.”"],[12,12,"Nao profet i talem se, “Bifo, bubu ya blong yumi Jekob* i ronwe i go stap long kantri ya Mesopotemia. Long ples ya, hem i go stap wok blong wan man, blong i save tekem wan dota blong hem, mo i stap lukaot long sipsip blong man ya bakegen, blong i save tekem narafala dota blong hem.","Nao profet i talem se, “Bifo, bubu ya blong yumi Jekob* i ronwe i go stap long kantri ya Mesopotemia. Long ples ya, hem i go stap wok blong wan man, blong i save tekem wan dota blong hem, mo i stap lukaot long sipsip blong man ya bakegen, blong i save tekem narafala dota blong hem."],[12,13,"Biaen, Hae God i sanem wan profet blong i go tekemaot ol laen blong olfala ya, blong oli no moa wokslef* long Ijip, mo profet ya i stap lukaot gud long olgeta.","Biaen, Hae God i sanem wan profet blong i go tekemaot ol laen blong olfala ya, blong oli no moa wokslef* long Ijip, mo profet ya i stap lukaot gud long olgeta."],[12,14,"Yumi ya, yumi laen blong olgeta, be naoia yufala i mekem Hae God i kros we i kros tumas. Yufala i stap kilim ol man oli ded, be hem bambae i givimbak fasin ya long yufala long fulmak blong hem. Bambae hem i panisimgud yufala, from we yufala i mekem bigfala sem long nem blong hem.”","Yumi ya, yumi laen blong olgeta, be naoia yufala i mekem Hae God i kros we i kros tumas. Yufala i stap kilim ol man oli ded, be hem bambae i givimbak fasin ya long yufala long fulmak blong hem. Bambae hem i panisimgud yufala, from we yufala i mekem bigfala sem long nem blong hem.”"],[13,1,"Nao Profet Hosea i talem se, “Yumi ya, yumi ol man Isrel* ya, mo bifo, taem yumi tok, ol laen* blong yumi long saot oli fraet, from we oli luk yumi se yumi strong moa. Be yufala i mekem sin, from we yufala i go mekem wosip long god ya Bal,* mo from samting ya, bambae yufala i mas ded.","Nao Profet Hosea i talem se, “Yumi ya, yumi ol man Isrel* ya, mo bifo, taem yumi tok, ol laen* blong yumi long saot oli fraet, from we oli luk yumi se yumi strong moa. Be yufala i mekem sin, from we yufala i go mekem wosip long god ya Bal,* mo from samting ya, bambae yufala i mas ded."],[13,2,"Oltaem, taem yufala i stap wokem ol pija blong god ya long silva, blong mekem wosip long olgeta, yufala i stap mekem sin agens long Hae God. Ol pija ya, man nomo i wokem plan blong hem, mo man nomo i wokem long gudhan blong hem, nao yufala i stap talemaot se yufala i mas go mekem sakrefaes long olgeta. Ol god ya oli pija blong bul nomo. ?Bambae man i go kis long bul olsem wanem?","Oltaem, taem yufala i stap wokem ol pija blong god ya long silva, blong mekem wosip long olgeta, yufala i stap mekem sin agens long Hae God. Ol pija ya, man nomo i wokem plan blong hem, mo man nomo i wokem long gudhan blong hem, nao yufala i stap talemaot se yufala i mas go mekem sakrefaes long olgeta. Ol god ya oli pija blong bul nomo. ?Bambae man i go kis long bul olsem wanem?"],[13,3,"Bambae yufala i mas lus kwiktaem, olsem smok blong hil long eli moning. Bambae yufala i lus olsem wota blong naet, we taem san i stap kam antap, i lus kwiktaem nomo. Bambae yufala i olsem doti blong wit,* we win i blu long hem, i karem i go. Bambae yufala i lus olsem smok blong faea we i flae i go.”","Bambae yufala i mas lus kwiktaem, olsem smok blong hil long eli moning. Bambae yufala i lus olsem wota blong naet, we taem san i stap kam antap, i lus kwiktaem nomo. Bambae yufala i olsem doti blong wit,* we win i blu long hem, i karem i go. Bambae yufala i lus olsem smok blong faea we i flae i go.”"],[13,4,"Nao profet i talemaot we Hae God i talem se, “Mi mi Hae God, mi God blong yufala, we bifo, mi tekem ol bubu blong yufala oli aot long Ijip oli kam. Mi nomo mi God blong yufala, i no moa gat narafala god olsem mi. Mi nao mi sevem yufala.","Nao profet i talemaot we Hae God i talem se, “Mi mi Hae God, mi God blong yufala, we bifo, mi tekem ol bubu blong yufala oli aot long Ijip oli kam. Mi nomo mi God blong yufala, i no moa gat narafala god olsem mi. Mi nao mi sevem yufala."],[13,5,"Bifo taem we ol bubu blong yufala oli stap wokbaot long draeples, we i no gat wota long hem, be mi nao mi stap lukaot gud long olgeta.","Bifo taem we ol bubu blong yufala oli stap wokbaot long draeples, we i no gat wota long hem, be mi nao mi stap lukaot gud long olgeta."],[13,6,"Be taem olgeta oli kam stap long gudfala graon ya, oli gat plante kakae, mo oli stap harem gud tumas from. Nao tingting blong olgeta i go antap tumas, mo olgeta oli no moa tingbaot mi, mo fasin ya i stap yet kam kasem tede.","Be taem olgeta oli kam stap long gudfala graon ya, oli gat plante kakae, mo oli stap harem gud tumas from. Nao tingting blong olgeta i go antap tumas, mo olgeta oli no moa tingbaot mi, mo fasin ya i stap yet kam kasem tede."],[13,7,"Nao from samting ya, mi mi kros tumas long yufala, mo bambae mi kam spolemgud yufala olsem we laeon i kakae man. Bambae mi stap wet blong spolem yufala, olsem anamol ya leped* we i stap haed long saed blong rod blong jam long man blong i kakae.","Nao from samting ya, mi mi kros tumas long yufala, mo bambae mi kam spolemgud yufala olsem we laeon i kakae man. Bambae mi stap wet blong spolem yufala, olsem anamol ya leped* we i stap haed long saed blong rod blong jam long man blong i kakae."],[13,8,"Bambae mi kros tumas long yufala, mi kam spolem yufala, olsem anamol ya bea we i kros tumas from we wan man i stilim ol pikinini blong hem, nao i holem man ya i tereterem hem. Taem mi faenem yufala, bambae mi kilim yufala wantaem nomo, olsem laeon we i faenem wan anamol, i kilim, i kakae.","Bambae mi kros tumas long yufala, mi kam spolem yufala, olsem anamol ya bea we i kros tumas from we wan man i stilim ol pikinini blong hem, nao i holem man ya i tereterem hem. Taem mi faenem yufala, bambae mi kilim yufala wantaem nomo, olsem laeon we i faenem wan anamol, i kilim, i kakae."],[13,9,"“Ol man Isrel. Mi bambae mi kilim yufala evriwan i ded. ?Hu nao bambae i stap blong givhan long yufala?","“Ol man Isrel. Mi bambae mi kilim yufala evriwan i ded. ?Hu nao bambae i stap blong givhan long yufala?"],[13,10,"Yufala i stap talem se, ‘Yumi mas gat king blong yumi, mo yumi mas gat ol man blong lidim yumi.’ ?Be king ya bambae i mekem wanem? ?Mo ol lida ya bambae oli givhan long yufala olsem wanem?","Yufala i stap talem se, ‘Yumi mas gat king blong yumi, mo yumi mas gat ol man blong lidim yumi.’ ?Be king ya bambae i mekem wanem? ?Mo ol lida ya bambae oli givhan long yufala olsem wanem?"],[13,11,"Bifo, mi mi kros long yufala, nao mi letem we yufala i gat ol king blong yufala, be naoia, from we mi kros tumas long yufala, mi tekemaot olgeta bakegen.","Bifo, mi mi kros long yufala, nao mi letem we yufala i gat ol king blong yufala, be naoia, from we mi kros tumas long yufala, mi tekemaot olgeta bakegen."],[13,12,"“Olgeta sin blong yufala, mi mi raetemdaon olgeta evriwan finis long wan buk. Mo buk ya i stap gud nomo, i no gat wan samting bambae i save spolem.","“Olgeta sin blong yufala, mi mi raetemdaon olgeta evriwan finis long wan buk. Mo buk ya i stap gud nomo, i no gat wan samting bambae i save spolem."],[13,13,"Yufala i gat janis blong kasem laef, be hed blong yufala i krangke tumas, nao yufala i no wantem. Yufala i olsem pikinini we i stap long bel blong mama blong hem, we i taem blong hem blong i bon, be hem i no save kamaot.","Yufala i gat janis blong kasem laef, be hed blong yufala i krangke tumas, nao yufala i no wantem. Yufala i olsem pikinini we i stap long bel blong mama blong hem, we i taem blong hem blong i bon, be hem i no save kamaot."],[13,14,"Naoia, yufala i stap go long Hom* blong ol Dedman ya. Mo mi bambae mi no save blokem yufala, mi no save tekemaot yufala long paoa blong ded. !Ded! !Yu kam panisim olgeta ya! !Hom blong ol Dedman! !Yu kam spolem olgeta ya! !Mi mi no moa gat sore long olgeta nating!","Naoia, yufala i stap go long Hom* blong ol Dedman ya. Mo mi bambae mi no save blokem yufala, mi no save tekemaot yufala long paoa blong ded. !Ded! !Yu kam panisim olgeta ya! !Hom blong ol Dedman! !Yu kam spolem olgeta ya! !Mi mi no moa gat sore long olgeta nating!"],[13,15,"Ol man Isrel. Nating sipos yufala i gru bigwan olsem wael gras, be mi bambae mi sanem wan win i aot long draeples i kam, we i hot we i hot, nao bambae i mekem ol wota ya we yufala i stap dring oli drae evriwan. Ol gudgudfala samting blong yufala, mi bambae mi spolem olgeta evriwan.","Ol man Isrel. Nating sipos yufala i gru bigwan olsem wael gras, be mi bambae mi sanem wan win i aot long draeples i kam, we i hot we i hot, nao bambae i mekem ol wota ya we yufala i stap dring oli drae evriwan. Ol gudgudfala samting blong yufala, mi bambae mi spolem olgeta evriwan."],[13,16,"Ol man Sameria.* Bambae mi givim panis long yufala, from we oltaem yufala i stap girap agens long mi. Ol enemi blong yufala bambae oli kam kilim yufala evriwan i ded long taem blong faet. Bambae oli kam smasemgud ol pikinini blong yufala long graon, mo bambae oli holem ol woman blong yufala we oli gat bel, oli splitim bel blong olgeta blong kilim olgeta i ded.”","Ol man Sameria.* Bambae mi givim panis long yufala, from we oltaem yufala i stap girap agens long mi. Ol enemi blong yufala bambae oli kam kilim yufala evriwan i ded long taem blong faet. Bambae oli kam smasemgud ol pikinini blong yufala long graon, mo bambae oli holem ol woman blong yufala we oli gat bel, oli splitim bel blong olgeta blong kilim olgeta i ded.”"],[14,1,"Nao Profet Hosea i talem long ol man Isrel* se, “Olgeta. Hae God i God blong yumi, mo yufala i mas kambak long hem. Ol sin blong yufala i plante tumas, i mekem yufala i stambol, yufala i foldaon.","Nao Profet Hosea i talem long ol man Isrel* se, “Olgeta. Hae God i God blong yumi, mo yufala i mas kambak long hem. Ol sin blong yufala i plante tumas, i mekem yufala i stambol, yufala i foldaon."],[14,2,"Yufala i mas tanem tingting blong yufala, blong kambak long hem bakegen. Yufala i mas kam prea long hem, yufala i mas talem se, ‘Hae God. Plis yu fogivim mifala, yu tekemaot ol sin blong mifala, mo yu lesin long prea blong mifala, nao bambae mifala i stap presem yu bakegen, olsem we mifala i promes bifo.","Yufala i mas tanem tingting blong yufala, blong kambak long hem bakegen. Yufala i mas kam prea long hem, yufala i mas talem se, ‘Hae God. Plis yu fogivim mifala, yu tekemaot ol sin blong mifala, mo yu lesin long prea blong mifala, nao bambae mifala i stap presem yu bakegen, olsem we mifala i promes bifo."],[14,3,"Ol man Asiria bambae oli no save sevem mifala, mo ol hos blong faet blong mifala neva bambae oli save blokem mifala long taem blong faet. Neva bambae mifala i save singaot ol narafala god ya bakegen, se oli god blong mifala. Hae God, i no moa gat narafala man blong givhan long mifala. Plis yu soemaot we yu yu gat sore long mifala.’ ”","Ol man Asiria bambae oli no save sevem mifala, mo ol hos blong faet blong mifala neva bambae oli save blokem mifala long taem blong faet. Neva bambae mifala i save singaot ol narafala god ya bakegen, se oli god blong mifala. Hae God, i no moa gat narafala man blong givhan long mifala. Plis yu soemaot we yu yu gat sore long mifala.’ ”"],[14,4,"Nao Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel.* Naoia mi mi no moa kros long yufala. Bambae mi tekem yufala i kambak long mi bakegen, nao bambae mi lavem yufala long olgeta tingting blong mi.","Nao Profet Hosea i talemaot we Hae God i talem se, “Ol man Isrel.* Naoia mi mi no moa kros long yufala. Bambae mi tekem yufala i kambak long mi bakegen, nao bambae mi lavem yufala long olgeta tingting blong mi."],[14,5,"Bambae mi mekem i gud long yufala, olsem we ren i foldaon long graon we i drae, i mekem i kam gud bakegen. Bambae yufala i olsem tri we i karem ol gudgudfala flaoa blong hem. Bambae yufala i stanap strong olsem ol sida* blong Lebanon, we rus blong olgeta i godaon olgeta.","Bambae mi mekem i gud long yufala, olsem we ren i foldaon long graon we i drae, i mekem i kam gud bakegen. Bambae yufala i olsem tri we i karem ol gudgudfala flaoa blong hem. Bambae yufala i stanap strong olsem ol sida* blong Lebanon, we rus blong olgeta i godaon olgeta."],[14,6,"Bambae laef blong yufala i kam niuwan bakegen, i olsem bigfala tri ya olif* we i gat ol niufala lif blong hem. Bambae yufala i gat gudfala laef, we ol man oli harem gud long hem, olsem we oli save harem smel blong sida blong Lebanon we i naes we i naes.","Bambae laef blong yufala i kam niuwan bakegen, i olsem bigfala tri ya olif* we i gat ol niufala lif blong hem. Bambae yufala i gat gudfala laef, we ol man oli harem gud long hem, olsem we oli save harem smel blong sida blong Lebanon we i naes we i naes."],[14,7,"Bambae yufala i stap bakegen aninit long han blong mi, mo mi bambae mi lukaot gud long yufala. Bambae yufala i olsem garen we i stap karem plante kakae. Bambae yufala i olsem plantesen blong grep,* we i stap karem fulap frut long hem. Nem blong yufala bambae i go kasem evri ples, olsem nem blong waen blong Lebanon.","Bambae yufala i stap bakegen aninit long han blong mi, mo mi bambae mi lukaot gud long yufala. Bambae yufala i olsem garen we i stap karem plante kakae. Bambae yufala i olsem plantesen blong grep,* we i stap karem fulap frut long hem. Nem blong yufala bambae i go kasem evri ples, olsem nem blong waen blong Lebanon."],[14,8,"Long taem ya, bambae yufala i no moa save mekem wosip long ol narafala god bakegen. Taem yufala i prea long mi, mi bambae mi harem prea blong yufala, mo mi bambae mi lukaot long yufala. Bambae mi olsem wan gudfala tri we lif blong hem i no save foldaon, we yufala bambae i save kam haed long gudfala sed blong hem. Olgeta gudgudfala samting we bambae yufala i kasem, mi nomo bambae mi stamba blong olgeta.”","Long taem ya, bambae yufala i no moa save mekem wosip long ol narafala god bakegen. Taem yufala i prea long mi, mi bambae mi harem prea blong yufala, mo mi bambae mi lukaot long yufala. Bambae mi olsem wan gudfala tri we lif blong hem i no save foldaon, we yufala bambae i save kam haed long gudfala sed blong hem. Olgeta gudgudfala samting we bambae yufala i kasem, mi nomo bambae mi stamba blong olgeta.”"],[14,9,"Nao Profet Hosea i talem se, “Olgeta we oli waes oli mas savegud ol tok ya we mi mi talem, mo oli mas holem i stap gud long tingting blong olgeta. Olgeta fasin blong Hae God i stret gud olgeta, mo oltaem, ol stret man oli stap longtaem, from we oli stap folem ol fasin ya. Be ol man nogud oli stambol, mo oli foldaon, from we oli no save tinghevi long olgeta.”","Nao Profet Hosea i talem se, “Olgeta we oli waes oli mas savegud ol tok ya we mi mi talem, mo oli mas holem i stap gud long tingting blong olgeta. Olgeta fasin blong Hae God i stret gud olgeta, mo oltaem, ol stret man oli stap longtaem, from we oli stap folem ol fasin ya. Be ol man nogud oli stambol, mo oli foldaon, from we oli no save tinghevi long olgeta.”"]]}};